export const LESSON_INDEX: LessonIndexChunk[] = [{"id":"lhx_phase1_chapitres_1_2_intro_1","kind":"html","lessonKey":"phase1_chapitres_1_2","title":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","lessonTitle":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","unitId":1,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 1 : تركيب البروتين 🎯 الهدف العلمي : بيّن أن تركيب البروتين يتم في الهيولى بالضبط على مستوى الشبكة الهيولية الداخلية المحببة (REG). ⏱️ المدة التقديرية للتعلم الذاتي : 20 دقيقة 🎯 الهدف العلمي : افهم كيفية ترجمة اللغة النووية (4 أحرف) إلى لغة بروتينية (20 حمض أميني)، وفسّر آلية تنشيط الحمض الأميني بالـ ARNt . ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","تذكير","بالمكتسبات","ومقر","تركيب","البروتين","الاول","التخصص","للبروتينات","بالضبط","الشبكه","الهيوليه","المحببه","كيفيه","ترجمه","اللغه","النوويه","بروتينيه"],"aliases":["الدرس 1","تذكير بالمكتسبات ومقر تركيب البروتين"]},{"id":"lhx_phase1_chapitres_1_2_card1_1","kind":"html","lessonKey":"phase1_chapitres_1_2","title":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","lessonTitle":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","unitId":1,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ التساؤل الجوهري لبداية الوحدة تتميز الخلايا الحية بقدرتها الفائقة على اصطناع بروتينات متنوعة (إنزيمات، هرمونات، أجسام مضادة) تضمن تخصصها الوظيفي. انطلاقا من مكتسباتك حول البنية الدقيقة للخلية، أين يتم بالضبط تجميع الأحماض الأمينية لتركيب هذه البروتينات داخل الخلية؟ للتأكد من المقر الدقيق لتركيب البروتين، قام العلماء بإجراء تجارب تتتبع مسار الأحماض الأمينية المشعة داخل الخلايا الإفرازية (مثل خلايا البنكرياس).","keywords":["الدرس","تذكير","بالمكتسبات","ومقر","تركيب","البروتين","وضعيه","الانطلاق","وبناء","العلميه","التساول","الجوهري","لبدايه","تتميز","الخلايا","الحيه","بقدرتها","الفايقه"],"aliases":["الدرس 1","تذكير بالمكتسبات ومقر تركيب البروتين"]},{"id":"lhx_phase1_chapitres_1_2_card2_1","kind":"html","lessonKey":"phase1_chapitres_1_2","title":"خلية عنقودية للبنكرياس بعد 3 دقائق من الحضن في وسط به لوسين مشع ³H-Leucine (1/2)","lessonTitle":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","unitId":1,"part":1,"total":2,"text":"2 التحليل المنهجي لتجربة التصوير الإشعاعي الذاتي (الأحماض الأمينية المشعة) خلية عنقودية للبنكرياس بعد 3 دقائق من الحضن في وسط به لوسين مشع ³H-Leucine النواة الشبكة الهيولية المحببة (REG) جهاز غولجي حويصلات إفرازية 🔴 النقاط الحمراء تشير إلى الإشعاع المتركز في الشبكة الهيولية الداخلية المحببة بعد 3 دقائق فقط. منهجية البكالوريا : الاستدلال العلمي 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة (وثيقة حاضرة) · البوابة 2 → 📷 صورة (حلّل/صِف → 1→2→4 ) · السنّ 2:","keywords":["خليه","عنقوديه","للبنكرياس","بعد","دقايق","الحضن","وسط","لوسين","مشع","leucine","الدرس","تذكير","بالمكتسبات","ومقر","تركيب","البروتين","لتجربه","التصوير"],"aliases":["خلية عنقودية للبنكرياس بعد 3 دقائق من الحضن في وسط به لوسين مشع ³H-Leucine"]},{"id":"lhx_phase1_chapitres_1_2_card2_2","kind":"html","lessonKey":"phase1_chapitres_1_2","title":"خلية عنقودية للبنكرياس بعد 3 دقائق من الحضن في وسط به لوسين مشع ³H-Leucine (2/2)","lessonTitle":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","unitId":1,"part":2,"total":2,"text":"استخرج رقم + وحدة + اتجاه قبل أي تفسير لماذا استعمل العلماء الأحماض الأمينية المشعة تحديدًا؟ • الأحماض الأمينية هي الوحدات البنائية الأساسية لتركيب البروتينات. • العنصر المشع (التريتيوم ³H) يسمح بتحديد المقر الدقيق ومتابعة الحركية الزمنية داخل العضيات الخلوية. النتيجة الحاسمة : بعد مدة قصيرة (3 دقائق)، يظهر الإشعاع حصريا على مستوى الشبكة الهيولية الداخلية المحببة REG ، مما يثبت أنها المقر الحقيقي لتركيب البروتين في الخلية.","keywords":["خليه","عنقوديه","للبنكرياس","بعد","دقايق","الحضن","وسط","لوسين","مشع","leucine","الدرس","تذكير","بالمكتسبات","ومقر","تركيب","البروتين","استخرج","اتجاه"],"aliases":["خلية عنقودية للبنكرياس بعد 3 دقائق من الحضن في وسط به لوسين مشع ³H-Leucine"]},{"id":"lhx_phase1_chapitres_1_2_card3_1","kind":"html","lessonKey":"phase1_chapitres_1_2","title":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","lessonTitle":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","unitId":1,"part":1,"total":1,"text":"3 المستكشف التفاعلي لحركية البروتين داخل الخلية الإفرازية اضغط على الزمن التجريبي لمتابعة مسار البروتين المصنوع حديثا : ⏱️ بعد 3 دقائق (البداية) ⏱️ بعد 20 دقيقة (النضج) ⏱️ بعد 120 دقيقة (الإفراز) ⏱️ الحالة عند الزمن 3 دقائق : يتمركز الإشعاع كليا على مستوى الشبكة الهيولية الداخلية المحببة ( REG ) المتواجدة في الهيولى. وهذا يدل على أن عملية دمج الأحماض الأمينية وتركيب السلسلة البيبتيدية تبدأ هنا بفضل الريبوزومات المتصلة بأغشية الشبكة.","keywords":["الدرس","تذكير","بالمكتسبات","ومقر","تركيب","البروتين","المستكشف","التفاعلي","لحركيه","الافرازيه","الزمن","التجريبي","لمتابعه","المصنوع","حديثا","دقايق","البدايه","النضج"],"aliases":["الدرس 1","تذكير بالمكتسبات ومقر تركيب البروتين"]},{"id":"lhx_phase1_chapitres_1_2_card4_1","kind":"html","lessonKey":"phase1_chapitres_1_2","title":"الحقيقة العلمية المعتمدة في البكالوريا","lessonTitle":"الدرس 1 : تذكير بالمكتسبات ومقر تركيب البروتين","unitId":1,"part":1,"total":1,"text":"4 الخلاصة والتقويم الذاتي (النشاط 1) الحقيقة العلمية المعتمدة في البكالوريا يتم تركيب البروتين عند حقيقيات النوى في الهيولى (الستوبلازم) ، وبالتحديد على مستوى الشبكة الهيولية الداخلية المحببة ( Réticulum Endoplasmique Granuleux ) انطلاقا من الأحماض الأمينية. اختبر فهمك : لماذا تسمى الشبكة الهيولية بـ \"المحببة\" أو \"الفعالة\"؟ أ) لاحتوائها على حبيبات الجليكوجين المخزنة للطاقة. ب) لوجود جسيمات دقيقة متصلة بغشائها الخارجي تسمى الريبوزومات ( Ribosomes ). ج) لأنها تحتوي على ثقوب نووية تسمح بخروج الـ ADN .","keywords":["الحقيقه","العلميه","المعتمده","البكالوريا","الدرس","تذكير","بالمكتسبات","ومقر","تركيب","البروتين","الخلاصه","والتقويم","حقيقيات","النوي","الستوبلازم","وبالتحديد","الشبكه","الهيوليه"],"aliases":["الحقيقة العلمية المعتمدة في البكالوريا"]},{"id":"lhx_phase1_chapitres_1_2_2_intro_1","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"كيف نترجم 4 أحرف إلى 20 كلمة؟","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 1 : تركيب البروتين 🎯 الهدف العلمي : بيّن أن تركيب البروتين يتم في الهيولى بالضبط على مستوى الشبكة الهيولية الداخلية المحببة (REG). ⏱️ المدة التقديرية للتعلم الذاتي : 20 دقيقة 🎯 الهدف العلمي : افهم كيفية ترجمة اللغة النووية (4 أحرف) إلى لغة بروتينية (20 حمض أميني)، وفسّر آلية تنشيط الحمض الأميني بالـ ARNt . ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","نترجم","احرف","الي","كلمه؟","الاول","التخصص","للبروتينات","بالضبط","الشبكه","الهيوليه","المحببه","كيفيه","ترجمه","اللغه","النوويه","بروتينيه","اميني"],"aliases":["كيف نترجم 4 أحرف إلى 20 كلمة؟"]},{"id":"lhx_phase1_chapitres_1_2_2_card1_1","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"كيف نترجم 4 أحرف إلى 20 كلمة؟ (1/2)","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":1,"total":2,"text":"1 الإشكالية الرياضية والبيولوجية للشفرة الوراثية ⚠️ كيف نترجم 4 أحرف إلى 20 كلمة؟ تتكون اللغة النووية للـ ARNm من 4 قواعد آزوتية فقط ( A, U, C, G ) ، بينما تتكون اللغة البروتينية من 20 حمضاً أمينياً مختلفاً في بالطبيعة. كيف يمكن لأربع قواعد فقط أن تشفر وتنظم ترتيب 20 حمضاً أمينياً دون أي نقص أو تداخل؟ بالبرهان الرياضي المنطقي : • إذا كانت كل قاعدة تشفر لحمض أميني واحد ($4^1 = 4$) : هذا غير كافٍ لتغطية 20 حمضاً. • إذا كانت كل قاعدتين تشفران لحمض أميني ($4^2 = 16$) : يبقى العدد غير كافٍ.","keywords":["كيف","نترجم","احرف","الي","كلمه؟","الرياضيه","والبيولوجيه","للشفره","الوراثيه","تتكون","اللغه","النوويه","قواعد","ازوتيه","بينما","البروتينيه","امينيا","مختلفا"],"aliases":["كيف نترجم 4 أحرف إلى 20 كلمة؟"]},{"id":"lhx_phase1_chapitres_1_2_2_card1_2","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"كيف نترجم 4 أحرف إلى 20 كلمة؟ (2/2)","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":2,"total":2,"text":"• الاستنتاج الحتمي ($4^3 = 64$) : كل 3 قواعد آزوتية متتالية (رامزة) تشفر لحمض أميني واحد. وبما أن 64 > 20، فهذا يفسر تشفير عدة رامزات لحمض أميني واحد (الترادف).","keywords":["كيف","نترجم","احرف","الي","كلمه؟","الاستنتاج","الحتمي","قواعد","ازوتيه","متتاليه","رامزه","اميني","تشفير","رامزات","الترادف"],"aliases":["كيف نترجم 4 أحرف إلى 20 كلمة؟"]},{"id":"lhx_phase1_chapitres_1_2_2_card2_1","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"الحمض الأميني : الميثيونين (Méthionine - Met) (1/2)","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":1,"total":2,"text":"2 فك شفرة البكالوريا التفاعلي (جدول الشفرة الوراثية) 🔑 تذكير منهجي: البوابة 1 → 📄 ورقة · البوابة 2 → 🎬 فيلم (فسّر/علل → 1→2→3→4 ) · السنّ 3: لأنّ مسبوقة بمعطى من الوثيقة اختر القواعد الآزوتية الثلاث (الرامزة على الـ ARNm ) لاكتشاف الحمض الأميني الموافق ومعنى الرامزات الخاصة : الحرف الأول (5') : A (أدينين) U (يوراسيل) C (سيتوزين) G (غوانين) الحرف الثاني : U (يوراسيل) A (أدينين) C (سيتوزين) G (غوانين) الحرف الثالث (3') : G (غوانين) A (أدينين) U (يوراسيل) C (سيتوزين) 5'- AUG -3' الحمض الأميني :","keywords":["الحمض","الاميني","الميثيونين","thionine","met","كيف","نترجم","احرف","الي","كلمه؟","التفاعلي","الشفره","الوراثيه","تذكير","منهجي","البوابه","مسبوقه","بمعطي"],"aliases":["الحمض الأميني","الميثيونين (Méthionine - Met)"]},{"id":"lhx_phase1_chapitres_1_2_2_card2_2","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"الحمض الأميني : الميثيونين (Méthionine - Met) (2/2)","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":2,"total":2,"text":"الميثيونين (Méthionine - Met) 🟢 هذه هي رامزة البداية (Codon d'initiation) التي تنطلق منها دائما عملية الترجمة في الخلية.","keywords":["الحمض","الاميني","الميثيونين","thionine","met","كيف","نترجم","احرف","الي","كلمه؟","رامزه","البدايه","codon","initiation","تنطلق","دايما","عمليه","الترجمه"],"aliases":["الحمض الأميني","الميثيونين (Méthionine - Met)"]},{"id":"lhx_phase1_chapitres_1_2_2_card3_1","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"شروط ومتطلبات عملية التنشيط (1/2)","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":1,"total":2,"text":"3 آلية تنشيط الأحماض الأمينية (المرحلة التحضيرية للترجمة) لكي يشارك الحمض الأميني في تركيب البروتين، يجب أن يُربط أولاً بالناقل الخاص به وهو الـ ARNt (ARN de transfert) . تتم هذه العملية بتدخل ثلاثة عناصر جوهرية : شروط ومتطلبات عملية التنشيط 🧪 حمض أميني حر ( AA ) في الهيولى. 🧬 ناقل نوعي ( ARNt ) يمتلك موقعين : موقع تثبيت الحمض الأميني، وموقع الرامزة المضادة ( Anticodon ). ⚡ طاقة جزيئية ( ATP ) لإنشاء الرابطة الغنية بالطاقة. ⚙️ إنزيم التنشيط النوعي ( Aminoacyl-ARNt synthétase ) . 🔑 مفتاح المنهجية:","keywords":["شروط","ومتطلبات","عمليه","التنشيط","كيف","نترجم","احرف","الي","كلمه؟","تنشيط","الاحماض","الامينيه","المرحله","التحضيريه","للترجمه","يشارك","الحمض","الاميني"],"aliases":["شروط ومتطلبات عملية التنشيط"]},{"id":"lhx_phase1_chapitres_1_2_2_card3_2","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"شروط ومتطلبات عملية التنشيط (2/2)","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":2,"total":2,"text":"البوابة 1 → 📄 ورقة · البوابة 2 → 🎬 فيلم (فسّر/علل → 1→2→3→4 ) · السنّ 3: لأنّ مسبوقة بمعطى من الوثيقة خطوات التنشيط في البكالوريا 1. يتوضع كل من الحمض الأميني والـ ARNt في المواقع الفعالة النوعية لإنزيم التنشيط. 2. تتم إماهة جزيئة الـ ATP لربط الحمض الأميني بالـ ARNt برابطة إسترية غنية بالطاقة. 3. يتحرر المعقد (حمض أميني - ARNt منشط) وينفصل عن الإنزيم ليتجه نحو الريبوزوم.","keywords":["شروط","ومتطلبات","عمليه","التنشيط","كيف","نترجم","احرف","الي","كلمه؟","البوابه","مسبوقه","بمعطي","الوثيقه","خطوات","يتوضع","الحمض","الاميني","المواقع"],"aliases":["شروط ومتطلبات عملية التنشيط"]},{"id":"lhx_phase1_chapitres_1_2_2_card4_1","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"كيف نترجم 4 أحرف إلى 20 كلمة؟","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 حدّد مقر تركيب البروتين عند حقيقيات النوى وشروط تنشيط الأحماض الأمينية. يتم تركيب البروتين في الهيولى وبالتحديد على مستوى الشبكة الهيولية المحببة. يبدأ التعبير المورثي بالاستنساخ في النواة واكتماله بالترجمة في الهيولى. تحمل النواة المعلومة الوراثية التي تنتقل إلى الهيولى لإنجاز التركيب. تنشط الأحماض الأمينية بإنزيمات وبطاقة ATP قبل ارتباطها بـ ARNt الموافق. يحمل الـ ARNm الرسول المعلومة الوراثية من النواة إلى الهيولى. 🔑 المصطلح المفتاحي في البكالوريا : الشبكة الهيولية المحببة / مقر تركيب البروتين","keywords":["كيف","نترجم","احرف","الي","كلمه؟","خلاصه","الدرس","حقيقيات","النوي","وشروط","تنشيط","الاحماض","الامينيه","وبالتحديد","الشبكه","الهيوليه","المحببه","التعبير"],"aliases":["كيف نترجم 4 أحرف إلى 20 كلمة؟"]},{"id":"lhx_phase1_chapitres_1_2_2_card5_1","kind":"html","lessonKey":"phase1_chapitres_1_2_2","title":"1. كم عدد الرامزات التي لا تشفر لأي حمض أميني وتسمى \"رامزات التوقف\" ( Codons STOP )؟","lessonTitle":"كيف نترجم 4 أحرف إلى 20 كلمة؟","unitId":1,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. كم عدد الرامزات التي لا تشفر لأي حمض أميني وتسمى \"رامزات التوقف\" ( Codons STOP )؟ أ) رامزة واحدة فقط وهي AUG . ب) 3 رامزات وهي : UAA, UAG, UGA . ج) 64 رامزة بالكامل. 2. إذا حدث طفرة أدت إلى تخريب موقع الرامزة المضادة ( Anticodon ) في جزيئة الـ ARNt ، ماذا يحدث؟ أ) يتوقف استنساخ الـ ADN داخل النواة. ب) يفشل الـ ARNt في التعرف على رامزة الـ ARNm الموافقة أثناء الترجمة في الريبوزوم. ج) لا يتحلل جزيء الـ ATP أبداً.","keywords":["عدد","الرامزات","التي","تشفر","لاي","حمض","اميني","وتسمي","رامزات","التوقف","codons","stop","كيف","نترجم","احرف","الي","كلمه؟","رامزه"],"aliases":["1. كم عدد الرامزات التي لا تشفر لأي حمض أميني وتسمى \"رامزات التوقف\" ( Codons STOP )؟"]},{"id":"lhx_lecon_transcription_intro_1","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة الأولى : تركيب البروتين 🎯 الهدف الحصري للدرس : حدّد مقر وآلية التصنيع الحيوي لجزيئة الـ ARNm انطلاقا من الـ ADN. ⏱️ المدة التقديرية للتعلم الذاتي : 20 دقيقة (بدون معلم)","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الاول","التخصص","للبروتينات","الاولي","الحصري","للدرس","واليه","التصنيع","الحيوي","لجزييه"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card1_1","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ التناقض الظاهري (مفتاح فهم الدرس) تتواجد المعلومات الوراثية ADN داخل النواة عند حقيقيات النوى، بينما تتم عملية تركيب البروتينات في الهيولى (الستوبلازم) . علما أن جزيئة الـ ADN لا تغادر النواة أبدا بسبب حجمها الجزيئي الضخم، كيف تنتقل نسخة من هذه المعلومات إلى الهيولى لتركيب البروتين الخاص بها؟ لحل هذه الإشكالية، اقترح العلماء وجود وسيط كيميائي (جزيئة ناقلة) ينقل الرسالة الوراثية من النواة إلى الهيولى. سميت هذه الجزيئة بـ الـ ARNm (حمض ريبي نووي رسول - ARN messager) .","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","وضعيه","الانطلاق","وبناء","العلميه","التناقض","الظاهري","مفتاح","تتواجد","حقيقيات","النوي،"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card2_1","kind":"html","lessonKey":"lecon_transcription","title":"شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H) (1/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":4,"text":"2 التحليل المنهجي للتجربة التاريخية (إثبات دور ومقر تصنيع الـ ARNm) 🧪 تجربة التصوير الإشعاعي الذاتي 🔬 الملاحظة بالمجهر الإلكتروني (ظاهرة الاستنساخ) شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H) الزمن t = 15 دقيقة النواة الزمن t = 90 دقيقة النواة 🔴 النقاط الحمراء تمثل الإشعاع (اليوراسيل المشع المدمج في الـ ARNm ). منهجية البكالوريا : تحليل وثيقة 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 📷 صورة (حلّل → 1→2→4 ) · استخرج الزمن + المقر (نواة/هيولى) قبل الاستنتاج كيف نجيب عن السؤال :","keywords":["شروط","ونتايج","التجربه","بقع","اشعاعيه","اليوراسيل","المشع","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","للتجربه","التاريخيه","اثبات"],"aliases":["شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H)"]},{"id":"lhx_lecon_transcription_card2_2","kind":"html","lessonKey":"lecon_transcription","title":"شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H) (2/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":2,"total":4,"text":"\"حلل نتائج التجربة ثم استنتج؟\" 1. التعريف بالوثيقة : تمثل الوثيقة تتبع مسار الإشعاع في خلية حيوانية بعد حضنها في وسط يحتوي على اليوراسيل المشع (قاعدة مميزة للـ ARN ). 2. الملاحظة (التحليل الصارم دون تفسير) : • بعد 15 دقيقة : يتمركز الإشعاع كليا داخل النواة . • بعد 90 دقيقة : ينتقل الإشعاع من النواة ليستقر في الهيولى . 3. الاستنتاج الدقيق : يتم تركيب الـ ARNm داخل النواة ، ثم ينتقل إلى الهيولى حاملا معه نسخة من المعلومات الوراثية.","keywords":["شروط","ونتايج","التجربه","بقع","اشعاعيه","اليوراسيل","المشع","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","نتايج","استنتج؟","التعريف"],"aliases":["شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H)"]},{"id":"lhx_lecon_transcription_card2_3","kind":"html","lessonKey":"lecon_transcription","title":"شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H) (3/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":3,"total":4,"text":"صورة بالمجهر الإلكتروني ورسم تخطيطي لـ \"شجرة الريسمان\" خيط الـ ADN اتجاه الاستنساخ ➡️ 🟢 الخيوط الخضراء المتدرجة في الطول تمثل جزيئات الـ ARNm قيد التشكل، 🟠 الكريات البرتقالية تمثل إنزيم ARN polymérase . منهجية البكالوريا : استخراج المعلومات من الشكل 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 📷 صورة (حلّل → 1→2→4 ) · استخرج الزمن + المقر (نواة/هيولى) قبل الاستنتاج ماذا نستفيد من ظاهرة التعدد الاستنساخي؟ تظهر الصورة ارتباط عدة جزيئات من إنزيم ARN polymérase (ARN بوليميراز) بنفس مورثة الـ ADN في آن واحد،","keywords":["شروط","ونتايج","التجربه","بقع","اشعاعيه","اليوراسيل","المشع","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","بالمجهر","الالكتروني","تخطيطي"],"aliases":["شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H)"]},{"id":"lhx_lecon_transcription_card2_4","kind":"html","lessonKey":"lecon_transcription","title":"شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H) (4/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":4,"total":4,"text":"مما يسمح بإنتاج كميات هائلة من جزيئات الـ ARNm خلال فترة زمنية قصيرة. قاعدة تحديد اتجاه الاستنساخ في أسئلة البكالوريا : يتجه الاستنساخ دائما من الجهة التي تكون فيها خيوط الـ ARNm قصيرة (بداية المورثة) نحو الجهة التي تكون فيها خيوط الـ ARNm طويلة (نهاية المورثة) .","keywords":["شروط","ونتايج","التجربه","بقع","اشعاعيه","اليوراسيل","المشع","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","بانتاج","كميات","هايله"],"aliases":["شروط ونتائج التجربة (بقع إشعاعية للـ اليوراسيل المشع ³H)"]},{"id":"lhx_lecon_transcription_card3_1","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (1/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":4,"text":"3 المحاكي التفاعلي لآلية الاستنساخ (قاعدة تكامل القواعد الآزوتية) 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 🎬 فيلم (فسّر → 1→2→3→4 ) · لأنّ مسبوقة بمعطى (اتجاه الاستنساخ من القصير → الطويل) يقوم إنزيم الـ ARN polymérase بفتح سلسلتي الـ ADN ، ويقرأ السلسلة المستنسخة ( Brin transcrit 3'→5' ) ليركب جزيئة الـ ARNm عن طريق ربط النكليوتيدات الريبية الحرة بالتكامل : سلسلة الـ ADN المستنسخة (Brin Transcrit 3'→5') :","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","المحاكي","التفاعلي","لاليه","الاستنساخ","قاعده","تكامل","القواعد","الازوتيه","مفتاح","المنهجيه"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card3_2","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (2/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":2,"total":4,"text":"3'- T A C - G C T - A A G - C T A - A T T -5' سلسلة الـ ARNm المتشكلة (اضغط على الزر لتركيب النكليوتيدات) : 5'- _ _ _ - _ _ _ - _ _ _ - _ _ _ - _ _ _ -3' ⚡ إضافة الرامزة التالية 🔄 إعادة المحاكاة 💡 تنبيه هام جدا لبكالوريا العلوم التجريبية : فرق بين السلسلة المستنسخة وغير المستنسخة! الـ ARNm يتكامل مع السلسلة المستنسخة ( Brin Transcrit 3'→5' ). حيث تقابل التايمين T قاعدة الأدينين A ، وتقابل الأدينين A قاعدة اليوراسيل U (وليس T !).","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","سلسله","المتشكله","لتركيب","النكليوتيدات","اضافه","الرامزه","التاليه","اعاده","المحاكاه","تنبيه"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card3_3","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (3/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":3,"total":4,"text":"الـ ARNm يطابق السلسلة غير المستنسخة ( Brin Non Transcrit 5'→3' ) مع استبدال كل قاعدة تايمين T بقاعدة يوراسيل U . 🧬 نضج الـ ARNm في النواة : القطع غير الدالة (Introns) والدالة (Exons) الـ ARNm الناتج مباشرة عن الاستنساخ يدعى ARNm ما قبل الرسول (pre-messenger ARNm). قبل خروجه من النواة، تُحذَف منه قطع تُدعى القطع غير الدالة (Introns) لأنها لا تُترجم إلى أحماض أمينية، وتبقى القطع الدالة (Exons) التي تُترجم فعلاً إلى أحماض أمينية. النتيجة : ARNm ناضج أقصر طولاً يغادر النواة إلى الهيولى.","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","يطابق","المستنسخه","transcrit","استبدال","قاعده","تايمين","بقاعده","يوراسيل","القطع","الداله"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card3_4","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (4/4)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":4,"total":4,"text":"هذه الظاهرة (النضج/الإزالة) موجودة فقط في الخلايا حقيقية النواة (الإنسان، الحيوان، النبات). في أوليات النواة (البكتيريا) لا يوجد نضج : الترجمة تنطلق على الـ ARNm مباشرة أثناء استنساخه. الفرق بين ARNm الأولي (طويل، به Introns) و ARNm ناضج (أقصر، Exons فقط) سؤال بات في البكالوريا.","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الظاهره","النضج","الازاله","موجوده","الخلايا","حقيقيه","الانسان،","الحيوان،","النبات","اوليات"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card4_1","kind":"html","lessonKey":"lecon_transcription","title":"✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا) : (1/3)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":3,"text":"4 الخلاصة المعتمدة في البكالوريا (الرسم التخطيطي + النص العلمي) ✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا) : مقدمة (طرح الإشكالية) يعتبر الـ ADN الدعامة الجزيئية للمعلومات الوراثية ويتموضع داخل النواة عند حقيقيات النوى، بينما يتم تركيب البروتينات في الهيولى. فكيف تنتقل نسخة من المعلومة الوراثية من النواة إلى الهيولى؟ العرض (مراحل الاستنساخ) تتم عملية الاستنساخ داخل النواة بتدخل إنزيم الـ ARN polymérase وفق ثلاث مراحل متتالية : • مرحلة البداية :","keywords":["النص","العلمي","النموذجي","معايير","تنقيط","المصحح","البكالوريا","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الخلاصه","المعتمده","الرسم"],"aliases":["✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا)"]},{"id":"lhx_lecon_transcription_card4_2","kind":"html","lessonKey":"lecon_transcription","title":"✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا) : (2/3)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":2,"total":3,"text":"يرتبط إنزيم الـ ARN polymérase بـ منطقة البداية للمورثة، فيقوم بفتح سلسلتي الـ ADN بعد تكسير الروابط الهيدروجينية، ويبدأ بدمج النكليوتيدات الريبية الحرة. • مرحلة الاستطالة : ينتقل الإنزيم على طول السلسلة المستنسخة ( 3'→5' )، ويستمر في ربط النكليوتيدات الريبية وفق مبدأ التكامل ( A يقابلها U ، و C يقابلها G )، فتستطيل جزيئة الـ ARNm . • مرحلة النهاية : يصل الإنزيم إلى تسلسل النهاية ، فينفصل عن الـ ADN ، وتتحرر جزيئة الـ ARNm المتشكلة، وتلتحم سلسلتا الـ ADN من جديد.","keywords":["النص","العلمي","النموذجي","معايير","تنقيط","المصحح","البكالوريا","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","يرتبط","polym","منطقه"],"aliases":["✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا)"]},{"id":"lhx_lecon_transcription_card4_3","kind":"html","lessonKey":"lecon_transcription","title":"✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا) : (3/3)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":3,"total":3,"text":"خاتمة (الإجابة عن الإشكالية) يؤدي الاستنساخ إلى تشكل الـ ARNm الذي يغادر النواة عبر الثقوب النووية نحو الهيولى ليكون قالبًا لتركيب البروتين الخاص.","keywords":["النص","العلمي","النموذجي","معايير","تنقيط","المصحح","البكالوريا","الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","خاتمه","الاجابه","الاستنساخ"],"aliases":["✍️ النص العلمي النموذجي (معايير تنقيط المصحح في البكالوريا)"]},{"id":"lhx_lecon_transcription_card5_1","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (1/2)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 حدّد مقر وآلية استنساخ جزيئة الـ ARNm انطلاقاً من الـ ADN. يجري الاستنساخ في النواة انطلاقاً من إحدى سلسلتي الـ ADN (السلسلة المستنسخة). يحتاج الاستنساخ إلى إنزيم ARN بوليميراز وإلى نيوكليوتيدات ثلاثية الفوسفات (ATP, GTP, CTP, UTP). يقرأ الإنزيم السلسلة باتجاه 3'→5' ويركب الـ ARNm باتجاه 5'→3' وفق مبدأ التكامل (A-U, T-A, G-C). ينطلق الاستنساخ عند المنطلق (Promoteur) ويتوقف عند رامزة النهاية. يخرج الـ ARNm الناضج إلى الهيولى ليتوجه إلى الريبوزوم حيث الترجمة. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","خلاصه","واليه","جزييه","انطلاقا","الاستنساخ","سلسلتي","المستنسخه","يحتاج","بوليميراز","نيوكليوتيدات"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card5_2","kind":"html","lessonKey":"lecon_transcription","title":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (2/2)","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":2,"total":2,"text":"استنساخ المعلومات الوراثية (Transcription)","keywords":["الدرس","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","transcription"],"aliases":["الدرس 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lhx_lecon_transcription_card6_1","kind":"html","lessonKey":"lecon_transcription","title":"1. ما هو الإنزيم المسؤول حصريا عن عملية استنساخ الـ ARNm ؟","lessonTitle":"الدرس 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":1,"text":"5 التقويم الذاتي الفوري (اختبر استيعابك دون مساعدة) 1. ما هو الإنزيم المسؤول حصريا عن عملية استنساخ الـ ARNm ؟ أ) إنزيم ADN Polymérase ب) إنزيم ARN Polymérase ج) إنزيم الهيليكاز ( Hélicase ) 2. إذا كانت قطعة من السلسلة غير المستنسخة للـ ADN تحمل التسلسل 5'- ATG CGC -3' ، فإن تسلسل الـ ARNm الموافق هو: أ) 5'- UAC GCG -3' ب) 5'- AUG CGC -3' ج) 5'- TAC GCG -3'","keywords":["الانزيم","المسوول","حصريا","عمليه","استنساخ","arnm","الدرس","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","التقويم","الفوري","اختبر","استيعابك","مساعده"],"aliases":["1. ما هو الإنزيم المسؤول حصريا عن عملية استنساخ الـ ARNm ؟"]},{"id":"lhx_phase2_chapitres_3_4_intro_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"الدرس 4 : مراحل الترجمة","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 1 : تركيب البروتين 🎯 الهدف العلمي : حدّد المراحل الثلاث للترجمة (البداية، الاستطالة، النهاية) ودور متعدد الريبوزوم في تضخيم التصنيع. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : ميّز بدقة بين المستويات الأربعة (أولية، ثانوية، ثالثية، رابعية) وحدّد الروابط الأربعة المسؤولة عن استقرار البنية الثلاثية. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","مراحل","الترجمه","الاول","التخصص","للبروتينات","المراحل","الثلاث","للترجمه","البدايه،","الاستطاله،","النهايه","متعدد","الريبوزوم","تضخيم","التصنيع","المستويات","الاربعه"],"aliases":["الدرس 4","مراحل الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card1_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"الدرس 4 : مراحل الترجمة","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف يتحول الـ ARNm إلى سلسلة بيبتيدية في أجزاء من الثانية؟ بعد وصول الـ ARNm إلى الهيولى، وتنشيط الأحماض الأمينية بارتباطها مع جزيئات الـ ARNt ، تتدخل عضيات دقيقة تسمى الريبوزومات ( Ribosomes ) لقراءة شفرة الـ ARNm وربط الأحماض الأمينية بروابط بيبتيدية. كيف تتم هذه العملية زمنياً ومكانياً داخل الريبوزوم؟ وكيف تضمن الخلية سرعة الإنتاج؟","keywords":["الدرس","مراحل","الترجمه","وضعيه","الانطلاق","وبناء","العلميه","يتحول","سلسله","بيبتيديه","اجزاء","الثانيه؟","الهيولي،","وتنشيط","الاحماض","الامينيه","بارتباطها","تتدخل"],"aliases":["الدرس 4","مراحل الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card2_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"صورة بالمجهر الإلكتروني ورسم تفسيري لمتعدد الريبوزوم أثناء الترجمة (1/2)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":2,"text":"2 التحليل المنهجي لظاهرة متعدد الريبوزوم (البوليزوم - Polysome) صورة بالمجهر الإلكتروني ورسم تفسيري لمتعدد الريبوزوم أثناء الترجمة خيط الـ ARNm (5' → 3') اتجاه حركة الريبوزومات على الـ ARNm ➡️ 🟡 الخيوط الصفراء المتدرجة في الطول تمثل السلاسل البيبتيدية قيد التشكل. منهجية البكالوريا : التفسير والأهمية البيولوجية ما هو متعدد الريبوزوم؟ وما فائدته للخلية؟ التعريف : متعدد الريبوزوم ( Polysome ) هو خيط واحد من الـ ARNm ترتبط به عدة ريبوزومات في نفس الوقت، حيث يقوم كل ريبوزوم بترجمة نفس الرسالة الوراثية.","keywords":["صوره","بالمجهر","الالكتروني","ورسم","تفسيري","لمتعدد","الريبوزوم","اثناء","الترجمه","الدرس","مراحل","لظاهره","متعدد","البوليزوم","polysome","اتجاه","الريبوزومات","الخيوط"],"aliases":["صورة بالمجهر الإلكتروني ورسم تفسيري لمتعدد الريبوزوم أثناء الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card2_2","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"صورة بالمجهر الإلكتروني ورسم تفسيري لمتعدد الريبوزوم أثناء الترجمة (2/2)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":2,"total":2,"text":"الأهمية البيولوجية (سؤال كلاسيكي في البكالوريا) : يسمح متعدد الريبوزوم بتركيب كميات كبيرة جدا من نفس البروتين في مدة زمنية قصيرة جداً ، استجابة لحاجة الخلية والعضوية الفورية.","keywords":["صوره","بالمجهر","الالكتروني","ورسم","تفسيري","لمتعدد","الريبوزوم","اثناء","الترجمه","الدرس","مراحل","الاهميه","البيولوجيه","كلاسيكي","متعدد","بتركيب","كميات","كبيره"],"aliases":["صورة بالمجهر الإلكتروني ورسم تفسيري لمتعدد الريبوزوم أثناء الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card3_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"🔬 اختر مرحلة من المراحل أعلاه لمعاينة تفاصيلها الجزيئية","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":1,"text":"3 المحاكي التفاعلي لخطوات الترجمة داخل الريبوزوم يتكون الريبوزوم من تحت وحدتين (صغرى وكبرى)، ويحتوي على موقعين تحفيزيين : الموقع الببتيدي ( Site P ) والموقع الأميني ( Site A ). اضغط لتنفيذ مراحل الترجمة : 1️⃣ مرحلة البداية (Initiation) 2️⃣ مرحلة الاستطالة (Élongation) 3️⃣ مرحلة النهاية (Terminaison) 🔬 اختر مرحلة من المراحل أعلاه لمعاينة تفاصيلها الجزيئية ستشاهد كيف يتحرك الريبوزوم خطوة بخطوة (بمقدار رامزة واحدة) وكيف تتشكل الرابطة البيبتيدية.","keywords":["اختر","مرحله","المراحل","اعلاه","لمعاينه","تفاصيلها","الجزيييه","الدرس","مراحل","الترجمه","المحاكي","التفاعلي","لخطوات","الريبوزوم","يتكون","وحدتين","وكبري","ويحتوي"],"aliases":["🔬 اختر مرحلة من المراحل أعلاه لمعاينة تفاصيلها الجزيئية"]},{"id":"lhx_phase2_chapitres_3_4_card4_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"ملخص المراحل الثلاث للترجمة (1/2)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":2,"text":"4 الخلاصة والتقويم الذاتي (النشاط 4) ملخص المراحل الثلاث للترجمة • البداية : توضع تحت الوحدة الصغرى على رامزة البداية AUG ، ثم ارتباط المعقد ( ARNt - Méthionine ) في الموقع P ، تليها التحاق تحت الوحدة الكبرى. • الاستطالة : دخول المعقد الثاني إلى الموقع A ، تشكل رابطة ببتيدية بين الميثيونين والحمض الثاني، ثم حركة الريبوزوم برامزة واحدة (انتقال الموقع A إلى P ). • النهاية : وصول الريبوزوم إلى إحدى رامزات التوقف ( UAA, UAG, UGA )، انفصال تحت وحدتي الريبوزوم، وتحرر السلسلة البيبتيدية ثم ينفصل الميثيونين الأول غالبا.","keywords":["ملخص","المراحل","الثلاث","للترجمه","الدرس","مراحل","الترجمه","الخلاصه","والتقويم","البدايه","الصغري","رامزه","ارتباط","المعقد","thionine","تليها","التحاق","الكبري"],"aliases":["ملخص المراحل الثلاث للترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card4_2","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"ملخص المراحل الثلاث للترجمة (2/2)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":2,"total":2,"text":"اختبر فهمك : أين تتشكل الرابطة البيبتيدية أثناء مرحلة الاستطالة في الريبوزوم؟ أ) بين الحمض الأميني المحمول على الـ ARNt في الموقع P والحمض الأميني الجديد في الموقع A . ب) بين تحت الوحدة الصغرى وتحت الوحدة الكبرى للريبوزوم. ج) بين رامزة الـ ARNm والرامزة المضادة للـ ARNt .","keywords":["ملخص","المراحل","الثلاث","للترجمه","الدرس","مراحل","الترجمه","اختبر","تتشكل","الرابطه","البيبتيديه","اثناء","مرحله","الاستطاله","الريبوزوم؟","الحمض","الاميني","المحمول"],"aliases":["ملخص المراحل الثلاث للترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card5_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"الدرس 4 : مراحل الترجمة","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":1,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 5، ص 34) الوحدة: D1-U1 — تركيب البروتين — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. 📌 المخطط التحصيلي لعملية تركيب البروتين كما في الكتاب : ADN (النواة عند حقيقيات النواة) ⬇ استنساخ ARNm ⬇ ترجمة على الريبوزوم (تحت الوحدة الكبرى) ⬇ سلسلة ببتيدية ⬇ بروتين بوظيفة محددة يميز المخطط الرسمي بين موقع الترجمة عند أوليات النواة (في الهيولى) وعند حقيقيات النواة (على الشبكة الهيولية) — تنسيق قرائي لعناصر المخطط دون تغيير مضمونه.","keywords":["الدرس","مراحل","الترجمه","المعرفيه","الرسمي","للكتاب","المدرسي","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي","مقروءا","المخطط","التحصيلي","لعمليه"],"aliases":["الدرس 4","مراحل الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card6_1","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"الدرس 4 : مراحل الترجمة (1/3)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":1,"total":3,"text":"🗺 المخطط الشامل لآليات تركيب البروتين الأصل المُدرج — تحوي طبقة الصورة أخطاء استخراج آلي معروفة (مثلا: «اللواة» بدل «النواة»، «المعلمة الواقعية»)؛ النسخة النصية المصححة أدناه هي المرجع القرائي. حقيقيات النواة (Eukaryotes) ADN داخل النواة (غلاف نووي مسامي) ⬇ استنساخ في النواة ARNm طليعي ⬇ معالجة (حذف القطع غير الدالة Introns) ARNm ناضج ← يخرج عبر المسام النووية ⬇ ترجمة في الهيولى على البوليزوم ⬇ سلسلة ببتيدية المرحلتان في مكانين مختلفين وفي وقتين مختلفين (بفصل الغشاء النووي).","keywords":["الدرس","مراحل","الترجمه","المخطط","الشامل","لاليات","الاصل","المدرج","الصوره","اخطاء","استخراج","معروفه","اللواه","المعلمه","الواقعيه","النسخه","النصيه","المصححه"],"aliases":["الدرس 4","مراحل الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card6_2","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"الدرس 4 : مراحل الترجمة (2/3)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":2,"total":3,"text":"أوليات النواة (Prokaryotes) ADN في الهيولى (بدون نواة محددة الحدود) ⬇ استنساخ في الهيولى ARNm ← ترجمة فورية على الريبوزوم ⬇ سلسلة ببتيدية يمكن للترجمة أن تنطلق قبل انتهاء الاستنساخ : المرحلتان في نفس المكان وفي آن واحد. مراحل التعبير الجيني : ١. الاستنساخ (Transcription) تركيب ARNm انطلاقا من السلسلة المستنسخة للـ ADN بواسطة ARN بوليميراز (انطلاق ← استطالة ← نهاية). ٢. نضج ARNm (Maturation) حذف القطع غير الدالة (Introns) والاحتفاظ بالقطع الدالة (Exons) : ARNm طليعي ← ناضج. ٣.","keywords":["الدرس","مراحل","الترجمه","اوليات","prokaryotes","محدده","الحدود","استنساخ","ترجمه","فوريه","الريبوزوم","سلسله","ببتيديه","للترجمه","تنطلق","انتهاء","الاستنساخ","المرحلتان"],"aliases":["الدرس 4","مراحل الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_card6_3","kind":"html","lessonKey":"phase2_chapitres_3_4","title":"الدرس 4 : مراحل الترجمة (3/3)","lessonTitle":"الدرس 4 : مراحل الترجمة","unitId":1,"part":3,"total":3,"text":"الترجمة (Traduction) انطلاق برامزة AUG في الموقع P، استطالة برابطة ببتيدية، توقف برامزة UAA/UAG/UGA. ٤. نضج وتوجيه البروتين انطواء البروتين واتجاهه إلى مقر وظيفته (داخل/خارج الخلية عبر الشبكة الهيولية الفعالة والحويصلات وجهاز غولجي). 🗺 مخطط مُعاد بناؤه آلياً من النص الرسمي للكتاب (ص 34 + مصير البروتين) — كل مفرداته مثبتة في النص (تحقّق آلي داخلي: 12/12).","keywords":["الدرس","مراحل","الترجمه","traduction","انطلاق","برامزه","استطاله","برابطه","ببتيديه،","وتوجيه","انطواء","واتجاهه","وظيفته","الشبكه","الهيوليه","الفعاله","والحويصلات","وجهاز"],"aliases":["الدرس 4","مراحل الترجمة"]},{"id":"lhx_phase2_chapitres_3_4_2_intro_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 1 : تركيب البروتين 🎯 الهدف العلمي : حدّد المراحل الثلاث للترجمة (البداية، الاستطالة، النهاية) ودور متعدد الريبوزوم في تضخيم التصنيع. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : ميّز بدقة بين المستويات الأربعة (أولية، ثانوية، ثالثية، رابعية) وحدّد الروابط الأربعة المسؤولة عن استقرار البنية الثلاثية. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","الاول","التخصص","للبروتينات","المراحل","الثلاث","للترجمه","البدايه،","الاستطاله،","النهايه","متعدد","الريبوزوم"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card1_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":1,"text":"1 الإشكالية الأساسية للوحدة الثانية ⚠️ لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟ بعد انتهاء الترجمة، لا تبقى السلسلة البيبتيدية كخيط مستقيم طويل، بل تلتف وتنطوي بشكل ثلاثي الأبعاد دقيق ومحدد وراثيا يسمى البنية الفراغية ( Structure spatiale ) . ما هي المستويات المتدرجة لهذه البنية؟ وما هي الروابط الكيميائية التي تحافظ على استقرارها وتمنحها التخصص الوظيفي؟","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","الاساسيه","للوحده","الثانيه","انتهاء","الترجمه،","البيبتيديه","مستقيم","طويل،","وتنطوي","ثلاثي","الابعاد"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card2_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"1️⃣ البنية الأولية ( Structure Primaire )","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":1,"text":"2 المختبر الافتراضي لمستويات البنية الفراغية الأربعة اضغط على المستوى الفراغي لمعاينة خصائصه الهندسية والروابط المساهمة فيه : 1️⃣ البنية الأولية (Primaire) 2️⃣ البنية الثانوية (Secondaire) 3️⃣ البنية الثالثية (Tertiaire) 4️⃣ البنية الرابعية (Quaternaire) 1️⃣ البنية الأولية ( Structure Primaire ) هي تسلسل خطي بسيط للأحماض الأمينية المرتبطة ببعضها البعض بواسطة روابط ببتيدية ( Liaisons peptidiques التكافؤية قوية ) فقط. لا تمتلك البنية الأولية أي التفاف أو وظيفة بيولوجية فعالة.","keywords":["البنيه","الاوليه","structure","primaire","لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","المختبر","الافتراضي","لمستويات","الفراغيه","الاربعه","المستوي","الفراغي"],"aliases":["1️⃣ البنية الأولية ( Structure Primaire )"]},{"id":"lhx_phase2_chapitres_3_4_2_card3_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"تصنيف الروابط حسب القوة والنوعية (1/2)","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":2,"text":"3 الروابط الكيميائية الأربعة المسؤولة عن استقرار البنية الثالثية تستقر البنية الثالثية بفضل نشأة روابط كيميائية بين الجذور الحرة ( Radicaux R ) للأحماض الأمينية المحددة وراثياً : تصنيف الروابط حسب القوة والنوعية 🔒 جسور ثنائية الكبريت ( Ponts disulfures ) : رابطة تكافؤية قوية جداً تنشأ بين جذري حمضين من السيستيين ( Cys - Cys ). ⚡ روابط شاردية الأيونية ( Liaisons ioniques ) : تجاذب كهربائي بين جذر سالب (حامضي) وجذر موجب (قاعدي). 💧 تجاذب الجذور الكارهة للماء ( Interactions hydrophobes ) :","keywords":["تصنيف","الروابط","حسب","القوه","والنوعيه","لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","الكيمياييه","الاربعه","المسووله","استقرار","الثالثيه","تستقر"],"aliases":["تصنيف الروابط حسب القوة والنوعية"]},{"id":"lhx_phase2_chapitres_3_4_2_card3_2","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"تصنيف الروابط حسب القوة والنوعية (2/2)","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":2,"total":2,"text":"تجمع الجذور غير القطبية نحو الداخل بعيداً عن الماء. 🧲 روابط هيدروجينية ( Liaisons hydrogènes ) : روابط ضعيفة بين ذرات ذات كهروسلبية مختلفة ( H ... O ). قاعدة ذهبية في أسئلة البكالوريا تتوقف وظيفة البروتين على بنيته الفراغية الثلاثية أو الرابعية ، وهذه الأخيرة تتوقف على عدد ونوع وترتيب الأحماض الأمينية (البنية الأولية) التي تحدد مواضع الروابط الكيميائية بدقة. أي تغير في تسلسل الأحماض الأمينية (طفرة) يؤدي إلى تغير أماكن الروابط، وبالتالي تخريب البنية الفراغية وفقدان الوظيفة.","keywords":["تصنيف","الروابط","حسب","القوه","والنوعيه","لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","الجذور","القطبيه","الداخل","بعيدا","روابط","هيدروجينيه"],"aliases":["تصنيف الروابط حسب القوة والنوعية"]},{"id":"lhx_phase2_chapitres_3_4_2_card4_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر المراحل الثلاث للترجمة على مستوى متعدد الريبوزومات. تجري الترجمة على الريبوزومات المجتمعة في متعدد ريبوزومات يترجم ARNm واحداً. تبدأ مرحلة البداية برامزة AUG وارتباط ARNt-ميثيونين في الموقع P. تتشكل الرابطة الببتيدية أثناء الاستطالة ويتقدم الريبوزوم رامزة بعد رامزة. تتوقف الترجمة عند رامزة توقف فتتحرر السلسلة الببتيدية من الريبوزوم. يسمح متعدد الريبوزومات بتركيب عدة نسخ من البروتين في الوقت نفسه. 🔑 المصطلح المفتاحي في البكالوريا : المراحل الثلاث للترجمة / متعدد الريبوزومات","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","خلاصه","الدرس","المراحل","الثلاث","للترجمه","متعدد","الريبوزومات","الترجمه","المجتمعه","ريبوزومات","يترجم"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card5_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"1. ما هو الفرق الأساسي الذي يميز البنية الرابعية عن البنية الثالثية؟","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. ما هو الفرق الأساسي الذي يميز البنية الرابعية عن البنية الثالثية؟ أ) البنية الرابعية تتكون من تجمع تحت وحدتين أو أكثر (سلسلتين بيبتيديتين أو أكثر ذوات بنية ثالثية). ب) البنية الرابعية لا تحتوي على أي روابط بيبتيدية. ج) البنية الرابعية تتواجد داخل النواة فقط. 2. ما هي الرابطة التكافؤية (القوية جداً) الوحيدة التي تساهم في استقرار البنية الثالثية؟ أ) الرابطة الهيدروجينية. ب) الرابطة الشاردية الأيونية. ج) الجسر ثنائي الكبريت ( Pont disulfure ).","keywords":["الفرق","الاساسي","الذي","يميز","البنيه","الرابعيه","الثالثيه؟","لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","تتكون","وحدتين","سلسلتين","بيبتيديتين"],"aliases":["1. ما هو الفرق الأساسي الذي يميز البنية الرابعية عن البنية الثالثية؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card6_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":1,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 5، ص 34) الوحدة: D1-U1 — تركيب البروتين — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. 📌 المخطط التحصيلي لعملية تركيب البروتين كما في الكتاب : ADN (النواة عند حقيقيات النواة) ⬇ استنساخ ARNm ⬇ ترجمة على الريبوزوم (تحت الوحدة الكبرى) ⬇ سلسلة ببتيدية ⬇ بروتين بوظيفة محددة يميز المخطط الرسمي بين موقع الترجمة عند أوليات النواة (في الهيولى) وعند حقيقيات النواة (على الشبكة الهيولية) — تنسيق قرائي لعناصر المخطط دون تغيير مضمونه.","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","المعرفيه","الرسمي","للكتاب","المدرسي","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card7_1","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟ (1/3)","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":1,"total":3,"text":"🗺 المخطط الشامل لآليات تركيب البروتين الأصل المُدرج — تحوي طبقة الصورة أخطاء استخراج آلي معروفة (مثلا: «اللواة» بدل «النواة»، «المعلمة الواقعية»)؛ النسخة النصية المصححة أدناه هي المرجع القرائي. حقيقيات النواة (Eukaryotes) ADN داخل النواة (غلاف نووي مسامي) ⬇ استنساخ في النواة ARNm طليعي ⬇ معالجة (حذف القطع غير الدالة Introns) ARNm ناضج ← يخرج عبر المسام النووية ⬇ ترجمة في الهيولى على البوليزوم ⬇ سلسلة ببتيدية المرحلتان في مكانين مختلفين وفي وقتين مختلفين (بفصل الغشاء النووي).","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","المخطط","الشامل","لاليات","الاصل","المدرج","الصوره","اخطاء","استخراج","معروفه","اللواه","المعلمه"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card7_2","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟ (2/3)","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":2,"total":3,"text":"أوليات النواة (Prokaryotes) ADN في الهيولى (بدون نواة محددة الحدود) ⬇ استنساخ في الهيولى ARNm ← ترجمة فورية على الريبوزوم ⬇ سلسلة ببتيدية يمكن للترجمة أن تنطلق قبل انتهاء الاستنساخ : المرحلتان في نفس المكان وفي آن واحد. مراحل التعبير الجيني : ١. الاستنساخ (Transcription) تركيب ARNm انطلاقا من السلسلة المستنسخة للـ ADN بواسطة ARN بوليميراز (انطلاق ← استطالة ← نهاية). ٢. نضج ARNm (Maturation) حذف القطع غير الدالة (Introns) والاحتفاظ بالقطع الدالة (Exons) : ARNm طليعي ← ناضج. ٣.","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","اوليات","prokaryotes","محدده","الحدود","استنساخ","ترجمه","فوريه","الريبوزوم","سلسله","ببتيديه","للترجمه"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_phase2_chapitres_3_4_2_card7_3","kind":"html","lessonKey":"phase2_chapitres_3_4_2","title":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟ (3/3)","lessonTitle":"لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟","unitId":1,"part":3,"total":3,"text":"الترجمة (Traduction) انطلاق برامزة AUG في الموقع P، استطالة برابطة ببتيدية، توقف برامزة UAA/UAG/UGA. ٤. نضج وتوجيه البروتين انطواء البروتين واتجاهه إلى مقر وظيفته (داخل/خارج الخلية عبر الشبكة الهيولية الفعالة والحويصلات وجهاز غولجي). 🗺 مخطط مُعاد بناؤه آلياً من النص الرسمي للكتاب (ص 34 + مصير البروتين) — كل مفرداته مثبتة في النص (تحقّق آلي داخلي: 12/12).","keywords":["لماذا","يفقد","البروتين","وظيفته","اذا","تغيرت","شكله؟","الترجمه","traduction","انطلاق","برامزه","استطاله","برابطه","ببتيديه،","وتوجيه","انطواء","واتجاهه","الشبكه"],"aliases":["لماذا يفقد البروتين وظيفته إذا تغيرت شكله؟"]},{"id":"lhx_lecon_representation_intro_1","kind":"html","lessonKey":"lecon_representation","title":"الدرس 1 : تمثيل البنية الفراغية للبروتين","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة الثانية : العلاقة بين بنية ووظيفة البروتين 🎯 الهدف العلمي : وميّز بين نماذج راستوب الثلاثة وحدّد النموذج المناسب للسؤال المطروح في البكالوريا. ⏱️ المدة التقديرية للتعلم الذاتي : 20 دقيقة","keywords":["الدرس","تمثيل","البنيه","الفراغيه","للبروتين","الاول","التخصص","للبروتينات","الثانيه","العلاقه","ووظيفه","نماذج","راستوب","الثلاثه","النموذج","المناسب","للسوال","المطروح"],"aliases":["الدرس 1","تمثيل البنية الفراغية للبروتين"]},{"id":"lhx_lecon_representation_card1_1","kind":"html","lessonKey":"lecon_representation","title":"الدرس 1 : تمثيل البنية الفراغية للبروتين","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلمية ⚠️ ثلاث صور مختلفة لجزيء واحد، فأيها البنية الحقيقية؟ عرض برنامج Rastop نفس جزيء الليزوزيم بثلاث صور مختلفة تماما : كومة من الكرات الملونة، وتشابك من العيدان، وشريط ملتف. علما أن الجزيء واحد لا يتغير، فكيف نفسر هذا الاختلاف؟ وأي صورة نعتمد للإجابة عن أسئلة البكالوريا؟ لحل هذه الإشكالية، يجب أن نفهم أن صور راستوب ليست صورا فوتوغرافية، بل نماذج (Modèles) : كل نموذج يُظهر جانبا من البنية ويُخفي جوانب أخرى، ويُختار حسب السؤال المطروح.","keywords":["الدرس","تمثيل","البنيه","الفراغيه","للبروتين","وضعيه","الانطلاق","وبناء","العلميه","مختلفه","لجزيء","واحد،","فايها","الحقيقيه؟","برنامج","rastop","الليزوزيم","بثلاث"],"aliases":["الدرس 1","تمثيل البنية الفراغية للبروتين"]},{"id":"lhx_lecon_representation_card2_1","kind":"html","lessonKey":"lecon_representation","title":"نموذج الكرات : كل ذرة كرة بحجمها الحقيقي (1/3)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":3,"text":"2 التحليل المنهجي لوثيقتي النمذجة (ماذا يُظهر كل نموذج؟) 🧪 نموذج الكرات المكدسة 🔬 النموذج الشريطي نموذج الكرات : كل ذرة كرة بحجمها الحقيقي كل كرة = ذرة (C ،O ،N ،S) بحجم فان دير فالس 🔵 يُظهر الحجم الحقيقي والتكامل السطحي بين تحت الوحدات، ولا يُظهر ما بداخل الجزيء. منهجية البكالوريا : تحليل وثيقة 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 📷 صورة · صِف ما يُرى (كرات متلاصقة) قبل الاستنتاج ماذا نستخرج من نموذج الكرات؟ 1. التعريف بالوثيقة :","keywords":["نموذج","الكرات","ذره","كره","بحجمها","الحقيقي","الدرس","تمثيل","البنيه","الفراغيه","للبروتين","لوثيقتي","النمذجه","نموذج؟","المكدسه","النموذج","الشريطي","الحجم"],"aliases":["نموذج الكرات","كل ذرة كرة بحجمها الحقيقي"]},{"id":"lhx_lecon_representation_card2_2","kind":"html","lessonKey":"lecon_representation","title":"نموذج الكرات : كل ذرة كرة بحجمها الحقيقي (2/3)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":2,"total":3,"text":"تمثيل كروي مكدس لجزيء بروتيني حيث تُمثل كل ذرة بكرة بنصف قطرها الحقيقي. 2. الملاحظة : لا فراغات بين الكرات، والسطح الخارجي أملس متصل، ولا تظهر أي لولبيات أو أوراق. 3. الاستنتاج : هذا النموذج يُظهر الحجم الحقيقي والتجمع الرباعي للبروتين، لكنه يُخفي البنيات الثانوية والروابط الداخلية . النموذج الشريطي : مسار السلسلة الببتيدية فقط لولب α ورقة β الشريط يتبع العمود الفقري للسلسلة ويُخفي الذرات 🟠 البرتقالي = لوالب α · 🔵 الأسهم = أوراق β · 🟢 = منعطفات. منهجية البكالوريا : استخراج المعلومات من الشكل 🔑 مفتاح المنهجية:","keywords":["نموذج","الكرات","ذره","كره","بحجمها","الحقيقي","الدرس","تمثيل","البنيه","الفراغيه","للبروتين","لجزيء","بروتيني","قطرها","الملاحظه","فراغات","الكرات،","والسطح"],"aliases":["نموذج الكرات","كل ذرة كرة بحجمها الحقيقي"]},{"id":"lhx_lecon_representation_card2_3","kind":"html","lessonKey":"lecon_representation","title":"نموذج الكرات : كل ذرة كرة بحجمها الحقيقي (3/3)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":3,"total":3,"text":"البوابة 1 → 📄 ورقة · البوابة 2 → 📷 صورة · عُد اللوالب والأسهم قبل المقارنة متى نختار النموذج الشريطي؟ عندما يسأل الموضوع عن المقارنة بين بنيتين (طبيعي/طافر) أو عن أثر طفرة على الطي ، لأن الشريطي وحده يُظهر اللوالب والأوراق والمنعطفات، أي مستوى البنية الثانوية والثالثية .","keywords":["نموذج","الكرات","ذره","كره","بحجمها","الحقيقي","الدرس","تمثيل","البنيه","الفراغيه","للبروتين","البوابه","اللوالب","والاسهم","المقارنه","نختار","النموذج","الشريطي؟"],"aliases":["نموذج الكرات","كل ذرة كرة بحجمها الحقيقي"]},{"id":"lhx_lecon_representation_card3_1","kind":"html","lessonKey":"lecon_representation","title":"الدرس 1 : تمثيل البنية الفراغية للبروتين (1/2)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":2,"text":"3 دليل اختيار النموذج (النموذج الثالث : العيدان) 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 🎬 فيلم · لأنّ السؤال يحدد النموذج لا الجزيء يُظهر نموذج العيدان والكرات (Bâtonnets) كل ذرة وكل رابطة كيميائية، لذلك يُستعمل لدراسة تفاصيل الموقع الفعال : الأحماض الأمينية المتقاربة فراغيا والروابط بين جذورها. جدول الاختيار المعتمد في التصحيح : سؤال مقارنة / طفرة ← الشريطي | سؤال موقع فعال / روابط ← العيدان | سؤال حجم / تجمع ← الكرات 💡 خطأ شائع في البكالوريا : الخلط بين النموذج والبنية!","keywords":["الدرس","تمثيل","البنيه","الفراغيه","للبروتين","اختيار","النموذج","الثالث","العيدان","مفتاح","المنهجيه","البوابه","السوال","الجزيء","نموذج","والكرات","tonnets","رابطه"],"aliases":["الدرس 1","تمثيل البنية الفراغية للبروتين"]},{"id":"lhx_lecon_representation_card3_2","kind":"html","lessonKey":"lecon_representation","title":"الدرس 1 : تمثيل البنية الفراغية للبروتين (2/2)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":2,"total":2,"text":"تغير النموذج لا يغير الجزيء : نفس البروتين بثلاث صور، والمعلومة المستخرجة تتوقف على النموذج المختار. اذكر دائما ماذا يُظهر النموذج وماذا يُخفي قبل أي استنتاج.","keywords":["الدرس","تمثيل","البنيه","الفراغيه","للبروتين","النموذج","الجزيء","بثلاث","والمعلومه","المستخرجه","تتوقف","المختار","دايما","وماذا","استنتاج"],"aliases":["الدرس 1","تمثيل البنية الفراغية للبروتين"]},{"id":"lhx_lecon_representation_card4_1","kind":"html","lessonKey":"lecon_representation","title":"✍️ النص العلمي النموذجي : (1/2)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":2,"text":"4 الخلاصة المعتمدة في البكالوريا (الرسم التخطيطي + النص العلمي) ✍️ النص العلمي النموذجي : مقدمة (طرح الإشكالية) يأخذ كل بروتين بنية فراغية محددة تحدد وظيفته، ويعرض برنامج Rastop هذه البنية بعدة نماذج مختلفة لنفس الجزيء، فأي نموذج نعتمد؟ العرض (النماذج الثلاثة) • نموذج الكرات المكدسة : يُظهر الحجم الحقيقي والتجمع الرباعي والتكامل السطحي، ويُخفي البنيات الداخلية. • النموذج الشريطي : يُظهر اللوالب α والأوراق β والمنعطفات، ويُستعمل للمقارنة وكشف أثر الطفرات على الطي. • نموذج العيدان : يُظهر الذرات والروابط بتفصيل،","keywords":["النص","العلمي","النموذجي","الدرس","تمثيل","البنيه","الفراغيه","للبروتين","الخلاصه","المعتمده","الرسم","التخطيطي","مقدمه","بروتين","فراغيه","محدده","وظيفته،","ويعرض"],"aliases":["✍️ النص العلمي النموذجي"]},{"id":"lhx_lecon_representation_card4_2","kind":"html","lessonKey":"lecon_representation","title":"✍️ النص العلمي النموذجي : (2/2)","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":2,"total":2,"text":"ويُستعمل لدراسة الموقع الفعال. خاتمة (الإجابة عن الإشكالية) لا توجد صورة واحدة حقيقية والباقي خاطئ : النماذج متكاملة، ويُختار النموذج حسب السؤال المطروح في الموضوع.","keywords":["النص","العلمي","النموذجي","الدرس","تمثيل","البنيه","الفراغيه","للبروتين","ويستعمل","لدراسه","خاتمه","الاجابه","واحده","حقيقيه","والباقي","النماذج","متكامله،","ويختار"],"aliases":["✍️ النص العلمي النموذجي"]},{"id":"lhx_lecon_representation_card5_1","kind":"html","lessonKey":"lecon_representation","title":"الدرس 1 : تمثيل البنية الفراغية للبروتين","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 اختر النموذج الجزيئي الموافق لتمثيل البنية الفراغية للبروتين. يعطي نموذج الكرات صورة فراغية كاملة يظهر فيها كل ذرة بحجمها الحقيقي. يظهر النموذج الشريطي مسار السلسلة الببتيدية والبنى الثانوية فقط. تكشف النماذج الثلاثة الروابط المساهمة في استقرار البنية ثلاثية الأبعاد. يسمح النموذج الشريطي بإبراز موضع استبدال حمض أميني وأثره على البنية. ينتقى النموذج الموافق للسؤال المطروح: الفراغ الكامل أو المسار أو البنى. 🔑 المصطلح المفتاحي في البكالوريا : النماذج الجزيئية للبنية الفراغية","keywords":["الدرس","تمثيل","البنيه","الفراغيه","للبروتين","خلاصه","النموذج","الجزييي","الموافق","لتمثيل","نموذج","الكرات","فراغيه","كامله","بحجمها","الحقيقي","الشريطي","الببتيديه"],"aliases":["الدرس 1","تمثيل البنية الفراغية للبروتين"]},{"id":"lhx_lecon_representation_card6_1","kind":"html","lessonKey":"lecon_representation","title":"1. ماذا يُظهر النموذج الشريطي للبروتين؟","lessonTitle":"الدرس 1 : تمثيل البنية الفراغية للبروتين","unitId":2,"part":1,"total":1,"text":"5 التقويم الذاتي الفوري (اختبر استيعابك دون مساعدة) 1. ماذا يُظهر النموذج الشريطي للبروتين؟ أ) البنيات الثانوية (لوالب α وأوراق β) والمنعطفات ومسار السلسلة ب) كل ذرة على حدة بحجمها الحقيقي ج) تتابع النكليوتيدات في المورثة 2. لإظهار أثر استبدال حمض الغلوتاميك بالفالين في الهيموغلوبين (المنجلي)، أي نموذج نختار؟ أ) النموذج الشريطي، لأنه يكشف تغير الطي الفراغي للسلسلة ب) نموذج الكرات، لأنه يُظهر عدد الذرات ج) لا نحتاج أي نموذج، تكفي الصيغة الجزيئية","keywords":["ماذا","يظهر","النموذج","الشريطي","للبروتين؟","الدرس","تمثيل","البنيه","الفراغيه","للبروتين","التقويم","الفوري","اختبر","استيعابك","مساعده","البنيات","الثانويه","لوالب"],"aliases":["1. ماذا يُظهر النموذج الشريطي للبروتين؟"]},{"id":"lhx_phase3_chapitres_5_6_intro_1","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 2 : العلاقة بين بنية ووظيفة البروتين 🎯 الهدف العلمي : بيّن تجريبي أن تخصص البروتين متوقف على بنيته الفراغية (تجربة أنفنصن Anfinsen)، وفسّر الأمراض الوراثية (مثل فقر الدم المنجلي) على المستوى الجزيئي. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : عرّف الإنزيم كوسيط حيوي، ووضّح الخصوصية المزدوجة (تخصص مادة التفاعل وتخصص نوع التفاعل) ونموذج التوافق المحرض. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","الاول","التخصص","للبروتينات","تجريبي","متوقف","بنيته","الفراغيه","تجربه","انفنصن","anfinsen","الامراض","الوراثيه"],"aliases":["الدرس 3","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lhx_phase3_chapitres_5_6_card1_1","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف يؤدي تغير حمض أميني واحد إلى مرض قاتل؟ في مرض فقر الدم المنجلي ( Drépanocytose )، تتحول كريات الدم الحمراء من الشكل القرصي المرن إلى شكل منجلي صلب، مما يسبب انسداد الأوعية الدموية واختناق الخلايا. السبب هو استبدال حمض أميني واحد فقط (الغلوتاميك Glu بالفالين Val ) في السلسلة البيبتيدية للهيموغلوبين! كيف يفسر هذا على ضوء العلاقة بين البنية الفراغية والوظيفة؟","keywords":["الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","وضعيه","الانطلاق","وبناء","العلميه","اميني","قاتل؟","المنجلي","panocytose","تتحول","كريات","الحمراء","الشكل"],"aliases":["الدرس 3","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lhx_phase3_chapitres_5_6_card2_1","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"خطوات تجربة أنفنصن على إنزيم الريبونكلياز (Ribonucléase) ذو 4 جسور ثنائية الكبريت (1/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":2,"text":"2 التحليل المنهجي للتجربة التاريخية للكرياتين أنفنصن (Anfinsen) على الريبونكلياز خطوات تجربة أنفنصن على إنزيم الريبونكلياز (Ribonucléase) ذو 4 جسور ثنائية الكبريت 1. بنية طبيعية فعالة (100%) + يوريا و β-مركابتوإيثانول 2. فقدان البنية والفعالية (0%) إزالة المواد الكيميائية 3. استرجاع البنية والفعالية (100%) 🧪 مادة اليوريا تعيق الروابط الهيدروجينية، و β-مركابتوإيثانول يكسر الجسور ثنائية الكبريت. منهجية البكالوريا : الاستنتاج من خطوات التجربة ماذا نستنتج من تجربة أنفنصن الحائزة على نوبل؟ 1.","keywords":["خطوات","تجربه","انفنصن","علي","انزيم","الريبونكلياز","ribonucl","ase","جسور","ثناييه","الكبريت","الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","للتجربه"],"aliases":["خطوات تجربة أنفنصن على إنزيم الريبونكلياز (Ribonucléase) ذو 4 جسور ثنائية الكبريت"]},{"id":"lhx_phase3_chapitres_5_6_card2_2","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"خطوات تجربة أنفنصن على إنزيم الريبونكلياز (Ribonucléase) ذو 4 جسور ثنائية الكبريت (2/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":2,"total":2,"text":"تكسير الروابط الكيميائية (تخريب البنية الفراغية) يؤدي مباشرة إلى فقدان الوظيفة البيولوجية للبروتين. 2. إزالة عوامل التخريب تسمح للبروتين بالانطواء التلقائي الصحيح واسترجاع بنيته وفعاليته. الاستنتاج الذهبي في البكالوريا : البنية الفراغية الثلاثية للبروتين محددة ومفروضة وراثياً بعدد ونوع وترتيب الأحماض الأمينية التي تشكل السلسلة البيبتيدية (البنية الأولية).","keywords":["خطوات","تجربه","انفنصن","علي","انزيم","الريبونكلياز","ribonucl","ase","جسور","ثناييه","الكبريت","الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","تكسير"],"aliases":["خطوات تجربة أنفنصن على إنزيم الريبونكلياز (Ribonucléase) ذو 4 جسور ثنائية الكبريت"]},{"id":"lhx_phase3_chapitres_5_6_card3_1","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"🟢 الهيموغلوبين الطبيعي (HbA) (1/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":2,"text":"3 محاكي الطفرات الوراثية وتأثيرها على بروتين الهيموغلوبين (HbA مقابل HbS) تحدد المورثة ( ADN ) تسلسل الأحماض الأمينية في البروتين. اضغط لإحداث طفرة استبدال وملاحظة النتيجة الجزيئية والخلويـة : 🟢 الحالة الطبيعية (الهيموغلوبين HbA) 🔴 طفرة مرض فقر الدم المنجلي (الهيموغلوبين HbS) 🟢 الهيموغلوبين الطبيعي (HbA) Codons : 5'- ... - CCU - GAG - GAG - ... -3' Acides aminés : ... - Pro(4) - Glu(6) - Glu(7) - ... الحمض الأميني رقم 6 هو حمض الغلوتاميك ( Glu المحب للماء) .","keywords":["الهيموغلوبين","الطبيعي","hba","الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","محاكي","الطفرات","الوراثيه","وتاثيرها","بروتين","مقابل","المورثه","تسلسل","الاحماض"],"aliases":["🟢 الهيموغلوبين الطبيعي (HbA)"]},{"id":"lhx_phase3_chapitres_5_6_card3_2","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"🟢 الهيموغلوبين الطبيعي (HbA) (2/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":2,"total":2,"text":"يبقى جزيء الهيموغلوبين ذائباً ومنفصلاً في هيولى كرية الدم الحمراء، فتحتفظ الكرية بشكلها القرصي المرن القادر على نقل الأكسجين والمرور بسلاسة في الشعيرات الدموية.","keywords":["الهيموغلوبين","الطبيعي","hba","الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","ذايبا","ومنفصلا","هيولي","الحمراء،","فتحتفظ","الكريه","بشكلها","القرصي","المرن"],"aliases":["🟢 الهيموغلوبين الطبيعي (HbA)"]},{"id":"lhx_phase3_chapitres_5_6_card4_1","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"الخلاصة الشاملة للوحدة الثانية (تنقيط البكالوريا) (1/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":2,"text":"4 الخلاصة والتقويم الذاتي (النشاط 3) الخلاصة الشاملة للوحدة الثانية (تنقيط البكالوريا) تتوقف التخصص الوظيفي للبروتين على بنيته الفراغية الدقيقة ، والتي تتحدد وراثياً بتسلسل الأحماض الأمينية في سلسلته البيبتيدية. تنشأ روابط كيميائية دقيقة في مواضع محددة للحفاظ على استقرار هذه البنية. أي تغير وراثي (طفرة) قد يغير حمضاً أمينياً أو أكثر، مما يغير مواضع الروابط فيؤدي إلى تغير البنية الفراغية وبالتالي فقدان الوظيفة والإصابة بالمرض. اختبر فهمك :","keywords":["الخلاصه","الشامله","للوحده","الثانيه","تنقيط","البكالوريا","الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","والتقويم","تتوقف","التخصص","للبروتين","بنيته","الفراغيه"],"aliases":["الخلاصة الشاملة للوحدة الثانية (تنقيط البكالوريا)"]},{"id":"lhx_phase3_chapitres_5_6_card4_2","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"الخلاصة الشاملة للوحدة الثانية (تنقيط البكالوريا) (2/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":2,"total":2,"text":"لماذا تسبب طفرة استبدال (الغلوتاميك بالفالين) في الموضع 6 لمرض فقر الدم المنجلي؟ أ) لأن الفالين ( Val ) كاره للماء، فيؤدي لتجمع وتراص جزيئات الهيموغلوبين في ألياف صلبة تشوه كرية الدم. ب) لأن الفالين يمنع حدوث عملية الاستنساخ داخل النواة. ج) لأن الفالين يكسر جميع الجسور ثنائية الكبريت في الريبوزوم.","keywords":["الخلاصه","الشامله","للوحده","الثانيه","تنقيط","البكالوريا","الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","استبدال","الغلوتاميك","بالفالين","الموضع","المنجلي؟","الفالين"],"aliases":["الخلاصة الشاملة للوحدة الثانية (تنقيط البكالوريا)"]},{"id":"lhx_phase3_chapitres_5_6_card5_1","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين (1/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 8، ص 152) الوحدة: D1-U2 — بنية البروتين ووظيفته — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. ترتبط الأحماض الأمينية المتتالية في السلسلة الببتيدية بروابط تكافؤية تدعى الروابط الببتيدية ، وتنشأ من تفاعل مجموعة الكربوكسيل (COOH) لحمض أميني مع مجموعة الأمين (NH2) لحمض أميني آخر مع خروج جزيئة ماء. تحوي السلسلة الببتيدية مهما كان طولها طرفاً أمينياً في البداية وطرفاً كربوكسيلياً في النهاية،","keywords":["الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","المعرفيه","الرسمي","للكتاب","المدرسي","ووظيفته","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي"],"aliases":["الدرس 3","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lhx_phase3_chapitres_5_6_card5_2","kind":"html","lessonKey":"phase3_chapitres_5_6","title":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين (2/2)","lessonTitle":"الدرس 3 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":2,"total":2,"text":"ويبدأ قراءة تتابع الأحماض الأمينية دائماً من الطرف الأميني. تعتمد الخصائص الكهربائية والأمفوتيرية للببتيدات والبروتينات على نوع الجذور الحامضية والقاعدية، فتكتسب شحنات موجبة أو سالبة حسب pH الوسط. تحافظ البروتينات على بنياتها الفراغية المحددة نتيجة روابط تنشأ بين المجموعات الكيميائية لجذور الأحماض الأمينية في مواقع محددة (جسور ثنائية الكبريت، روابط هيدروجينية وشاردية). يؤدي تفكيك هذه الروابط بعوامل فيزيائية (كالحرارة) أو كيميائية (كالأحماض والقواعد) إلى تغيير البنية الفراغية للبروتين.","keywords":["الدرس","العلاقه","بين","بنيه","ووظيفه","البروتين","ويبدا","قراءه","تتابع","الاحماض","الامينيه","دايما","الطرف","الاميني","تعتمد","الخصايص","الكهرباييه","والامفوتيريه"],"aliases":["الدرس 3","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lhx_phase3_chapitres_5_6_2_intro_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 2 : العلاقة بين بنية ووظيفة البروتين 🎯 الهدف العلمي : بيّن تجريبي أن تخصص البروتين متوقف على بنيته الفراغية (تجربة أنفنصن Anfinsen)، وفسّر الأمراض الوراثية (مثل فقر الدم المنجلي) على المستوى الجزيئي. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : عرّف الإنزيم كوسيط حيوي، ووضّح الخصوصية المزدوجة (تخصص مادة التفاعل وتخصص نوع التفاعل) ونموذج التوافق المحرض. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","الاول","التخصص","للبروتينات","العلاقه","ووظيفه","تجريبي","متوقف","بنيته","الفراغيه","تجربه"],"aliases":["كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟"]},{"id":"lhx_phase3_chapitres_5_6_2_card1_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":1,"text":"1 الإشكالية الأساسية للوحدة الثالثة ⚠️ كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟ تتطلب التفاعلات الكيميائية في المختبر درجات حرارة مرتفعة وأحماضاً قوية لتفكيك الجزيئات المعقدة، بينما تتم نفس التفاعلات داخل الخلايا الحية في درجة حرارة هادئة (37°C) وبسرعة فائقة جداً. يعود هذا الفضل للإنزيمات ( Enzymes ). ما هو السر البنيوي في الإنزيم الذي يمنحه هذه القدرة والخصوصية الفائقة؟","keywords":["كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","الاساسيه","للوحده","الثالثه","تتطلب","التفاعلات","الكيمياييه","المختبر","درجات","مرتفعه","واحماضا"],"aliases":["كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟"]},{"id":"lhx_phase3_chapitres_5_6_2_card2_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"نموذج التوافق المحرض (التداخل والتكامل البنيوي أثناء اقتراب مادة التفاعل) (1/2)","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":2,"text":"2 التحليل المنهجي للموقع الفعال ونموذج التوافق المحرض (Adaptation Induite) نموذج التوافق المحرض (التداخل والتكامل البنيوي أثناء اقتراب مادة التفاعل) الإنزيم (E) قبل الارتباط مادة التفاعل (S) معقد (E - S) متوافق 💡 عند اقتراب مادة التفاعل، يغير الإنزيم شكل موقعه الفعال ليتكامل بنيوياً مع مادة التفاعل. مفاهيم البكالوريا الأساسية ما هو الموقع الفعال ( Site Actif )؟ هو تجويف أو منطقة محددة في البنية الفراغية للإنزيم، يتكون من عدد قليل من الأحماض الأمينية المحددة وراثياً، وينقسم إلى قسمين :","keywords":["نموذج","التوافق","المحرض","التداخل","والتكامل","البنيوي","اثناء","اقتراب","ماده","التفاعل","كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم"],"aliases":["نموذج التوافق المحرض (التداخل والتكامل البنيوي أثناء اقتراب مادة التفاعل)"]},{"id":"lhx_phase3_chapitres_5_6_2_card2_2","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"نموذج التوافق المحرض (التداخل والتكامل البنيوي أثناء اقتراب مادة التفاعل) (2/2)","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":2,"total":2,"text":"• موقع التثبيت ( Site de fixation ) : يتعرف ويثبت مادة التفاعل ( Substrat S ). • موقع التحفيز ( Site catalytique ) : ينجز التفاعل الكيميائي. التوافق المحرض ( Adaptation Induite ) : التكامل البنيوي بين الموقع الفعال ومادة التفاعل قد لا يكون موجوداً قبل الارتباط، بل يحرض اقتراب مادة التفاعل الإنزيمَ على تغيير شكله الفراغي ليصبح متكاملاً معها.","keywords":["نموذج","التوافق","المحرض","التداخل","والتكامل","البنيوي","اثناء","اقتراب","ماده","التفاعل","كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم"],"aliases":["نموذج التوافق المحرض (التداخل والتكامل البنيوي أثناء اقتراب مادة التفاعل)"]},{"id":"lhx_phase3_chapitres_5_6_2_card3_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"🧪 اضغط على أحد التفاعلات أعلاه لمشاهدة تأثير الخصوصية","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":1,"text":"3 مختبر الخصوصية المزدوجة للإنزيمات تتميز الإنزيمات بخصوصية عالية جداً، فهي متخصصة بالنسبة لمادة التفاعل ( Substrat ) وبالنسبة لنوع التفاعل ( Type de réaction ) . اضغط لاختبار الخصوصية : 🧪 إنزيم السكراز (Saccharase) + سكر السكروز 🧪 إنزيم السكراز + سكر المالتوز 🧪 اضغط على أحد التفاعلات أعلاه لمشاهدة تأثير الخصوصية ستلاحظ هل يتشكل المعقد الإنزيمي ( ES ) أم يحدث تنافر بنيوي.","keywords":["اضغط","علي","احد","التفاعلات","اعلاه","لمشاهده","تاثير","الخصوصيه","كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","مختبر","المزدوجه"],"aliases":["🧪 اضغط على أحد التفاعلات أعلاه لمشاهدة تأثير الخصوصية"]},{"id":"lhx_phase3_chapitres_5_6_2_card4_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟ (1/2)","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 بيّن أن تسلسل الأحماض الأمينية يحدد البنية الفراغية، وأن الوظيفة مرتبطة بالبنية. تثبت تجربة إعادة التطوي أن تسلسل الأحماض الأمينية يحدد البنية الفراغية الأصلية. يؤدي التمييه إلى فقدان البنية الفراغية والوظيفة مع تغير شكل الموقع الفعال. تستقر البنية ثلاثية الأبعاد بروابط ضعيفة وجسر ثنائي الكبريت (رابطة تكافؤية). يغير استبدال حمض أميني واحد شكل الموقع الفعال فيتغير نمط عمل الإنزيم. تتوقف خصوصية الإنزيم المزدوج على البنية الفراغية للموقع الفعال ومادة محددة. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","خلاصه","الدرس","تسلسل","الاحماض","الامينيه","الفراغيه،","الوظيفه","مرتبطه","بالبنيه","تجربه"],"aliases":["كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟"]},{"id":"lhx_phase3_chapitres_5_6_2_card4_2","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟ (2/2)","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":2,"total":2,"text":"التسلسل يحدد البنية / العلاقة بين البنية والوظيفة","keywords":["كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","التسلسل","العلاقه","والوظيفه"],"aliases":["كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟"]},{"id":"lhx_phase3_chapitres_5_6_2_card5_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"1. ماذا نقصد بأن الإنزيم ذو \"خصوصية مزدوجة\"؟","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ماذا نقصد بأن الإنزيم ذو \"خصوصية مزدوجة\"؟ أ) أنه متخصص في مادة تفاعل واحدة (أو مجموعة محددة) ومتخصص في نوع تفاعل كيميائي واحد (تحلل، بناء، أكسدة...). ب) أنه يعمل في النواة وفي الهيولى في نفس الوقت. ج) أنه يستهلك جزيئتين من الـ ATP لكل تفاعل.","keywords":["ماذا","نقصد","بان","الانزيم","خصوصيه","مزدوجه","كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","متخصص","تفاعل","واحده","مجموعه"],"aliases":["1. ماذا نقصد بأن الإنزيم ذو \"خصوصية مزدوجة\"؟"]},{"id":"lhx_phase3_chapitres_5_6_2_card6_1","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟ (1/2)","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 8، ص 152) الوحدة: D1-U2 — بنية البروتين ووظيفته — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. ترتبط الأحماض الأمينية المتتالية في السلسلة الببتيدية بروابط تكافؤية تدعى الروابط الببتيدية ، وتنشأ من تفاعل مجموعة الكربوكسيل (COOH) لحمض أميني مع مجموعة الأمين (NH2) لحمض أميني آخر مع خروج جزيئة ماء. تحوي السلسلة الببتيدية مهما كان طولها طرفاً أمينياً في البداية وطرفاً كربوكسيلياً في النهاية،","keywords":["كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","المعرفيه","الرسمي","للكتاب","المدرسي","ووظيفته","الكتاب","بتنسيق","قرايي،","تغيير","المعني،"],"aliases":["كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟"]},{"id":"lhx_phase3_chapitres_5_6_2_card6_2","kind":"html","lessonKey":"phase3_chapitres_5_6_2","title":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟ (2/2)","lessonTitle":"كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟","unitId":2,"part":2,"total":2,"text":"ويبدأ قراءة تتابع الأحماض الأمينية دائماً من الطرف الأميني. تعتمد الخصائص الكهربائية والأمفوتيرية للببتيدات والبروتينات على نوع الجذور الحامضية والقاعدية، فتكتسب شحنات موجبة أو سالبة حسب pH الوسط. تحافظ البروتينات على بنياتها الفراغية المحددة نتيجة روابط تنشأ بين المجموعات الكيميائية لجذور الأحماض الأمينية في مواقع محددة (جسور ثنائية الكبريت، روابط هيدروجينية وشاردية). يؤدي تفكيك هذه الروابط بعوامل فيزيائية (كالحرارة) أو كيميائية (كالأحماض والقواعد) إلى تغيير البنية الفراغية للبروتين.","keywords":["كيف","تنجز","الانزيمات","تفاعلات","معقده","درجه","حراره","الجسم","ويبدا","قراءه","تتابع","الاحماض","الامينيه","دايما","الطرف","الاميني","تعتمد","الخصايص"],"aliases":["كيف تنجز الإنزيمات تفاعلات معقدة في درجة حرارة الجسم (37°C)؟"]},{"id":"lhx_lecon_activite_structure_intro_1","kind":"html","lessonKey":"lecon_activite_structure","title":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة الثالثة : النشاط الإنزيمي للبروتينات 🎯 الهدف العلمي : فسّر النوعية المزدوجة للإنزيم انطلاقا من بنية موقعه الفعال (المعقد ES). ⏱️ المدة التقديرية للتعلم الذاتي : 20 دقيقة","keywords":["الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","الاول","التخصص","للبروتينات","الثالثه","النوعيه","المزدوجه","للانزيم","انطلاقا","موقعه","المعقد"],"aliases":["الدرس 2","النشاط الإنزيمي وعلاقته ببنية الإنزيم"]},{"id":"lhx_lecon_activite_structure_card1_1","kind":"html","lessonKey":"lecon_activite_structure","title":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلمية ⚠️ نفس النشا يُهضم في الفم ولا يُهضم في المعدة، فلماذا؟ يحول لعاب الفم (إنزيم Amylase ) النشا إلى سكريات في دقائق عند 37°C ، بينما لا يؤثر إنزيم المعدة (الببسين) في النشا إطلاقا، ولا يؤثر الأميلاز في السليلوز رغم تشابههما الكيميائي. علما أن الإنزيمات كلها بروتينات، فمن أين تأتي هذه الدقة في الاختيار؟ لحل هذه الإشكالية، يجب أن نكتشف العلاقة بين بنية الإنزيم الفراغية (موقعه الفعال) و نشاطه التحفيزي تجاه ركيزة محددة وتفاعل محدد.","keywords":["الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","وضعيه","الانطلاق","وبناء","العلميه","النشا","المعده،","فلماذا؟","amylase","سكريات","دقايق","بينما","المعده"],"aliases":["الدرس 2","النشاط الإنزيمي وعلاقته ببنية الإنزيم"]},{"id":"lhx_lecon_activite_structure_card2_1","kind":"html","lessonKey":"lecon_activite_structure","title":"أنبوبان : نشا + أميلاز / سليلوز + أميلاز (37°C) (1/3)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":3,"text":"2 التحليل المنهجي لتجربتي النوعية والبنية 🧪 النوعية تجاه الركيزة 🔬 البنية شرط النشاط أنبوبان : نشا + أميلاز / سليلوز + أميلاز (37°C) نشا + أميلاز راسب فهلنغ أحمر سليلوز + أميلاز أزرق اليود يبقى 🔴 الراسب الأحمر = سكريات مختزلة (تحول النشا) · 🔵 بقاء الأزرق = لا تحول (السليلوز). منهجية البكالوريا : تحليل وثيقة 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 📷 صورة · قارن الأنبوبين (شاهد/تجريبي) قبل الاستنتاج ماذا نستنتج عن النوعية تجاه الركيزة؟ 1. التعريف بالوثيقة :","keywords":["انبوبان","نشا","اميلاز","سليلوز","الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","لتجربتي","النوعيه","والبنيه","الركيزه","فهلنغ","اليود","الراسب","الاحمر"],"aliases":["أنبوبان","نشا + أميلاز / سليلوز + أميلاز (37°C)"]},{"id":"lhx_lecon_activite_structure_card2_2","kind":"html","lessonKey":"lecon_activite_structure","title":"أنبوبان : نشا + أميلاز / سليلوز + أميلاز (37°C) (2/3)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":2,"total":3,"text":"نتيجتا تجربتين بنفس الإنزيم (الأميلاز) ونفس الشروط، بركيزتين مختلفتين (النشا والسليلوز). 2. الملاحظة : تحول النشا (راسب أحمر) وعدم تحول السليلوز (أزرق ثابت). 3. الاستنتاج : الإنزيم نوعي تجاه ركيزته : لا يتكامل بنيويا إلا مع جزيئة محددة الشكل. أميلاز عند 37°C وعند 80°C ثم التبريد موقع فعال سليم (37°) موقع مشوه (80°) : لا تكامل ← لا نشاط 🟢 الشكل المنتظم = تكامل مع الركيزة · 🔴 الشكل المشوه = فقدان التكامل نهائيا. منهجية البكالوريا : استخراج المعلومات من الشكل 🔑 مفتاح المنهجية:","keywords":["انبوبان","نشا","اميلاز","سليلوز","الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","نتيجتا","تجربتين","الاميلاز","الشروط،","بركيزتين","مختلفتين","النشا","والسليلوز"],"aliases":["أنبوبان","نشا + أميلاز / سليلوز + أميلاز (37°C)"]},{"id":"lhx_lecon_activite_structure_card2_3","kind":"html","lessonKey":"lecon_activite_structure","title":"أنبوبان : نشا + أميلاز / سليلوز + أميلاز (37°C) (3/3)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":3,"total":3,"text":"البوابة 1 → 📄 ورقة · البوابة 2 → 📷 صورة · اربط الشكل (بنية) بالنشاط (وظيفة) لماذا لا يستعيد الإنزيم نشاطه بعد التسخين؟ الحرارة المرتفعة تكسر الروابط الضعيفة (هيدروجينية وشاردية) فيتشوه الموقع الفعال تشوها غير عكسي ، فلا يتشكل المعقد ES : النشاط = البنية .","keywords":["انبوبان","نشا","اميلاز","سليلوز","الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","البوابه","الشكل","بالنشاط","وظيفه","يستعيد","نشاطه","التسخين؟","المرتفعه"],"aliases":["أنبوبان","نشا + أميلاز / سليلوز + أميلاز (37°C)"]},{"id":"lhx_lecon_activite_structure_card3_1","kind":"html","lessonKey":"lecon_activite_structure","title":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم (1/2)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":2,"text":"3 آلية العمل : الموقع الفعال والمعقد ES والتكامل المحفز 🔑 مفتاح المنهجية: البوابة 1 → 📄 ورقة · البوابة 2 → 🎬 فيلم · لأنّ التكامل بنيوي قبل أن يكون كيميائيا يتكون الموقع الفعال من منطقتين متكاملتين : منطقة التثبيت (تمسك الركيزة) و منطقة التحفيز (تحولها)، من أحماض أمينية متقاربة فراغيا وليست متجاورة بالضرورة في السلسلة. معادلة النشاط الإنزيمي : E + S → [ES] → E + P (الإنزيم لا يُستهلك) 💡 التكامل المحفز (Koshland) مقابل القفل والمفتاح (Fischer)!","keywords":["الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","العمل","والمعقد","والتكامل","المحفز","مفتاح","المنهجيه","البوابه","التكامل","بنيوي","كيمياييا","يتكون","منطقتين"],"aliases":["الدرس 2","النشاط الإنزيمي وعلاقته ببنية الإنزيم"]},{"id":"lhx_lecon_activite_structure_card3_2","kind":"html","lessonKey":"lecon_activite_structure","title":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم (2/2)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":2,"total":2,"text":"عند اقتراب الركيزة يتغير شكل الموقع الفعال ليحتضنها (تكامل محفز) ثم يعود لشكله بعد تحرير النواتج. من هنا النوعية المزدوجة : نوعية تجاه الركيزة ونوعية تجاه التفاعل (تفكيك/تركيب/تحويل).","keywords":["الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","اقتراب","الركيزه","يتغير","ليحتضنها","تكامل","لشكله","تحرير","النواتج","النوعيه","المزدوجه","نوعيه","ونوعيه"],"aliases":["الدرس 2","النشاط الإنزيمي وعلاقته ببنية الإنزيم"]},{"id":"lhx_lecon_activite_structure_card4_1","kind":"html","lessonKey":"lecon_activite_structure","title":"✍️ النص العلمي النموذجي : (1/2)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":2,"text":"4 الخلاصة المعتمدة في البكالوريا (الرسم التخطيطي + النص العلمي) ✍️ النص العلمي النموذجي : مقدمة (طرح الإشكالية) تسرع الإنزيمات التفاعلات الحيوية في شروط الجسم دون أن تُستهلك، وتختار ركائزها بدقة، فما أساس هذه النوعية؟ العرض (الموقع الفعال والمعقد) • الموقع الفعال : جيب بنيوي من منطقتي تثبيت وتحفيز، بأحماض أمينية متقاربة فراغيا. • المعقد ES : ارتباط مؤقت بالتكامل البنيوي (تكامل محفز)، يليه التحول ثم تحرير الإنزيم سليما. • البنية شرط النشاط : أي تخرب للموقع (حرارة، pH متطرف) يلغي التكامل والنشاط.","keywords":["النص","العلمي","النموذجي","الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","الخلاصه","المعتمده","الرسم","التخطيطي","مقدمه","الانزيمات","التفاعلات","الحيويه","الجسم"],"aliases":["✍️ النص العلمي النموذجي"]},{"id":"lhx_lecon_activite_structure_card4_2","kind":"html","lessonKey":"lecon_activite_structure","title":"✍️ النص العلمي النموذجي : (2/2)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":2,"total":2,"text":"خاتمة (الإجابة عن الإشكالية) النوعية المزدوجة للإنزيم (ركيزة + تفاعل) ناتجة عن التكامل البنيوي لموقعه الفعال، لذلك فتغير البنية يعني فقدان الوظيفة.","keywords":["النص","العلمي","النموذجي","الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","خاتمه","الاجابه","النوعيه","المزدوجه","للانزيم","ركيزه","تفاعل","ناتجه","التكامل"],"aliases":["✍️ النص العلمي النموذجي"]},{"id":"lhx_lecon_activite_structure_card5_1","kind":"html","lessonKey":"lecon_activite_structure","title":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم (1/2)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 بيّن أن النشاط الإنزيمي مرتبط بالبنية الفراغية للموقع الفعال. يحفز الإنزيم تحول المادة عبر معقد إنزيم-مادة يتشكل على الموقع الفعال. تملك الأميلاز خصوصية تجاه النشا دون السليلوز رغم تشابه الوحدات المونومرية. يوقف التبريد النشاط مؤقتاً دون تخريب البنية، ويخربه التسخين القوي نهائياً. يتوقف شكل الموقع الفعال على البنية الفراغية للإنزيم فتتحدد به خصوصيته تجاه المادة. يؤدي تخريب البنية الفراغية بتغير الحرارة أو pH إلى فقدان الخصوصية والنشاط الإنزيمي. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","خلاصه","مرتبط","بالبنيه","الفراغيه","للموقع","يتشكل","الاميلاز","خصوصيه","النشا","السليلوز","تشابه","الوحدات"],"aliases":["الدرس 2","النشاط الإنزيمي وعلاقته ببنية الإنزيم"]},{"id":"lhx_lecon_activite_structure_card5_2","kind":"html","lessonKey":"lecon_activite_structure","title":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم (2/2)","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":2,"total":2,"text":"الخصوصية الإنزيمية / الموقع الفعال","keywords":["الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","الخصوصيه","الانزيميه"],"aliases":["الدرس 2","النشاط الإنزيمي وعلاقته ببنية الإنزيم"]},{"id":"lhx_lecon_activite_structure_card6_1","kind":"html","lessonKey":"lecon_activite_structure","title":"1. مما يتكون الموقع الفعال للإنزيم؟","lessonTitle":"الدرس 2 : النشاط الإنزيمي وعلاقته ببنية الإنزيم","unitId":3,"part":1,"total":1,"text":"5 التقويم الذاتي الفوري (اختبر استيعابك دون مساعدة) 1. مما يتكون الموقع الفعال للإنزيم؟ أ) منطقتا تثبيت الركيزة وتحفيز التفاعل، من أحماض أمينية متقاربة فراغيا ب) سلسلة كاملة من الأحماض الأمينية للإنزيم ج) جزيء الركيزة نفسها 2. لماذا يفقد الأميلاز نشاطه نهائيا بعد تسخينه إلى 80°C؟ أ) لتخرب بنيته الفراغية (موقعه الفعال) تشوها غير عكسي يمنع تشكل المعقد ES ب) لتبخر الركيزة من الوسط ج) لاستهلاك الإنزيم كليا في التفاعل","keywords":["مما","يتكون","الموقع","الفعال","للانزيم؟","الدرس","النشاط","الانزيمي","وعلاقته","ببنيه","الانزيم","التقويم","الفوري","اختبر","استيعابك","مساعده","منطقتا","تثبيت"],"aliases":["1. مما يتكون الموقع الفعال للإنزيم؟"]},{"id":"lhx_phase4_chapitres_7_8_intro_1","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 3 : النشاط الإنزيمي للبروتينات 🎯 الهدف العلمي : حدّد مفهوم درجة الحموضة المثلى (pH optimum)، وفسّر تأثير تغير الـ pH على الحالة الكهربائية (التأين) للجذور الحرة في الموقع الفعال. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : وميّز بين التأثير الرجعي للتبريد (قلة الحركية الجزيئية) والتأثير غير الرجعي للحرارة المرتفعة (التخريب الحراري للروابط الضعيفة). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","الاول","التخصص","للبروتينات","الانزيمي","مفهوم","الحموضه","المثلي","optimum","الحاله"],"aliases":["الدرس 3","دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم"]},{"id":"lhx_phase4_chapitres_7_8_card1_1","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا يعمل إنزيم الببسين في المعدة (pH = 2) ويتوقف في الأمعاء؟ تعمل إنزيمات المعدة في وسط شديد الحموضة ( pH ≈ 2 )، بينما تعمل إنزيمات اللعاب في وسط معتدل ( pH ≈ 7 )، وإنزيمات البنكرياس في الأمعاء في وسط قاعدي ( pH ≈ 8.5 ). وإذا نقلنا إنزيم المعدة إلى الأمعاء يتوقف نشاطه كلياً! كيف يؤثر تغير رقم الـ pH على البنية الجزيئية للموقع الفعال للإنزيم؟","keywords":["الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","وضعيه","الانطلاق","وبناء","العلميه","الببسين","المعده","ويتوقف","الامعاء؟","انزيمات"],"aliases":["الدرس 3","دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم"]},{"id":"lhx_phase4_chapitres_7_8_card2_1","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"منحنى النشاط الإنزيمي بدلالة الـ pH (شكل الجرس المنحني) (1/2)","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":1,"total":2,"text":"2 التحليل المنهجي لمنحنى سرعة النشاط الإنزيمي بدلالة الـ pH منحنى النشاط الإنزيمي بدلالة الـ pH (شكل الجرس المنحني) pH الوسط السرعة Vi السرعة الأعظمية Vmax pH أمثل (Optimum) وسط حامضي (تأين موجـب) وسط قاعدي (تأين سالـب) 📈 يبلغ النشاط الإنزيمي ذروته عند قيمة محددة تسمى الـ pH الأمثل، وينخفض يميناً ويساراً. منهجية البكالوريا : التفسير الجزيئي لتأثير الـ pH لماذا ينخفض النشاط بالابتعاد عن الـ pH الأمثل؟","keywords":["منحني","النشاط","الانزيمي","بدلاله","شكل","الجرس","المنحني","الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","لمنحني","السرعه"],"aliases":["منحنى النشاط الإنزيمي بدلالة الـ pH (شكل الجرس المنحني)"]},{"id":"lhx_phase4_chapitres_7_8_card2_2","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"منحنى النشاط الإنزيمي بدلالة الـ pH (شكل الجرس المنحني) (2/2)","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":2,"total":2,"text":"يتكون الموقع الفعال للإنزيم من أحماض أمينية ذات جذور حرة ( Radicaux R ) تحمل مجموعات كيميائية قابلة للتأين (الأمينية -NH₂ والكربوكسيلية -COOH ). • عند الـ pH الأمثل : تكون شحنات الجذور الحرة في الموقع الفعال مناسبة تماماً لنشأة الروابط الانتقالية مع مادة التفاعل، فيحدث التكامل البنيوي ويصل التفاعل لسرعته القصوى. • في وسط حامضي أو قاعدي جداً : تتغير الحالة الكهربائية (تأين الجذور الحرة)، فتتكسر الروابط الشاردية والهيدروجينية، مما يغير شكل الموقع الفعال ويمنع تثبيت مادة التفاعل.","keywords":["منحني","النشاط","الانزيمي","بدلاله","شكل","الجرس","المنحني","الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","يتكون","للانزيم"],"aliases":["منحنى النشاط الإنزيمي بدلالة الـ pH (شكل الجرس المنحني)"]},{"id":"lhx_phase4_chapitres_7_8_card3_1","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"🟢 الحالة عند الـ pH الأمثل (Optimum)","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":1,"total":1,"text":"3 محاكي تأين الموقع الفعال بدلالة pH الوسط اختر حالة حموضة الوسط لمعاينة الشحنة الكهربائية للجذور الحرة في الموقع الفعال وسرعة الإنزيم : 🔴 وسط حامضي قوي (pH 🟢 الوسط الأمثل (pH = pH optimum) 🔵 وسط قاعدي قوي (pH > pH optimum) 🟢 الحالة عند الـ pH الأمثل (Optimum) Radicaux R : -COO⁻ و -NH₃⁺ (شحنات متوازنة ومثالية) الشحنات الكهربائية لأحماض الموقع الفعال تتوافق هندسياً وكهربائياً مع شحنات مادة التفاعل ( Substrat ). يتشكل المعقد ( ES ) بسهولة وتكون سرعة النشاط الإنزيمي أعظمية ( Vmax = 100% ).","keywords":["الحاله","عند","الامثل","optimum","الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","محاكي","بدلاله","حموضه","لمعاينه","الشحنه"],"aliases":["🟢 الحالة عند الـ pH الأمثل (Optimum)"]},{"id":"lhx_phase4_chapitres_7_8_card4_1","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"1. ماذا يحدث للجذور الحرة الأمينية ( -NH₂ ) في الموقع الفعال عند وضع الإنزيم في وسط شديد الحموضة ( pH حامضي جداً )؟","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ماذا يحدث للجذور الحرة الأمينية ( -NH₂ ) في الموقع الفعال عند وضع الإنزيم في وسط شديد الحموضة ( pH حامضي جداً )؟ أ) تسلك سلوك القاعدة وتكتسب بروتونات ( H⁺ ) فتصبح شحنتها موجبة ( -NH₃⁺ ). ب) تفقد بروتونات وتصبح سالبة الشحنة. ج) تتحول إلى جسور ثنائية الكبريت.","keywords":["ماذا","يحدث","للجذور","الحره","الامينيه","الموقع","الفعال","عند","وضع","الانزيم","وسط","شديد","الحموضه","حامضي","جدا","الدرس","دراسه","تاثير"],"aliases":["1. ماذا يحدث للجذور الحرة الأمينية ( -NH₂ ) في الموقع الفعال عند وضع الإنزيم في وسط شديد الحموضة ( pH حامضي جداً )؟"]},{"id":"lhx_phase4_chapitres_7_8_card5_1","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم (1/2)","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 9-12، ص 68) الوحدة: U3 — النشاط الإنزيمي للبروتينات — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. « الإنزيمات هي بروتينات تعمل على تسريع التفاعلات الكيميائية في شروط محددة، وتتميز بتأثيرها النوعي اتجاه مادة التفاعل (الركيزة)، وهي لا تستهلك أثناء التفاعل. » يعتمد التأثير النوعي على تشكل معقد إنزيم-مادة التفاعل ES ؛ تتكون روابط ضعيفة انتقالية بين الركيزة ومنطقة صغيرة من الإنزيم تعرف بـ الموقع الفعال (site actif) . شكل الموقع الفعال مكمّل لشكل الركيزة،","keywords":["الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","المعرفيه","الرسمي","للكتاب","المدرسي","الانزيمي","للبروتينات","الكتاب","بتنسيق","قرايي،"],"aliases":["الدرس 3","دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم"]},{"id":"lhx_phase4_chapitres_7_8_card5_2","kind":"html","lessonKey":"phase4_chapitres_7_8","title":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم (2/2)","lessonTitle":"الدرس 3 : دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم","unitId":3,"part":2,"total":2,"text":"وقد يحدث التكامل عند اقترابها حيث تحفز الإنزيم على تغيير بنيته الفراغية : التكامل المحفّز (Adaptation induite) . لكل إنزيم pH مثلى و حرارة مثلى (37°C عند الإنسان) يكون عندهما النشاط أعظميا. عند الحرارة المرتفعة يبدأ تخرب الإنزيم بتكسير الروابط المحافظة على بنيته الفراغية، فيفقد نشاطه بصورة غير عكسية. نصّ الحصيلة مصحَّح يدوياً من الكتاب المدرسي (ص 68)؛ لم تُستخرج هذه الصفحات آلياً.","keywords":["الدرس","دراسه","تاثير","تغير","درجه","الوسط","علي","نشاط","الانزيم","التكامل","اقترابها","تغيير","بنيته","الفراغيه","المحفز","adaptation","induite","حراره"],"aliases":["الدرس 3","دراسة تأثير تغير درجة pH الوسط على نشاط الإنزيم"]},{"id":"lhx_phase4_chapitres_7_8_2_intro_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 3 : النشاط الإنزيمي للبروتينات 🎯 الهدف العلمي : حدّد مفهوم درجة الحموضة المثلى (pH optimum)، وفسّر تأثير تغير الـ pH على الحالة الكهربائية (التأين) للجذور الحرة في الموقع الفعال. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : وميّز بين التأثير الرجعي للتبريد (قلة الحركية الجزيئية) والتأثير غير الرجعي للحرارة المرتفعة (التخريب الحراري للروابط الضعيفة). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا","نغليها؟","الاول","التخصص","للبروتينات","الانزيمي","مفهوم","الحموضه","المثلي","optimum","تاثير","الحاله"],"aliases":["لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟"]},{"id":"lhx_phase4_chapitres_7_8_2_card1_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":1,"text":"1 الإشكالية الأساسية لختام الوحدة الثالثة ⚠️ لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟ عند التبريد أو التجميد، يتوقف نشاط الإنزيمات الميكروبية المحللة، ولكن عند إعادة تسخينها إلى 37°C تسترجع الإنزيمات نشاطها كلياً! بينما إذا غلينا اللقاح أو الإنزيم عند 80°C يتوقف نشاطه نهائياً ولا يعود أبداً عند تبريده! لماذا يكون تأثير التبريد مؤقتاً (رجعي) بينما تأثير الغليان دائم (غير رجعي)؟","keywords":["لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا","نغليها؟","الاساسيه","لختام","الثالثه","التبريد","التجميد،","يتوقف","الانزيمات","الميكروبيه","المحلله،","اعاده"],"aliases":["لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟"]},{"id":"lhx_phase4_chapitres_7_8_2_card2_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"منحنى تأثير الحرارة (غير متناظر : انخفاض تدريجي بالتبريد، وسقوط حاد بالغليان) (1/2)","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":2,"text":"2 التحليل المنهجي لمنحنى النشاط الإنزيمي بدلالة درجة الحرارة منحنى تأثير الحرارة (غير متناظر : انخفاض تدريجي بالتبريد، وسقوط حاد بالغليان) الحرارة (°C) السرعة Vi 37°C أمثـل تبريد (توقف مؤقت رجعي) تسخين (تخريب لا رجعي) 💡 عند 0°C تنخفض الطاقة الحركية، بينما عند 70°C تتكسر الروابط الهيدروجينية. التبرير المعتمد في البكالوريا المقارنة الجزيئية الدقيقة بين التبريد والغليان • عند درجات الحرارة المنخفضة (0°C إلى 4°C) : تقل الطاقة الحركية لجزيئات الإنزيم ومادة التفاعل، فتقل التصادمات الفعالة ويتوقف التفاعل،","keywords":["منحني","تاثير","الحراره","غير","متناظر","انخفاض","تدريجي","بالتبريد،","وسقوط","حاد","بالغليان","لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا"],"aliases":["منحنى تأثير الحرارة (غير متناظر","انخفاض تدريجي بالتبريد، وسقوط حاد بالغليان)"]},{"id":"lhx_phase4_chapitres_7_8_2_card2_2","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"منحنى تأثير الحرارة (غير متناظر : انخفاض تدريجي بالتبريد، وسقوط حاد بالغليان) (2/2)","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":2,"total":2,"text":"لكن البنية الفراغية تبقى سليمة تماماً (تأثير عكوس / رجعي). • عند درجات الحرارة المرتفعة (> 60°C) : تزداد الاهتزازات الجزيئية بشدة مما يؤدي إلى تكسر الروابط الضعيفة (خاصة الهيدروجينية) المحافظة على استقرار البنية الثلاثية. يفقد الإنزيم شكله وموقعه الفعال نهائياً (تخريب غير رجعي - Dénaturation irréversible ).","keywords":["منحني","تاثير","الحراره","غير","متناظر","انخفاض","تدريجي","بالتبريد،","وسقوط","حاد","بالغليان","لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا"],"aliases":["منحنى تأثير الحرارة (غير متناظر","انخفاض تدريجي بالتبريد، وسقوط حاد بالغليان)"]},{"id":"lhx_phase4_chapitres_7_8_2_card3_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"🌡️ درجة الحرارة المثلى (37°C)","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":1,"text":"3 مختبر الحرارة الإنزيمي التفاعلي اختر درجة الحرارة لمعاينة حركة الجزيئات وحالة الروابط الفراغية : ❄️ تجميد (0°C) 🌡️ حرارة الجسم المثلى (37°C) 🔥 غليان حراري (> 75°C) 🌡️ درجة الحرارة المثلى (37°C) تكون الطاقة الحركية للجزيئات مثالية، فيحدث أقصى عدد ممكن من التصادمات الفعالة بين الموقع الفعال للإنزيم ومادة التفاعل في وحدة الزمن، مع بقاء البنية الفراغية مستقرة تماماً ( Vmax = 100% ).","keywords":["درجه","الحراره","المثلي","لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا","نغليها؟","مختبر","الانزيمي","التفاعلي","لمعاينه","الجزييات","وحاله","الروابط"],"aliases":["🌡️ درجة الحرارة المثلى (37°C)"]},{"id":"lhx_phase4_chapitres_7_8_2_card4_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر تأثير تغيرات pH الوسط ودرجة الحرارة على النشاط الإنزيمي. يملك كل إنزيم pH أمثل تعتمد قيمته على الوسط الذي يعمل فيه. يغير الابتعاد عن pH الأمثل شحنات الأطراف المشحونة للموقع الفعال فتتبدل بنية الإنزيم الفراغية. ينخفض النشاط الإنزيمي بشدة في الوسط الحمضي القوي أو القاعدي القوي. يوقف التبريد النشاط الإنزيمي مؤقتاً دون تخريب البنية الفراغية. يخرب التسخين القوي الموقع الفعال فيفقد الإنزيم نشاطه بشكل نهائي. 🔑 المصطلح المفتاحي في البكالوريا : pH الأمثل / الموقع الفعال","keywords":["لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا","نغليها؟","خلاصه","الدرس","تاثير","تغيرات","الوسط","ودرجه","الانزيمي","تعتمد","قيمته","الابتعاد"],"aliases":["لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟"]},{"id":"lhx_phase4_chapitres_7_8_2_card5_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"1. لماذا نستطيع استرجاع النشاط الإنزيمي بعد تبريده إلى 0°C، ولا نستطيع استرجاعه بعد تسخينه إلى 80°C؟","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":1,"text":"4 تقويم النشاط 4 : أسئلة البكالوريا المتكررة 1. لماذا نستطيع استرجاع النشاط الإنزيمي بعد تبريده إلى 0°C، ولا نستطيع استرجاعه بعد تسخينه إلى 80°C؟ أ) لأن التبريد يقلل الحركة الجزيئية دون تخريب الروابط الفراغية، بينما التسخين يكسر الروابط الضعيفة ويخرب الموقع الفعال نهائياً. ب) لأن الإنزيم يتجمد فيموت ثم يحيى عند التسخين. ج) لأن التبريد يكسر الجسور ثنائية الكبريت فقط.","keywords":["لماذا","نستطيع","استرجاع","النشاط","الانزيمي","بعد","تبريده","الي","ولا","استرجاعه","تسخينه","نحفظ","اللحوم","واللقاحات","الثلاجه","نغليها؟","التبريد","الحركه"],"aliases":["1. لماذا نستطيع استرجاع النشاط الإنزيمي بعد تبريده إلى 0°C، ولا نستطيع استرجاعه بعد تسخينه إلى 80°C؟"]},{"id":"lhx_phase4_chapitres_7_8_2_card6_1","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟ (1/2)","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 9-12، ص 68) الوحدة: U3 — النشاط الإنزيمي للبروتينات — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. « الإنزيمات هي بروتينات تعمل على تسريع التفاعلات الكيميائية في شروط محددة، وتتميز بتأثيرها النوعي اتجاه مادة التفاعل (الركيزة)، وهي لا تستهلك أثناء التفاعل. » يعتمد التأثير النوعي على تشكل معقد إنزيم-مادة التفاعل ES ؛ تتكون روابط ضعيفة انتقالية بين الركيزة ومنطقة صغيرة من الإنزيم تعرف بـ الموقع الفعال (site actif) . شكل الموقع الفعال مكمّل لشكل الركيزة،","keywords":["لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا","نغليها؟","المعرفيه","الرسمي","للكتاب","المدرسي","الانزيمي","للبروتينات","الكتاب","بتنسيق","قرايي،","تغيير"],"aliases":["لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟"]},{"id":"lhx_phase4_chapitres_7_8_2_card6_2","kind":"html","lessonKey":"phase4_chapitres_7_8_2","title":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟ (2/2)","lessonTitle":"لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟","unitId":3,"part":2,"total":2,"text":"وقد يحدث التكامل عند اقترابها حيث تحفز الإنزيم على تغيير بنيته الفراغية : التكامل المحفّز (Adaptation induite) . لكل إنزيم pH مثلى و حرارة مثلى (37°C عند الإنسان) يكون عندهما النشاط أعظميا. عند الحرارة المرتفعة يبدأ تخرب الإنزيم بتكسير الروابط المحافظة على بنيته الفراغية، فيفقد نشاطه بصورة غير عكسية. نصّ الحصيلة مصحَّح يدوياً من الكتاب المدرسي (ص 68)؛ لم تُستخرج هذه الصفحات آلياً.","keywords":["لماذا","نحفظ","اللحوم","واللقاحات","الثلاجه","الي","ولا","نغليها؟","التكامل","اقترابها","تغيير","بنيته","الفراغيه","المحفز","adaptation","induite","حراره","الانسان"],"aliases":["لماذا نحفظ اللحوم واللقاحات في الثلاجة (0°C إلى 4°C) ولا نغليها؟"]},{"id":"lhx_phase5_chapitres_9_10_intro_1","kind":"html","lessonKey":"phase5_chapitres_9_10","title":"الدرس 2 : الذات واللاذات","lessonTitle":"الدرس 2 : الذات واللاذات","unitId":4,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 4 : دور البروتينات في الدفاع عن الذات 🎯 الهدف العلمي : عرّف الذات واللاذات، وحدّد بنية وأصل التنوع الوراثي لجزيئات معقد التوافق النسيجي الرئيسي (CMH-I و CMH-II). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد البنية الجزيئية والمحددات الغشائية لكريات الدم الحمراء، وفسّر الأساس الوراثي والإنزيمي للزمر الدموية ونقل الدم السليم. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","الذات","واللاذات","الاول","التخصص","للبروتينات","البروتينات","الدفاع","واللاذات،","التنوع","الوراثي","لجزييات","التوافق","النسيجي","الرييسي","الجزيييه","والمحددات","الغشاييه"],"aliases":["الدرس 2","الذات واللاذات"]},{"id":"lhx_phase5_chapitres_9_10_card1_1","kind":"html","lessonKey":"phase5_chapitres_9_10","title":"الدرس 2 : الذات واللاذات","lessonTitle":"الدرس 2 : الذات واللاذات","unitId":4,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا يرفض الجسم زرع الأعضاء من شخص آخر؟ عند زرع جلد أو كلية من متبرع إلى مستقبل (حتى بين الإخوة في كثير من الأحيان)، يقوم جهاز المناعة للمستقبل بمهاجمة العضو المزروع وتخريبه بعد عدة أيام (رفض الطعم Rejet de greffe )، بينما لو نقلنا جلداً من الشخص نفسه يقبله الجسم فوراً! كيف يميز جهاز المناعة بين خلايا جسده (الذات Soi ) والخلايا الغريبة (اللاذات Non-soi )؟","keywords":["الدرس","الذات","واللاذات","وضعيه","الانطلاق","وبناء","العلميه","الجسم","الاعضاء","متبرع","مستقبل","الاخوه","الاحيان","المناعه","للمستقبل","بمهاجمه","العضو","المزروع"],"aliases":["الدرس 2","الذات واللاذات"]},{"id":"lhx_phase5_chapitres_9_10_card2_1","kind":"html","lessonKey":"phase5_chapitres_9_10","title":"البنية الفراغية لجزيئات الـ CMH على غشاء الخلية (1/2)","lessonTitle":"الدرس 2 : الذات واللاذات","unitId":4,"part":1,"total":2,"text":"2 التحليل المنهجي لبنية مؤشرات الهوية البيولوجية (CMH-I و CMH-II) البنية الفراغية لجزيئات الـ CMH على غشاء الخلية الغشاء الهيولي للخلية β2m CMH الصنف I على جميع الخلايا المنواة CMH الصنف II على الخلايا المناعية (CPA, LB) 🟢 تمتلك كل جزيئة CMH في قمتها تجويفاً مخصصاً لعرض البيبتيد المستضدي. منهجية البكالوريا : التمييز بين الصنفين I و II ما هو مصدر التنوع الهائل في جزيئات الـ CMH؟ تشرف على تركيب بروتينات الـ CMH مورثات تقع على الصبغي رقم 6 عند الإنسان (نظام HLA )، وتتميز بـ : • تعدد المورثات ( Polygénie ) :","keywords":["البنيه","الفراغيه","لجزييات","cmh","علي","غشاء","الخليه","الدرس","الذات","واللاذات","لبنيه","موشرات","الهويه","البيولوجيه","للخليه","الصنف","الخلايا","المنواه"],"aliases":["البنية الفراغية لجزيئات الـ CMH على غشاء الخلية"]},{"id":"lhx_phase5_chapitres_9_10_card2_2","kind":"html","lessonKey":"phase5_chapitres_9_10","title":"البنية الفراغية لجزيئات الـ CMH على غشاء الخلية (2/2)","lessonTitle":"الدرس 2 : الذات واللاذات","unitId":4,"part":2,"total":2,"text":"مورثات A, B, C للصنف I، ومورثات DP, DQ, DR للصنف II. • تعدد الأليلات ( Polyallélisme ) : كل مورثة لها عشرات الأليلات في الطبيعة. • تساوي السيادة ( Codominance ) : جميع أليلات الأبوين يتم تعبيرها معاً على غشاء الخلية دون سيادة وتنحي.","keywords":["البنيه","الفراغيه","لجزييات","cmh","علي","غشاء","الخليه","الدرس","الذات","واللاذات","مورثات","للصنف","ومورثات","الاليلات","polyall","lisme","مورثه","عشرات"],"aliases":["البنية الفراغية لجزيئات الـ CMH على غشاء الخلية"]},{"id":"lhx_phase5_chapitres_9_10_card3_1","kind":"html","lessonKey":"phase5_chapitres_9_10","title":"👤 الزرع الذاتي ( Autogreffe )","lessonTitle":"الدرس 2 : الذات واللاذات","unitId":4,"part":1,"total":1,"text":"3 مختبر التوافق النسيجي وزرع الطعوم اختر نوع المتبرع لمعاينة التوافق النسيجي وحكم جهاز المناعة : 👤 زرع ذاتي (من جسم المصاب نفسه) 👯 زرع من توأم حقيقي (مماثل وراثياً) ❌ زرع من متبرع غريب (غير متوافق) 👤 الزرع الذاتي ( Autogreffe ) مؤشرات الـ CMH للخلية المزروعة متطابقة 100% مع مؤشرات خلايا المستقبل. يتعرف عليها جهاز المناعة كـ \"ذات\" ( Soi ) فيتم قبول الطعم ونمو الأوعية الدموية فيه.","keywords":["الزرع","الذاتي","autogreffe","الدرس","الذات","واللاذات","مختبر","التوافق","النسيجي","الطعوم","المتبرع","لمعاينه","المناعه","المصاب","حقيقي","مماثل","وراثيا","متبرع"],"aliases":["👤 الزرع الذاتي ( Autogreffe )"]},{"id":"lhx_phase5_chapitres_9_10_card4_1","kind":"html","lessonKey":"phase5_chapitres_9_10","title":"1. أين تتواجد مؤشرات الـ CMH من الصنف الأول ( CMH-I ) في جسم الإنسان؟","lessonTitle":"الدرس 2 : الذات واللاذات","unitId":4,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. أين تتواجد مؤشرات الـ CMH من الصنف الأول ( CMH-I ) في جسم الإنسان؟ أ) على الغشاء الهيولي لجميع الخلايا المنواة في الجسم. ب) على سطح كريات الدم الحمراء فقط. ج) داخل النواة متصلة بالـ ADN .","keywords":["اين","تتواجد","موشرات","cmh","الصنف","الاول","جسم","الانسان؟","الدرس","الذات","واللاذات","لجميع","الخلايا","المنواه","الجسم","كريات","الحمراء","متصله"],"aliases":["1. أين تتواجد مؤشرات الـ CMH من الصنف الأول ( CMH-I ) في جسم الإنسان؟"]},{"id":"lhx_phase5_chapitres_9_10_2_intro_1","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 4 : دور البروتينات في الدفاع عن الذات 🎯 الهدف العلمي : عرّف الذات واللاذات، وحدّد بنية وأصل التنوع الوراثي لجزيئات معقد التوافق النسيجي الرئيسي (CMH-I و CMH-II). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد البنية الجزيئية والمحددات الغشائية لكريات الدم الحمراء، وفسّر الأساس الوراثي والإنزيمي للزمر الدموية ونقل الدم السليم. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","الاول","التخصص","للبروتينات","البروتينات","الدفاع","الذات","واللاذات،","التنوع","الوراثي","لجزييات"],"aliases":["لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟"]},{"id":"lhx_phase5_chapitres_9_10_2_card1_1","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":1,"total":1,"text":"1 الإشكالية الجزيئية للزمر الدموية ⚠️ لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟ كريات الدم الحمراء خلايا عديمة النواة، وبالتالي فهي لا تحمل مؤشرات الـ CMH ! ومع ذلك، فإن نقل دم غير متوافق يسبب حدوث تراص قاتل (الارتصام Agglutination ) لكريات المعطي داخل أوعية المستقبل. ما هي المحددات الغشائية السكرية والبروتينية التي تحملها كريات الدم الحمراء وتحدد هويتها؟","keywords":["لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","الجزيييه","للزمر","الدمويه","كريات","الحمراء","خلايا","عديمه","النواه،","وبالتالي","موشرات"],"aliases":["لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟"]},{"id":"lhx_phase5_chapitres_9_10_2_card2_1","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"المحددات المستضدية الغشائية للزمر الأربعة (ABO) على المادة الأساسية H (1/2)","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":1,"total":2,"text":"2 التحليل المنهجي للمستضدات الغشائية والأساس الوراثي (الصبغي 9) المحددات المستضدية الغشائية للزمر الأربعة (ABO) على المادة الأساسية H الزمرة O (مادة H فقط) الزمرة A (مستضد A) الزمرة B (مستضد B) الزمرة AB (مستضد A و B) 💡 الأزرق : N-أستيل غالاكتوز أمين، البنفسجي : D-غالاکتوز. التفسير الإنزيمي والوراثي في البكالوريا كيف تشرف المورثة (الصبغي 9) على تحديد الزمرة؟ تشرف المورثة ( I ) على الصبغي 9 على تركيب إنزيم ناقل للسكر ( Glycosyltransférase ) يضيف سكراً نهائياً للمادة الأساسية H : • الأليل A (سائد) :","keywords":["المحددات","المستضديه","الغشاييه","للزمر","الاربعه","abo","علي","الماده","الاساسيه","لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","للمستضدات"],"aliases":["المحددات المستضدية الغشائية للزمر الأربعة (ABO) على المادة الأساسية H"]},{"id":"lhx_phase5_chapitres_9_10_2_card2_2","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"المحددات المستضدية الغشائية للزمر الأربعة (ABO) على المادة الأساسية H (2/2)","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":2,"total":2,"text":"يركب إنزيم يضيف N-acétylgalactosamine $\\rightarrow$ مستضد A. • الأليل B (سائد) : يركب إنزيم يضيف D-galactose $\\rightarrow$ مستضد B. • الأليل O (متنحٍ) : طفرة تؤدي لتركيب إنزيم طافر غير فعال، فتبقى المادة H على حالها.","keywords":["المحددات","المستضديه","الغشاييه","للزمر","الاربعه","abo","علي","الماده","الاساسيه","لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","tylgalactosamine"],"aliases":["المحددات المستضدية الغشائية للزمر الأربعة (ABO) على المادة الأساسية H"]},{"id":"lhx_phase5_chapitres_9_10_2_card3_1","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"✅ نقل آمن وناجح (من O⁻ إلى A⁺)","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":1,"total":1,"text":"3 مختبر نقل الدم التفاعلي (قاعدة عدم الارتصام) قاعدة نقل الدم السليم : يجب ألا يلتقي مستضد كريات المعطي مع الجسم المضاد في مصل المستقبل . اختبار النقل : 🩸 نقل من O⁻ (معطي عام) إلى A⁺ ⚠️ نقل من A⁺ إلى مستقبل B⁻ ✅ نقل آمن وناجح (من O⁻ إلى A⁺) كريات الدم الحمراء للمعطي ( O⁻ ) خالية تماماً من أي مستضد غشائي ( A, B, Rh ). وبالتالي لن تهاجمها الأجسام المضادة الموجودة في مصل المستقبل، ولا يحدث أي ارتصام.","keywords":["نقل","امن","وناجح","الي","لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","مختبر","التفاعلي","قاعده","الارتصام","السليم","يلتقي"],"aliases":["✅ نقل آمن وناجح (من O⁻ إلى A⁺)"]},{"id":"lhx_phase5_chapitres_9_10_2_card4_1","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟ (1/2)","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 حدّد مفهومي الذات واللاذات، وبيّن الدور المناعي لجزيئات CMH وزمر الدم. يميز الجسم مكوناته الذاتية عن اللاذات الغريبة بفضل جزيئات بروتينية غشائية. تعبرز جزيئات CMH-I على سطح جميع الخلايا المنواة لعرض شظايا البروتينات الداخلية. تعبرز جزيئات CMH-II من طرف خلايا مناعية متخصصة لعرض شظايا اللاذات المبتلعة. تتحدد زمر الدم (A, B, AB, O وعامل الريسوس) ببروتينات على سطح كريات الدم الحمراء. يحمل مصل الزمرة O أجساماً مضادة ضد A و B، مما يفرض شروط التوافق في نقل الدم. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","خلاصه","الدرس","مفهومي","الذات","واللاذات،","الدور","المناعي","لجزييات","الجسم","مكوناته"],"aliases":["لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟"]},{"id":"lhx_phase5_chapitres_9_10_2_card4_2","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟ (2/2)","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":2,"total":2,"text":"الذات واللاذات / المعقد الملائم للنسج (CMH)","keywords":["لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","الذات","واللاذات","المعقد","الملايم","للنسج"],"aliases":["لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟"]},{"id":"lhx_phase5_chapitres_9_10_2_card5_1","kind":"html","lessonKey":"phase5_chapitres_9_10_2","title":"1. ماذا يحمل مصل (بلازما) شخص ذو زمرة دموية ( O⁻ ) من أجسام مضادة؟","lessonTitle":"لماذا تكون الزمرة O معطياً عاماً بينما الزمرة AB مستقبلاً عاماً؟","unitId":4,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. ماذا يحمل مصل (بلازما) شخص ذو زمرة دموية ( O⁻ ) من أجسام مضادة؟ أ) يحمل أجساماً مضادة ضد A وأجساماً مضادة ضد B ( Anti-A و Anti-B ). ب) لا يحمل أي أجسام مضادة نهائياً. ج) يحمل مستضدات A و B.","keywords":["ماذا","يحمل","مصل","بلازما","شخص","زمره","دمويه","اجسام","مضاده؟","لماذا","تكون","الزمره","معطيا","عاما","بينما","مستقبلا","عاما؟","اجساما"],"aliases":["1. ماذا يحمل مصل (بلازما) شخص ذو زمرة دموية ( O⁻ ) من أجسام مضادة؟"]},{"id":"lhx_phase6_chapitres_11_12_intro_1","kind":"html","lessonKey":"phase6_chapitres_11_12","title":"الدرس 5 : مصدر الأجسام المضادة","lessonTitle":"الدرس 5 : مصدر الأجسام المضادة","unitId":4,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 4 : دور البروتينات في الدفاع عن الذات 🎯 الهدف العلمي : بيّن الطبيعة البروتينية للأجسام المضادة (غلوبيلينات غاما)، وحدّد بنيتها الجزيئية في شكل حرف Y ومواقع التخصص. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : وضّح دور المعقد المناعي في إبطال مفعول المستضد، صف المراحل الأربعة لعملية بلعمة المعقد المناعي بواسطة الماكروفاج. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","مصدر","الاجسام","المضاده","الاول","التخصص","للبروتينات","البروتينات","الدفاع","الذات","الطبيعه","البروتينيه","للاجسام","غلوبيلينات","بنيتها","الجزيييه","ومواقع","المعقد"],"aliases":["الدرس 5","مصدر الأجسام المضادة"]},{"id":"lhx_phase6_chapitres_11_12_card1_1","kind":"html","lessonKey":"phase6_chapitres_11_12","title":"الدرس 5 : مصدر الأجسام المضادة","lessonTitle":"الدرس 5 : مصدر الأجسام المضادة","unitId":4,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف يحمي المصل المناعي حيواناً من سم الكزاز القاتل؟ إذا حقنا حيواناً بسم الكزاز الفعّال يموت فوراً. ولكن إذا حقناه بـ مصل (سيروم مأخوذ من دم حيوان محصن ضد الكزاز) ثم حقناه بالسم القاتل، فإنه يعيش ولا تظهر عليه أي أعراض! وهذا يعني أن المصل يحتوي على جزيئات دفاعية نوعية تتدخل في السوائل (الأخلاط : الدم واللمف). ما هي الطبيعة الكيميائية لهذه الجزيئات (الأجسام المضادة)؟ وكيف تتوافق بنيتها الجزيئية في شكل حرف Y مع أداء وظيفتها بدقة؟","keywords":["الدرس","مصدر","الاجسام","المضاده","وضعيه","الانطلاق","وبناء","العلميه","المصل","المناعي","حيوانا","الكزاز","القاتل؟","حقناه","سيروم","ماخوذ","حيوان","بالسم"],"aliases":["الدرس 5","مصدر الأجسام المضادة"]},{"id":"lhx_phase6_chapitres_11_12_card2_1","kind":"html","lessonKey":"phase6_chapitres_11_12","title":"البنية الجزيئية المفصلة للجسم المضاد (4 سلاسل بيبتيدية : 2 ثقيلة H + 2 خفيفة L) (1/2)","lessonTitle":"الدرس 5 : مصدر الأجسام المضادة","unitId":4,"part":1,"total":2,"text":"2 التحليل المنهجي للرحلان الكهربائي لمصل الدم وبنية الجسم المضاد في شكل حرف Y البنية الجزيئية المفصلة للجسم المضاد (4 سلاسل بيبتيدية : 2 ثقيلة H + 2 خفيفة L) سلسلتان ثقيلتان (H) سلسلة خفيفة (L) جسور ثنائية الكبريت S-S موقع تثبيت محدد المستضد (المنطقة المتغيرة) 💡 المنطقة الثابتة (الأسفل) متماثلة عند جميع الأجسام المضادة، والمنطقة المتغيرة (الأعلى) تتغير حسب المستضد. منهجية البكالوريا : استخراج المعلومات الجزيئية ما هو مميزات البنية الفراغية للجسم المضاد؟","keywords":["البنيه","الجزيييه","المفصله","للجسم","المضاد","سلاسل","بيبتيديه","ثقيله","خفيفه","الدرس","مصدر","الاجسام","المضاده","للرحلان","الكهربايي","وبنيه","الجسم","سلسلتان"],"aliases":["البنية الجزيئية المفصلة للجسم المضاد (4 سلاسل بيبتيدية","2 ثقيلة H + 2 خفيفة L)"]},{"id":"lhx_phase6_chapitres_11_12_card2_2","kind":"html","lessonKey":"phase6_chapitres_11_12","title":"البنية الجزيئية المفصلة للجسم المضاد (4 سلاسل بيبتيدية : 2 ثقيلة H + 2 خفيفة L) (2/2)","lessonTitle":"الدرس 5 : مصدر الأجسام المضادة","unitId":4,"part":2,"total":2,"text":"الجسم المضاد بروتين ينتمي لمجموعة غلوبيلينات غاما ( γ-globulines ) ، يتكون من 4 سلاسل بيبتيدية : • سلسلتان ثقيلتان ( Chaînes Lourdes - H ) متماثلتان داخل الجزيء. • سلسلتان خفيفتان ( Chaînes Légères - L ) متماثلتان. • ترتبط السلاسل فيما بينها بواسطة جسور ثنائية الكبريت ( Ponts disulfures S-S ) . • التخصص الفائق : يمتلك الجسم المضاد موقعين متماثلين لتثبيت محدد المستضد في قمة المنطقة المتغيرة، يتكاملان بنيوياً معه بدقة.","keywords":["البنيه","الجزيييه","المفصله","للجسم","المضاد","سلاسل","بيبتيديه","ثقيله","خفيفه","الدرس","مصدر","الاجسام","المضاده","الجسم","بروتين","ينتمي","لمجموعه","غلوبيلينات"],"aliases":["البنية الجزيئية المفصلة للجسم المضاد (4 سلاسل بيبتيدية","2 ثقيلة H + 2 خفيفة L)"]},{"id":"lhx_phase6_chapitres_11_12_card3_1","kind":"html","lessonKey":"phase6_chapitres_11_12","title":"⭐ المنطقة المتغيرة (المتخصصة في المستضد)","lessonTitle":"الدرس 5 : مصدر الأجسام المضادة","unitId":4,"part":1,"total":1,"text":"3 مختبر تشريح الجسم المضاد التفاعلي اضغط على منطقة من الجسم المضاد لمعاينة تخصصها الوظيفي : ⭐ المنطقة المتغيرة (موقع التثبيت) ⚓ المنطقة الثابتة (موقع تثبيت البلعمية) 🔒 الجسور ثنائية الكبريت (S-S) ⭐ المنطقة المتغيرة (المتخصصة في المستضد) توجد في نهايات السلاسل الثقيلة والخفيفة (الجزء العلوي لحرف Y). تختلف متتالية الأحماض الأمينية في هذه المنطقة باختلاف المستضد، مما يمنح الجسم المضاد خصوصية فائقة تشبه المفتاح والقفل مع محدد المستضد ( Épitope ).","keywords":["المنطقه","المتغيره","المتخصصه","المستضد","الدرس","مصدر","الاجسام","المضاده","مختبر","تشريح","الجسم","المضاد","التفاعلي","منطقه","لمعاينه","تخصصها","التثبيت","الثابته"],"aliases":["⭐ المنطقة المتغيرة (المتخصصة في المستضد)"]},{"id":"lhx_phase6_chapitres_11_12_card4_1","kind":"html","lessonKey":"phase6_chapitres_11_12","title":"1. أين تقع المنطقة المتغيرة التي تشكل موقع تثبيت محدد المستضد في جزيء الجسم المضاد؟","lessonTitle":"الدرس 5 : مصدر الأجسام المضادة","unitId":4,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. أين تقع المنطقة المتغيرة التي تشكل موقع تثبيت محدد المستضد في جزيء الجسم المضاد؟ أ) في النهايات الأمينية (الجزء العلوي) للسلاسل الثقيلة والخفيفة معاً. ب) في الجزء السفلي للسلاسل الثقيلة فقط. ج) في الجسور ثنائية الكبريت.","keywords":["اين","تقع","المنطقه","المتغيره","التي","تشكل","موقع","تثبيت","محدد","المستضد","جزيء","الجسم","المضاد؟","الدرس","مصدر","الاجسام","المضاده","النهايات"],"aliases":["1. أين تقع المنطقة المتغيرة التي تشكل موقع تثبيت محدد المستضد في جزيء الجسم المضاد؟"]},{"id":"lhx_phase6_chapitres_11_12_2_intro_1","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 4 : دور البروتينات في الدفاع عن الذات 🎯 الهدف العلمي : بيّن الطبيعة البروتينية للأجسام المضادة (غلوبيلينات غاما)، وحدّد بنيتها الجزيئية في شكل حرف Y ومواقع التخصص. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : وضّح دور المعقد المناعي في إبطال مفعول المستضد، صف المراحل الأربعة لعملية بلعمة المعقد المناعي بواسطة الماكروفاج. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["يقوم","الجسم","المضاد","بقتل","المستضد","بنفسه؟","الاول","التخصص","للبروتينات","البروتينات","الدفاع","الذات","الطبيعه","البروتينيه","للاجسام","المضاده","غلوبيلينات","بنيتها"],"aliases":["هل يقوم الجسم المضاد بقتل المستضد بنفسه؟"]},{"id":"lhx_phase6_chapitres_11_12_2_card1_1","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":1,"total":1,"text":"1 الإشكالية الأساسية لختام الاستجابة الخلطية ⚠️ هل يقوم الجسم المضاد بقتل المستضد بنفسه؟ يعتقد الكثيرون أن الجسم المضاد يقتل أو يدمر البكتيريا أو السم فور ارتباطه به، وهذا خطأ علمي فادح في البكالوريا! الجسم المضاد يرتبط بالمستضد مشكلاً المعقد المناعي ( Complexe Immun ) الذي يبطل مفعوله ويمنع انتشاره فقط. كيف يتم إذن التخلص النهائي من هذا المعقد المناعي وتدميره داخل الجسم؟","keywords":["يقوم","الجسم","المضاد","بقتل","المستضد","بنفسه؟","الاساسيه","لختام","الاستجابه","الخلطيه","يعتقد","الكثيرون","البكتيريا","ارتباطه","يرتبط","بالمستضد","مشكلا","المعقد"],"aliases":["هل يقوم الجسم المضاد بقتل المستضد بنفسه؟"]},{"id":"lhx_phase6_chapitres_11_12_2_card2_1","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"مراحل بلعمة المعقد المناعي (التثبيت ← الابتلاع ← الهضم ← الإطراح) (1/2)","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":1,"total":2,"text":"2 التحليل المنهجي لخطوات البلعمة (Phagocytose) بتدخل البلعمية الكبيرة (Macrophage) مراحل بلعمة المعقد المناعي (التثبيت ← الابتلاع ← الهضم ← الإطراح) مستقبل غشائي للموقع Fc Ag البلعمية الكبيرة (Macrophage) ليزوزومات تفرز إنزيمات هاضمة 💡 يثبت الماكروفاج المعقد المناعي عن طريق تكامل مستقبله الغشائي مع الجزء الثابت Fc للجسم المضاد. الخطوات الأربعة المعتمدة في البكالوريا كيف يتم هضم المعقد المناعي؟ مرحلة التثبيت : يرتبط الجزء الثابت ( Fc ) للجسم المضاد في المعقد المناعي بمستقبلات غشائية نوعية على سطح البلعمية الكبيرة.","keywords":["مراحل","بلعمه","المعقد","المناعي","التثبيت","الابتلاع","الهضم","الاطراح","يقوم","الجسم","المضاد","بقتل","المستضد","بنفسه؟","لخطوات","البلعمه","phagocytose","بتدخل"],"aliases":["مراحل بلعمة المعقد المناعي (التثبيت ← الابتلاع ← الهضم ← الإطراح)"]},{"id":"lhx_phase6_chapitres_11_12_2_card2_2","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"مراحل بلعمة المعقد المناعي (التثبيت ← الابتلاع ← الهضم ← الإطراح) (2/2)","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":2,"total":2,"text":"مرحلة الابتلاع : ترسل البلعمية أرجلاً كاذبة ( Pseudopodes ) تحيط بالمعقد المناعي وتشكل فجوة بلعمية ( Phagosome ). مرحلة الهضم : تلتحم الليزوزومات ( Lysosomes ) مع الفجوة وتفرز إنزيمات التحلل المائي لتفكيك المستضد والجسم المضاد. مرحلة الإطراح : تطرح فضلات الهضم خارج الخلية.","keywords":["مراحل","بلعمه","المعقد","المناعي","التثبيت","الابتلاع","الهضم","الاطراح","يقوم","الجسم","المضاد","بقتل","المستضد","بنفسه؟","مرحله","البلعميه","ارجلا","كاذبه"],"aliases":["مراحل بلعمة المعقد المناعي (التثبيت ← الابتلاع ← الهضم ← الإطراح)"]},{"id":"lhx_phase6_chapitres_11_12_2_card3_1","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"1️⃣ التثبيت النوعي على مستقبلات البلعمية","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":1,"total":1,"text":"3 محاكي البلعمة التفاعلي خطوة بخطوة اضغط لتنفيذ مراحل القضاء النهائي على المعقد المناعي : 1️⃣ التثبيت على المستقبل Fc 2️⃣ الإحاطة والابتلاع 3️⃣ الهضم الليزوزومي 1️⃣ التثبيت النوعي على مستقبلات البلعمية تتميز البلعميات الكبيرة بامتلاك مستقبلات غشائية تتكامل بنيوياً مع المنطقة الثابتة ( Fragment Fc ) للأجسام المضادة. هذا التثبيت يسرع ويسهل عملية البلعمة مقارنة بابتلاع المستضد لوحده.","keywords":["التثبيت","النوعي","علي","مستقبلات","البلعميه","يقوم","الجسم","المضاد","بقتل","المستضد","بنفسه؟","محاكي","البلعمه","التفاعلي","بخطوه","لتنفيذ","مراحل","القضاء"],"aliases":["1️⃣ التثبيت النوعي على مستقبلات البلعمية"]},{"id":"lhx_phase6_chapitres_11_12_2_card4_1","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 بيّن مصدر الأجسام المضادة، وفسّر الفرق بين الاستجابة الأولية والثانوية. تصنع الأجسام المضادة من طرف اللمفاويات B المتمايزة إلى خلايا بلازمية. تتميز الاستجابة المناعية الأولية بفترة كامن وبمستوى أجسام مضادة منخفض. يولد التلقيح الثاني استجابة ثانوية أسرع وأقوى بفضل خلايا الذاكرة. تضمن خلايا الذاكرة المناعة المكتسبة طويلة المدى. تتزايد الأجسام المضادة بعد التلقيح الأول ثم تتناقص بعد زوال المستضد من الوسط الداخلي. 🔑 المصطلح المفتاحي في البكالوريا : الاستجابة الأولية والثانوية / خلايا الذاكرة","keywords":["يقوم","الجسم","المضاد","بقتل","المستضد","بنفسه؟","خلاصه","الدرس","الاجسام","المضاده،","الفرق","الاستجابه","الاوليه","والثانويه","المضاده","اللمفاويات","المتمايزه","خلايا"],"aliases":["هل يقوم الجسم المضاد بقتل المستضد بنفسه؟"]},{"id":"lhx_phase6_chapitres_11_12_2_card5_1","kind":"html","lessonKey":"phase6_chapitres_11_12_2","title":"1. ما هو الدور المباشر الذي يلعبه تشكل \"المعقد المناعي\" (ارتباط الجسم المضاد بالمستضد)؟","lessonTitle":"هل يقوم الجسم المضاد بقتل المستضد بنفسه؟","unitId":4,"part":1,"total":1,"text":"4 تقويم النشاط 4 : أسئلة البكالوريا المتكررة 1. ما هو الدور المباشر الذي يلعبه تشكل \"المعقد المناعي\" (ارتباط الجسم المضاد بالمستضد)؟ أ) إبطال مفعول المستضد (منع تكاثره وانتشاره وتأثيره السام) وتسهيل بلعمته من طرف الماكروفاج. ب) التحلل الذاتي والفوري للبكتيريا دون الحاجة لبلعميات. ج) تحويل المستضد إلى كريات دم حمراء.","keywords":["الدور","المباشر","الذي","يلعبه","تشكل","المعقد","المناعي","ارتباط","الجسم","المضاد","بالمستضد","يقوم","بقتل","المستضد","بنفسه؟","ابطال","مفعول","تكاثره"],"aliases":["1. ما هو الدور المباشر الذي يلعبه تشكل \"المعقد المناعي\" (ارتباط الجسم المضاد بالمستضد)؟"]},{"id":"lhx_phase7_chapitres_13_14_intro_1","kind":"html","lessonKey":"phase7_chapitres_13_14","title":"الدرس 7 : طرق تأثير اللمفاويات LTc","lessonTitle":"الدرس 7 : طرق تأثير اللمفاويات LTc","unitId":4,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 4 : دور البروتينات في الدفاع عن الذات 🎯 الهدف العلمي : حدّد آلية التعرف المزدوج للخلايا اللمفاوية السامة (LTc) على الخلية المصابة، وفسّر الصدمة الحلولية بواسطة البرفورين والغرانزيم. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن أن الخلايا LT4 هي المايسترو المحور المركزي للاستجابة المناعية (الخلطية والخلوية معاً) عن طريق إفراز هرمون الأنترلوكين-2. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","طرق","تاثير","اللمفاويات","ltc","الاول","التخصص","للبروتينات","البروتينات","الدفاع","الذات","التعرف","المزدوج","للخلايا","اللمفاويه","السامه","المصابه،","الصدمه"],"aliases":["الدرس 7","طرق تأثير اللمفاويات LTc"]},{"id":"lhx_phase7_chapitres_13_14_card1_1","kind":"html","lessonKey":"phase7_chapitres_13_14","title":"الدرس 7 : طرق تأثير اللمفاويات LTc","lessonTitle":"الدرس 7 : طرق تأثير اللمفاويات LTc","unitId":4,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف يقضي الجسم على الفيروسات المختبئة داخل الخلايا المصابة؟ الأجسام المضادة في الدم واللمف لا تستطيع الدخول إلى داخل الخلايا المصابة بالفيروسات ولا تستطيع الوصول إلى الخلايا السرطانية. لذلك يتدخل نمط آخر من المناعة يعتمد على خلايا قاتلة متخصصة تسمى الخلايا اللمفاوية التائية السامة ( LTc - T cytotoxiques ) الناتجة عن تمايز اللمفاويات LT8 . كيف تتعرف الخلية التائية القاتلة على الخلية المصابة بدقة؟ وكيف تقوم بتفجيرها وإعدامها؟","keywords":["الدرس","طرق","تاثير","اللمفاويات","ltc","وضعيه","الانطلاق","وبناء","العلميه","الجسم","الفيروسات","المختبيه","الخلايا","المصابه؟","الاجسام","المضاده","واللمف","تستطيع"],"aliases":["الدرس 7","طرق تأثير اللمفاويات LTc"]},{"id":"lhx_phase7_chapitres_13_14_card2_1","kind":"html","lessonKey":"phase7_chapitres_13_14","title":"آلية التعرف المزدوج وإفراز البرفورين لإحداث الصدمة الحلولية (1/2)","lessonTitle":"الدرس 7 : طرق تأثير اللمفاويات LTc","unitId":4,"part":1,"total":2,"text":"2 التحليل المنهجي للتعرف المزدوج والصدمة الحلولية (البرفورين Perforine) آلية التعرف المزدوج وإفراز البرفورين لإحداث الصدمة الحلولية الخلية اللمفاوية القاتلة (LTc) TCR CD8 الخلية المصابة بالفيروس Ag جزيئات البرفورين 💡 يتكامل مستقبل TCR مع المستضد، ومؤشر CD8 مع جزيئة CMH-I (تعرف مزدوج). منهجية البكالوريا : تفاصيل الصدمة الحلولية كيف تعدم الخلية LTc الخلية المصابة؟ التعرف المزدوج ( Double reconnaissance ) : يرتبط مستقبل TCR للخلية LTc بالبيبتيد المستضدي، ويرتبط مؤشر CD8 بجزيئة CMH-I للخلية المصابة.","keywords":["اليه","التعرف","المزدوج","وافراز","البرفورين","لاحداث","الصدمه","الحلوليه","الدرس","طرق","تاثير","اللمفاويات","ltc","للتعرف","والصدمه","perforine","اللمفاويه","القاتله"],"aliases":["آلية التعرف المزدوج وإفراز البرفورين لإحداث الصدمة الحلولية"]},{"id":"lhx_phase7_chapitres_13_14_card2_2","kind":"html","lessonKey":"phase7_chapitres_13_14","title":"آلية التعرف المزدوج وإفراز البرفورين لإحداث الصدمة الحلولية (2/2)","lessonTitle":"الدرس 7 : طرق تأثير اللمفاويات LTc","unitId":4,"part":2,"total":2,"text":"إفراز البرفورين والغرانزيم : يثير التعرف المزدوج إفراز حويصلات تحتوي على بروتينات البرفورين ( Perforine ) وإنزيمات الغرانزيم ( Granzyme ) . تشكل الثقوب الغشائية : تتبلمر جزيئات البرفورين بوجود شوارد الكالسيوم مشكلة ثقوباً وأنابيب مفتوحة في غشاء الخلية المصابة. الصدمة الحلولية ( Choc osmotique ) : يدخل الماء والشوارد بكثافة عبر الثقوب فتنفجر الخلية المصابة، ويدخل الغرانزيم ليهدم الـ ADN ويحفز الانتحار الخلوي.","keywords":["اليه","التعرف","المزدوج","وافراز","البرفورين","لاحداث","الصدمه","الحلوليه","الدرس","طرق","تاثير","اللمفاويات","ltc","افراز","والغرانزيم","حويصلات","تحتوي","بروتينات"],"aliases":["آلية التعرف المزدوج وإفراز البرفورين لإحداث الصدمة الحلولية"]},{"id":"lhx_phase7_chapitres_13_14_card3_1","kind":"html","lessonKey":"phase7_chapitres_13_14","title":"1️⃣ التعرف المزدوج الدقيق","lessonTitle":"الدرس 7 : طرق تأثير اللمفاويات LTc","unitId":4,"part":1,"total":1,"text":"3 محاكي \"قبلة الموت\" الخلوية التفاعلي اضغط لمتابعة المراحل المتسلسلة لعملية القضاء الخلوي : 1️⃣ التعرف المزدوج والالتصاق 2️⃣ إفراز وبلمرة البرفورين 3️⃣ انفجار الخلية المصابة 1️⃣ التعرف المزدوج الدقيق تضمن الخلية القاتلة LTc أنها لا تهاجم إلا الخلية التابعة للذات المصابة بالمستضد المحدد، وذلك باشتراط تطابق الـ CD8 مع CMH-I وتطابق الـ TCR مع المستضد معاً.","keywords":["التعرف","المزدوج","الدقيق","الدرس","طرق","تاثير","اللمفاويات","ltc","محاكي","الموت","الخلويه","التفاعلي","لمتابعه","المراحل","المتسلسله","لعمليه","القضاء","الخلوي"],"aliases":["1️⃣ التعرف المزدوج الدقيق"]},{"id":"lhx_phase7_chapitres_13_14_card4_1","kind":"html","lessonKey":"phase7_chapitres_13_14","title":"1. ما هو الدور الدقيق الذي يلعبه بروتين \"البرفورين\" ( Perforine ) في القضاء على الخلية المصابة؟","lessonTitle":"الدرس 7 : طرق تأثير اللمفاويات LTc","unitId":4,"part":1,"total":1,"text":"4 تقويم النشاط 5 : أسئلة البكالوريا المتكررة 1. ما هو الدور الدقيق الذي يلعبه بروتين \"البرفورين\" ( Perforine ) في القضاء على الخلية المصابة؟ أ) يتبلمر في غشاء الخلية المصابة مشكلاً ثقوباً تسمح بدخول الماء والشوارد والغرانزيم لإحداث صدمة حلولية مميتة. ب) يتحول إلى جسم مضاد يرتبط بالفيروس في الدم. ج) يقوم ببلعمة الخلية السرطانية مباشرة.","keywords":["الدور","الدقيق","الذي","يلعبه","بروتين","البرفورين","perforine","القضاء","علي","الخليه","المصابه؟","الدرس","طرق","تاثير","اللمفاويات","ltc","يتبلمر","المصابه"],"aliases":["1. ما هو الدور الدقيق الذي يلعبه بروتين \"البرفورين\" ( Perforine ) في القضاء على الخلية المصابة؟"]},{"id":"lhx_phase7_chapitres_13_14_2_intro_1","kind":"html","lessonKey":"phase7_chapitres_13_14_2","title":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","lessonTitle":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","unitId":4,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 4 : دور البروتينات في الدفاع عن الذات 🎯 الهدف العلمي : حدّد آلية التعرف المزدوج للخلايا اللمفاوية السامة (LTc) على الخلية المصابة، وفسّر الصدمة الحلولية بواسطة البرفورين والغرانزيم. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن أن الخلايا LT4 هي المايسترو المحور المركزي للاستجابة المناعية (الخلطية والخلوية معاً) عن طريق إفراز هرمون الأنترلوكين-2. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","يدمر","فيروس","الايدز","vih","المناعه","بالكامل","رغم","انه","يهاجم","خلايا","lt4","فقط؟","الاول","التخصص","للبروتينات","البروتينات","الدفاع"],"aliases":["لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟"]},{"id":"lhx_phase7_chapitres_13_14_2_card1_1","kind":"html","lessonKey":"phase7_chapitres_13_14_2","title":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","lessonTitle":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","unitId":4,"part":1,"total":1,"text":"1 الإشكالية الكبرى لختام وحدة المناعة ⚠️ لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟ يهاجم فيروس السيدا ( VIH ) حصرياً الخلايا اللمفاوية التائية المساعدة LT4 (التي تحمل مؤشر CD4 ) . وعندما يتناقص عدد خلايا LT4 ، تنهار المناعة الخلطية (إنتاج الأجسام المضادة من طرف LB ) وتنهار المناعة الخلوية ( LTc ) معاً، فيموت المريض بأبسط الأمراض الانتهازية! كيف تفسر هذا الدور المحوري والخارق لخلايا LT4 في التنسيق بين جميع الخلايا المناعية؟","keywords":["لماذا","يدمر","فيروس","الايدز","vih","المناعه","بالكامل","رغم","انه","يهاجم","خلايا","lt4","فقط؟","الكبري","لختام","السيدا","حصريا","الخلايا"],"aliases":["لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟"]},{"id":"lhx_phase7_chapitres_13_14_2_card2_1","kind":"html","lessonKey":"phase7_chapitres_13_14_2","title":"مخطط التنسيق والتحفيز بواسطة الأنترلوكين-2 المفرز من خلايا LTh المساعدة (1/2)","lessonTitle":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","unitId":4,"part":1,"total":2,"text":"2 التحليل المنهجي للتعاون الخلوي وإفراز مبلغ الأنترلوكين-2 (IL-2) مخطط التنسيق والتحفيز بواسطة الأنترلوكين-2 المفرز من خلايا LTh المساعدة LT4 المساعدة IL-2 IL-2 الخلية LB الخلية LT8 💡 بدون هرمون IL-2 لا تتكاثر ولا تتمايز الخلايا LB ولا LT8. سر البكالوريا في المناعة لماذا تعتبر LT4 محور المناعة النوعية؟ تتعرف خلايا LT4 بواسطة مؤشر CD4 على البيبتيد المستضدي المعروض على جزيئة CMH-II للبلعميات الكبيرة ( CPA ). بعد التعرف،","keywords":["مخطط","التنسيق","والتحفيز","بواسطه","الانترلوكين","المفرز","خلايا","lth","المساعده","لماذا","يدمر","فيروس","الايدز","vih","المناعه","بالكامل","رغم","انه"],"aliases":["مخطط التنسيق والتحفيز بواسطة الأنترلوكين-2 المفرز من خلايا LTh المساعدة"]},{"id":"lhx_phase7_chapitres_13_14_2_card2_2","kind":"html","lessonKey":"phase7_chapitres_13_14_2","title":"مخطط التنسيق والتحفيز بواسطة الأنترلوكين-2 المفرز من خلايا LTh المساعدة (2/2)","lessonTitle":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","unitId":4,"part":2,"total":2,"text":"تتكاثر وتتمايز إلى خلايا مساعدة ( LTh - T helper ) تفرز مبلغاً كيميائياً أساسياً هو الأنترلوكين-2 ( Interleukine-2 IL-2 ) الذي يعمل على : • تحفيز تكاثر وتمايز LB المحسسة إلى خلايا بلازمية منتجة للأجسام المضادة. • تحفيز تكاثر وتمايز LT8 المحسسة إلى خلايا قاتلة LTc . 🔑 قاعدة اختيار نمط الاستجابة المناسبة (BAC) : مستضد داخل خلوي (فيروس داخل خلية، خلية سرطانية) ← استجابة خلوية (LTc) · مستضد خارج خلوي حر (بكتيريا حرة، سم، فيروس حر في الأخلاط) ← استجابة خلطية (أجسام مضادة) · المنسق في الحالتين خلايا LT4 عبر IL-2 .","keywords":["مخطط","التنسيق","والتحفيز","بواسطه","الانترلوكين","المفرز","خلايا","lth","المساعده","لماذا","يدمر","فيروس","الايدز","vih","المناعه","بالكامل","رغم","انه"],"aliases":["مخطط التنسيق والتحفيز بواسطة الأنترلوكين-2 المفرز من خلايا LTh المساعدة"]},{"id":"lhx_phase7_chapitres_13_14_2_card3_1","kind":"html","lessonKey":"phase7_chapitres_13_14_2","title":"🟢 استجابة مناعية قوية ومتكاملة","lessonTitle":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","unitId":4,"part":1,"total":1,"text":"3 مختبر أوركسترا المناعة التفاعلي اختبر حدوث الاستجابة المناعية في وجود وفي غياب خلايا المايسترو LT4 : 🟢 مناعة طبيعية بوجود خلايا LT4 🔴 غياب خلايا LT4 (مرض السيدا VIH) 🟢 استجابة مناعية قوية ومتكاملة تفرز خلايا LTh كميات وفيرة من مبلغ IL-2 . تستجيب اللمفاويات LB وتنتج ملايين الأجسام المضادة، وتستجيب اللمفاويات LT8 وتتحول لجحافل قاتلة LTc ، فيتم تطهير العضوية بنجاح من المستضد.","keywords":["استجابه","مناعيه","قويه","ومتكامله","لماذا","يدمر","فيروس","الايدز","vih","المناعه","بالكامل","رغم","انه","يهاجم","خلايا","lt4","فقط؟","مختبر"],"aliases":["🟢 استجابة مناعية قوية ومتكاملة"]},{"id":"lhx_phase7_chapitres_13_14_2_card4_1","kind":"html","lessonKey":"phase7_chapitres_13_14_2","title":"1. لماذا لا تستجيب الخلايا اللمفاوية غير المحسسة (التي لم تتعرف بعد على المستضد) لهرمون الأنترلوكين-2 ( IL-2 )؟","lessonTitle":"لماذا يدمر فيروس الإيدز (VIH) المناعة بالكامل رغم أنه يهاجم خلايا LT4 فقط؟","unitId":4,"part":1,"total":1,"text":"4 تقويم النشاط 6 : أسئلة البكالوريا المتكررة 1. لماذا لا تستجيب الخلايا اللمفاوية غير المحسسة (التي لم تتعرف بعد على المستضد) لهرمون الأنترلوكين-2 ( IL-2 )؟ أ) لأن الخلية اللمفاوية لا تقوم بتركيب وعرض المستقبلات الغشائية الخاصة بالـ IL-2 إلا بعد تعرفها وتنشيطها بالمستضد. ب) لأن هرمون IL-2 يدمر الخلايا غير المحسسة. ج) لأن الخلايا غير المحسسة لا تمتلك غشاء هيولياً.","keywords":["لماذا","تستجيب","الخلايا","اللمفاويه","غير","المحسسه","التي","تتعرف","بعد","علي","المستضد","لهرمون","الانترلوكين","يدمر","فيروس","الايدز","vih","المناعه"],"aliases":["1. لماذا لا تستجيب الخلايا اللمفاوية غير المحسسة (التي لم تتعرف بعد على المستضد) لهرمون الأنترلوكين-2 ( IL-2 )؟"]},{"id":"lhx_phase8_chapitres_15_16_intro_1","kind":"html","lessonKey":"phase8_chapitres_15_16","title":"الدرس 4 : كمون الراحة","lessonTitle":"الدرس 4 : كمون الراحة","unitId":5,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 5 : دور البروتينات في الاتصال العصبي 🎯 الهدف العلمي : حدّد أصل كمون الراحة (توزع الأيونات غير المتكافئ) ووضّح دور قنوات التسرب ومضخة الصوديوم/بوتاسيوم المستهلكة للـ ATP. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر أطوار منحنى كمون العمل (زوال الاستقطاب، عودة الاستقطاب، فرط الاستقطاب) بالعمل المتسلسل للقنوات الفولطية للـ Na⁺ والـ K⁺. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","كمون","الراحه","الاول","التخصص","للبروتينات","البروتينات","الاتصال","العصبي","الايونات","المتكافي","قنوات","التسرب","ومضخه","الصوديوم","بوتاسيوم","المستهلكه","اطوار"],"aliases":["الدرس 4","كمون الراحة"]},{"id":"lhx_phase8_chapitres_15_16_card1_1","kind":"html","lessonKey":"phase8_chapitres_15_16","title":"الدرس 4 : كمون الراحة","lessonTitle":"الدرس 4 : كمون الراحة","unitId":5,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا يكون داخل الليف العصبي سالباً وخارجه موجباً أثناء الراحة؟ عند وضع إلكترود داخل ليف عصبي حي غير مستثار وإلكترود آخر على سطحه، نقيس فرق جهد ثابت يقارب -70 mV يسمى كمون الراحة ( Potentiel de repos ) . وهذا يعني أن غشاء الليف العصبي مستقطب كهربائياً. ما هي البروتينات الغشائية المسؤولة عن نشأة وثبات هذا الاستقطاب رغم وجود ظاهرة الانتشار الغشائي للأيونات؟","keywords":["الدرس","كمون","الراحه","وضعيه","الانطلاق","وبناء","العلميه","الليف","العصبي","سالبا","وخارجه","موجبا","اثناء","الراحه؟","الكترود","مستثار","والكترود","سطحه،"],"aliases":["الدرس 4","كمون الراحة"]},{"id":"lhx_phase8_chapitres_15_16_card2_1","kind":"html","lessonKey":"phase8_chapitres_15_16","title":"البروتينات المتدخلة في كمون الراحة على الغشاء الهيولي لليف العصبي (1/2)","lessonTitle":"الدرس 4 : كمون الراحة","unitId":5,"part":1,"total":2,"text":"2 التحليل المنهجي لقنوات التسرب المفتوحة باستمرار ومضخة Na⁺/K⁺-ATPase البروتينات المتدخلة في كمون الراحة على الغشاء الهيولي لليف العصبي الوسط الخارجي (غني بـ Na⁺ موجب +) الوسط الداخلي (غني بـ K⁺ سالب -70 mV) قناة تسرب K⁺ (خروج وفق التدرج) قناة تسرب Na⁺ (دخول وفق التدرج) مضخة ATP خروج 3 Na⁺ دخول 2 K⁺ 💡 تعمل المضخة عكس تدرج التركيز باستهلاك الطاقة (ATP) للحفاظ على ثبات كمون الراحة. منهجية البكالوريا : التفسير الأيوني الدقيق كيف يثبت الكمون عند -70 mV ؟ توزع غير متساوٍ للأيونات : تركيز Na⁺ مرتفع في الخارج،","keywords":["البروتينات","المتدخله","كمون","الراحه","علي","الغشاء","الهيولي","لليف","العصبي","الدرس","لقنوات","التسرب","المفتوحه","باستمرار","ومضخه","atpase","الوسط","الخارجي"],"aliases":["البروتينات المتدخلة في كمون الراحة على الغشاء الهيولي لليف العصبي"]},{"id":"lhx_phase8_chapitres_15_16_card2_2","kind":"html","lessonKey":"phase8_chapitres_15_16","title":"البروتينات المتدخلة في كمون الراحة على الغشاء الهيولي لليف العصبي (2/2)","lessonTitle":"الدرس 4 : كمون الراحة","unitId":5,"part":2,"total":2,"text":"وتركيز K⁺ مرتفع في الداخل. قنوات التسرب (التسرب المفتوحة باستمرار) : يسمح نفاذية الغشاء لـ K⁺ بالخروج نحو الخارج (نفاذية أكبر)، ودخول قليل لـ Na⁺ نحو الداخل، مما يجعل الداخل سالباً والخارج موجباً. مضخة الصوديوم/بوتاسيوم ( Pompe Na⁺/K⁺ ) : لو استمر التسرب لتساوى التركيز وزال الكمون! لذلك تتدخل المضخة لتطرح 3 شوارد Na⁺ نحو الخارج وتدخل شاردتي 2 K⁺ نحو الداخل عكس تدرج التركيز باستهلاك طاقة ATP .","keywords":["البروتينات","المتدخله","كمون","الراحه","علي","الغشاء","الهيولي","لليف","العصبي","الدرس","وتركيز","مرتفع","الداخل","قنوات","التسرب","المفتوحه","باستمرار","نفاذيه"],"aliases":["البروتينات المتدخلة في كمون الراحة على الغشاء الهيولي لليف العصبي"]},{"id":"lhx_phase8_chapitres_15_16_card3_1","kind":"html","lessonKey":"phase8_chapitres_15_16","title":"🟢 ثبات كمون الراحة عند (-70 mV)","lessonTitle":"الدرس 4 : كمون الراحة","unitId":5,"part":1,"total":1,"text":"3 محاكي مضخة الصوديوم/بوتاسيوم التفاعلي اختبر تأثير تثبيط المضخة (بواسطة سم السيانيد أو الدنيتروفينول DNP المانع لإنتاج ATP) : 🟢 الحالة العادية (مضخة نشطة بوجود ATP) 🔴 إضافة مادة DNP (توقف إنتاج ATP) 🟢 ثبات كمون الراحة عند (-70 mV) تستهلك المضخة جزيئات الـ ATP لتعوض باستمرار شوارد Na⁺ و K⁺ المتسربة عبر قنوات التسرب. يظل التباين الأيوني ثابتاً ويبقى الليف مستقطباً وجاهزاً لنقل السيالة العصبية.","keywords":["ثبات","كمون","الراحه","عند","الدرس","محاكي","الصوديوم","بوتاسيوم","التفاعلي","اختبر","تاثير","تثبيط","المضخه","بواسطه","السيانيد","الدنيتروفينول","المانع","لانتاج"],"aliases":["🟢 ثبات كمون الراحة عند (-70 mV)"]},{"id":"lhx_phase8_chapitres_15_16_card4_1","kind":"html","lessonKey":"phase8_chapitres_15_16","title":"1. ما هو نوع النقل الذي تقوم به مضخة ( Na⁺/K⁺-ATPase )؟","lessonTitle":"الدرس 4 : كمون الراحة","unitId":5,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ما هو نوع النقل الذي تقوم به مضخة ( Na⁺/K⁺-ATPase )؟ أ) نقل فعال ( Transport actif ) يتم عكس تدرج التركيز ويستهلك طاقة جزيئة الـ ATP . ب) انتشار حر وسلبي وفق تدرج التركيز دون طاقة. ج) بلعمة خلوية.","keywords":["نوع","النقل","الذي","تقوم","مضخه","atpase","الدرس","كمون","الراحه","transport","actif","التركيز","ويستهلك","جزييه","انتشار","وسلبي","بلعمه","خلويه"],"aliases":["1. ما هو نوع النقل الذي تقوم به مضخة ( Na⁺/K⁺-ATPase )؟"]},{"id":"lhx_phase8_chapitres_15_16_2_intro_1","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 5 : دور البروتينات في الاتصال العصبي 🎯 الهدف العلمي : حدّد أصل كمون الراحة (توزع الأيونات غير المتكافئ) ووضّح دور قنوات التسرب ومضخة الصوديوم/بوتاسيوم المستهلكة للـ ATP. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر أطوار منحنى كمون العمل (زوال الاستقطاب، عودة الاستقطاب، فرط الاستقطاب) بالعمل المتسلسل للقنوات الفولطية للـ Na⁺ والـ K⁺. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول","الليف","العصبي","اجزاء","الملي","ثانيه؟","الاول","التخصص","للبروتينات","البروتينات","الاتصال","الراحه"],"aliases":["كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟"]},{"id":"lhx_phase8_chapitres_15_16_2_card1_1","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":1,"total":1,"text":"1 الإشكالية الأيونية لكمون العمل ⚠️ كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟ عند إحداث تنبيه فعال لليف عصبي (تنبيه يفوق عتبة زوال الاستقطاب Seuil > -50 mV )، تظهر موجة سريعة ومميزة تسمى كمون العمل ( Potentiel d'Action PA ) يبلغ ذروته عند +30 mV ثم يعود للراحة. ما هي القنوات الغشائية التي تنفتح وتنغلق بدقة زمنية فائقة لتوليد هذا الكمون؟","keywords":["كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول","الليف","العصبي","اجزاء","الملي","ثانيه؟","الايونيه","لكمون","العمل","احداث","تنبيه","الاستقطاب"],"aliases":["كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟"]},{"id":"lhx_phase8_chapitres_15_16_2_card2_1","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"منحنى كمون العمل أحادي الطور والأطوار الأيونية الموافقة (1/2)","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":1,"total":2,"text":"2 التحليل المنهجي لمنحنى كمون العمل والقنوات المبوبة كهربائياً منحنى كمون العمل أحادي الطور والأطوار الأيونية الموافقة -70 mV +30 mV 1. زوال الاستقطاب (دخول Na⁺) 2. عودة الاستقطاب (خروج K⁺) 3. فرط الاستقطاب 📈 تنفتح قنوات Na⁺ الفولطية أولاً وبسرعة، ثم تنغلق وتفتح قنوات K⁺ الفولطية ببطء. التفسير الأيوني المفصل في البكالوريا ماذا يحدث في كل طور من أطوار كمون العمل؟ زوال الاستقطاب ( Dépolarisation من -70 إلى +30 mV ) : انفتح سريع للقنوات المبوبة كهربائياً للـ Na⁺ ، فيدخل الصوديوم بكثافة نحو الداخل وفق تدرج التركيز.","keywords":["منحني","كمون","العمل","احادي","الطور","والاطوار","الايونيه","الموافقه","كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول","الليف","العصبي","اجزاء"],"aliases":["منحنى كمون العمل أحادي الطور والأطوار الأيونية الموافقة"]},{"id":"lhx_phase8_chapitres_15_16_2_card2_2","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"منحنى كمون العمل أحادي الطور والأطوار الأيونية الموافقة (2/2)","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":2,"total":2,"text":"عودة الاستقطاب ( Repolarisation نحو -70 mV ) : انغلاق قنوات Na⁺ الفولطية وانفتح القنوات المبوبة كهربائياً للـ K⁺ ، فيخرج البوتاسيوم نحو الخارج. فرط الاستقطاب ( Hyperpolarisation نحو -80 mV ) : تأخر انغلاق قنوات K⁺ الفولطية مما يؤدي لاستمرار خروج البوتاسيوم. العودة للراحة : تدخل مضخة Na⁺/K⁺-ATPase لاسترجاع التراكيز الأصلية.","keywords":["منحني","كمون","العمل","احادي","الطور","والاطوار","الايونيه","الموافقه","كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول","الليف","العصبي","اجزاء"],"aliases":["منحنى كمون العمل أحادي الطور والأطوار الأيونية الموافقة"]},{"id":"lhx_phase8_chapitres_15_16_2_card3_1","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"1️⃣ زوال الاستقطاب الصاعق (+30 mV)","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":1,"total":1,"text":"3 محاكي أطوار كمون العمل التفاعلي اضغط على الطور لمشاهدة حالة القنوات الفولطية في غشاء الليف : 1️⃣ طور زوال الاستقطاب 2️⃣ طور عودة الاستقطاب 3️⃣ طور فرط الاستقطاب 1️⃣ زوال الاستقطاب الصاعق (+30 mV) تفتح قنوات الصوديوم الفولطية ( Canaux Na⁺ voltage-dépendants ) بسرعة فائقة. يدخل تيار جارف من شوارد Na⁺ الموجبة إلى داخل الليف، فينقلب شحنته من سالب إلى موجب.","keywords":["زوال","الاستقطاب","الصاعق","+30","كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول","الليف","العصبي","اجزاء","الملي","ثانيه؟","محاكي","اطوار"],"aliases":["1️⃣ زوال الاستقطاب الصاعق (+30 mV)"]},{"id":"lhx_phase8_chapitres_15_16_2_card4_1","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر الأساس الأيوني والبروتيني لكمون الراحة عند العصبون. يسجل غشاء العصبون في حالة الراحة فرق جهد يقدر بحوالي −70 mV. ينشأ كمون الراحة من تفاوت تركيز الأيونات بين الوسط الداخلي والخارجي. يعمل الغشاء في الراحة منفذاً أكثر لشوارد K+ التي تخرج بالانتشار البسيط. تضمن مضخة Na+/K+ (باستهلاك ATP) حفظ التفاوت في التركيزات الأيونية. يقوم التوازن الكهركيميائي عند حد تثبت قيمة كمون الراحة. 🔑 المصطلح المفتاحي في البكالوريا : كمون الراحة / مضخة Na+ و K+","keywords":["كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول","الليف","العصبي","اجزاء","الملي","ثانيه؟","خلاصه","الدرس","الاساس","الايوني","والبروتيني","لكمون"],"aliases":["كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟"]},{"id":"lhx_phase8_chapitres_15_16_2_card5_1","kind":"html","lessonKey":"phase8_chapitres_15_16_2","title":"1. لماذا يتميز كمون العمل بخاصية \"قانون الكل أو لا شيء\" ( Loi du tout ou rien )؟","lessonTitle":"كيف تتولد وتنتقل السيالة العصبية على طول الليف العصبي في أجزاء من الملي ثانية؟","unitId":5,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. لماذا يتميز كمون العمل بخاصية \"قانون الكل أو لا شيء\" ( Loi du tout ou rien )؟ أ) لأن التنبيه الذي يقل عن العتبة ( Seuil ) لا يفتح القنوات الفولطية فلا يسجل أي كمون عمل، أما التنبيه الذي يفوق العتبة فيولد كمون عمل بسعة ثابتة دوماً (+30 mV). ب) لأن الليف العصبي يموت بعد كل تنبيه. ج) لأن سعة كمون العمل تزداد بازدياد شدة التنبيه إلى ما لا نهاية.","keywords":["لماذا","يتميز","كمون","العمل","بخاصيه","قانون","الكل","شيء","loi","tout","rien","كيف","تتولد","وتنتقل","السياله","العصبيه","علي","طول"],"aliases":["1. لماذا يتميز كمون العمل بخاصية \"قانون الكل أو لا شيء\" ( Loi du tout ou rien )؟"]},{"id":"lhx_phase9_chapitres_17_18_intro_1","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"الدرس 3 : آلية النقل المشبكي","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 5 : دور البروتينات في الاتصال العصبي 🎯 الهدف العلمي : فسّر النقل أحادي الاتجاه للرسالة العصبية على مستوى المشبك الكيميائي، ودور قنوات Ca²⁺ الفولطية والقنوات المبوبة كيميائياً وإنزيم AChE. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : وميّز بين المشبك التنبيهي والتثبيطي (GABA وتدفق Cl⁻)، واحسب الحصيلة الجبرية للتجميع الفضائي والزمني في القطعة الابتدائية SI. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","اليه","النقل","المشبكي","الاول","التخصص","للبروتينات","البروتينات","الاتصال","العصبي","احادي","الاتجاه","للرساله","العصبيه","المشبك","الكيميايي،","قنوات","الفولطيه"],"aliases":["الدرس 3","آلية النقل المشبكي"]},{"id":"lhx_phase9_chapitres_17_18_card1_1","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"الدرس 3 : آلية النقل المشبكي","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف تعبر السيالة العصبية الفراغ الفاصل بين خليتين عصبيتين؟ لا تتصل الخلايا العصبية فيما بينها اتصالاً فيزيائياً مباشراً، بل يفصل بينها فراغ دقيق يسمى الشق المشبكي ( Fente synaptique ≈ 20 nm) . ولا تستطيع السيالة الكهربائية (كمون العمل) القفز عبر هذا الشق! كيف تتحول الرسالة الكهربائية إلى رسالة كيميائية في المشبك ثم تعود لرسالة كهربائية في الخلية الموالية؟","keywords":["الدرس","اليه","النقل","المشبكي","وضعيه","الانطلاق","وبناء","العلميه","السياله","العصبيه","الفراغ","الفاصل","خليتين","عصبيتين؟","الخلايا","بينها","اتصالا","فيزياييا"],"aliases":["الدرس 3","آلية النقل المشبكي"]},{"id":"lhx_phase9_chapitres_17_18_card2_1","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي (1/3)","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":1,"total":3,"text":"2 التحليل المنهجي لخطوات النقل المشبكي الكيميائي (مشبك تنبيهي أستيل كولين) البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي الزر قبل المشبكي (Presynaptique) قنوات Ca²⁺ الشق المشبكي (تحرير الأستيل كولين ACh) الغشاء بعد المشبكي (Postsynaptique) مستقبلات-قنوات كيميائية 💡 يفتح دخول Ca²⁺ الحويصلات، ويرتبط ACh بالمستقبلات فيدخل Na⁺ ليولد PPSE. منهجية البكالوريا : الخطوات الزمنية الستة كيف تنتقل السيالة عبر المشبك؟ وصول موجة كمون العمل ( PA ) إلى الغشاء قبل المشبكي.","keywords":["البنيه","التشريحيه","والجزيييه","للمشبك","الكيميايي","التنبيهي","الدرس","اليه","النقل","المشبكي","لخطوات","تنبيهي","استيل","كولين","presynaptique","قنوات","تحرير","الاستيل"],"aliases":["البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي"]},{"id":"lhx_phase9_chapitres_17_18_card2_2","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي (2/3)","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":2,"total":3,"text":"انفتح قنوات الكالسيوم الفولطية ( Ca²⁺ voltage-dépendants ) ودخول شوارد Ca²⁺ نحو الهيولى. يحفز الكالسيوم هجرة والتحام الحويصلات المشبكية مع الغشاء وإطراح الأستيل كولين ( ACh ) في الشق المشبكي. تثبت جزيئتا ACh على الموقعين النوعيين للمستقبل القنوي ( Récepteur-canal مبوب كيميائياً ) على الغشاء بعد المشبكي. تنفتح القناة الكيميائية ويدخل تيار جارف من شوارد الصوديوم ( Na⁺ ) مولداً كموناً بعد مشبكي تنبيهي ( PPSE ) زوال استقطاب.","keywords":["البنيه","التشريحيه","والجزيييه","للمشبك","الكيميايي","التنبيهي","الدرس","اليه","النقل","المشبكي","انفتح","قنوات","الكالسيوم","الفولطيه","voltage","pendants","ودخول","شوارد"],"aliases":["البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي"]},{"id":"lhx_phase9_chapitres_17_18_card2_3","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي (3/3)","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":3,"total":3,"text":"يتدخل إنزيم الأستيل كولين إستراز ( AChE ) ليفكك ACh إلى كولين وحمض أستيك وتغلق القناة فوراً (تجنب التنبيه المستمر). 🔬 تقنية Patch-clamp (رُقاقة الغشاء) : تقنية تجريبية رسمية في الكتاب تسمح بقياس تيار أيونات عبر قناة غشائية مفردة : تُلاصَق قطارة زجاجية مجهرية بقطعة غشاء تحتوي قناة واحدة، فيُسجَّل مد وجزر الشوارد عبرها. هي التي برهنت أن القنوات تنفتح وتنغلق بشكل متقطع (وضعا مفتوح/مغلق) وأن القنوات المبوبة كهربائياً حساسة لفرق الجهد بينما القنوات الكيميائية حساسة للمبلغ العصبي.","keywords":["البنيه","التشريحيه","والجزيييه","للمشبك","الكيميايي","التنبيهي","الدرس","اليه","النقل","المشبكي","يتدخل","الاستيل","كولين","استراز","ليفكك","استيك","وتغلق","القناه"],"aliases":["البنية التشريحية والجزيئية للمشبك الكيميائي التنبيهي"]},{"id":"lhx_phase9_chapitres_17_18_card3_1","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"🟢 النقل المشبكي الطبيعي","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":1,"total":1,"text":"3 محاكي المشبك الكيميائي وإنزيم الإستراز التفاعلي اختر مرحلة أو تأثير دواء مشبكي لملاحظة استجابة المستقبل القنوي : 🟢 نقل طبيعي ناجح (إفراز وتفكيك ACh) 🔴 تأثير سم الكرار (Curare - شلل عضلات) ⚠️ غاز السارين أو المبيدات الحشرية (تثبيط AChE) 🟢 النقل المشبكي الطبيعي يرتبط الأستيل كولين مؤقتاً، يفتح المستقبل القنوي، يدخل الصوديوم فتتولد موجة تنبيهية ( PPSE ). ثم يتدخل إنزيم AChE ليفككه في أجزاء من الملي ثانية وتعود العضلة للراحة.","keywords":["النقل","المشبكي","الطبيعي","الدرس","اليه","محاكي","المشبك","الكيميايي","وانزيم","الاستراز","التفاعلي","مرحله","تاثير","مشبكي","لملاحظه","استجابه","المستقبل","القنوي"],"aliases":["🟢 النقل المشبكي الطبيعي"]},{"id":"lhx_phase9_chapitres_17_18_card4_1","kind":"html","lessonKey":"phase9_chapitres_17_18","title":"1. ما هو الفرق البنيوي والوظيفي بين القنوات المبوبة كهربائياً والقنوات المبوبة كيميائياً؟","lessonTitle":"الدرس 3 : آلية النقل المشبكي","unitId":5,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ما هو الفرق البنيوي والوظيفي بين القنوات المبوبة كهربائياً والقنوات المبوبة كيميائياً؟ أ) المبوبة كهربائياً تفتح بتغير فرق الجهد (على طول الليف العصبي)، أما المبوبة كيميائياً فتفتح عند تثبيت مبلغ كيميائي مثل ACh (على الغشاء بعد المشبكي). ب) لا يوجد أي فرق بينهما. ج) القنوات الكيميائية تستهلك طاقة ATP الفورية.","keywords":["الفرق","البنيوي","والوظيفي","بين","القنوات","المبوبه","كهرباييا","والقنوات","كيمياييا؟","الدرس","اليه","النقل","المشبكي","بتغير","الجهد","الليف","العصبي","كيمياييا"],"aliases":["1. ما هو الفرق البنيوي والوظيفي بين القنوات المبوبة كهربائياً والقنوات المبوبة كيميائياً؟"]},{"id":"lhx_phase9_chapitres_17_18_2_intro_1","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 5 : دور البروتينات في الاتصال العصبي 🎯 الهدف العلمي : فسّر النقل أحادي الاتجاه للرسالة العصبية على مستوى المشبك الكيميائي، ودور قنوات Ca²⁺ الفولطية والقنوات المبوبة كيميائياً وإنزيم AChE. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : وميّز بين المشبك التنبيهي والتثبيطي (GABA وتدفق Cl⁻)، واحسب الحصيلة الجبرية للتجميع الفضائي والزمني في القطعة الابتدائية SI. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء","عندما","تتلقي","الاف","السيالات","المتضاده؟","الاول","التخصص","للبروتينات","البروتينات","الاتصال"],"aliases":["كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟"]},{"id":"lhx_phase9_chapitres_17_18_2_card1_1","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":1,"total":1,"text":"1 الإشكالية الحسابية للخلية العصبية المحركة ⚠️ كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟ تتصل الخلية العصبية المحركة في النخاع الشوكي بآلاف النهايات العصبية. بعضها يرسل أوامر تنبيهية (انقباض) وبعضها يرسل أوامر تثبيطية (استرخاء كبح). كيف تقوم هذه الخلية بدمج وحساب كل هذه الرسائل الكيميائية المتضادة في القطعة الابتدائية ( Segment Initial SI ) لتقرر توليد كمون عمل واحد أو الصمت؟","keywords":["كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء","عندما","تتلقي","الاف","السيالات","المتضاده؟","الحسابيه","للخليه","المحركه","النخاع","الشوكي"],"aliases":["كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟"]},{"id":"lhx_phase9_chapitres_17_18_2_card2_1","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"مقارنة بين الكمون التنبيهي (PPSE) والكمون التثبيطي (PPSI) (1/2)","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":1,"total":2,"text":"2 التحليل المنهجي للمشبك التثبيطي (GABA) وظاهرة الإدماج العصبي مقارنة بين الكمون التنبيهي (PPSE) والكمون التثبيطي (PPSI) -70 -50 عتبة PPSE (زوال استقطاب) دخول شوارد Na⁺ -70 PPSI (فرط استقطاب) دخول شوارد Cl⁻ (أو خروج K⁺) 💡 يقرب PPSE المنحنى من العتبة (-50 mV)، بينما يبعد PPSI المنحنى عن العتبة (-80 mV). مبدأ الإدماج في البكالوريا كيف يحسب القطعة الابتدائية ( SI ) الحصيلة؟ تقوم الخلية العصبية بعد المشبكية بدمج الكمونات القادمة وفق آليتين : • التجميع الفضائي ( Sommation spatiale ) :","keywords":["مقارنه","بين","الكمون","التنبيهي","ppse","والكمون","التثبيطي","ppsi","كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء","عندما","تتلقي"],"aliases":["مقارنة بين الكمون التنبيهي (PPSE) والكمون التثبيطي (PPSI)"]},{"id":"lhx_phase9_chapitres_17_18_2_card2_2","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"مقارنة بين الكمون التنبيهي (PPSE) والكمون التثبيطي (PPSI) (2/2)","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":2,"total":2,"text":"جمع سيالات تصل في نفس الوقت من نهايات عصبية مختلفة ومتعددة. • التجميع الزمني ( Sommation temporelle ) : جمع سيالات متقاربة جداً في الزمن قادمة من نفس النهاية العصبية قبل المشبكية. قاعدة اتخاذ القرار : إذا كانت الحصيلة الجبرية في القطعة الابتدائية SI تفوق أو تساوي عتبة التنبيه ( ≥ -50 mV )، تنفتح قنوات Na⁺ الفولطية وينطلق كمون عمل. وإذا كانت الحصيلة دون العتبة يبقى الليف في حالة راحة.","keywords":["مقارنه","بين","الكمون","التنبيهي","ppse","والكمون","التثبيطي","ppsi","كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء","عندما","تتلقي"],"aliases":["مقارنة بين الكمون التنبيهي (PPSE) والكمون التثبيطي (PPSI)"]},{"id":"lhx_phase9_chapitres_17_18_2_card3_1","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"🟢 تجميع فضائي يفوق العتبة (-40 mV)","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":1,"total":1,"text":"3 آلة حساب الإدماج العصبي التفاعلية اختر مزيج التنبيهات القادمة للخلية الحركية لمعرفة هل يتولد كمون عمل في القطعة الابتدائية : 🟢 2 تنبيه تنبيهي (+15 mV لكل مشبك PPSE) 🔴 تنبيه تنبيهي واحد + تنبيه تثبيطي واحد (PPSE + PPSI) 🟢 تجميع فضائي يفوق العتبة (-40 mV) كمون الراحة (-70 mV) + 30 mV تنبيه = -40 mV . بما أن الحصيلة تفوق عتبة التوليد (-50 mV)، يولد القطعة الابتدائية SI كمون عمل كامل (+30 mV) ينتقل نحو العضلة.","keywords":["تجميع","فضايي","يفوق","العتبه","كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء","عندما","تتلقي","الاف","السيالات","المتضاده؟","الادماج"],"aliases":["🟢 تجميع فضائي يفوق العتبة (-40 mV)"]},{"id":"lhx_phase9_chapitres_17_18_2_card4_1","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر آلية النقل المشبكي الأحادي الاتجاه بواسطة الأستيل كولين. تصل السيولة العصبية إلى النهاية المشبكية في صورة كمونات عمل كهربائية. يحرض وصول الكمون العمل تحرر الناقل العصبي ACh من الحويصلات بالدمج الخلوي. يرتبط ACh بمرابطه المبوبة كيميائياً على الغشاء بعد المشبكي فتنفتح قنوات Na+. ينشأ كمون عمل بعد مشبكي ينتقل نحو العصبون أو الخلية الهدف. يفكك إنزيم AChE الناقل العصبي فيتوقف التأثير (نقل أحادي الاتجاه). 🔑 المصطلح المفتاحي في البكالوريا : المشبك / الأستيل كولين (ACh)","keywords":["كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء","عندما","تتلقي","الاف","السيالات","المتضاده؟","خلاصه","الدرس","النقل","المشبكي","الاحادي"],"aliases":["كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟"]},{"id":"lhx_phase9_chapitres_17_18_2_card5_1","kind":"html","lessonKey":"phase9_chapitres_17_18_2","title":"1. ما هو المبلغ العصبي الرئيسي والمستقبل الأيوني المسؤول عن نشأة الكمون التثبيطي ( PPSI )؟","lessonTitle":"كيف تتخذ الخلية العصبية الحركية قرار الانقباض أو الاسترخاء عندما تتلقى آلاف السيالات المتضادة؟","unitId":5,"part":1,"total":1,"text":"4 تقويم النشاط 4 : أسئلة البكالوريا المتكررة 1. ما هو المبلغ العصبي الرئيسي والمستقبل الأيوني المسؤول عن نشأة الكمون التثبيطي ( PPSI )؟ أ) حمض الغابا ( GABA ) الذي يفتح القنوات المبوبة كيميائياً للكلور ( Cl⁻ ) فيدخل الكلور السالب محدثاً فرط استقطاب. ب) الأستيل كولين الذي يدخل شوارد الكالسيوم. ج) إنزيم الأستيل كولين إستراز.","keywords":["المبلغ","العصبي","الرييسي","والمستقبل","الايوني","المسوول","نشاه","الكمون","التثبيطي","ppsi","كيف","تتخذ","الخليه","العصبيه","الحركيه","قرار","الانقباض","الاسترخاء"],"aliases":["1. ما هو المبلغ العصبي الرئيسي والمستقبل الأيوني المسؤول عن نشأة الكمون التثبيطي ( PPSI )؟"]},{"id":"lhx_phase10_chapitres_19_20_intro_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 5 : دور البروتينات في الاتصال العصبي 🎯 الهدف العلمي : فسّر نقل رسالة الألم بواسطة المادة P، وآلية الكبح الطبيعي بالأنكيفالين مقابل التسكين القوي للمورفين (التماثل البنيوي مع المستقبلات الأفيونية). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد الصانعة الخضراء كمقر للتركيب الضوئي، وميّز بنيوياً بين التيلاكويد (مقر الكيميوضوئية) والحشوة (مقر الكيميوحيوية). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","الاول","التخصص","للبروتينات","البروتينات","الاتصال","العصبي","رساله","الالم","بواسطه","واليه","الكبح","الطبيعي"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_card1_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف يوقف المورفين آلام الحروق والعمليات الجراحية الشديدة؟ عند التعرض لإصابة أو حرق، ترسل العصبونات الحسية سيالات الألم نحو الدماغ عن طريق إفراز مبلغ كيميائي منبه يسمى المادة P ( Substance P ) في النخاع الشوكي. يمتلك الجسم نظام كبح طبيعي يفرز مادة الأنكيفالين ( Enképhaline ) لتخفيف الألم مؤقتاً. ويعتبر المورفين ( Morphine ) أقوى مسكن طبي عرفه الإنسان. كيف يقلد المورفين عمل الأنكيفالين الطبيعي ليمنع انتقال رسالة الألم في المشبك؟","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","وضعيه","الانطلاق","وبناء","العلميه","المورفين","الحروق","والعمليات","الجراحيه","الشديده؟","التعرض","لاصابه","العصبونات"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_card2_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"آلية التثبيط قبل المشبكي لرسالة الألم (المادة P مقابل الأنكيفالين/المورفين) (1/2)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":2,"text":"2 التحليل المنهجي لمشبك الألم والمستقبلات الأفيونية قبل المشبكية آلية التثبيط قبل المشبكي لرسالة الألم (المادة P مقابل الأنكيفالين/المورفين) نهاية العصبون الحسي للألم مادة P عصبون جامع (أنكيفالين) مستقبل أفيوني قناة Ca²⁺ العصبون الوارد نحو الدماغ (الشعور بالألم) 💡 ارتباط المورفين بالمستقبل الأفيوني يغلق قنوات Ca²⁺ فيمنع إطراح المادة P. منهجية البكالوريا : التماثل البنيوي والتثبيط كيف يكبح المورفين الألم؟ في الحالة العادية (إحساس بالألم) : تدخل شوارد Ca²⁺ للزر الحسي، تطرح المادة P ،","keywords":["اليه","التثبيط","قبل","المشبكي","لرساله","الالم","الماده","مقابل","الانكيفالين","المورفين","الدرس","تاثير","المخدرات","علي","مستوي","المشابك","لمشبك","والمستقبلات"],"aliases":["آلية التثبيط قبل المشبكي لرسالة الألم (المادة P مقابل الأنكيفالين/المورفين)"]},{"id":"lhx_phase10_chapitres_19_20_card2_2","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"آلية التثبيط قبل المشبكي لرسالة الألم (المادة P مقابل الأنكيفالين/المورفين) (2/2)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":2,"total":2,"text":"ترتبط بمستقبلاتها في العصبون الوارد للدماغ فيشعر الإنسان بالألم. التماثل البنيوي ( Mimétisme structural ) : يمتلك المورفين والأنكيفالين نفس البنية الفراغية في جزء الجزيء المخصص للارتباط بالمستقبلات الأفيونية قبل المشبكية. التثبيط قبل المشبكي : ارتبط المورفين يمنع انفتح قنوات Ca²⁺ الفولطية للزر الحسي، فلا يدخل الكالسيوم ولا تفرز المادة P نهائياً، فينقطع وصول سيالة الألم للدماغ.","keywords":["اليه","التثبيط","قبل","المشبكي","لرساله","الالم","الماده","مقابل","الانكيفالين","المورفين","الدرس","تاثير","المخدرات","علي","مستوي","المشابك","ترتبط","بمستقبلاتها"],"aliases":["آلية التثبيط قبل المشبكي لرسالة الألم (المادة P مقابل الأنكيفالين/المورفين)"]},{"id":"lhx_phase10_chapitres_19_20_card3_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"🔴 الشعور بألم حاد ومستمر","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":1,"text":"3 محاكي مشبك الألم وتأثير المورفين التفاعلي اختر الحالة المشبكية لملاحظة إفراز المادة P وانتقال رسالة الألم : 🔴 إصابة مؤلمة (إفراز كثيف للمادة P) 🟣 تدخل الأنكيفالين الطبيعي (كبح مؤقت) 🟢 حقن المورفين الطبي (تسكين عميق ودائم) 🔴 الشعور بألم حاد ومستمر قنوات الكالسيوم مفتوحة، تفرز المادة P بكثافة في الشق المشبكي وتولد تواتراً عالياً من كمونات العمل نحو الدماغ.","keywords":["الشعور","بالم","حاد","ومستمر","الدرس","تاثير","المخدرات","علي","مستوي","المشابك","محاكي","الالم","وتاثير","المورفين","التفاعلي","الحاله","المشبكيه","لملاحظه"],"aliases":["🔴 الشعور بألم حاد ومستمر"]},{"id":"lhx_phase10_chapitres_19_20_card4_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"1. أين تتواجد المستقبلات الأفيونية الخاصة بالأنكيفالين والمورفين؟ وما هو تأثير ارتباط المورفين بها؟","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":1,"text":"4 تقويم النشاط 5 : أسئلة البكالوريا المتكررة 1. أين تتواجد المستقبلات الأفيونية الخاصة بالأنكيفالين والمورفين؟ وما هو تأثير ارتباط المورفين بها؟ أ) تتواجد على الغشاء قبل المشبكي للعصبون الحسي للألم، وارتباط المورفين بها يغلق قنوات Ca²⁺ ويمنع إطراح المادة P. ب) تتواجد في النواة وتخرب الـ ADN. ج) تتواجد في العضلات وتسبب انقباضها.","keywords":["اين","تتواجد","المستقبلات","الافيونيه","الخاصه","بالانكيفالين","والمورفين؟","وما","تاثير","ارتباط","المورفين","بها؟","الدرس","المخدرات","علي","مستوي","المشابك","المشبكي"],"aliases":["1. أين تتواجد المستقبلات الأفيونية الخاصة بالأنكيفالين والمورفين؟ وما هو تأثير ارتباط المورفين بها؟"]},{"id":"lhx_phase10_chapitres_19_20_card5_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك (1/3)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":3,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 24-30، ص 156-164) الوحدة: U5 — دور البروتينات في الاتصال العصبي — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. تنتقل الرسالة العصبية في الليف قبل المشبكي على شكل تواترات كمونات عمل ، وتتحول على مستوى المشبك إلى رسالة مشفرة بتركيز المبلغ العصبي . كمون الراحة (−70 mV) : قنوات تسرب مفتوحة باستمرار (ناقلية K⁺ أكبر) + مضخة Na⁺/K⁺ بنشاط ATPase (3 Na⁺ خارجا / 2 K⁺ داخلًا، عكس تدرج التركيز). كمون العمل :","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","المعرفيه","الرسمي","للكتاب","المدرسي","البروتينات","الاتصال","العصبي","الكتاب","بتنسيق","قرايي،","تغيير","المعني"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_card5_2","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك (2/3)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":2,"total":3,"text":"زوال استقطاب (قنوات Na⁺ فولطية) ← عودة استقطاب (قنوات K⁺ فولطية) ← إفراط في الاستقطاب. وصول الموجة للزر المشبكي ← انفتاح قنوات Ca²⁺ ← هجرة الحويصلات وتحرير الأستيل كولين ← تثبيته على القنوات المبوبة كيميائيا (5 تحت وحدات) ← زوال استقطاب بعد مشبكي PPSE. المشابك التثبيطية : المبلغ GABA يفتح قنوات Cl⁻ ← إفراط في الاستقطاب PPSI؛ لا يُهدم GABA بل يُمتص لإعادة الاستعمال. الإدماج العصبي : تجميع فضائي + زمني؛ إذا بلغ المحصلة العتبة تولد كمون عمل. المخدرات تخل بالنقل المشبكي في 6 مستويات: التركيب، التخزين، التحرير،","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","استقطاب","قنوات","فولطيه","افراط","الاستقطاب","الموجه","المشبكي","انفتاح","الحويصلات","وتحرير","الاستيل","كولين"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_card5_3","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك (3/3)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":3,"total":3,"text":"المستقبل القنوي، إنزيمات التفكيك، إعادة الامتصاص.","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","المستقبل","القنوي،","انزيمات","التفكيك،","اعاده","الامتصاص"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_card6_1","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك (1/2)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":1,"total":2,"text":"🗺 مخطط تحصيلي — آلية النقل العصبي على مستوى المشبك (ص 165) الصورة الأصلية من الكتاب (ص 165) — تحوي طبقة الصورة أخطاء استخراج آلي («الفقوات» بدل القنوات...)؛ التسلسل المصحح أدناه هو المرجع القرائي. يتوجه كمون العمل نحو النهاية العصبية. وصول موجة زوال استقطاب إلى النهاية العصبية يؤدي إلى انفتاح القنوات الغشائية لـ Ca²⁺. تدفق شوارد Ca²⁺ عبر القنوات المفتوحة. اندماج غشاء الحويصلات المشبكية مع الغشاء قبل المشبكي. تحرير المبلغ العصبي في الشق المشبكي . يُركَّب المبلغ العصبي ويُخزَّن في حويصلات مشبكية.","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","تحصيلي","النقل","العصبي","المشبك","الصوره","الاصليه","الكتاب","اخطاء","استخراج","الفقوات","القنوات","التسلسل"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_card6_2","kind":"html","lessonKey":"phase10_chapitres_19_20","title":"الدرس 7 : تأثير المخدرات على مستوى المشابك (2/2)","lessonTitle":"الدرس 7 : تأثير المخدرات على مستوى المشابك","unitId":5,"part":2,"total":2,"text":"تثبيت المبلغ العصبي على المستقبلات الغشائية (القنوات المرتبطة بالكيمياء). انفتاح قنوات الصوديوم المرتبطة بالكيمياء. دخول شوارد الصوديوم يولد كمون عمل في غشاء الخلية بعد المشبكية. إعادة تكوين الحويصلات المشبكية انطلاقا من الغشاء (لإعادة الاستعمال). 🗺 الصورة الأصلية + تنسيق قرائي مصحح — المفردات مثبتة في النص الرسمي (تحقّق آلي داخلي).","keywords":["الدرس","تاثير","المخدرات","علي","مستوي","المشابك","تثبيت","المبلغ","العصبي","المستقبلات","الغشاييه","القنوات","المرتبطه","بالكيمياء","انفتاح","قنوات","الصوديوم","شوارد"],"aliases":["الدرس 7","تأثير المخدرات على مستوى المشابك"]},{"id":"lhx_phase10_chapitres_19_20_2_intro_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":1,"text":"المجال الأول : التخصص الوظيفي للبروتينات • الوحدة 5 : دور البروتينات في الاتصال العصبي 🎯 الهدف العلمي : فسّر نقل رسالة الألم بواسطة المادة P، وآلية الكبح الطبيعي بالأنكيفالين مقابل التسكين القوي للمورفين (التماثل البنيوي مع المستقبلات الأفيونية). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد الصانعة الخضراء كمقر للتركيب الضوئي، وميّز بنيوياً بين التيلاكويد (مقر الكيميوضوئية) والحشوة (مقر الكيميوحيوية). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","الاول","التخصص","للبروتينات","البروتينات","الاتصال","العصبي","رساله","الالم","بواسطه"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card1_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":1,"text":"1 الإشكالية الطاقوية الكبرى للمجال الثاني ⚠️ كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ تعتبر النباتات اليخضورات المنتجات الأولية للطاقة في المحيط الحيوي، حيث تقوم بظاهرة التركيب الضوئي ( Photosynthèse ) التي تحول الطاقة الضوئية الفزيائية إلى طاقة كيميائية كامنة مخزنة في الروابط الكربونية للجزيئات العضوية (النشا والغلوكوز). أين تتم هذه الظاهرة بالتحديد داخل الخلية النباتية؟ وكيف تتلاءم البنية المجهرية الفوقية لعضية \"الصانعة الخضراء\" مع أداء هذه التفاعلات المعقدة؟","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","الطاقويه","الكبري","للمجال","الثاني","تعتبر","اليخضورات","المنتجات","الاوليه","للطاقه"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card2_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"رسم تخطيطي ثلاثي الأبعاد لـ الصانعة الخضراء (Chloroplaste) ومقصوراتها (1/2)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":2,"text":"2 التحليل المنهجي للبنية الفوقية للصانعة الخضراء بالمجهر الإلكتروني رسم تخطيطي ثلاثي الأبعاد لـ الصانعة الخضراء (Chloroplaste) ومقصوراتها غشاء خارجي وغشاء داخلي يفصل بينهما فراغ بين غشائي الحشوة (Stroma) بذرة (Granum) تيلاكويد حشوي حبيبة نشا 🟢 التيلاكويد يحمل أصبغة اليخضور، والحشوة تحتوي على إنزيم الروبيسكو (Rubisco). أساسيات المجال الثاني في البكالوريا مقارنة المقصورتين الفعالتين في الصانعة • التيلاكويد ( Thylakoïde ) : أكياس غشائية مسطحة تتوضع أحياناً فوق بعضها مشكلة البذرة ( Granum ).","keywords":["رسم","تخطيطي","ثلاثي","الابعاد","الصانعه","الخضراء","chloroplaste","ومقصوراتها","كيف","تحول","النباتات","اشعه","الشمس","الي","سكر","النشا؟","للبنيه","الفوقيه"],"aliases":["رسم تخطيطي ثلاثي الأبعاد لـ الصانعة الخضراء (Chloroplaste) ومقصوراتها"]},{"id":"lhx_phase10_chapitres_19_20_2_card2_2","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"رسم تخطيطي ثلاثي الأبعاد لـ الصانعة الخضراء (Chloroplaste) ومقصوراتها (2/2)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":2,"total":2,"text":"يحتوي غشاؤها على أصبغة اليخضور ( Chlorophylle ) والأنظمة الضوئية ( PS I و PS II ) وإنزيم الـ ATP synthase $\\leftarrow$ مقر المرحلة الكيميوضوئية. • الحشوة ( Stroma أو ستروما ) : سائل أساسي غني بالإنزيمات (خاصة إنزيم Rubisco المثبت للـ CO₂ ) ومرافقات الإنزيمات وحبيبات النشا والـ ADN $\\leftarrow$ مقر المرحلة الكيميوحيوية (حلقة كالفن).","keywords":["رسم","تخطيطي","ثلاثي","الابعاد","الصانعه","الخضراء","chloroplaste","ومقصوراتها","كيف","تحول","النباتات","اشعه","الشمس","الي","سكر","النشا؟","يحتوي","غشاوها"],"aliases":["رسم تخطيطي ثلاثي الأبعاد لـ الصانعة الخضراء (Chloroplaste) ومقصوراتها"]},{"id":"lhx_phase10_chapitres_19_20_2_card3_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"🌿 غشاء التيلاكويد (مقر المرحلة الكيميوضوئية)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":1,"text":"3 المجهر الإلكتروني الافتراضي لمقصورات الصانعة الخضراء اضغط على المقنصورة لاكتشاف شروط وتفاعلات المرحلة التابعة لها : 🌿 غشاء التيلاكويد (المرحلة الكيميوضوئية) 🧪 الحشوة / الستروما (المرحلة الكيميوحيوية) 🌿 غشاء التيلاكويد (مقر المرحلة الكيميوضوئية) يتطلب ضوءاً مباشراً. تقوم الأنظمة الضوئية بامتصاص الفوتونات وأكسدة الماء ( H₂O ) لانطلاق غاز الأكسجين ( O₂ )، وتركيب طاقة ATP وإرجاع النواقل ( NADPH, H⁺ ).","keywords":["غشاء","التيلاكويد","مقر","المرحله","الكيميوضوييه","كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","المجهر","الالكتروني","الافتراضي","لمقصورات"],"aliases":["🌿 غشاء التيلاكويد (مقر المرحلة الكيميوضوئية)"]},{"id":"lhx_phase10_chapitres_19_20_2_card4_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (1/2)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 اشرح تأثير المخدرات على النقل المشبكي، وحدّد مقر التركيب الضوئي وبنيته. تؤثر المخدرات على مراحل النقل المشبكي: تحرر الناقل، ارتباطه بمرابطه، أو تفككه. يقلد المورفين الأنكيفالين بتماثل بنيوي فيرتبط بمرابطه الأفيونية ويكبح رسالة الألم. يقع مقر التركيب الضوئي في الصانعة الخضراء، عضية مقسمة إلى التيلاكويد والحشوة. تجري المرحلة الكيموضوئية على أغشية التيلاكويد، والكيميوحيوية في الحشوة. تنتج التفاعلات الضوئية ATP و NADPH تستعملهما الحشوة لتحويل CO2 إلى مادة عضوية. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","خلاصه","الدرس","تاثير","المخدرات","النقل","المشبكي،","وبنيته","مراحل","المشبكي"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card4_2","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (2/2)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":2,"total":2,"text":"المرابط الأفيونية / الصانعة الخضراء","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","المرابط","الافيونيه","الصانعه"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card5_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"1. لماذا تعتبر الصانعة الخضراء عضية مقسمة إلى مقصورات ( Compartimentée )؟","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. لماذا تعتبر الصانعة الخضراء عضية مقسمة إلى مقصورات ( Compartimentée )؟ أ) لأنها تحتوي على فراغات وأغشية منفصلة (التيلاكويد والحشوة) تمنح شروطاً كيميائية وإنزيمية مختلفة ومستقلة تسمح بحدوث مرحلتي التركيب الضوئي بانتظام. ب) لأنها تحتوي على نواة مستقلة. ج) لأنها تتواجد في خلايا الإنسان.","keywords":["لماذا","تعتبر","الصانعه","الخضراء","عضيه","مقسمه","الي","مقصورات","compartiment","كيف","تحول","النباتات","اشعه","الشمس","سكر","النشا؟","لانها","تحتوي"],"aliases":["1. لماذا تعتبر الصانعة الخضراء عضية مقسمة إلى مقصورات ( Compartimentée )؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card6_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (1/3)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":3,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 24-30، ص 156-164) الوحدة: U5 — دور البروتينات في الاتصال العصبي — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. تنتقل الرسالة العصبية في الليف قبل المشبكي على شكل تواترات كمونات عمل ، وتتحول على مستوى المشبك إلى رسالة مشفرة بتركيز المبلغ العصبي . كمون الراحة (−70 mV) : قنوات تسرب مفتوحة باستمرار (ناقلية K⁺ أكبر) + مضخة Na⁺/K⁺ بنشاط ATPase (3 Na⁺ خارجا / 2 K⁺ داخلًا، عكس تدرج التركيز). كمون العمل :","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","المعرفيه","الرسمي","للكتاب","المدرسي","البروتينات","الاتصال","العصبي","الكتاب","بتنسيق"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card6_2","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (2/3)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":2,"total":3,"text":"زوال استقطاب (قنوات Na⁺ فولطية) ← عودة استقطاب (قنوات K⁺ فولطية) ← إفراط في الاستقطاب. وصول الموجة للزر المشبكي ← انفتاح قنوات Ca²⁺ ← هجرة الحويصلات وتحرير الأستيل كولين ← تثبيته على القنوات المبوبة كيميائيا (5 تحت وحدات) ← زوال استقطاب بعد مشبكي PPSE. المشابك التثبيطية : المبلغ GABA يفتح قنوات Cl⁻ ← إفراط في الاستقطاب PPSI؛ لا يُهدم GABA بل يُمتص لإعادة الاستعمال. الإدماج العصبي : تجميع فضائي + زمني؛ إذا بلغ المحصلة العتبة تولد كمون عمل. المخدرات تخل بالنقل المشبكي في 6 مستويات: التركيب، التخزين، التحرير،","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","استقطاب","قنوات","فولطيه","افراط","الاستقطاب","الموجه","المشبكي","انفتاح","الحويصلات"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card6_3","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (3/3)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":3,"total":3,"text":"المستقبل القنوي، إنزيمات التفكيك، إعادة الامتصاص.","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","المستقبل","القنوي،","انزيمات","التفكيك،","اعاده","الامتصاص"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card7_1","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (1/2)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":1,"total":2,"text":"🗺 مخطط تحصيلي — آلية النقل العصبي على مستوى المشبك (ص 165) الصورة الأصلية من الكتاب (ص 165) — تحوي طبقة الصورة أخطاء استخراج آلي («الفقوات» بدل القنوات...)؛ التسلسل المصحح أدناه هو المرجع القرائي. يتوجه كمون العمل نحو النهاية العصبية. وصول موجة زوال استقطاب إلى النهاية العصبية يؤدي إلى انفتاح القنوات الغشائية لـ Ca²⁺. تدفق شوارد Ca²⁺ عبر القنوات المفتوحة. اندماج غشاء الحويصلات المشبكية مع الغشاء قبل المشبكي. تحرير المبلغ العصبي في الشق المشبكي . يُركَّب المبلغ العصبي ويُخزَّن في حويصلات مشبكية.","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","تحصيلي","النقل","العصبي","المشبك","الصوره","الاصليه","الكتاب","اخطاء","استخراج"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase10_chapitres_19_20_2_card7_2","kind":"html","lessonKey":"phase10_chapitres_19_20_2","title":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟ (2/2)","lessonTitle":"كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟","unitId":5,"part":2,"total":2,"text":"تثبيت المبلغ العصبي على المستقبلات الغشائية (القنوات المرتبطة بالكيمياء). انفتاح قنوات الصوديوم المرتبطة بالكيمياء. دخول شوارد الصوديوم يولد كمون عمل في غشاء الخلية بعد المشبكية. إعادة تكوين الحويصلات المشبكية انطلاقا من الغشاء (لإعادة الاستعمال). 🗺 الصورة الأصلية + تنسيق قرائي مصحح — المفردات مثبتة في النص الرسمي (تحقّق آلي داخلي).","keywords":["كيف","تحول","النباتات","الخضراء","اشعه","الشمس","الي","سكر","النشا؟","تثبيت","المبلغ","العصبي","المستقبلات","الغشاييه","القنوات","المرتبطه","بالكيمياء","انفتاح"],"aliases":["كيف تحول النباتات الخضراء أشعة الشمس إلى سكر النشا؟"]},{"id":"lhx_phase11_chapitres_21_22_intro_1","kind":"html","lessonKey":"phase11_chapitres_21_22","title":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","lessonTitle":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","unitId":6,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 1 : آليات تحويل الطاقة الضوئية إلى طاقة كيميائية كامنة 🎯 الهدف العلمي : حدّد دور الأنظمة الضوئية (PSII و PSI) في التقاط الفوتونات، وبيّن أن مصدر غاز الأكسجين المنطلق هو التحلل الضوئي لجزيئة الماء. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر تدرج تركيز البروتونات، ودور الكرية المذنبة (ATP synthase) في فسفرة الـ ADP وإرجاع مستقبل الإلكترونات النهائي (NADP⁺). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","تفاعلات","المرحله","الكيموضوييه","الثاني","التحولات","الطاقويه","اليات","تحويل","الضوييه","كيمياييه","كامنه","الانظمه","التقاط","الفوتونات،","الاكسجين","المنطلق","التحلل"],"aliases":["الدرس 3","تفاعلات المرحلة الكيموضوئية"]},{"id":"lhx_phase11_chapitres_21_22_card1_1","kind":"html","lessonKey":"phase11_chapitres_21_22","title":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","lessonTitle":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","unitId":6,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ من أين يأتي الأكسجين الذي نتنفسه؟ من غاز CO₂ أم من الماء H₂O؟ تطرح النباتات الخضراء المعرضة للضوء غاز الأكسجين ( O₂ ) في الهواء. ولعقود طويلة اعتقد العلماء أن هذا الأكسجين ناتج عن تفكيك غاز ثاني أكسيد الكربون ( CO₂ )، حتى أثبتت تجارب الأكسجين المشع (تجربة روبن وكامن تجربة هيل) أن مصدر الأكسجين هو تفكيك جزيئات الماء ( H₂O ) وليس الـ CO₂! كيف يقوم الضوء واليخضور بكسر جزيء الماء الشديد الثبات؟","keywords":["الدرس","تفاعلات","المرحله","الكيموضوييه","وضعيه","الانطلاق","وبناء","العلميه","الاكسجين","نتنفسه؟","النباتات","الخضراء","المعرضه","للضوء","الهواء","ولعقود","طويله","اعتقد"],"aliases":["الدرس 3","تفاعلات المرحلة الكيموضوئية"]},{"id":"lhx_phase11_chapitres_21_22_card2_1","kind":"html","lessonKey":"phase11_chapitres_21_22","title":"آلية امتصاص الفوتونات وأكسدة الماء عند مستوى النظام الضوئي PS II (1/2)","lessonTitle":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","unitId":6,"part":1,"total":2,"text":"2 التحليل المنهجي للنظام الضوئي (Photosystème) والتحلل الضوئي للماء آلية امتصاص الفوتونات وأكسدة الماء عند مستوى النظام الضوئي PS II الحشوة (Stroma) تجويف التيلاكويد (Lumen - غني بالبروتونات H⁺) P680 PS II فوتون ضوئي 2 e⁻ 2 H₂O → O₂ ↑ + 4 H⁺ + 4 e⁻ 💡 يتهيج اليخضور P680 فيفقد إلكترونات، ويعوضها فوراً من أكسدة الماء. منهجية البكالوريا : التفاعل الكيميائي المؤكسد لماذا يتأكسد الماء بالتحديد؟ تهيج مركز التفاعل ( Photo-oxydation ) : يمتص النظام الضوئي الثاني ( PS II ) طاقة الفوتونات،","keywords":["اليه","امتصاص","الفوتونات","واكسده","الماء","عند","مستوي","النظام","الضويي","الدرس","تفاعلات","المرحله","الكيموضوييه","للنظام","photosyst","والتحلل","للماء","الحشوه"],"aliases":["آلية امتصاص الفوتونات وأكسدة الماء عند مستوى النظام الضوئي PS II"]},{"id":"lhx_phase11_chapitres_21_22_card2_2","kind":"html","lessonKey":"phase11_chapitres_21_22","title":"آلية امتصاص الفوتونات وأكسدة الماء عند مستوى النظام الضوئي PS II (2/2)","lessonTitle":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","unitId":6,"part":2,"total":2,"text":"فينتقل جزيء اليخضور المركزي ( P680 ) إلى حالة تهيج عالية الطاقة ويفقد إلكترونين ( 2e⁻ )، فيصبح مؤكسداً وغير مستقر ( P680⁺ ). التحلل الضوئي للماء ( Photolyse de l'eau ) : لاسترجاع استقراره وإلكتروناته المفقودة، يقوم إنزيم متصل بـ PS II في تجويف التيلاكويد بأكسدة جزيئات الماء وفق المعادلة الشهيرة : 2 H₂O → O₂ ↑ + 4 H⁺ + 4 e⁻","keywords":["اليه","امتصاص","الفوتونات","واكسده","الماء","عند","مستوي","النظام","الضويي","الدرس","تفاعلات","المرحله","الكيموضوييه","فينتقل","اليخضور","المركزي","عاليه","ويفقد"],"aliases":["آلية امتصاص الفوتونات وأكسدة الماء عند مستوى النظام الضوئي PS II"]},{"id":"lhx_phase11_chapitres_21_22_card3_1","kind":"html","lessonKey":"phase11_chapitres_21_22","title":"☀️ تهيج اليخضور في مركز التفاعل P680","lessonTitle":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","unitId":6,"part":1,"total":1,"text":"3 محاكي التحلل الضوئي للماء وتهيج اليخضور اضغط لإسقاط فوتون ضوئي على النظام الضوئي PS II ومتابعة الإلكترونات : ☀️ إسقاط فوتون على PS II (تهيج وفقدان e⁻) 💧 أكسدة جزيء الماء (تعويض e⁻ وانطلاق O₂) ☀️ تهيج اليخضور في مركز التفاعل P680 تجمع أصبغة الهوائي الطاقة الضوئية وتوجهها نحو اليخضور P680 . يقفز إلكترونان إلى مدار طاقوي أعلى ويغادران النظام الضوئي نحو الناقل الأول في السلسلة التركيبية الضوئية.","keywords":["تهيج","اليخضور","مركز","التفاعل","p680","الدرس","تفاعلات","المرحله","الكيموضوييه","محاكي","التحلل","للماء","وتهيج","لاسقاط","فوتون","النظام","ومتابعه","الالكترونات"],"aliases":["☀️ تهيج اليخضور في مركز التفاعل P680"]},{"id":"lhx_phase11_chapitres_21_22_card4_1","kind":"html","lessonKey":"phase11_chapitres_21_22","title":"1. أين تتراكم شوارد الهيدروجين (البروتونات H⁺ ) الناتجة عن أكسدة الماء في الصانعة الخضراء؟","lessonTitle":"الدرس 3 : تفاعلات المرحلة الكيموضوئية","unitId":6,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. أين تتراكم شوارد الهيدروجين (البروتونات H⁺ ) الناتجة عن أكسدة الماء في الصانعة الخضراء؟ أ) داخل تجويف التيلاكويد ( Lumen du thylakoïde ) مما يجعل تجويفه حامضياً جداً مقارنة بالحشوة. ب) في الحشوة ( Stroma ) مباشرة. ج) تطرح خارج الخلية النباتية مع الأكسجين.","keywords":["اين","تتراكم","شوارد","الهيدروجين","البروتونات","الناتجه","اكسده","الماء","الصانعه","الخضراء؟","الدرس","تفاعلات","المرحله","الكيموضوييه","تجويف","التيلاكويد","lumen","thylako"],"aliases":["1. أين تتراكم شوارد الهيدروجين (البروتونات H⁺ ) الناتجة عن أكسدة الماء في الصانعة الخضراء؟"]},{"id":"lhx_phase11_chapitres_21_22_2_intro_1","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 1 : آليات تحويل الطاقة الضوئية إلى طاقة كيميائية كامنة 🎯 الهدف العلمي : حدّد دور الأنظمة الضوئية (PSII و PSI) في التقاط الفوتونات، وبيّن أن مصدر غاز الأكسجين المنطلق هو التحلل الضوئي لجزيئة الماء. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر تدرج تركيز البروتونات، ودور الكرية المذنبة (ATP synthase) في فسفرة الـ ADP وإرجاع مستقبل الإلكترونات النهائي (NADP⁺). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تتحول","طاقه","الالكترونات","المتحركه","الي","جزييات","بطاريه","atp","الثاني","التحولات","الطاقويه","اليات","تحويل","الضوييه","كيمياييه","كامنه","الانظمه"],"aliases":["كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟"]},{"id":"lhx_phase11_chapitres_21_22_2_card1_1","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":1,"total":1,"text":"1 الإشكالية الكيميائية للمرحلة الضوئية ⚠️ كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟ تنتقل الإلكترونات المنطلقة من النظام الضوئي PS II عبر سلسلة من النواقل البروتينية الغشائية (السلسلة التركيبية الضوئية) حتى تصل إلى المستقبل النهائي في الحشوة وهو مرافق الإنزيم NADP⁺ ليتم إرجاعه إلى NADPH, H⁺ . وفي نفس الوقت يُنتج كمية هائلة من جزيئات الطاقة ATP . كيف يتم اقتران نقل الإلكترونات بضخ البروتونات وتدوير إنزيم الـ ATP synthase (الفسفرة الضوئية)؟","keywords":["كيف","تتحول","طاقه","الالكترونات","المتحركه","الي","جزييات","بطاريه","atp","الكيمياييه","للمرحله","الضوييه","تنتقل","المنطلقه","النظام","سلسله","النواقل","البروتينيه"],"aliases":["كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟"]},{"id":"lhx_phase11_chapitres_21_22_2_card2_1","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"مخطط نقل الإلكترونات وضخ البروتونات لتوليد طاقة ATP (1/2)","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":1,"total":2,"text":"2 التحليل المنهجي للسلسلة التركيبية الضوئية وآلية عمل الكرية المذذبة مخطط نقل الإلكترونات وضخ البروتونات لتوليد طاقة ATP الحشوة (Stroma - تركيز H⁺ منخفض) تجويف التيلاكويد (تركيز H⁺ مرتفع جداً) T₂ ضخ H⁺ ATP synthase ADP + Pi → ATP 💡 خروج البروتونات H⁺ عبر الكرية المذذبة يحفز فسفرة ADP إلى ATP. خطوات الفسفرة في البكالوريا كيف تعمل الكرية المذذبة ( ATP synthase )؟ نشأة التدرج الكهروكيميائي : تتراكم البروتونات H⁺ في تجويف التيلاكويد (من أكسدة الماء ومن ضخ الناقل T₂ )، بينما يقل تركيزها في الحشوة، فينشأ تدرج تركيز قوي.","keywords":["مخطط","نقل","الالكترونات","وضخ","البروتونات","لتوليد","طاقه","atp","كيف","تتحول","المتحركه","الي","جزييات","بطاريه","للسلسله","التركيبيه","الضوييه","واليه"],"aliases":["مخطط نقل الإلكترونات وضخ البروتونات لتوليد طاقة ATP"]},{"id":"lhx_phase11_chapitres_21_22_2_card2_2","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"مخطط نقل الإلكترونات وضخ البروتونات لتوليد طاقة ATP (2/2)","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":2,"total":2,"text":"خروج البروتونات ( تبديد التدرج ) : الغشاء غير منفذ للبروتونات، فالمنفذ الوحيد لخروجها نحو الحشوة هو عبر قناة الكرية المذذبة ( ATP synthase ) . الفسفرة الضوئية ( Photophosphorylation ) : خروج السيل الجارف من H⁺ يحرر طاقة تدير الجزء التحفيزي للكرية المذذبة وتدمج الفوسفات ( Pi ) مع الـ ADP لإنتاج جزيئات الـ ATP .","keywords":["مخطط","نقل","الالكترونات","وضخ","البروتونات","لتوليد","طاقه","atp","كيف","تتحول","المتحركه","الي","جزييات","بطاريه","تبديد","التدرج","للبروتونات،","فالمنفذ"],"aliases":["مخطط نقل الإلكترونات وضخ البروتونات لتوليد طاقة ATP"]},{"id":"lhx_phase11_chapitres_21_22_2_card3_1","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"⚡ الفسفرة الضوئية الناجحة","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":1,"total":1,"text":"3 محاكي إنتاج نواتج المرحلة الكيميوضوئية اضغط لتنفيذ الخطوة النهائية وتزويد الحشوة بالطاقة والنوادي المرجعة : ⚡ خروج H⁺ عبر ATP synthase (إنتاج ATP) 🧪 وصول e⁻ للإنزيم المرجع (إنتاج NADPH, H⁺) ⚡ الفسفرة الضوئية الناجحة تنتج المرحلة الكيميوضوئية مركبين جوهريين في الحشوة : بطاريات الطاقة ATP والنوادي الغنية بالإلكترونات NADPH, H⁺ . هذان المركبان هما الوقود الحصري الذي سيشغل المرحلة الكيميوحيوية (حلقة كالفن) لبناء سكر النشا.","keywords":["الفسفره","الضوييه","الناجحه","كيف","تتحول","طاقه","الالكترونات","المتحركه","الي","جزييات","بطاريه","atp","محاكي","انتاج","نواتج","المرحله","الكيميوضوييه","لتنفيذ"],"aliases":["⚡ الفسفرة الضوئية الناجحة"]},{"id":"lhx_phase11_chapitres_21_22_2_card4_1","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟ (1/2)","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 حدّد دور النظامين الضوئيين PSII و PSI ومصدر الأكسجين المنطلق. تجري المرحلة الكيموضوئية على أغشية التيلاكويد وتضم النظامين الضوئيين PSII و PSI والسيبلاست. يلتقط الكلوروفيل الفوتونات فتشتد طاقة إلكتروناته وينطلق عبر سلسلة نقل الإلكترونات. مصدر الأكسجين المنطلق هو التحلل الضوئي لجزيئة الماء وتحرر البروتونات والإلكترونات. يولد تدرج البروتونات بين حشية التيلاكويد والحشوة قوة دافعة لإنزيم ATP-synthase. يُرجع آخر مستقبل للإلكترونات NADP+ إلى NADPH بمشاركة H+. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["كيف","تتحول","طاقه","الالكترونات","المتحركه","الي","جزييات","بطاريه","atp","خلاصه","الدرس","النظامين","الضوييين","ومصدر","الاكسجين","المنطلق","المرحله","الكيموضوييه"],"aliases":["كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟"]},{"id":"lhx_phase11_chapitres_21_22_2_card4_2","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟ (2/2)","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":2,"total":2,"text":"التحلل الضوئي للماء / النظامان الضوئيان","keywords":["كيف","تتحول","طاقه","الالكترونات","المتحركه","الي","جزييات","بطاريه","atp","التحلل","للماء","النظامان","الضوييان"],"aliases":["كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟"]},{"id":"lhx_phase11_chapitres_21_22_2_card5_1","kind":"html","lessonKey":"phase11_chapitres_21_22_2","title":"1. ماذا يحدث لإنتاج الـ ATP إذا وضعنا تيلاكويد معزول في وسط يحتوي على مادة تجعل الغشاء منفذاً حراً لشوارد الهيدروجين ( H⁺ )؟","lessonTitle":"كيف تتحول طاقة الإلكترونات المتحركة إلى جزيئات بطارية (ATP)؟","unitId":6,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ماذا يحدث لإنتاج الـ ATP إذا وضعنا تيلاكويد معزول في وسط يحتوي على مادة تجعل الغشاء منفذاً حراً لشوارد الهيدروجين ( H⁺ )؟ أ) يتوقف إنتاج الـ ATP نهائياً، لأن نفاذية الغشاء تمنع تشكل تدرج تركيز البروتونات ( H⁺ )، فلا تعبر شوارد H⁺ عبر الكرية المذذبة. ب) يتضاعف إنتاج الـ ATP عشر مرات. ج) يتحول التيلاكويد إلى ميتوكندرون.","keywords":["ماذا","يحدث","لانتاج","atp","اذا","وضعنا","تيلاكويد","معزول","وسط","يحتوي","علي","ماده","تجعل","الغشاء","منفذا","حرا","لشوارد","الهيدروجين"],"aliases":["1. ماذا يحدث لإنتاج الـ ATP إذا وضعنا تيلاكويد معزول في وسط يحتوي على مادة تجعل الغشاء منفذاً حراً لشوارد الهيدروجين ( H⁺ )؟"]},{"id":"lhx_phase12_chapitres_23_24_intro_1","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 1 : آليات تحويل الطاقة الضوئية إلى طاقة كيميائية كامنة 🎯 الهدف العلمي : حدّد خطوات حلقة كالفن (التثبيت، الإرجاع، التجديد)، ووضّح دور إنزيم الروبيسكو واستهلاك نواتج المرحلة الضوئية (ATP و NADPH). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن تجريبي أن المرحلتين متكاملتان وضروريتان لبعضهما، واكتب المعادلة الإجمالية واحسب استهلاك طاقة ATP لنبتة واحدة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","تفاعلات","المرحله","الكيموحيويه","الثاني","التحولات","الطاقويه","اليات","تحويل","الضوييه","كيمياييه","كامنه","خطوات","كالفن","التثبيت،","الارجاع،","التجديد","الروبيسكو"],"aliases":["الدرس 4","تفاعلات المرحلة الكيموحيوية"]},{"id":"lhx_phase12_chapitres_23_24_card1_1","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف يبني النبات جذوعه وأوراقه وثماره انطلاقا من غاز في الهواء؟ المادة العضوية للنبات (سكر النشا، السليلوز، الغلوكوز) تتكون أساساً من سلاسل كربونية ( C-C ). والمصدر الوحيد لهذا الكربون هو غاز ثاني أكسيد الكربون ( CO₂ ) الموجود في الهواء بنسبة ضئيلة جداً (0.04%). كيف تقوم الحشوة (الستروما) باقتناص وتثبيت جزيئات الـ CO₂ الغازية وربطها معاً لتشكيل سكر الغلوكوز (C₆H₁₂O₆) الصلب والغني بالطاقة؟","keywords":["الدرس","تفاعلات","المرحله","الكيموحيويه","وضعيه","الانطلاق","وبناء","العلميه","النبات","جذوعه","واوراقه","وثماره","انطلاقا","الهواء؟","العضويه","للنبات","النشا،","السليلوز،"],"aliases":["الدرس 4","تفاعلات المرحلة الكيموحيوية"]},{"id":"lhx_phase12_chapitres_23_24_card2_1","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"مخطط حلقة كالفن (دورة إدماج الكربون في الحشوة بتدخل إنزيم Rubisco) (1/2)","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":1,"total":2,"text":"2 التحليل المنهجي لتجارب كالفن وبنسون (الكربون المشع ¹⁴CO₂) وخطوات الحلقة مخطط حلقة كالفن (دورة إدماج الكربون في الحشوة بتدخل إنزيم Rubisco) + 6 CO₂ (تثبيـت) إنزيم Rubisco 12 APG (C₃) استهلاك 12 ATP/NADPH 1 غلوكوز (C₆H₁₂O₆) 6 RuBP (C₅) تجديد بـ 6 ATP 💡 أول مركب ثابت يتشكل بعد تثبيت CO₂ هو حمض الفوسفوغليسيريك APG (C₃). منهجية البكالوريا : أطوار حلقة كالفن الثلاثة كيف تعمل حلقة كالفن؟ مرحلة التثبيت ( Fixation ) : يثبت غاز CO₂ على مستقبل خماسي الكربون هو الـ RuBP (ريبولوز ثنائي الفوسفات) بتدخل إنزيم Rubisco ،","keywords":["مخطط","حلقه","كالفن","دوره","ادماج","الكربون","الحشوه","بتدخل","انزيم","rubisco","الدرس","تفاعلات","المرحله","الكيموحيويه","لتجارب","وبنسون","المشع","وخطوات"],"aliases":["مخطط حلقة كالفن (دورة إدماج الكربون في الحشوة بتدخل إنزيم Rubisco)"]},{"id":"lhx_phase12_chapitres_23_24_card2_2","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"مخطط حلقة كالفن (دورة إدماج الكربون في الحشوة بتدخل إنزيم Rubisco) (2/2)","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":2,"total":2,"text":"فيعطي مباشرة جزيئتين من مركب ثلاثي الكربون هو APG (حمض الفوسفوغليسيريك) . مرحلة الإرجاع ( Réduction ) : يرجع حمض APG إلى سكر ثلاثي فوسفغليسيرألديهيد ( PGAL ) باستهلاك طاقة ATP وإلكترونات NADPH, H⁺ القادمة من المرحلة الضوئية. مرحلة التجديد والبناء : يُستعمل 1/6 من سكر PGAL لتركيب سكر الغلوكوز سداسي الكربون ( C₆H₁₂O₆ ) والنشا، بينما تُستعمل 5/6 المتبقية لتجديد الـ RuBP لاستمرار الحلقة باستهلاك ATP .","keywords":["مخطط","حلقه","كالفن","دوره","ادماج","الكربون","الحشوه","بتدخل","انزيم","rubisco","الدرس","تفاعلات","المرحله","الكيموحيويه","فيعطي","مباشره","جزييتين","ثلاثي"],"aliases":["مخطط حلقة كالفن (دورة إدماج الكربون في الحشوة بتدخل إنزيم Rubisco)"]},{"id":"lhx_phase12_chapitres_23_24_card3_1","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"1️⃣ الخطوة الأولى : تثبيت غاز الكربون CO₂","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":1,"total":1,"text":"3 محاكي عجلة كالفن التفاعلي اضغط لتنفيذ خطوات حلقة كالفن وبناء جزيء غلوكوز كامل (يتطلب 6 دورات وتثبيت 6 CO₂) : 1️⃣ تثبيت 6 CO₂ بواسطة إنزيم Rubisco 2️⃣ إرجاع 12 APG إلى 12 PGAL 3️⃣ بناء الغلوكوز وتجديد الـ RuBP 1️⃣ الخطوة الأولى : تثبيت غاز الكربون CO₂ يقوم إنزيم الروبيسكو ( Rubisco ) بدمج 6 جزيئات من غاز CO₂ (6 كربون) مع 6 جزيئات من مستقبل RuBP (30 كربون). تتشكل 12 جزيئة من حمض APG ثلاثي الكربون (المجموع 36 ذرة كربون وثابتة).","keywords":["الخطوه","الاولي","تثبيت","غاز","الكربون","الدرس","تفاعلات","المرحله","الكيموحيويه","محاكي","كالفن","التفاعلي","لتنفيذ","خطوات","وبناء","غلوكوز","يتطلب","دورات"],"aliases":["1️⃣ الخطوة الأولى","تثبيت غاز الكربون CO₂"]},{"id":"lhx_phase12_chapitres_23_24_card4_1","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"1. ما هو الإنزيم الرئيسي المتدخل في المرحلة الكيميوحيوية (حشوة الصانعة) ومسؤول عن تثبيت الـ CO₂ ؟","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":1,"total":1,"text":"4 تقويم النشاط 4 : أسئلة البكالوريا المتكررة 1. ما هو الإنزيم الرئيسي المتدخل في المرحلة الكيميوحيوية (حشوة الصانعة) ومسؤول عن تثبيت الـ CO₂ ؟ أ) إنزيم الروبيسكو ( Rubisco - Ribulose-1,5-bisphosphate carboxylase ). ب) إنزيم الـ ATP synthase . ج) إنزيم الأستيل كولين إستراز.","keywords":["الانزيم","الرييسي","المتدخل","المرحله","الكيميوحيويه","حشوه","الصانعه","ومسوول","تثبيت","الدرس","تفاعلات","الكيموحيويه","الروبيسكو","rubisco","ribulose","bisphosphate","carboxylase","synthase"],"aliases":["1. ما هو الإنزيم الرئيسي المتدخل في المرحلة الكيميوحيوية (حشوة الصانعة) ومسؤول عن تثبيت الـ CO₂ ؟"]},{"id":"lhx_phase12_chapitres_23_24_card5_1","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"الدرس 4 : تفاعلات المرحلة الكيموحيوية (1/2)","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 34) الوحدة: D2-U6 — التركيب الضوئي — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. « التركيب الضوئي هو آلية تسمح بتحويل الطاقة الضوئية إلى طاقة كيميائية مخزنة في شكل جزيئات عضوية مثل النشا، وفق المعادلة : » n(H₂O) + n(CO₂) ──(ضوء + يخضور)──► (CH₂O)ₙ + n(O₂) تتطلب العملية توفر الضوء واليخضور، وتتم في الصانعات الخضراء المقسمة إلى حجرات. تحتوي أغشية التيلاكويد على : أغشية ضوئية (النظامان PS-I و PS-II)، ناقلات الإلكترونات،","keywords":["الدرس","تفاعلات","المرحله","الكيموحيويه","المعرفيه","الرسمي","للكتاب","المدرسي","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي","مقروءا","بتحويل","الضوييه"],"aliases":["الدرس 4","تفاعلات المرحلة الكيموحيوية"]},{"id":"lhx_phase12_chapitres_23_24_card5_2","kind":"html","lessonKey":"phase12_chapitres_23_24","title":"الدرس 4 : تفاعلات المرحلة الكيموحيوية (2/2)","lessonTitle":"الدرس 4 : تفاعلات المرحلة الكيموحيوية","unitId":6,"part":2,"total":2,"text":"ومعقد بروتيني كبير يركب ATP. تحتوي الحشوة على مواد الأيض الوسطية والمرافقات الإنزيمية (ATP, NADP) وإنزيمات التركيب العضوي. للظاهرة مرحلتان : مرحلة كيموضوئية على أغشية التيلاكويد، ومرحلة كيميوحيوية في الحشوة.","keywords":["الدرس","تفاعلات","المرحله","الكيموحيويه","ومعقد","بروتيني","تحتوي","الحشوه","الايض","الوسطيه","والمرافقات","الانزيميه","وانزيمات","العضوي","للظاهره","مرحلتان","مرحله","كيموضوييه"],"aliases":["الدرس 4","تفاعلات المرحلة الكيموحيوية"]},{"id":"lhx_phase12_chapitres_23_24_2_intro_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 1 : آليات تحويل الطاقة الضوئية إلى طاقة كيميائية كامنة 🎯 الهدف العلمي : حدّد خطوات حلقة كالفن (التثبيت، الإرجاع، التجديد)، ووضّح دور إنزيم الروبيسكو واستهلاك نواتج المرحلة الضوئية (ATP و NADPH). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن تجريبي أن المرحلتين متكاملتان وضروريتان لبعضهما، واكتب المعادلة الإجمالية واحسب استهلاك طاقة ATP لنبتة واحدة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","الثاني","التحولات","الطاقويه","اليات","تحويل","الضوييه","كيمياييه"],"aliases":["لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟"]},{"id":"lhx_phase12_chapitres_23_24_2_card1_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":1,"text":"1 الإشكالية الختامية للوحدة الأولى من المجال الثاني ⚠️ لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟ تسمى المرحلة الثانية بالمرحلة الكيميوحيوية لأنها لا تتطلب ضوءاً بشكل مباشر في تفاعلاتها. ولكن تجريبياً، إذا نقلنا نبتة من الضوء إلى الظلام التام، تتوقف حلقة كالفن عن تثبيت CO₂ بعد ثوانٍ معدودة! وكذلك إذا منعنا الـ CO₂ في الضوء تتوقف أكسدة الماء في التيلاكويد! كيف يفسر هذا الترابط الوثيق والتكامل التام بين المرحلتين؟","keywords":["لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","الختاميه","للوحده","الاولي","الثاني","الثانيه","بالمرحله","لانها"],"aliases":["لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟"]},{"id":"lhx_phase12_chapitres_23_24_2_card2_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"مخطط الازدواج الوظيفي (دورة جزيئات الطاقة والنواقل بين التيلاكويد والحشوة) (1/2)","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":2,"text":"2 التحليل المنهجي لمخطط التكامل والازدواج الوظيفي بين التيلاكويد والحشوة مخطط الازدواج الوظيفي (دورة جزيئات الطاقة والنواقل بين التيلاكويد والحشوة) التيلاكويد (ضوء) المرحلة الكيميوضوئية H₂O → O₂ ↑ الحشوة (Rubisco) المرحلة الكيميوحيوية CO₂ → سكر النشا ATP + NADPH, H⁺ ADP + Pi + NADP⁺ 💡 المرحلة الضوئية تنتج الوقود، والمرحلة الحيوية تستهلكه وترجع فوارغه. تعليل التكامل في البكالوريا لماذا لا تعمل مرحلة دون الأخرى؟ • المرحلة الكيميوضوئية تزود المرحلة الكيميوحيوية بـ :","keywords":["مخطط","الازدواج","الوظيفي","دوره","جزييات","الطاقه","والنواقل","بين","التيلاكويد","والحشوه","لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم"],"aliases":["مخطط الازدواج الوظيفي (دورة جزيئات الطاقة والنواقل بين التيلاكويد والحشوة)"]},{"id":"lhx_phase12_chapitres_23_24_2_card2_2","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"مخطط الازدواج الوظيفي (دورة جزيئات الطاقة والنواقل بين التيلاكويد والحشوة) (2/2)","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":2,"total":2,"text":"طاقة ATP ونواقل الهيدروجين المرجعة NADPH, H⁺ الضرورية لإرجاع حمض APG وبناء الغلوكوز. وفي غياب الضوء تنفد هذه النواتج وتتوقف حلقة كالفن. • المرحلة الكيميوحيوية تزود المرحلة الكيميوضوئية بـ : النواقل المؤكسدة فارغة الشحنة ADP + Pi و NADP⁺ . وفي غياب الـ CO₂ تتوقف حلقة كالفن، فتتراكم النواقل المرجعة ويتوقف أكسدة الماء في التيلاكويد لعدم وجود مستقبلات إلكترونات فارغة!","keywords":["مخطط","الازدواج","الوظيفي","دوره","جزييات","الطاقه","والنواقل","بين","التيلاكويد","والحشوه","لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم"],"aliases":["مخطط الازدواج الوظيفي (دورة جزيئات الطاقة والنواقل بين التيلاكويد والحشوة)"]},{"id":"lhx_phase12_chapitres_23_24_2_card3_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"☀️ ضوء + CO₂ : تركيب ضوئي نشط 100%","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":1,"text":"3 مختبر التكامل الوظيفي التفاعلي اختر الشرط التجريبي لمعاينة استجابة المرحلتين وحصيلة التركيب الضوئي : ☀️ ضوء + غاز CO₂ (تكامل طبيعي مستمر) 🌑 ظلام + غاز CO₂ (توقف الكيميوحيوية) ☀️ ضوء دون غاز CO₂ (توقف الكيميوضوئية) ☀️ ضوء + CO₂ : تركيب ضوئي نشط 100% المرحلتان تعملان بتناغم دوري مثالي. ينتج التيلاكويد طاقة ATP وتستهلكها الحشوة لتثبيت CO₂ وبناء النشا، ثم تعود الفوارغ للتيلاكويد ليعاد شحنها بالضوء.","keywords":["ضوء","تركيب","ضويي","نشط","100","لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","مختبر","التكامل"],"aliases":["☀️ ضوء + CO₂","تركيب ضوئي نشط 100%"]},{"id":"lhx_phase12_chapitres_23_24_2_card4_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟ (1/2)","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 فسّر تفاعلات المرحلة الكيميوحيوية (حلقة كالفن) وتحويل CO2 إلى مادة عضوية. تجري المرحلة الكيميوحيوية في حشوة الصانعة الخضراء ولا تحتاج إلى ضوء مباشرة. يتثبت CO2 على الريبولوز ثنائي الفوسفات (5C) بفضل إنزيم Rubisco. تُرجع سكريات ثلاثية الفوسفات باستعمال ATP و NADPH القادمين من المرحلة الكيموضوئية. يتجزأ جزء من السكريات المثلثة لتجديد مستقبل CO2 ويدور بذلك التفاعل حلقة. توجه بقية السكريات نحو تركيب الغلوكوز والنشا مخزنة الطاقة كيميائياً كامنة. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","خلاصه","الدرس","تفاعلات","كالفن","وتحويل","عضويه","الصانعه"],"aliases":["لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟"]},{"id":"lhx_phase12_chapitres_23_24_2_card4_2","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟ (2/2)","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":2,"total":2,"text":"المرحلة الكيميوحيوية / حلقة كالفن","keywords":["لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","كالفن"],"aliases":["لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟"]},{"id":"lhx_phase12_chapitres_23_24_2_card5_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"1. كم تستهلك حلقة كالفن لتركيب جزيء غلوكوز واحد ( C₆H₁₂O₆ ) انطلاقا من 6 جزيئات CO₂ ؟","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":1,"text":"4 تقويم النشاط 5 : الحصيلة الطاقوية الشاملة 1. كم تستهلك حلقة كالفن لتركيب جزيء غلوكوز واحد ( C₆H₁₂O₆ ) انطلاقا من 6 جزيئات CO₂ ؟ أ) تستهلك 18 جزيئة ATP و 12 جزيئة NADPH, H⁺ (المعادلة : 6CO₂ + 18ATP + 12NADPH, H⁺ → الغلوكوز). ب) تستهلك 2 ATP فقط. ج) لا تستهلك أي طاقة نهائياً.","keywords":["تستهلك","حلقه","كالفن","لتركيب","جزيء","غلوكوز","واحد","انطلاقا","جزييات","لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها"],"aliases":["1. كم تستهلك حلقة كالفن لتركيب جزيء غلوكوز واحد ( C₆H₁₂O₆ ) انطلاقا من 6 جزيئات CO₂ ؟"]},{"id":"lhx_phase12_chapitres_23_24_2_card6_1","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟ (1/2)","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 34) الوحدة: D2-U6 — التركيب الضوئي — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. « التركيب الضوئي هو آلية تسمح بتحويل الطاقة الضوئية إلى طاقة كيميائية مخزنة في شكل جزيئات عضوية مثل النشا، وفق المعادلة : » n(H₂O) + n(CO₂) ──(ضوء + يخضور)──► (CH₂O)ₙ + n(O₂) تتطلب العملية توفر الضوء واليخضور، وتتم في الصانعات الخضراء المقسمة إلى حجرات. تحتوي أغشية التيلاكويد على : أغشية ضوئية (النظامان PS-I و PS-II)، ناقلات الإلكترونات،","keywords":["لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","المعرفيه","الرسمي","للكتاب","المدرسي","الكتاب","بتنسيق","قرايي،"],"aliases":["لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟"]},{"id":"lhx_phase12_chapitres_23_24_2_card6_2","kind":"html","lessonKey":"phase12_chapitres_23_24_2","title":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟ (2/2)","lessonTitle":"لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟","unitId":6,"part":2,"total":2,"text":"ومعقد بروتيني كبير يركب ATP. تحتوي الحشوة على مواد الأيض الوسطية والمرافقات الإنزيمية (ATP, NADP) وإنزيمات التركيب العضوي. للظاهرة مرحلتان : مرحلة كيموضوئية على أغشية التيلاكويد، ومرحلة كيميوحيوية في الحشوة.","keywords":["لماذا","تتوقف","المرحله","الكيميوحيويه","الظلام","بعد","ثوان","رغم","انها","تتطلب","ضوءا؟","ومعقد","بروتيني","تحتوي","الحشوه","الايض","الوسطيه","والمرافقات"],"aliases":["لماذا تتوقف المرحلة الكيميوحيوية في الظلام بعد ثوانٍ رغم أنها لا تتطلب ضوءاً؟"]},{"id":"lhx_phase13_chapitres_25_26_intro_1","kind":"html","lessonKey":"phase13_chapitres_25_26","title":"الدرس 3 : التحلل السكري","lessonTitle":"الدرس 3 : التحلل السكري","unitId":7,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 2 : آليات تحويل الطاقة الكيميائية الكامنة إلى ATP 🎯 الهدف العلمي : حدّد الهيولى الأساسية كمقر للتحلل السكري، صف خطوات تفكيك الغلوكوز (C₆) إلى جزيئتي حمض البيروفيك (2 × C₃) مع إنتاج 2 ATP و 2 NADH, H⁺. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد المادة الأساسية للميتوكندرون كمقر لحلقة كريبس، صف تشكل الأستيل مرافق أ ونواتج حلقة كريبس (CO₂ و NADH و FADH₂ و ATP). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","التحلل","السكري","الثاني","التحولات","الطاقويه","اليات","تحويل","الكيمياييه","الكامنه","الاساسيه","للتحلل","السكري،","خطوات","تفكيك","الغلوكوز","جزييتي","البيروفيك"],"aliases":["الدرس 3","التحلل السكري"]},{"id":"lhx_phase13_chapitres_25_26_card1_1","kind":"html","lessonKey":"phase13_chapitres_25_26","title":"الدرس 3 : التحلل السكري","lessonTitle":"الدرس 3 : التحلل السكري","unitId":7,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف تستخرج الخلية الطاقة الأولية من الغلوكوز حتى في غياب الأكسجين؟ تستهلك الخلايا الحية جزيء الغلوكوز ( C₆H₁₂O₆ ) كمصدر رئيسي للطاقة السريعة. وقبل أن يدخل الغلوكوز إلى الميتوكندرون (في التنفس) أو يتخمر، يمر بمرحلة أولية ومشتركة تحدث في الهيولى الأساسية ( Hyaloplasme ) ولا تتطلب أكسجناً، تسمى التحلل السكري ( Glycolyse ) . كيف يتم كسر الغلوكوز سداسي الكربون إلى جزيئتين من حمض البيروفيك ثلاثي الكربون ( CH₃-CO-COOH )؟ وما هي الحصيلة الطاقوية الصافية لهذه المرحلة؟","keywords":["الدرس","التحلل","السكري","وضعيه","الانطلاق","وبناء","العلميه","تستخرج","الاوليه","الغلوكوز","الاكسجين؟","تستهلك","الخلايا","الحيه","كمصدر","رييسي","للطاقه","السريعه"],"aliases":["الدرس 3","التحلل السكري"]},{"id":"lhx_phase13_chapitres_25_26_card2_1","kind":"html","lessonKey":"phase13_chapitres_25_26","title":"مخطط التحلل السكري (تفكيك الغلوكوز C₆ إلى 2 بيروفيك C₃) (1/2)","lessonTitle":"الدرس 3 : التحلل السكري","unitId":7,"part":1,"total":2,"text":"2 التحليل المنهجي لمراحل التحلل السكري في الهيولى (التنشيط والانشطار والأكسدة) مخطط التحلل السكري (تفكيك الغلوكوز C₆ إلى 2 بيروفيك C₃) غلوكوز (C₆) استهلاك 2 ATP فركتوز ثنائي الفوسفات (C₆) انشطـار PGAL (C₃) PGAL (C₃) 2 ATP + NADH 2 ATP + NADH بيروفيك (C₃) بيروفيك (C₃) 💡 الحصيلة الصافية : +2 ATP و +2 NADH, H⁺ لكل جزيء غلوكوز. منهجية البكالوريا : المراحل الكيميائية الثلاثة كيف يفكك الغلوكوز في الهيولى؟ مرحلة التنشيط بالفسفرة :","keywords":["مخطط","التحلل","السكري","تفكيك","الغلوكوز","الي","بيروفيك","الدرس","لمراحل","التنشيط","والانشطار","والاكسده","غلوكوز","استهلاك","فركتوز","ثنايي","الفوسفات","انشطار"],"aliases":["مخطط التحلل السكري (تفكيك الغلوكوز C₆ إلى 2 بيروفيك C₃)"]},{"id":"lhx_phase13_chapitres_25_26_card2_2","kind":"html","lessonKey":"phase13_chapitres_25_26","title":"مخطط التحلل السكري (تفكيك الغلوكوز C₆ إلى 2 بيروفيك C₃) (2/2)","lessonTitle":"الدرس 3 : التحلل السكري","unitId":7,"part":2,"total":2,"text":"يستهلك الغلوكوز جزيئتي 2 ATP ليتحول إلى فركتوز 1،6 ثنائي الفوسفات ( Fructose 1,6-biphosphate ) نشط وغير مستقر. مرحلة الانشطار : ينشطر الفركتوز سداسي الكربون إلى جزيئتين من سكر ثلاثي الفوسفات ( 2 PGAL - C₃ ). مرحلة الأكسدة وإنتاج الطاقة : تتأكسد جزيئتا PGAL بنزع الهيدروجين وإرجاع جزيئتي 2 NAD⁺ إلى 2 NADH, H⁺ ، مع إنتاج 4 جزيئات ATP وتشكل جزيئتين من حمض البيروفيك ( 2 Acide Pyruvique C₃ ) .","keywords":["مخطط","التحلل","السكري","تفكيك","الغلوكوز","الي","بيروفيك","الدرس","يستهلك","جزييتي","ليتحول","فركتوز","ثنايي","الفوسفات","fructose","biphosphate","مستقر","مرحله"],"aliases":["مخطط التحلل السكري (تفكيك الغلوكوز C₆ إلى 2 بيروفيك C₃)"]},{"id":"lhx_phase13_chapitres_25_26_card3_1","kind":"html","lessonKey":"phase13_chapitres_25_26","title":"1️⃣ تنشيط الغلوكوز بالفسفرة","lessonTitle":"الدرس 3 : التحلل السكري","unitId":7,"part":1,"total":1,"text":"3 محاكي التحلل السكري التفاعلي اضغط لتنفيذ تفاعلات التحلل السكري وحساب الحصيلة الصافية : 1️⃣ استثمار 2 ATP لتنشيط الغلوكوز 2️⃣ انشطار السكر إلى جزيئتي PGAL 3️⃣ الأكسدة وإنتاج 4 ATP و 2 بيروفيك 1️⃣ تنشيط الغلوكوز بالفسفرة الغلوكوز جزيء مستقر جداً. لكي يبدأ التفاعل، يجب \"استثمار\" جزيئتي 2 ATP من هيولى الخلية لإضافة مجموعتي فوسفات للغلوكوز وتحويله لفركتوز ثنائي الفوسفات جاهز للانشطار.","keywords":["تنشيط","الغلوكوز","بالفسفره","الدرس","التحلل","السكري","محاكي","التفاعلي","لتنفيذ","تفاعلات","وحساب","الصافيه","استثمار","لتنشيط","انشطار","السكر","جزييتي","الاكسده"],"aliases":["1️⃣ تنشيط الغلوكوز بالفسفرة"]},{"id":"lhx_phase13_chapitres_25_26_card4_1","kind":"html","lessonKey":"phase13_chapitres_25_26","title":"1. لماذا تكون الحصيلة الطاقوية الصافية للتحلل السكري هي 2 ATP فقط رغم أنه يتم إنتاج 4 ATP في المرحلة الأخيرة؟","lessonTitle":"الدرس 3 : التحلل السكري","unitId":7,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. لماذا تكون الحصيلة الطاقوية الصافية للتحلل السكري هي 2 ATP فقط رغم أنه يتم إنتاج 4 ATP في المرحلة الأخيرة؟ أ) لأنه تم استهلاك (استثمار) 2 ATP في المرحلة الأولى لتنشيط الغلوكوز بالفسفرة (4 منتجة - 2 مستهلكة = 2 ATP صافية). ب) لأن الميتوكندرون يمتص 2 ATP فوراً. ج) لأن الغلوكوز يضيع نصف طاقته كحرارة.","keywords":["لماذا","تكون","الحصيله","الطاقويه","الصافيه","للتحلل","السكري","atp","فقط","رغم","انه","يتم","انتاج","المرحله","الاخيره؟","الدرس","التحلل","استهلاك"],"aliases":["1. لماذا تكون الحصيلة الطاقوية الصافية للتحلل السكري هي 2 ATP فقط رغم أنه يتم إنتاج 4 ATP في المرحلة الأخيرة؟"]},{"id":"lhx_phase13_chapitres_25_26_2_intro_1","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 2 : آليات تحويل الطاقة الكيميائية الكامنة إلى ATP 🎯 الهدف العلمي : حدّد الهيولى الأساسية كمقر للتحلل السكري، صف خطوات تفكيك الغلوكوز (C₆) إلى جزيئتي حمض البيروفيك (2 × C₃) مع إنتاج 2 ATP و 2 NADH, H⁺. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد المادة الأساسية للميتوكندرون كمقر لحلقة كريبس، صف تشكل الأستيل مرافق أ ونواتج حلقة كريبس (CO₂ و NADH و FADH₂ و ATP). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","يحرر","الميتوكندرون","الطاقه","الهايله","المخزنه","حمض","البيروفيك؟","الثاني","التحولات","الطاقويه","اليات","تحويل","الكيمياييه","الكامنه","الاساسيه","للتحلل","السكري،"],"aliases":["كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟"]},{"id":"lhx_phase13_chapitres_25_26_2_card1_1","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":1,"total":1,"text":"1 الإشكالية الميتوكندرية للتنفس الخلوي ⚠️ كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟ في وجود الأكسجين (وسط هوائي)، يدخل حمض البيروفيك ( CH₃-CO-COOH ) الناتج عن التحلل السكري إلى عضية متخصصة تسمى الميتوكندرون ( Mitochondrie ) . وبالتحديد في سائل المادة الأساسية ( Matrice ) ، يخضع لسلسلة تفاعلات دائرية أكسدة ونزع كربون تسمى حلقة كريبس ( Cycle de Krebs ) . كيف يتم هدم حمض البيروفيك كلياً إلى غاز CO₂؟ وما هي كمية النواقل المرجعة التي تنتجها هذه الحلقة؟","keywords":["كيف","يحرر","الميتوكندرون","الطاقه","الهايله","المخزنه","حمض","البيروفيك؟","الميتوكندريه","للتنفس","الخلوي","الاكسجين","هوايي","البيروفيك","الناتج","التحلل","السكري","متخصصه"],"aliases":["كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟"]},{"id":"lhx_phase13_chapitres_25_26_2_card2_1","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"مخطط حلقة كريبس لهدم الأستيل مرافق الإنزيم أ (Acétyl-CoA C₂) (1/2)","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":1,"total":2,"text":"2 التحليل المنهجي لتشكل الأستيل-CoA وحلقة كريبس في المادة الأساسية مخطط حلقة كريبس لهدم الأستيل مرافق الإنزيم أ (Acétyl-CoA C₂) بيروفيك (C₃) نزع CO₂ + NADH أستيل-CoA (C₂) أوكسالوأسيتات C₄ سترات C₆ حلقة كريبس النواتج لكل بيروفيك : 3 NADH + 1 FADH₂ + 1 ATP + 2 CO₂ 💡 يندمج الأستيل (C₂) مع مركب رباعي (C₄) ليعطي السترات (C₆) ثم يتأكسد. تفاعلات المادة الأساسية في البكالوريا ما هي خطوات هدم البيروفيك؟ المرحلة التمهيدية (تشكل الأستيل-CoA) :","keywords":["مخطط","حلقه","كريبس","لهدم","الاستيل","مرافق","الانزيم","tyl","coa","كيف","يحرر","الميتوكندرون","الطاقه","الهايله","المخزنه","حمض","البيروفيك؟","لتشكل"],"aliases":["مخطط حلقة كريبس لهدم الأستيل مرافق الإنزيم أ (Acétyl-CoA C₂)"]},{"id":"lhx_phase13_chapitres_25_26_2_card2_2","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"مخطط حلقة كريبس لهدم الأستيل مرافق الإنزيم أ (Acétyl-CoA C₂) (2/2)","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":2,"total":2,"text":"يخضع حمض البيروفيك ( C₃ ) في المادة الأساسية لنزع كربون ( CO₂ ↑ ) ونزع هيدروجين ( NADH, H⁺ ) ويرتبط بمرافق الإنزيم أ ليعطي مركب ثنائي الكربون الأستيل-CoA ( C₂ ) . دخول حلقة كريبس : يندمج الأستيل ( C₂ ) مع حمض الأوكسالوأسيتك ( C₄ ) ليعطي حمض الستريك ( Citrate C₆ ). تفاعلات نزع الكربون والهيدروجين : من خلال سلسلة تفاعلات دائرية، يُهدم السترات كلياً ليطرح جزيئتي 2 CO₂ ، ويرجع 3 نواقل 3 NAD⁺ → 3 NADH, H⁺ وناقل 1 FAD → 1 FADH₂ ، وينتج جزيئة طاقة واحدة 1 ATP ، ويتجدد الأوكسالوأسيتات لاستقبال أستيل جديد.","keywords":["مخطط","حلقه","كريبس","لهدم","الاستيل","مرافق","الانزيم","tyl","coa","كيف","يحرر","الميتوكندرون","الطاقه","الهايله","المخزنه","حمض","البيروفيك؟","البيروفيك"],"aliases":["مخطط حلقة كريبس لهدم الأستيل مرافق الإنزيم أ (Acétyl-CoA C₂)"]},{"id":"lhx_phase13_chapitres_25_26_2_card3_1","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"1️⃣ التفاعل التمهيدي في المادة الأساسية","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":1,"total":1,"text":"3 محاكي حلقة كريبس وحساب النواتج اضغط لمعاينة التفاعل التمهيدي وحساب نواتج دورة كريبس لجزيء غلوكوز واحد (يتطلب جزيئتي بيروفيك = دورتي كريبس) : 1️⃣ التفاعل التمهيدي (بيروفيك ← أستيل-CoA) 2️⃣ دورة كريبس واحدة (لـ 1 حمض بيروفيك) 3️⃣ الحصيلة الإجمالية للمادة الأساسية (لـ 1 غلوكوز = 2 بيروفيك) 1️⃣ التفاعل التمهيدي في المادة الأساسية قبل دخول حلقة كريبس، يفقد كل حمض بيروفيك ( C₃ ) جزيئة CO₂ ويرجع جزيئة 1 NAD⁺ → 1 NADH, H⁺ ويتصل بمرافق الإنزيم أ مشكلاً الأستيل-CoA ( C₂ ).","keywords":["التفاعل","التمهيدي","الماده","الاساسيه","كيف","يحرر","الميتوكندرون","الطاقه","الهايله","المخزنه","حمض","البيروفيك؟","محاكي","كريبس","وحساب","النواتج","لمعاينه","نواتج"],"aliases":["1️⃣ التفاعل التمهيدي في المادة الأساسية"]},{"id":"lhx_phase13_chapitres_25_26_2_card4_1","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 بيّن مراحل التحلل السكري وتحويل الغلوكوز إلى حمض البيروفيك. يقع مقر التحلل السكري في الهيولى ولا يحتاج إلى الأكسجين. تفكك جزيئة الغلوكوز (6C) إلى جزيئتي حمض البيروفيك (3C) بسلسلة تفاعلات إنزيمية. يربح التحلل السكري صافياً جزيئتي ATP وجزيئتي NADH (مختزلة). يدخل حمض البيروفيك إلى المتوكندري ليكمل تفككه في مرحلة لاحقة. يمثل التحلل السكري الخطوة الأولى المشتركة للأكسدة التنفسية والتخمر. 🔑 المصطلح المفتاحي في البكالوريا : التحلل السكري (Glycolyse) / حمض البيروفيك","keywords":["كيف","يحرر","الميتوكندرون","الطاقه","الهايله","المخزنه","حمض","البيروفيك؟","خلاصه","الدرس","مراحل","التحلل","السكري","وتحويل","الغلوكوز","البيروفيك","يحتاج","الاكسجين"],"aliases":["كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟"]},{"id":"lhx_phase13_chapitres_25_26_2_card5_1","kind":"html","lessonKey":"phase13_chapitres_25_26_2","title":"1. كم عدد جزيئات النواقل المرجعة ( NADH, H⁺ و FADH₂ ) التي تنتجها المادة الأساسية للميتوكندرون أثناء التفكيك التام لجزيء غلوكوز واحد (أي لـ 2 بيروفيك من التمهيدي إلى نهاية كريبس)؟","lessonTitle":"كيف يحرر الميتوكندرون الطاقة الهائلة المخزنة في حمض البيروفيك؟","unitId":7,"part":1,"total":1,"text":"4 تقويم النشاط 2 : الحصيلة النوادي المرجعة 1. كم عدد جزيئات النواقل المرجعة ( NADH, H⁺ و FADH₂ ) التي تنتجها المادة الأساسية للميتوكندرون أثناء التفكيك التام لجزيء غلوكوز واحد (أي لـ 2 بيروفيك من التمهيدي إلى نهاية كريبس)؟ أ) تنتج 8 جزيئات NADH, H⁺ (2 تمهيدي + 6 كريبس) و 2 جزيئات FADH₂ (من كريبس). ب) تنتج 2 NADH فقط. ج) تنتج 38 جزيئة FADH₂.","keywords":["عدد","جزييات","النواقل","المرجعه","nadh","fadh","التي","تنتجها","الماده","الاساسيه","للميتوكندرون","اثناء","التفكيك","التام","لجزيء","غلوكوز","واحد","بيروفيك"],"aliases":["1. كم عدد جزيئات النواقل المرجعة ( NADH, H⁺ و FADH₂ ) التي تنتجها المادة الأساسية للميتوكندرون أثناء التفكيك التام لجزيء غلوكوز واحد (أي لـ 2 بيروفيك من التمهيدي إلى نهاية كريبس)؟"]},{"id":"lhx_phase14_chapitres_27_28_intro_1","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"الدرس 5 : الفسفرة التأكسدية","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 2 : آليات تحويل الطاقة الكيميائية الكامنة إلى ATP 🎯 الهدف العلمي : وضّح دور النواقل البروتينية للأعراف الميتوكندرية في أكسدة النواقل المرجعة، وإرجاع الأكسجين إلى ماء، وفسفرة الـ ADP لإنتاج 38 ATP. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : قارن الهدم الكلي (التنفس 38 ATP) بالهدم الجزئي (التخمر 2 ATP)، صف تحول البيروفيك إلى إيثانول أو حمض اللبن لتجديد NAD⁺. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","الفسفره","التاكسديه","الثاني","التحولات","الطاقويه","اليات","تحويل","الكيمياييه","الكامنه","النواقل","البروتينيه","للاعراف","الميتوكندريه","اكسده","المرجعه،","وارجاع","الاكسجين"],"aliases":["الدرس 5","الفسفرة التأكسدية"]},{"id":"lhx_phase14_chapitres_27_28_card1_1","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"الدرس 5 : الفسفرة التأكسدية","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا نموت خلال دقائق معدودة إذا انقطع عنا الأكسجين؟ خلال التحلل السكري وحلقة كريبس، أنتج الغلوكوز 4 جزيئات ATP فقط بشكل مباشر، بينما تحولت بقية الطاقة إلى 10 جزيئات NADH, H⁺ وجزيئتي FADH₂ . هذه النواقل المرجعة بمثابة شيكات بنكية لا تستطيع الخلية استهلاكها مباشرة! كيف يقوم الغشاء الداخلي للميتوكندرون (الأعراف) في حضور الأكسجين بصرف هذه الشيكات وإعادة أكسدتها لإنتاج الرصيد النهائي الضخم (38 ATP)؟","keywords":["الدرس","الفسفره","التاكسديه","وضعيه","الانطلاق","وبناء","العلميه","دقايق","معدوده","انقطع","الاكسجين؟","التحلل","السكري","وحلقه","كريبس،","الغلوكوز","مباشر،","بينما"],"aliases":["الدرس 5","الفسفرة التأكسدية"]},{"id":"lhx_phase14_chapitres_27_28_card2_1","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية) (1/3)","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":1,"total":3,"text":"2 التحليل المنهجي للسلسلة التنفسية واقتران الأكسدة بالفسفرة مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية) الفراغ بين غشائي (تركيز H⁺ مرتفع جداً) المادة الأساسية (Matrice - أكسجين O₂) T₁ NADH → NAD⁺ T₆ ½ O₂ + 2 H⁺ + 2e⁻ → H₂O ATP synthase 38 ATP 💡 الأكسجين هو المستقبل النهائي للإلكترونات، ويتحول إلى ماء. خطوات الفسفرة التأكسدية كيف يركب الميتوكندرون 38 ATP؟ أكسدة النواقل المرجعة : تتأكسد جزيئات NADH, H⁺ عند الناقل T₁ وتتأكسد FADH₂ عند T₂ ، محررة إلكترونات وبروتونات.","keywords":["مخطط","السلسله","التنفسيه","علي","الغشاء","الداخلي","الاعراف","الميتوكندريه","الدرس","الفسفره","التاكسديه","للسلسله","واقتران","الاكسده","بالفسفره","الفراغ","غشايي","تركيز"],"aliases":["مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية)"]},{"id":"lhx_phase14_chapitres_27_28_card2_2","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية) (2/3)","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":2,"total":3,"text":"نقل الإلكترونات وضخ البروتونات : تنتقل الإلكترونات عبر نواقل السلسلة التنفسية، وتستغل طاقتها لضخ البروتونات H⁺ من المادة الأساسية نحو الفراغ بين غشائي، فينشأ تدرج تركيز. إرجاع الأكسجين ( المستقبل النهائي ) : تصل الإلكترونات للناقل الأخير ( T₆ ) فيتلتقطها الأكسجين الجزيئي ( O₂ ) ويتحد مع بروتونات الحشوة ليعطي جزيئات الماء ( H₂O ). إنتاج الـ ATP : تتدفق البروتونات المحبوسة عائدة نحو المادة الأساسية عبر الكرية المذذبة ( ATP synthase ) ، فيتم فسفرة الـ ADP لإنتاج الرصيد النهائي الكبير : 38 ATP (أو 36 حسب نوع الخلايا).","keywords":["مخطط","السلسله","التنفسيه","علي","الغشاء","الداخلي","الاعراف","الميتوكندريه","الدرس","الفسفره","التاكسديه","الالكترونات","البروتونات","تنتقل","نواقل","التنفسيه،","وتستغل","طاقتها"],"aliases":["مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية)"]},{"id":"lhx_phase14_chapitres_27_28_card2_3","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية) (3/3)","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":3,"total":3,"text":"🔑 بطاقة جزيئة الـ ATP (مورد BAC) : التركيب الكيميائي : قاعدة آزوتية (أدنين) + سكر خماسي (ريبوز) + 3 مجموعات فوسفات — الطاقة مخزنة في الرابطتين الغنيتين بين الفوسفات. النشاطات المستهلكة لـ ATP : الانقباض العضلي، النقل الفعال عبر الأغشية (مضخة Na⁺/K⁺)، التركيبات الحيوية (بروتينات، نشا)، النقل المشبكي وإعادة الاستقطاب.","keywords":["مخطط","السلسله","التنفسيه","علي","الغشاء","الداخلي","الاعراف","الميتوكندريه","الدرس","الفسفره","التاكسديه","بطاقه","جزييه","الكيميايي","قاعده","ازوتيه","ادنين","خماسي"],"aliases":["مخطط السلسلة التنفسية على الغشاء الداخلي (الأعراف الميتوكندرية)"]},{"id":"lhx_phase14_chapitres_27_28_card3_1","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"🟢 الحصيلة الطاقوية الكاملة للتنفس (38 ATP)","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":1,"total":1,"text":"3 محاكي السلسلة التنفسية وحساب الحصيلة اضغط لمعاينة صرف النواقل المرجعة واختبار تأثير سم السيانيد القاتل : 🟢 تنفس هوائي سليم (أكسدة النواقل وإنتاج 38 ATP) 🔴 إضافة سم السيانيد (تثبيط الناقل T₆ والاختناق) 🟢 الحصيلة الطاقوية الكاملة للتنفس (38 ATP) كل جزيئة 1 NADH, H⁺ تعطي 3 ATP (10 × 3 = 30 ATP). وكل جزيئة 1 FADH₂ تعطي 2 ATP (2 × 2 = 4 ATP). زائد 4 ATP مباشرة (2 من التحلل + 2 من كريبس) = المجموع 38 ATP .","keywords":["الحصيله","الطاقويه","الكامله","للتنفس","atp","الدرس","الفسفره","التاكسديه","محاكي","التنفسيه","وحساب","لمعاينه","النواقل","المرجعه","واختبار","تاثير","السيانيد","القاتل"],"aliases":["🟢 الحصيلة الطاقوية الكاملة للتنفس (38 ATP)"]},{"id":"lhx_phase14_chapitres_27_28_card4_1","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"1. ما هو المستقبل الإلكتروني والبروتوني النهائي في السلسلة التنفسية؟ وماذا ينتج عن إرجاعه؟","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ما هو المستقبل الإلكتروني والبروتوني النهائي في السلسلة التنفسية؟ وماذا ينتج عن إرجاعه؟ أ) غاز الأكسجين (O₂) هو المستقبل النهائي، وينتج عن إرجاعه جزيء الماء (H₂O). ب) غاز ثاني أكسيد الكربون هو المستقبل النهائي. ج) حمض البيروفيك هو المستقبل النهائي.","keywords":["المستقبل","الالكتروني","والبروتوني","النهايي","السلسله","التنفسيه؟","وماذا","ينتج","ارجاعه؟","الدرس","الفسفره","التاكسديه","الاكسجين","النهايي،","وينتج","ارجاعه","اكسيد","الكربون"],"aliases":["1. ما هو المستقبل الإلكتروني والبروتوني النهائي في السلسلة التنفسية؟ وماذا ينتج عن إرجاعه؟"]},{"id":"lhx_phase14_chapitres_27_28_card5_1","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"الدرس 5 : الفسفرة التأكسدية (1/2)","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 39، ص 222) الوحدة: D2-U7 — الأكسدة التنفسية — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. يتميز الغشاء الداخلي للميتوكوندري بالسلسلة التنفسية (نواقل الإلكترونات) وبالكريات المذنبة (إنزيم ATP-Synthase). لا تستعمل الميتوكوندري الغلوكوز، بل حمض البيروفيك الناتج من هدمه في الهيولى. حصيلة التحلل السكري : Glucose + 2NAD⁺ + 2ADP + 2Pi → 2 Acide pyruvique + 2ATP + 2NADH,H⁺ حصيلة حلقة كريبس (المعادلة الرسمية للكتاب،","keywords":["الدرس","الفسفره","التاكسديه","المعرفيه","الرسمي","للكتاب","المدرسي","الاكسده","التنفسيه","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي","مقروءا","يتميز"],"aliases":["الدرس 5","الفسفرة التأكسدية"]},{"id":"lhx_phase14_chapitres_27_28_card5_2","kind":"html","lessonKey":"phase14_chapitres_27_28","title":"الدرس 5 : الفسفرة التأكسدية (2/2)","lessonTitle":"الدرس 5 : الفسفرة التأكسدية","unitId":7,"part":2,"total":2,"text":"لجزيء أستيل-CoA واحد) : Acétyl-CoA + 3NAD⁺ + FAD + ADP + Pi → 2CO2 + 3NADH,H⁺ + FADH2 + ATP + CoA-SH حصيلة عدد ATP (الجدول الرسمي للكتاب) : المرحلة ATP مباشرة NADH,H⁺ FADH2 التحلل السكري (الهيولى) 2 2 0 حلقة كريبس (بخطوتها التحضيرية) 2 2 + 6 2 الفسفرة التأكسدية — أكسدة 10 NADH,H⁺ أكسدة 2 FADH2 الحصيلة 4 30 4 الفسفرة التأكسدية (المجموع) 34 ATP (أكسدة 10 NADH,H⁺ ← 30 + أكسدة 2 FADH₂ ← 4) الحصيلة الإجمالية : 38 ATP وفي التخمر (الهدم في غياب الأكسجين) تكون الطاقة المنتجة قليلة : 2 ATP فقط مقابل 38 ATP في التنفس.","keywords":["الدرس","الفسفره","التاكسديه","لجزيء","استيل","3nadh","fadh2","حصيله","الجدول","الرسمي","للكتاب","المرحله","مباشره","التحلل","السكري","كريبس","بخطوتها","التحضيريه"],"aliases":["الدرس 5","الفسفرة التأكسدية"]},{"id":"lhx_phase14_chapitres_27_28_2_intro_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 2 : آليات تحويل الطاقة الكيميائية الكامنة إلى ATP 🎯 الهدف العلمي : وضّح دور النواقل البروتينية للأعراف الميتوكندرية في أكسدة النواقل المرجعة، وإرجاع الأكسجين إلى ماء، وفسفرة الـ ADP لإنتاج 38 ATP. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : قارن الهدم الكلي (التنفس 38 ATP) بالهدم الجزئي (التخمر 2 ATP)، صف تحول البيروفيك إلى إيثانول أو حمض اللبن لتجديد NAD⁺. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟","الثاني","التحولات","الطاقويه","اليات","تحويل","الكيمياييه","الكامنه","النواقل","البروتينيه","للاعراف"],"aliases":["كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟"]},{"id":"lhx_phase14_chapitres_27_28_2_card1_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":1,"text":"1 الإشكالية الطاقوية للوسط اللاهوائي ⚠️ كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟ في غياب الأكسجين ( Anaérobiose )، تتوقف السلسلة التنفسية وتتوقف حلقة كريبس في الميتوكندرون لعدم وجود مستقبل نهائي للإلكترونات. ومع ذلك، تستمر خلايا الخميرة في الحياة والنمو البطيء، وتستمر عضلاتنا بالانقباض لعدة دقائق! كيف يتم التخلص من حمض البيروفيك وتجديد الـ NAD⁺ في الهيولى لضمان استمرار التحلل السكري وإنتاج الحد الأدنى من الطاقة (2 ATP)؟","keywords":["كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟","الطاقويه","للوسط","اللاهوايي","الاكسجين","robiose","تتوقف","التنفسيه","وتتوقف","كريبس","الميتوكندرون"],"aliases":["كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟"]},{"id":"lhx_phase14_chapitres_27_28_2_card2_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"مخطط التخمر اللبني والكحولي في الهيولى الأساسية (هدم جزئي للمادة العضوية) (1/2)","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":2,"text":"2 التحليل المنهجي لمساري التخمر الكحولي والتخمر اللبني مخطط التخمر اللبني والكحولي في الهيولى الأساسية (هدم جزئي للمادة العضوية) 2 حمض بيروفيك (C₃) نزع 2 CO₂ ↑ أستالديهيد (C₂) إرجاع بـ 2 NADH إيثانول (كحول C₂) إرجاع مباشر بـ 2 NADH حمض اللبن (C₃) تعب عضلي / زبادي 💡 الغرض البيولوجي للتخمر هو تجديد NAD⁺ لاستمرار التحلل السكري وإنتاج 2 ATP. التفاصيل الكيميائية في البكالوريا ما هو الفرق بين التخمرين؟ • التخمر الكحولي ( Fermentation Alcoolique الخميرة ) : يطرح حمض البيروفيك جزيئتي 2 CO₂ ،","keywords":["مخطط","التخمر","اللبني","والكحولي","الهيولي","الاساسيه","هدم","جزيي","للماده","العضويه","كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟"],"aliases":["مخطط التخمر اللبني والكحولي في الهيولى الأساسية (هدم جزئي للمادة العضوية)"]},{"id":"lhx_phase14_chapitres_27_28_2_card2_2","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"مخطط التخمر اللبني والكحولي في الهيولى الأساسية (هدم جزئي للمادة العضوية) (2/2)","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":2,"total":2,"text":"ثم يرجع بواسطة 2 NADH, H⁺ ليعطي كحول الإيثانول ( CH₃-CH₂OH ). • التخمر اللبني ( Fermentation Lactique العضلات / البكتيريا ) : يُرجع حمض البيروفيك مباشرة بواسطة 2 NADH, H⁺ دون طرح CO₂ ، ليعطي حمض اللبن الذي يسبب التعب العضلي. الحصيلة الطاقوية : 2 ATP فقط (لأن الكحول وحمض اللبن بقايا عضوية غنية بالطاقة لم تهدم).","keywords":["مخطط","التخمر","اللبني","والكحولي","الهيولي","الاساسيه","هدم","جزيي","للماده","العضويه","كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟"],"aliases":["مخطط التخمر اللبني والكحولي في الهيولى الأساسية (هدم جزئي للمادة العضوية)"]},{"id":"lhx_phase14_chapitres_27_28_2_card3_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"🟢 وسط هوائي (التنفس الخلوي)","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":1,"text":"3 مختبر مقارنة الهدم الكلي (التنفس) بالهدم الجزئي (التخمر) قارن بين استهلاك الخميرة للغلوكوز في الوسط الهوائي والوسط اللاهوائي : 🟢 وسط هوائي O₂ (تنفس : هدم كلي 38 ATP + تكاثر سريع) 🔴 وسط لاهوائي (تخمر : هدم جزئي 2 ATP + كحول إيثانول) 🟢 وسط هوائي (التنفس الخلوي) يتم هدم الغلوكوز كلياً إلى مواد معدنية خالية من الطاقة ( CO₂ + H₂O ). تنتج كمية هائلة من الطاقة ( 38 ATP ) تسمح بتكاثر ونمو سريع جداً لخلايا الخميرة.","keywords":["وسط","هوايي","التنفس","الخلوي","كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟","مختبر","مقارنه","الهدم","الكلي","بالهدم","الجزيي"],"aliases":["🟢 وسط هوائي (التنفس الخلوي)"]},{"id":"lhx_phase14_chapitres_27_28_2_card4_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر آلية الفسفرة التأكسدية ودور تدرج البروتونات في تركيب ATP. تجري الفسفرة التأكسدية على الغشاء الداخلي للمتوكندري (عرائس المتوكندري). تؤكسد سلسلة نقل الإلكترونات الناقلات المختزلة NADH و FADH2. يعد O2 المستقبل النهائي للإلكترونات فيتشكل مع البروتونات جزيئات الماء. يضخ تمرير الإلكترونات البروتونات نحو الحيز بين الغشائي مكوناً تدرجاً كهركيميائياً. يعود H+ إلى الترجمة عبر ATP-synthase فيركب كمية كبيرة من ATP. 🔑 المصطلح المفتاحي في البكالوريا : الفسفرة التأكسدية / سلسلة نقل الإلكترونات","keywords":["كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟","خلاصه","الدرس","الفسفره","التاكسديه","البروتونات","الداخلي","للمتوكندري","عرايس","المتوكندري","توكسد"],"aliases":["كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟"]},{"id":"lhx_phase14_chapitres_27_28_2_card5_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"1. لماذا تعتبر الحصيلة الطاقوية للتخمر (2 ATP) ضئيلة جداً مقارنة بالتنفس (38 ATP)؟","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":1,"text":"4 تقويم النشاط 4 : أسئلة البكالوريا المتكررة 1. لماذا تعتبر الحصيلة الطاقوية للتخمر (2 ATP) ضئيلة جداً مقارنة بالتنفس (38 ATP)؟ أ) لأن التخمر هدم جزئي للغلوكوز، حيث تبقى معظم الطاقة الكيميائية الكامنة مخزنة في الروابط الكربونية للمنتج العضوي النهائي (كحول الإيثانول أو حمض اللبن). ب) لأن التخمر يستهلك 36 ATP في الهيولى. ج) لأن الخميرة لا تحتوي على إنزيمات.","keywords":["لماذا","تعتبر","الحصيله","الطاقويه","للتخمر","atp","ضييله","جدا","مقارنه","بالتنفس","كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟"],"aliases":["1. لماذا تعتبر الحصيلة الطاقوية للتخمر (2 ATP) ضئيلة جداً مقارنة بالتنفس (38 ATP)؟"]},{"id":"lhx_phase14_chapitres_27_28_2_card6_1","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟ (1/2)","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 39، ص 222) الوحدة: D2-U7 — الأكسدة التنفسية — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. يتميز الغشاء الداخلي للميتوكوندري بالسلسلة التنفسية (نواقل الإلكترونات) وبالكريات المذنبة (إنزيم ATP-Synthase). لا تستعمل الميتوكوندري الغلوكوز، بل حمض البيروفيك الناتج من هدمه في الهيولى. حصيلة التحلل السكري : Glucose + 2NAD⁺ + 2ADP + 2Pi → 2 Acide pyruvique + 2ATP + 2NADH,H⁺ حصيلة حلقة كريبس (المعادلة الرسمية للكتاب،","keywords":["كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟","المعرفيه","الرسمي","للكتاب","المدرسي","الاكسده","التنفسيه","الكتاب","بتنسيق","قرايي،","تغيير"],"aliases":["كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟"]},{"id":"lhx_phase14_chapitres_27_28_2_card6_2","kind":"html","lessonKey":"phase14_chapitres_27_28_2","title":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟ (2/2)","lessonTitle":"كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟","unitId":7,"part":2,"total":2,"text":"لجزيء أستيل-CoA واحد) : Acétyl-CoA + 3NAD⁺ + FAD + ADP + Pi → 2CO2 + 3NADH,H⁺ + FADH2 + ATP + CoA-SH حصيلة عدد ATP (الجدول الرسمي للكتاب) : المرحلة ATP مباشرة NADH,H⁺ FADH2 التحلل السكري (الهيولى) 2 2 0 حلقة كريبس (بخطوتها التحضيرية) 2 2 + 6 2 الفسفرة التأكسدية — أكسدة 10 NADH,H⁺ أكسدة 2 FADH2 الحصيلة 4 30 4 الفسفرة التأكسدية (المجموع) 34 ATP (أكسدة 10 NADH,H⁺ ← 30 + أكسدة 2 FADH₂ ← 4) الحصيلة الإجمالية : 38 ATP وفي التخمر (الهدم في غياب الأكسجين) تكون الطاقة المنتجة قليلة : 2 ATP فقط مقابل 38 ATP في التنفس.","keywords":["كيف","تعيش","خلايا","الخميره","عضلاتنا","المجهده","دون","اكسجين؟","لجزيء","استيل","3nadh","fadh2","حصيله","الجدول","الرسمي","للكتاب","المرحله","مباشره"],"aliases":["كيف تعيش خلايا الخميرة أو عضلاتنا المجهدة دون أكسجين؟"]},{"id":"lhx_phase15_chapitres_29_30_intro_1","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 3 : تحويل الطاقة على المستوى ما فوق البنية الخلوية 🎯 الهدف العلمي : استخرج أوجه التشابه البنيوي (الأغشية والكرية المذنبة) والتمايز الوظيفي (فسفرة ضوئية مقابل فسفرة تأكسدية) بين العضيتين الطاقويتين. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن أن المادة تدور في حلقة مغلقة بين التركيب الضوئي والتنفس، بينما الطاقة تتدفق في اتجاه واحد وتتبدد كحرارة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","الثاني","تحويل","الخلويه","استخرج","التشابه","البنيوي","الاغشيه","والكريه","المذنبه","والتمايز","فسفره","ضوييه"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_card1_1","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي (1/2)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":1,"total":2,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا تتشابه آليات إنتاج الـ ATP في الصانعة والميتوكندرون رغم اختلاف وظائفهما؟ تقوم الصانعة الخضراء ببناء المادة العضوية (التركيب الضوئي)، بينما يقوم الميتوكندرون بهدم المادة العضوية (التنفس). ورغم هذا التضاد الوظيفي الظاهري، فإن كليهما يعتمد على غشاء داخلي متخصص يحمل سلاسل نقل إلكترونات ويضخ شوارد الهيدروجين ( H⁺ ) لتوليد تدرج كهروكيميائي يدير نفس الإنزيم المعجز : الكرية المذذبة ( ATP synthase ) !","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","وضعيه","الانطلاق","وبناء","العلميه","تتشابه","اليات","انتاج","الصانعه","والميتوكندرون","اختلاف","وظايفهما؟","الخضراء"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_card1_2","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي (2/2)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":2,"total":2,"text":"ما هي أوجه التشابه والاختلاف الدقيقة بين هذين المحركين الخلويين المعتمدة في البكالوريا؟","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","التشابه","والاختلاف","الدقيقه","المحركين","الخلويين","المعتمده","البكالوريا؟"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_card2_1","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين (1/3)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":1,"total":3,"text":"2 التحليل المنهجي المزدوج لغشاء التيلاكويد مقابل غشاء العرف الميتوكندري مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين 1. التيلاكويد في الصانعة الخضراء الحشوة (Stroma) تجويف التيلاكويد (Lumen - تراكم H⁺) ATP في الحشوة 2. الغشاء الداخلي (العرف) في الميتوكندرون الفراغ بين غشائي (تراكم H⁺) المادة الأساسية (Matrice) ATP في المادة الأساسية 💡 تستهلك الـ ATP حيث تنتج (الحشوة لبناء النشا)، بينما الـ ATP الميتوكندرية تُصدَّر نحو الهيولى لإنجاز مختلف الوظائف الحيوية. منهجية البكالوريا :","keywords":["مقارنه","اتجاه","البروتونات","وعمل","الكريه","المذذبه","العضيتين","الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","المزدوج","لغشاء","التيلاكويد","مقابل","العرف"],"aliases":["مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين"]},{"id":"lhx_phase15_chapitres_29_30_card2_2","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين (2/3)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":2,"total":3,"text":"جدول المقارنة النموذجي أوجه الاختلاف الدقيقة • المصدر الأولي للطاقة : طاقة ضوئية (فوتونات) في الصانعة، مقابل طاقة كيميائية (مستقلبات النواقل المرجعة NADH ) في الميتوكندرون. • المستقبل النهائي للإلكترونات : مرافق الإنزيم NADP⁺ في الصانعة، مقابل غاز الأكسجين O₂ في الميتوكندرون. • جهة ضخ البروتونات H⁺ : من الحشوة إلى تجويف التيلاكويد في الصانعة، ومن المادة الأساسية إلى الفراغ بين غشائي في الميتوكندرون. • مصير طاقة الـ ATP المنتجة : تستهلك محلياً في الحشوة لبناء السكر (حلقة كالفن)،","keywords":["مقارنه","اتجاه","البروتونات","وعمل","الكريه","المذذبه","العضيتين","الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","المقارنه","النموذجي","الاختلاف","الدقيقه","المصدر"],"aliases":["مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين"]},{"id":"lhx_phase15_chapitres_29_30_card2_3","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين (3/3)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":3,"total":3,"text":"مقابل تصديرها لهيولى الخلية لإنجاز مختلف الوظائف الحيوية. 🔑 المخطط التحصيلي للتحولات الطاقوية على المستوى الخلوي (BAC) : تركيب ضوئي : 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂ (طاقة ضوئية ← كيميائية كامنة) · تنفس : C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + 38ATP (كيميائية كامنة ← ATP) · المادة تدور في حلقة مغلقة والطاقة يصنعها الضوء ويبددها التنفس.","keywords":["مقارنه","اتجاه","البروتونات","وعمل","الكريه","المذذبه","العضيتين","الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","مقابل","تصديرها","لهيولي","لانجاز","مختلف"],"aliases":["مقارنة اتجاه ضخ البروتونات وعمل الكرية المذذبة في العضيتين"]},{"id":"lhx_phase15_chapitres_29_30_card3_1","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"🔬 تدرج تركيز البروتونات (H⁺)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":1,"total":1,"text":"3 محاكي المقارنة التفاعلي بين محركي الخلية اضغط على وجه المقارنة لاختبار حفظك لمعايير البكالوريا : 🔬 تدرج تركيز البروتونات (H⁺) 🎯 المستقبل النهائي للإلكترونات ⚡ الهدف الطاقوي والبيولوجي 🔬 تدرج تركيز البروتونات (H⁺) في الصانعة الخضراء يتراكم الـ H⁺ في داخل تجويف التيلاكويد (وسط حامضي). وفي الميتوكندرون يتراكم الـ H⁺ في الفراغ بين غشائي. وفي كلتا الحالتين، يتدفق الـ H⁺ عائداً عبر الكرية المذذبة لتركيب الـ ATP .","keywords":["تدرج","تركيز","البروتونات","الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","محاكي","المقارنه","التفاعلي","محركي","لاختبار","لمعايير","المستقبل","النهايي","للالكترونات"],"aliases":["🔬 تدرج تركيز البروتونات (H⁺)"]},{"id":"lhx_phase15_chapitres_29_30_card4_1","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"1. ما هو العامل المشترك الأساسي الذي يدير إنزيم الـ ATP synthase في كل من الصانعة الخضراء والميتوكندرون؟","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ما هو العامل المشترك الأساسي الذي يدير إنزيم الـ ATP synthase في كل من الصانعة الخضراء والميتوكندرون؟ أ) التدرج الكهروكيميائي لشوارد الهيدروجين ( H⁺ ) عبر الغشاء (النظرية الكيميوأسموزية). ب) غاز ثاني أكسيد الكربون. ج) أشعة الشمس المباشرة.","keywords":["العامل","المشترك","الاساسي","الذي","يدير","انزيم","atp","synthase","الصانعه","الخضراء","والميتوكندرون؟","الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","التدرج"],"aliases":["1. ما هو العامل المشترك الأساسي الذي يدير إنزيم الـ ATP synthase في كل من الصانعة الخضراء والميتوكندرون؟"]},{"id":"lhx_phase15_chapitres_29_30_card5_1","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي (1/4)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":1,"total":4,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 41) الوحدة: D2-U8 — التحولات الطاقوية — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. « تحتاج الكائنات الحية إلى إمداد مستمر من المواد ومن الطاقة لأداء مختلف الوظائف الحيوية والمحافظة على حياتها. تتكون الكائنات العليا (نباتية أو حيوانية) من خلايا مقسمة إلى حجرات مختلفة (هيولي، ميتوكوندري، صانعات خضراء) تحدث فيها تحولات للمادة والطاقة تختلف حسب نوع الخلية وشروط الوسط.","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","المعرفيه","الرسمي","للكتاب","المدرسي","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي","مقروءا"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_card5_2","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي (2/4)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":2,"total":4,"text":"» « ففي الخلايا النباتية اليخضورية أثناء النهار تقوم الخلية بتحويل الطاقة الضوئية إلى طاقة كيميائية كامنة في صورة جزيئات عضوية أثناء التركيب الضوئي في الصانعة الخضراء، وتحويل الطاقة الكيميائية الكامنة إلى طاقة قابلة للاستعمال في صورة ATP خلال التنفس الخلوي في الميتوكوندري. أثناء الليل تتوقف عملية التركيب الضوئي وتحصل الخلية النباتية على طاقتها من التنفس الخلوي. » « تمتاز الخلايا غير اليخضورية (حيوانية، فطريات،","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","الخلايا","النباتيه","اليخضوريه","اثناء","النهار","بتحويل","الضوييه","كيمياييه","كامنه","عضويه","الصانعه","الخضراء،"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_card5_3","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي (3/4)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":3,"total":4,"text":"بكتريا...) بقدرتها على تحويل الطاقة الكيميائية الكامنة في الجزيئات العضوية إلى طاقة قابلة للاستعمال خلال التنفس الخلوي في الظروف الهوائية، وبعض أنواع الخلايا تنتجها دون أكسجين عن طريق التخمر . » تستعمل الخلايا الحية جزيئات ATP في أداء الوظائف المختلفة أهمها : الحركة : تقلص العضلات، حركة الأسواط، حركة الصبغيات... البناء : بناء المركبات الكبيرة انطلاقا من جزيئات بسيطة (البروتين، السكريات الثنائية والمتعددة...). النقل الفعال : نقل المواد عكس تدرج التركيز (كمون الراحة في أغشية الألياف العصبية). المحافظة على الحرارة :","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","بكتريا","بقدرتها","تحويل","الكيمياييه","الكامنه","الجزييات","العضويه","قابله","للاستعمال","التنفس","الظروف","الهواييه،"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_card5_4","kind":"html","lessonKey":"phase15_chapitres_29_30","title":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي (4/4)","lessonTitle":"الدرس 1 : التحولات الطاقوية على المستوى الخلوي","unitId":8,"part":4,"total":4,"text":"إنتاج الحرارة أو التبريد حسب الوسط. « لا يمكن للحياة أن تستمر دون الإمداد المستمر من الطاقة والقدرة على تحويل الطاقة من صورة لأخرى بشكل مستمر. »","keywords":["الدرس","التحولات","الطاقويه","علي","المستوي","الخلوي","انتاج","التبريد","الوسط","للحياه","تستمر","الامداد","المستمر","والقدره","تحويل","لاخري","مستمر"],"aliases":["الدرس 1","التحولات الطاقوية على المستوى الخلوي"]},{"id":"lhx_phase15_chapitres_29_30_2_intro_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":1,"text":"المجال الثاني : التحولات الطاقوية • الوحدة 3 : تحويل الطاقة على المستوى ما فوق البنية الخلوية 🎯 الهدف العلمي : استخرج أوجه التشابه البنيوي (الأغشية والكرية المذنبة) والتمايز الوظيفي (فسفرة ضوئية مقابل فسفرة تأكسدية) بين العضيتين الطاقويتين. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن أن المادة تدور في حلقة مغلقة بين التركيب الضوئي والتنفس، بينما الطاقة تتدفق في اتجاه واحد وتتبدد كحرارة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","الثاني","التحولات","الطاقويه","تحويل"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card1_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":1,"text":"1 الإشكالية الكونية الختامية للمجال الثاني ⚠️ كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ تستهلك ملايين الحيوانات والبشر غاز الأكسجين والمادة العضوية يومياً وتطرح ثاني أكسيد الكربون والماء. ورغم هذا الاستهلاك الهائل، لا ينفد الأكسجين من الغلاف الجوي ولا يختنق العالم بالـ CO₂ ! كيف يحقق التكامل بين التركيب الضوئي (النباتات ذاتية التغذية) والتنفس الخلوي (الحيوانات غير ذاتية التغذية) دورة المادة وتدفق الطاقة في المحيط الحيوي؟","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","الكونيه","الختاميه","للمجال","الثاني"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card2_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"مخطط التكامل البيئي (دورة المادة المغلقة وتدفق الطاقة المفتوح) (1/2)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":2,"text":"2 التحليل المنهجي لدورة المادة وتدفق الطاقة في المحيط الحيوي مخطط التكامل البيئي (دورة المادة المغلقة وتدفق الطاقة المفتوح) الشمس طاقة ضوئية النباتات (التركيب الضوئي) O₂ + مادة عضوية الحيوانات (التنفس) CO₂ + H₂O (دورة المادة المغلقة) حرارة متبددة 💡 المادة تدور باستمرار دون ضياع، بينما الطاقة تتسرب كحرارة وتتطلب إمداداً شمسياً دائماً. الخلاصة الكبرى للمجال الثاني في البكالوريا ما هو الفرق بين مسار المادة ومسار الطاقة؟ • دورة المادة مغلقة ( Cycle fermé de la matière ) :","keywords":["مخطط","التكامل","البييي","دوره","الماده","المغلقه","وتدفق","الطاقه","المفتوح","كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين"],"aliases":["مخطط التكامل البيئي (دورة المادة المغلقة وتدفق الطاقة المفتوح)"]},{"id":"lhx_phase15_chapitres_29_30_2_card2_2","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"مخطط التكامل البيئي (دورة المادة المغلقة وتدفق الطاقة المفتوح) (2/2)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":2,"total":2,"text":"نواتج التنفس ( CO₂ + H₂O ) هي متطلبات التركيب الضوئي، ونواتج التركيب الضوئي ( O₂ + مادة عضوية ) هي متطلبات التنفس. ذرات الكربون والأكسجين والهيدروجين يعاد تدويرها إلى ما لا نهاية. • تدفق الطاقة وحيد الاتجاه ( Flux unidirectionnel de l'énergie ) : تدخل الطاقة للمحيط الحيوي كضوء شمس، تتحول في النبات لطاقة كيميائية، تستهلك في الخلية لإنجاز الأعمال، وتتبدد في النهاية على شكل حرارة ( Chaleur ) تتسرب للفضاء ولا يمكن إعادة استخدامها لبناء الغلوكوز!","keywords":["مخطط","التكامل","البييي","دوره","الماده","المغلقه","وتدفق","الطاقه","المفتوح","كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين"],"aliases":["مخطط التكامل البيئي (دورة المادة المغلقة وتدفق الطاقة المفتوح)"]},{"id":"lhx_phase15_chapitres_29_30_2_card3_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"🌍 توازن بيئي مستدام","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":1,"text":"3 محاكي توازن المحيط الحيوي التفاعلي اختر سيناريو بيئي لمعاينة تأثيره على دورة الحياة الأرضية : 🌍 توازن بيئي طبيعي (نباتات + حيوانات + شمس) 🌑 حجب أشعة الشمس (انقراض شامل) 🌍 توازن بيئي مستدام تضمن الشمس الإمداد الطاقوي المستمر، ويضمن التركيب الضوئي والتنفس إعادة تدوير الكربون والأكسجين. الحياة مستمرة ومتجددة.","keywords":["توازن","بييي","مستدام","كيف","يستمر","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","محاكي","المحيط"],"aliases":["🌍 توازن بيئي مستدام"]},{"id":"lhx_phase15_chapitres_29_30_2_card4_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ (1/2)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 قارن بين التركيب الضوئي والأكسدة التنفسية من حيث المقر والتفاعلات والطاقة. ينظم الكائن الحي ميزان الطاقة بتفاعلات تخليقية وتحللية مترابطة على مستوى الخلية. يلتقط التركيب الضوئي طاقة الضوء ويخزنها في المادة العضوية (تفاعلات بنائية). تفكك الأكسدة التنفسية المادة العضوية وتسترجع طاقتها في جزيئات ATP (تفاعلات هدمية). يتكامل المساران في دورة المادة والطاقة: تبادل O2 و CO2 بين الصانعة والمتوكندريا. تمثل جزيئة ATP العملة الطاقوية المشتركة بين جميع خلايا الكائنات الحية. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","خلاصه","الدرس","والاكسده","التنفسيه"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card4_2","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ (2/2)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":2,"total":2,"text":"التحولات الطاقوية / ATP","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","التحولات","الطاقويه"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card5_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"1. لماذا نقول إن الطاقة \"تتدفق\" في المحيط الحيوي ولا \"تدور\" مثل المادة؟","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. لماذا نقول إن الطاقة \"تتدفق\" في المحيط الحيوي ولا \"تدور\" مثل المادة؟ أ) لأن الطاقة تتحول في النهاية إلى حرارة متبددة في الفضاء لا تستطيع النباتات التقاطها لإعادة بناء الغلوكوز، مما يتطلب إمداداً شمسياً يومياً مستمراً. ب) لأن الشمس تدور حول الأرض. ج) لأن الطاقة تنفد من الكون.","keywords":["لماذا","نقول","الطاقه","تتدفق","المحيط","الحيوي","ولا","تدور","مثل","الماده؟","كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ"],"aliases":["1. لماذا نقول إن الطاقة \"تتدفق\" في المحيط الحيوي ولا \"تدور\" مثل المادة؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card6_1","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ (1/4)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":1,"total":4,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 41) الوحدة: D2-U8 — التحولات الطاقوية — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. « تحتاج الكائنات الحية إلى إمداد مستمر من المواد ومن الطاقة لأداء مختلف الوظائف الحيوية والمحافظة على حياتها. تتكون الكائنات العليا (نباتية أو حيوانية) من خلايا مقسمة إلى حجرات مختلفة (هيولي، ميتوكوندري، صانعات خضراء) تحدث فيها تحولات للمادة والطاقة تختلف حسب نوع الخلية وشروط الوسط.","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","المعرفيه","الرسمي","للكتاب","المدرسي"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card6_2","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ (2/4)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":2,"total":4,"text":"» « ففي الخلايا النباتية اليخضورية أثناء النهار تقوم الخلية بتحويل الطاقة الضوئية إلى طاقة كيميائية كامنة في صورة جزيئات عضوية أثناء التركيب الضوئي في الصانعة الخضراء، وتحويل الطاقة الكيميائية الكامنة إلى طاقة قابلة للاستعمال في صورة ATP خلال التنفس الخلوي في الميتوكوندري. أثناء الليل تتوقف عملية التركيب الضوئي وتحصل الخلية النباتية على طاقتها من التنفس الخلوي. » « تمتاز الخلايا غير اليخضورية (حيوانية، فطريات،","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","الخلايا","النباتيه","اليخضوريه","اثناء"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card6_3","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ (3/4)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":3,"total":4,"text":"بكتريا...) بقدرتها على تحويل الطاقة الكيميائية الكامنة في الجزيئات العضوية إلى طاقة قابلة للاستعمال خلال التنفس الخلوي في الظروف الهوائية، وبعض أنواع الخلايا تنتجها دون أكسجين عن طريق التخمر . » تستعمل الخلايا الحية جزيئات ATP في أداء الوظائف المختلفة أهمها : الحركة : تقلص العضلات، حركة الأسواط، حركة الصبغيات... البناء : بناء المركبات الكبيرة انطلاقا من جزيئات بسيطة (البروتين، السكريات الثنائية والمتعددة...). النقل الفعال : نقل المواد عكس تدرج التركيز (كمون الراحة في أغشية الألياف العصبية). المحافظة على الحرارة :","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","بكتريا","بقدرتها","تحويل","الكيمياييه"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase15_chapitres_29_30_2_card6_4","kind":"html","lessonKey":"phase15_chapitres_29_30_2","title":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟ (4/4)","lessonTitle":"كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟","unitId":8,"part":4,"total":4,"text":"إنتاج الحرارة أو التبريد حسب الوسط. « لا يمكن للحياة أن تستمر دون الإمداد المستمر من الطاقة والقدرة على تحويل الطاقة من صورة لأخرى بشكل مستمر. »","keywords":["كيف","يستمر","توازن","الحياه","علي","كوكب","الارض","منذ","ملايين","السنين","دون","نفاذ","الاكسجين","الكربون؟","انتاج","التبريد","الوسط","للحياه"],"aliases":["كيف يستمر توازن الحياة على كوكب الأرض منذ ملايين السنين دون نفاذ الأكسجين أو الكربون؟"]},{"id":"lhx_phase16_chapitres_31_32_intro_1","kind":"html","lessonKey":"phase16_chapitres_31_32","title":"الدرس 1 : تحديد الصفائح التكتونية","lessonTitle":"الدرس 1 : تحديد الصفائح التكتونية","unitId":9,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 1 : النشاط التكتوني للصفائح 🎯 الهدف العلمي : عرّف الغلاف الصخري والاستينوسفير، وبيّن أن سطح الأرض مقسم إلى صفائح صلبة تتحدد بأحزمة ضيقة وشديدة النشاط الزلزالي والبركاني. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن اتساع قاع المحيط بالأدلة الرسوبية (عمر وسُمك الرسوبيات) والأدلة المغناطيسية (تناوب الأشرطة المغناطيسية المتناظرة بالنسبة للظهيرة). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","تحديد","الصفايح","التكتونيه","الثالث","العامه","التكتوني","للصفايح","الغلاف","الصخري","والاستينوسفير،","صفايح","تتحدد","باحزمه","وشديده","الزلزالي","والبركاني","اتساع"],"aliases":["الدرس 1","تحديد الصفائح التكتونية"]},{"id":"lhx_phase16_chapitres_31_32_card1_1","kind":"html","lessonKey":"phase16_chapitres_31_32","title":"الدرس 1 : تحديد الصفائح التكتونية","lessonTitle":"الدرس 1 : تحديد الصفائح التكتونية","unitId":9,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا تتمركز 90% من زلازل وبراكين العالم في أحزمة جغرافية ضيقة جداً؟ عند رسم خريطة زلازل وبراكين الأرض، نلاحظ أنها لا تتوزع عشوائياً، بل تشكل أحزمة وخطوطاً ضيقة جداً تحيط بمساحات شاسعة وهادئة تكتونياً. ما الذي تمثله هذه المساحات الهادئة (الصفائح التكتونية)؟ وماذا يبرر هذا النشاط العنيف عند حدودها المشتركة؟","keywords":["الدرس","تحديد","الصفايح","التكتونيه","وضعيه","الانطلاق","وبناء","العلميه","تتمركز","زلازل","وبراكين","العالم","احزمه","جغرافيه","خريطه","الارض،","نلاحظ","تتوزع"],"aliases":["الدرس 1","تحديد الصفائح التكتونية"]},{"id":"lhx_phase16_chapitres_31_32_card2_1","kind":"html","lessonKey":"phase16_chapitres_31_32","title":"مقطع رأسي يبين الغلاف الصخري (Lithosphère) وأنواع الحدود التكتونية الثلاثة (1/2)","lessonTitle":"الدرس 1 : تحديد الصفائح التكتونية","unitId":9,"part":1,"total":2,"text":"2 التحليل المنهجي لمقطع في الغلاف الصخري (الصلب) العائم فوق الاستينوسفير (المطاطي) مقطع رأسي يبين الغلاف الصخري (Lithosphère) وأنواع الحدود التكتونية الثلاثة الاستينوسفير (Asthénosphere مطاطي لدن ساخن) صفيحة محيطية 1 صفيحة محيطية 2 صفيحة قارية 3 ظهرة (تباعد) غوص (تقارب) 💡 الغلاف الصخري صلب وسميك (100 كم) يطفو فوق الاستينوسفير اللدن. منهجية البكالوريا : المفاهيم التكتونية الأساسية ما هي الصفيحة التكتونية؟ وما أنواع حدودها؟ الصفيحة التكتونية ( Plaque tectonique ) :","keywords":["مقطع","راسي","يبين","الغلاف","الصخري","lithosph","وانواع","الحدود","التكتونيه","الثلاثه","الدرس","تحديد","الصفايح","لمقطع","الصلب","العايم","الاستينوسفير","المطاطي"],"aliases":["مقطع رأسي يبين الغلاف الصخري (Lithosphère) وأنواع الحدود التكتونية الثلاثة"]},{"id":"lhx_phase16_chapitres_31_32_card2_2","kind":"html","lessonKey":"phase16_chapitres_31_32","title":"مقطع رأسي يبين الغلاف الصخري (Lithosphère) وأنواع الحدود التكتونية الثلاثة (2/2)","lessonTitle":"الدرس 1 : تحديد الصفائح التكتونية","unitId":9,"part":2,"total":2,"text":"هي مساحة شاسعة وصلبة وهادئة تكتونياً من الغلاف الصخري ( Lithosphère )، تحدها أحزمة ضيقة نشطة بالزلازل والبراكين، وتصنف حدودها إلى 3 أنواع : • حدود البناء والتباعد ( Limites divergentes الظهرات المحيطية ) : تتسع عندها المحيطات وتتولد قشرة محيطية جديدة (براكين طفحية وزلازل سطحية). • حدود الهدم والتقارب ( Limites convergentes مناطق الغوص ) : تغوص صفيحة محيطية كثيفة تحت صفيحة قارية (زلازل عميقة وبراكين انفجارية). • حدود محافظة ( Limites conservatives الفوالق التحويلية ) : انزلاق أفقي للصفائح دون بناء أو هدم.","keywords":["مقطع","راسي","يبين","الغلاف","الصخري","lithosph","وانواع","الحدود","التكتونيه","الثلاثه","الدرس","تحديد","الصفايح","مساحه","شاسعه","وصلبه","وهاديه","تكتونيا"],"aliases":["مقطع رأسي يبين الغلاف الصخري (Lithosphère) وأنواع الحدود التكتونية الثلاثة"]},{"id":"lhx_phase16_chapitres_31_32_card3_1","kind":"html","lessonKey":"phase16_chapitres_31_32","title":"🌋 محور الظهرة المحيطية (Dorsale)","lessonTitle":"الدرس 1 : تحديد الصفائح التكتونية","unitId":9,"part":1,"total":1,"text":"3 محاكي حدود الصفائح التكتونية التفاعلي اضغط على نوع الحد التكتوني لمعاينة مميزاته الجيولوجية والزلزالية : 🌋 محور الظهرة المحيطية (حدود تباعد) 💥 منطقة الغوص (حدود تقارب وهدم) ↔️ فالق تحويلي (حدود محافظة) 🌋 محور الظهرة المحيطية (Dorsale) تتميز بقوى شد وتباعد تؤدي إلى صعود الماغما البازلتية الساخنة من الاستينوسفير. تشهد براكين بازلتية طفحية هادئة و زلازل سطحية قليلة العمق ( تتبع خسف الظهرة ( Rift ).","keywords":["محور","الظهره","المحيطيه","dorsale","الدرس","تحديد","الصفايح","التكتونيه","محاكي","التفاعلي","التكتوني","لمعاينه","مميزاته","الجيولوجيه","والزلزاليه","تباعد","منطقه","الغوص"],"aliases":["🌋 محور الظهرة المحيطية (Dorsale)"]},{"id":"lhx_phase16_chapitres_31_32_card4_1","kind":"html","lessonKey":"phase16_chapitres_31_32","title":"1. ما هو الفرق الفيزيائي الذي يسمح للغلاف الصخري ( Lithosphère ) بالطفو والحركة فوق الاستينوسفير ( Asthénosphère )؟","lessonTitle":"الدرس 1 : تحديد الصفائح التكتونية","unitId":9,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ما هو الفرق الفيزيائي الذي يسمح للغلاف الصخري ( Lithosphère ) بالطفو والحركة فوق الاستينوسفير ( Asthénosphère )؟ أ) الغلاف الصخري صلب وبارد، بينما الاستينوسفير لدن ومطاطي ( Ductile ) وأعلى حرارة بسبب سرعة الموجات الزلزالية المنخفضة (منطقة LVZ ). ب) الغلاف الصخري سائل والاستينوسفير صلب. ج) كلاهما صلب ومحكم الارتباط.","keywords":["الفرق","الفيزيايي","الذي","يسمح","للغلاف","الصخري","lithosph","بالطفو","والحركه","فوق","الاستينوسفير","asth","nosph","الدرس","تحديد","الصفايح","التكتونيه","الغلاف"],"aliases":["1. ما هو الفرق الفيزيائي الذي يسمح للغلاف الصخري ( Lithosphère ) بالطفو والحركة فوق الاستينوسفير ( Asthénosphère )؟"]},{"id":"lhx_phase16_chapitres_31_32_2_intro_1","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 1 : النشاط التكتوني للصفائح 🎯 الهدف العلمي : عرّف الغلاف الصخري والاستينوسفير، وبيّن أن سطح الأرض مقسم إلى صفائح صلبة تتحدد بأحزمة ضيقة وشديدة النشاط الزلزالي والبركاني. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن اتساع قاع المحيط بالأدلة الرسوبية (عمر وسُمك الرسوبيات) والأدلة المغناطيسية (تناوب الأشرطة المغناطيسية المتناظرة بالنسبة للظهيرة). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره","افريقيا","تبتعد","امريكا؟","الثالث","العامه","التكتوني","للصفايح","الغلاف","الصخري","والاستينوسفير،"],"aliases":["كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟"]},{"id":"lhx_phase16_chapitres_31_32_2_card1_1","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":1,"total":1,"text":"1 الإشكالية الجيولوجية لاتساع المحيطات ⚠️ كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟ في عام 1912، طرح ألفريد فيغنر نظرية زحزحة القارات مستنداً لتطابق السواحل والمستحاثات، لكنه عجز عن تفسير المحرك! وفي ستينيات القرن الماضي، قدمت سفن الحفر البحري والمسح المغناطيسي البرهان القاطع على اتساع قاع المحيط ( Expansion océanique ) انطلاقاً من الظهرات. كيف تثبت دراسة صخور البازلت والرسوبيات البحرية هذا الاتساع المستمر؟","keywords":["كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره","افريقيا","تبتعد","امريكا؟","الجيولوجيه","لاتساع","المحيطات","1912،","الفريد","فيغنر","نظريه"],"aliases":["كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟"]},{"id":"lhx_phase16_chapitres_31_32_2_card2_1","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"تناوب أشرطة المغناطيسية العادية والمقلوبة وسُمك الرسوبيات على جانبي الظهرة (1/2)","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":1,"total":2,"text":"2 التحليل المنهجي للأشرطة المغناطيسية المتناظرة وعمر الرسوبيات تناوب أشرطة المغناطيسية العادية والمقلوبة وسُمك الرسوبيات على جانبي الظهرة محور الظهرة (Rift - حديث جداً 0 سنة) رسوبيات قديمة وسميكة رسوبيات قديمة وسميكة ← اتساع وحركة تباعد القاع نحو القارات → 💡 التناظر التام للأشرطة بالنسبة لمحور الظهرة يثبت عمل الظهرة كمصنع مستمر لقاع المحيط. الأدلة القاطعة في البكالوريا ما هي شواهد اتساع قاع المحيط؟ الشاهد الرسوبي (الحفر البحري) : كلما ابتعدنا عن محور الظهرة واقتربنا من القارات، يزداد عمر الرسوبيات ويزداد سُمكها .","keywords":["تناوب","اشرطه","المغناطيسيه","العاديه","والمقلوبه","وسمك","الرسوبيات","علي","جانبي","الظهره","كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره"],"aliases":["تناوب أشرطة المغناطيسية العادية والمقلوبة وسُمك الرسوبيات على جانبي الظهرة"]},{"id":"lhx_phase16_chapitres_31_32_2_card2_2","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"تناوب أشرطة المغناطيسية العادية والمقلوبة وسُمك الرسوبيات على جانبي الظهرة (2/2)","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":2,"total":2,"text":"وهذا يثبت أن القاع القريب من الظهرة حديث التكوين، والقاع البعيد قديم. الشاهد المغناطيسي ( Paléomagnétisme ) : تحتوي صخور البازلت على معادن مغناطيسية (المغنيتيت) تسجل اتجاه الحقل المغناطيسي للأرض وقت تصلبها. نلاحظ وجود أشرطة مغناطيسية عادية ومقلوبة متناظرة تماماً بالنسبة لمحور الظهرة، مما يثبت أن القاع يتشكل باستمرار ويندفع بالتساوي نحو الجانبين.","keywords":["تناوب","اشرطه","المغناطيسيه","العاديه","والمقلوبه","وسمك","الرسوبيات","علي","جانبي","الظهره","كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره"],"aliases":["تناوب أشرطة المغناطيسية العادية والمقلوبة وسُمك الرسوبيات على جانبي الظهرة"]},{"id":"lhx_phase16_chapitres_31_32_2_card3_1","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"🌋 عند محور الظهرة مباشرة","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":1,"total":1,"text":"3 محاكي اتساع قاع المحيط والمغناطيسية القديمة اضغط لاختبار عمر وسُمك الرسوبيات حسب المسافة من محور الظهرة : 🌋 عند محور الظهرة مباشرة (المسافة = 0 كم) 🌊 على مسافة متوسطة (500 كم من الظهرة) 🏖️ بالقرب من الساحل القاري (1500 كم من الظهرة) 🌋 عند محور الظهرة مباشرة صخور بازلتية حديثة التكوين جداً (عمرها يقارب 0 سنة). سُمك الرسوبيات معدوم تماماً (0 متر) لعدم مرور وقت يسمح بترسب المستحاثات.","keywords":["عند","محور","الظهره","مباشره","كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره","افريقيا","تبتعد","امريكا؟","محاكي","اتساع","والمغناطيسيه"],"aliases":["🌋 عند محور الظهرة مباشرة"]},{"id":"lhx_phase16_chapitres_31_32_2_card4_1","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟ (1/2)","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":1,"total":2,"text":"📝 خلاصة الدرس 🎯 حدّد الصفائح التكتونية وأسس تحديدها انطلاقاً من توزيع الظواهر الجيولوجية. تنقسم القشرة الأرضية (الغلاف الصخري) إلى صفائح صلبة متحركة على مادة أكثر مرونة. ترسم حدود الصفائح من احتشاد النشاط الزلزالي والبركاني على امتداد أحزمة ضيقة. توجد حدود متباعدة (ظهرات محيطية) وحدود متقاربة (غوص وتصادم) وحدود منزلقة. تتحرك الصفائح بضع سنتيمترات في السنة تحت تأثير الطاقة الداخلية للأرض. يفسر نموذج الصفائح توزيع الزلازل والبراكين وسلاسل الجبال الكبرى. 🔑 المصطلح المفتاحي في البكالوريا :","keywords":["كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره","افريقيا","تبتعد","امريكا؟","خلاصه","الدرس","الصفايح","تحديدها","انطلاقا","توزيع","الظواهر"],"aliases":["كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟"]},{"id":"lhx_phase16_chapitres_31_32_2_card4_2","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟ (2/2)","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":2,"total":2,"text":"الصفائح التكتونية / حدود الصفائح","keywords":["كيف","نثبت","قاع","المحيط","الاطلسي","يتسع","وان","قاره","افريقيا","تبتعد","امريكا؟","الصفايح"],"aliases":["كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟"]},{"id":"lhx_phase16_chapitres_31_32_2_card5_1","kind":"html","lessonKey":"phase16_chapitres_31_32_2","title":"1. ماذا يدل التناظر الهندسي التام لأشرطة المغناطيسية القديمة (العادية والمقلوبة) على جانبي محور الظهرة المحيطية؟","lessonTitle":"كيف نثبت أن قاع المحيط الأطلسي يتسع وأن قارة إفريقيا تبتعد عن أمريكا؟","unitId":9,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. ماذا يدل التناظر الهندسي التام لأشرطة المغناطيسية القديمة (العادية والمقلوبة) على جانبي محور الظهرة المحيطية؟ أ) يدل على أن صخور قاع المحيط تتشكل بشكل مستمر وبسرعة متساوية من صعود الماغما في محور الظهرة، وتندفع نحو الجانبين بشكل متناظر مع مرور الزمن. ب) يدل على أن الأرض تتوقف عن الدوران. ج) يدل على أن المحيط يتقلص وينكمش في محور الظهرة.","keywords":["ماذا","يدل","التناظر","الهندسي","التام","لاشرطه","المغناطيسيه","القديمه","العاديه","والمقلوبه","علي","جانبي","محور","الظهره","المحيطيه؟","كيف","نثبت","قاع"],"aliases":["1. ماذا يدل التناظر الهندسي التام لأشرطة المغناطيسية القديمة (العادية والمقلوبة) على جانبي محور الظهرة المحيطية؟"]},{"id":"lhx_phase17_chapitres_33_34_intro_1","kind":"html","lessonKey":"phase17_chapitres_33_34","title":"الدرس 4 : الظواهر المرتبطة بالغوص","lessonTitle":"الدرس 4 : الظواهر المرتبطة بالغوص","unitId":9,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 1 : النشاط التكتوني للصفائح 🎯 الهدف العلمي : حدّد ظاهرة الغوص (انزلاق صفيحة محيطية كثيفة تحت صفيحة قارية)، وفسّر الشواهد الأربعة (الخندق، موشور المنضد، مستوى بنيوف، والشذوذ الحراري). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر الانصهار الجزئي لبيريدوتيت البرنس العلوي بفعل الإماهة (الماء المحرر من الصفيحة الغائصة)، وتشكل صخور الأنديزيت البركانية والغرانودوريت البلوتونية. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","الظواهر","المرتبطه","بالغوص","الثالث","العامه","التكتوني","للصفايح","ظاهره","الغوص","انزلاق","صفيحه","محيطيه","كثيفه","قاريه","الشواهد","الاربعه","الخندق،"],"aliases":["الدرس 4","الظواهر المرتبطة بالغوص"]},{"id":"lhx_phase17_chapitres_33_34_card1_1","kind":"html","lessonKey":"phase17_chapitres_33_34","title":"الدرس 4 : الظواهر المرتبطة بالغوص","lessonTitle":"الدرس 4 : الظواهر المرتبطة بالغوص","unitId":9,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا لا يزداد حجم الأرض رغم الاتساع المستمر لقاع المحيطات عند الظهرات؟ تنتج الظهرات المحيطية مساحات شاسعة من القشرة المحيطية الجديدة سنوياً منذ ملايين السنين. وبما أن حجم الكرة الأرضية وثابت ولا يتمدد، فإنه من الحتمي أن يتم هدم وابتلاع مساحات مساوية من القشرة المحيطية القديمة في مناطق أخرى من الأرض . هذه المناطق تسمى مناطق الغوص ( Zones de subduction ) . ما هي الشواهد الجيوفيزيائية والزلزالية التي تثبت حدوث هذا الغوص في عمق الستار (البرنس)؟","keywords":["الدرس","الظواهر","المرتبطه","بالغوص","وضعيه","الانطلاق","وبناء","العلميه","يزداد","الاتساع","المستمر","المحيطات","الظهرات؟","الظهرات","المحيطيه","مساحات","شاسعه","الجديده"],"aliases":["الدرس 4","الظواهر المرتبطة بالغوص"]},{"id":"lhx_phase17_chapitres_33_34_card2_1","kind":"html","lessonKey":"phase17_chapitres_33_34","title":"مقطع رأسي في منطقة غوص صفيحة محيطية تحت صفيحة قارية (1/2)","lessonTitle":"الدرس 4 : الظواهر المرتبطة بالغوص","unitId":9,"part":1,"total":2,"text":"2 التحليل المنهجي لمقطع في منطقة الغوص (مستوى بنيوف والشذوذ الحراري) مقطع رأسي في منطقة غوص صفيحة محيطية تحت صفيحة قارية الاستينوسفير (ساخن جداً) صفيحة محيطية (باردة وكثيفة) صفيحة قارية (طافية) الخندق وموشور المنضد مستوى بنيوف (زلازل عميقة) قوس بركاني انفجاري 💡 تتدرج بؤر الزلازل من سطحية عند الخندق إلى عميقة جداً (700 كم). الشواهد الأربعة المعتمدة في البكالوريا ما هي الأدلة الجيوفيزيائية على الغوص؟ الخندق المحيطي ( Fosse océanique ) : انخفاض بحري ضيق وعميق جداً يصل لـ 11 كم عند نقطة انحناء وغوص الصفيحة المحيطية.","keywords":["مقطع","راسي","منطقه","غوص","صفيحه","محيطيه","تحت","قاريه","الدرس","الظواهر","المرتبطه","بالغوص","لمقطع","الغوص","بنيوف","والشذوذ","الحراري","الاستينوسفير"],"aliases":["مقطع رأسي في منطقة غوص صفيحة محيطية تحت صفيحة قارية"]},{"id":"lhx_phase17_chapitres_33_34_card2_2","kind":"html","lessonKey":"phase17_chapitres_33_34","title":"مقطع رأسي في منطقة غوص صفيحة محيطية تحت صفيحة قارية (2/2)","lessonTitle":"الدرس 4 : الظواهر المرتبطة بالغوص","unitId":9,"part":2,"total":2,"text":"موشور المنضد ( Prisme d'accrétion ) : تجمع وكشط الطبقات الرسوبية البحرية المتراكمة فوق الصفيحة الغائصة على حافة الصفيحة الطافية كالجرافة. مستوى بنيوف ( Plan de Benioff ) : تتوزع بؤر الزلازل على طول مائل بزاوية حادة يمتد من الخندق حتى عمق 700 كم، مما يثبت انزلاق صفيحة صلبة كاسرة داخل الاستينوسفير. الشذوذ الحراري ( Anomalie thermique ) : شذوذ سالب (حرارة منخفضة غير عادية في العمق) على طول الصفيحة الغائصة لأنها باردة، وشذوذ موجب تحت القوس البركاني بسبب صعود الماغما.","keywords":["مقطع","راسي","منطقه","غوص","صفيحه","محيطيه","تحت","قاريه","الدرس","الظواهر","المرتبطه","بالغوص","موشور","المنضد","prisme","الطبقات","الرسوبيه","البحريه"],"aliases":["مقطع رأسي في منطقة غوص صفيحة محيطية تحت صفيحة قارية"]},{"id":"lhx_phase17_chapitres_33_34_card3_1","kind":"html","lessonKey":"phase17_chapitres_33_34","title":"💥 مستوى بنيوف للزلازل العميقة (Plan de Benioff)","lessonTitle":"الدرس 4 : الظواهر المرتبطة بالغوص","unitId":9,"part":1,"total":1,"text":"3 محاكي شواهد الغوص التفاعلي اضغط على الشاهد لاختبار عمق الزلازل والشذوذ الحراري : 🌊 الخندق المحيطي وموشور المنضد 💥 مستوى بنيوف للزلازل العميقة 🌡️ الشذوذ الحراري (السالب والموجب) 💥 مستوى بنيوف للزلازل العميقة (Plan de Benioff) في المناطق العادية لا توجد زلازل تحت عمق 100 كم لأن صخور الاستينوسفير مطاطية ولا تنكسر. أما في منطقة الغوص، فيثبت رصد زلازل على عمق 300 و 500 و 700 كم وجود صفيحة صخري صلبة وباردة تغوص وتنكسر داخل البرنس.","keywords":["مستوي","بنيوف","للزلازل","العميقه","plan","benioff","الدرس","الظواهر","المرتبطه","بالغوص","محاكي","شواهد","الغوص","التفاعلي","الشاهد","لاختبار","الزلازل","والشذوذ"],"aliases":["💥 مستوى بنيوف للزلازل العميقة (Plan de Benioff)"]},{"id":"lhx_phase17_chapitres_33_34_card4_1","kind":"html","lessonKey":"phase17_chapitres_33_34","title":"1. ما هو السبب الفيزيائي الكثافي الذي يجعل الصفيحة المحيطية تغوص تحت الصفيحة القارية وليس العكس؟","lessonTitle":"الدرس 4 : الظواهر المرتبطة بالغوص","unitId":9,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ما هو السبب الفيزيائي الكثافي الذي يجعل الصفيحة المحيطية تغوص تحت الصفيحة القارية وليس العكس؟ أ) لأن الغلاف الصخري المحيطي القديم يبرد ويزداد سمكه بمرور الزمن فتصبح كثافته (3.3 g/cm³) أعلى من كثافة الاستينوسفير والقشرة القارية (2.7 g/cm³)، فيغوص بقوة الثقل. ب) لأن الصفيحة القارية تحتوي على ماء أكثر. ج) لأن الجاذبية الأرضية أقوى فوق المحيطات.","keywords":["السبب","الفيزيايي","الكثافي","الذي","يجعل","الصفيحه","المحيطيه","تغوص","تحت","القاريه","وليس","العكس؟","الدرس","الظواهر","المرتبطه","بالغوص","الغلاف","الصخري"],"aliases":["1. ما هو السبب الفيزيائي الكثافي الذي يجعل الصفيحة المحيطية تغوص تحت الصفيحة القارية وليس العكس؟"]},{"id":"lhx_phase17_chapitres_33_34_2_intro_1","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 1 : النشاط التكتوني للصفائح 🎯 الهدف العلمي : حدّد ظاهرة الغوص (انزلاق صفيحة محيطية كثيفة تحت صفيحة قارية)، وفسّر الشواهد الأربعة (الخندق، موشور المنضد، مستوى بنيوف، والشذوذ الحراري). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر الانصهار الجزئي لبيريدوتيت البرنس العلوي بفعل الإماهة (الماء المحرر من الصفيحة الغائصة)، وتشكل صخور الأنديزيت البركانية والغرانودوريت البلوتونية. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","عند","حراره","منخفضه","800","الثالث","العامه","التكتوني","للصفايح","ظاهره","انزلاق","صفيحه","محيطيه"],"aliases":["كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟"]},{"id":"lhx_phase17_chapitres_33_34_2_card1_1","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":1,"total":1,"text":"1 الإشكالية الكيميائية للبراكين الانفجارية ⚠️ كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟ صخر البيريدوتيت الجاف المكون للستار (البرنس) لا ينصهر في المختبر إلا عند حرارة تفوق 1200°C. ولكن في منطقة الغوص، نجد أن بيريدوتيت البرنس العلوي للصفيحة الطافية ينصهر انصهاراً جزئياً عند حرارة تقارب 800°C فقط مولداً ماغما أنديزيتية لزجة وانفجارية! ما الذي يتدخل لخفض نقطة انصهار البيريدوتيت في هذه المنطقة بالتحديد؟","keywords":["كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","عند","حراره","منخفضه","800","الكيمياييه","للبراكين","الانفجاريه","الجاف","المكون","للستار","البرنس","المختبر"],"aliases":["كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟"]},{"id":"lhx_phase17_chapitres_33_34_2_card2_1","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية (1/3)","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":1,"total":3,"text":"2 التحليل المنهجي للتحول المعدني والإماهة والانصهار الجزئي مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية صفيحة غائصة (تحول معدني) تحرر الماء H₂O برنس علوي مماه (Péridotite hydraté) انصهار جزئي أنديزيت (سطحي) غرانودوريت (عميق) 💡 الماء يتدخل كصهارة تخفض عتبة انصهار البيريدوتيت من 1200° إلى 800°C. التسلسل الصخري المعتمد في البكالوريا كيف تتشكل صخور الغوص؟ التحول وتجفيف الصفيحة الغائصة : أثناء غوص القشرة المحيطية، تتعرض لضغط وحرارة متزايدين،","keywords":["مخطط","تحرر","الماء","الصفيحه","الغايصه","واماهه","وانصهار","بيريدوتيت","الطافيه","كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","عند","حراره","منخفضه"],"aliases":["مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية"]},{"id":"lhx_phase17_chapitres_33_34_2_card2_2","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية (2/3)","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":2,"total":3,"text":"فتتحول معادنها المميزة (الشيست الأخضر الغني بالماء $\\rightarrow$ شيست أزرق $\\rightarrow$ إكلوجيت)، ويؤدي هذا التحول إلى تحرر الماء ( H₂O ) . إماهة البرنس العلوي : يصعد الماء المحرر نحو صخر البيريدوتيت المكون للبرنس العلوي للصفيحة الطافية فيحدث له إماهة. الانصهار الجزئي والماغما : يؤدي الماء إلى خفض درجة انصهار البيريدوتيت ، فيحدث له انصهار جزئي مولداً ماغما غنية بالسيليس والغازات. التبريد السطحي والعميق : تصعد الماغما : جزء يتصلب في العمق ببطء معطياً صخر الغرانودوريت ( Granodiorite ذو بنية محببة ) ،","keywords":["مخطط","تحرر","الماء","الصفيحه","الغايصه","واماهه","وانصهار","بيريدوتيت","الطافيه","كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","عند","حراره","منخفضه"],"aliases":["مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية"]},{"id":"lhx_phase17_chapitres_33_34_2_card2_3","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية (3/3)","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":3,"total":3,"text":"وجزء ينفجر على السطح معطياً صخر الأنديزيت ( Andésite ذو بنية ميكروليتية ) المميز للأقواس البركانية.","keywords":["مخطط","تحرر","الماء","الصفيحه","الغايصه","واماهه","وانصهار","بيريدوتيت","الطافيه","كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","عند","حراره","منخفضه"],"aliases":["مخطط تحرر الماء من الصفيحة الغائصة وإماهة وانصهار بيريدوتيت الصفيحة الطافية"]},{"id":"lhx_phase17_chapitres_33_34_2_card3_1","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"💧 بيريدوتيت مماه عند 800°C (انصهار جزئي فعال)","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":1,"total":1,"text":"3 محاكي الانصهار الجزئي وتشكل الصخور قارن شروط انصهار البيريدوتيت وسرعة تبريد الماغما : 🔥 بيريدوتيت جاف عند 1000°C (لا انصهار) 💧 بيريدوتيت مماه عند 800°C (انصهار جزئي وماغما) 🌋 تبريد الماغما (أنديزيت مقابل غرانودوريت) 💧 بيريدوتيت مماه عند 800°C (انصهار جزئي فعال) وجود جزيئات الماء المحررة من تحول الصفيحة الغائصة يغير الخصائص الترموديناميكية لبلورات البيريدوتيت، فيخفض منحنى تصلبه ( Solidus ) فيبدأ بالانصهار الجزئي مولداً قطرات الماغما الصاعدة.","keywords":["بيريدوتيت","مماه","عند","800","انصهار","جزيي","فعال","كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","حراره","منخفضه","محاكي","الانصهار","الجزيي"],"aliases":["💧 بيريدوتيت مماه عند 800°C (انصهار جزئي فعال)"]},{"id":"lhx_phase17_chapitres_33_34_2_card4_1","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر الظواهر المرتبطة بالغوص على المستويين السطحي والعميق. يندس الغلاف المحيطي في الخنادق المحيطية تحت صفيحة أخرى (حدود متقاربة). تتوزع بؤر الزلازل على مستوى بنيوف المائل بعمق يصل إلى 700 كم. يسبب الانصهار الجزئي للوح المندس براكين وازعة على الصفيحة العلوية. يرافق الغوص تحول الصخور (المطاعن) وتشوهات طيات وفوالق. يفسر الغوص اختفاء المحيط القديم وتقارب القارات. 🔑 المصطلح المفتاحي في البكالوريا : الغوص / مستوى بنيوف","keywords":["كيف","ينصهر","صخر","البيريدوتيت","منطقه","الغوص","عند","حراره","منخفضه","800","خلاصه","الدرس","الظواهر","المرتبطه","بالغوص","المستويين","السطحي","والعميق"],"aliases":["كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟"]},{"id":"lhx_phase17_chapitres_33_34_2_card5_1","kind":"html","lessonKey":"phase17_chapitres_33_34_2","title":"1. ما هو الفرق البنيوي بين صخر الأنديزيت وصخر الغرانودوريت رغم أنهما ينتجان عن نفس الماغما؟","lessonTitle":"كيف ينصهر صخر البيريدوتيت في منطقة الغوص عند حرارة منخفضة (800°C)؟","unitId":9,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ما هو الفرق البنيوي بين صخر الأنديزيت وصخر الغرانودوريت رغم أنهما ينتجان عن نفس الماغما؟ أ) الغرانودوريت ذو بنية محببة (بلورات كبيرة مرئية) لأنه تصلب ببطء شديد في العمق، بينما الأنديزيت ذو بنية ميكروليتية (بلورات دقيقة وزجاج) لأنه تصلب بسرعة على السطح بعد الانفجار البركاني. ب) لا يوجد أي فرق بينهما. ج) الأنديزيت صخر رسوبي والغرانودوريت صخر متحول.","keywords":["الفرق","البنيوي","بين","صخر","الانديزيت","وصخر","الغرانودوريت","رغم","انهما","ينتجان","نفس","الماغما؟","كيف","ينصهر","البيريدوتيت","منطقه","الغوص","عند"],"aliases":["1. ما هو الفرق البنيوي بين صخر الأنديزيت وصخر الغرانودوريت رغم أنهما ينتجان عن نفس الماغما؟"]},{"id":"lhx_phase18_chapitres_35_36_intro_1","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 1 : النشاط التكتوني للصفائح 🎯 الهدف العلمي : حدّد مصدر الحرارة الداخلية للأرض (التفكك الإشعاعي)، وميّز بين التوصيل البطيء في الغلاف الصخري والحمل الحراري السريع في البرنس. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن أن الأرض تعمل كآلة حرارية تحول الطاقة الحرارية الداخلية إلى طاقة حركية ميكانيكية (تيارات الحمل الحراري) تدفع الظهرات وتسحب مناطق الغوص. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","الطاقه","الداخليه","للكره","الارضيه","الثالث","العامه","التكتوني","للصفايح","للارض","التفكك","الاشعاعي","التوصيل","البطيء","الغلاف","الصخري","والحمل","الحراري"],"aliases":["الدرس 3","الطاقة الداخلية للكرة الأرضية"]},{"id":"lhx_phase18_chapitres_35_36_card1_1","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ من أين تأتي الحرارة الهائلة التي تذيب الصخور وتدفع البراكين؟ عند النزول في المناجم العميقة، يلاحظ العمال ارتفاعاً مطرداً في درجة الحرارة (حوالي 30°C لكل كيلومتر في القشرة الأرضية) يسمى التدرج الجيوتحراري ( Gradient géothermique ) . وتصل حرارة نواة الأرض إلى 5000°C! ما هو المصدر الحقيقي لهذه الطاقة الداخلية الهائلة؟ وكيف تنتقل من أعماق الأرض نحو السطح؟","keywords":["الدرس","الطاقه","الداخليه","للكره","الارضيه","وضعيه","الانطلاق","وبناء","العلميه","الهايله","الصخور","وتدفع","البراكين؟","النزول","المناجم","العميقه،","يلاحظ","العمال"],"aliases":["الدرس 3","الطاقة الداخلية للكرة الأرضية"]},{"id":"lhx_phase18_chapitres_35_36_card2_1","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"مخطط طرق انتقال الحرارة في أغلفة الأرض (1/3)","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":1,"total":3,"text":"2 التحليل المنهجي لمصدر الحرارة وأنماط انتقالها (التوصيل مقابل الحمل الحراري) مخطط طرق انتقال الحرارة في أغلفة الأرض الغلاف الصخري الصلب (Lithosphère) انتقال بطيء جداً عن طريق التوصيل (Conduction دون حركة مادة) الستار / البرنس اللدن (Manteau - Asthénosphère) تيارات الحمل الحراري (Convection مع حركة مادة) صعود المادة الساخنة وهبوط المادة الباردة 💡 الحمل الحراري هو أسرع وأكفأ وسيلة لنقل الحرارة في الأغلفة اللدنة. منهجية البكالوريا : المفاهيم الحرارية ما هو مصدر الحرارة وكيف تنتقل؟ 1. مصدر الطاقة الداخلية :","keywords":["مخطط","طرق","انتقال","الحراره","اغلفه","الارض","الدرس","الطاقه","الداخليه","للكره","الارضيه","لمصدر","وانماط","انتقالها","التوصيل","مقابل","الحمل","الحراري"],"aliases":["مخطط طرق انتقال الحرارة في أغلفة الأرض"]},{"id":"lhx_phase18_chapitres_35_36_card2_2","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"مخطط طرق انتقال الحرارة في أغلفة الأرض (2/3)","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":2,"total":3,"text":"تنتج أساساً (حوالي 90%) عن التفكك الإشعاعي ( Désintégration radioactive ) للنظائر غير المستقرة الموجودة في صخور القشرة والبرنس (خاصة اليورانيوم ²³⁸U ، الثوريوم ²³²Th ، والبوتاسيوم ⁴⁰K )، بالإضافة للحرارة المتبقية من نشأة الأرض. 2. أنماط انتقال الحرارة : • التوصيل ( Conduction ) : انتقال الحرارة من جزيء لآخر دون حركة المادة . يتم في الغلاف الصخري الصلب ، وهو نقل بطيء جداً. • الحمل الحراري ( Convection ) : انتقال الحرارة عن طريق حركة وانتقال المادة نفسها (تصعد المادة الساخنة الخفيفة وتهبط الباردة الكثيفة).","keywords":["مخطط","طرق","انتقال","الحراره","اغلفه","الارض","الدرس","الطاقه","الداخليه","للكره","الارضيه","اساسا","حوالي","التفكك","الاشعاعي","gration","radioactive","للنظاير"],"aliases":["مخطط طرق انتقال الحرارة في أغلفة الأرض"]},{"id":"lhx_phase18_chapitres_35_36_card2_3","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"مخطط طرق انتقال الحرارة في أغلفة الأرض (3/3)","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":3,"total":3,"text":"يتم في البرنس اللدن وهو نقل سريع وفعال.","keywords":["مخطط","طرق","انتقال","الحراره","اغلفه","الارض","الدرس","الطاقه","الداخليه","للكره","الارضيه","البرنس","اللدن","وفعال"],"aliases":["مخطط طرق انتقال الحرارة في أغلفة الأرض"]},{"id":"lhx_phase18_chapitres_35_36_card3_1","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"🪨 النقل بالتوصيل (Conduction)","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":1,"total":1,"text":"3 محاكي طرق انتقال الحرارة التفاعلي قارن كفاءة التوصيل الحراري بالحمل الحراري في الصخور : 🪨 النقل بالتوصيل في الغلاف الصخري (Conduction) 🌋 النقل بالحمل الحراري في البرنس (Convection) 🪨 النقل بالتوصيل (Conduction) يحدث في الصخور الصلبة. تهتز الذرات الساخنة وتنقل الحرارة للذرات المجاورة دون أن تغادر مكانها. يعتبر الغلاف الصخري عازلاً حرارياً جيداً، مما يجعل تسرب الحرارة بالتوصيل بطيئاً جداً فيحافظ على سخونة باطن الأرض.","keywords":["النقل","بالتوصيل","conduction","الدرس","الطاقه","الداخليه","للكره","الارضيه","محاكي","انتقال","التفاعلي","كفاءه","التوصيل","الحراري","بالحمل","الصخور","الغلاف","الصخري"],"aliases":["🪨 النقل بالتوصيل (Conduction)"]},{"id":"lhx_phase18_chapitres_35_36_card4_1","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"1. ما هو المصدر الأول والأساسي للطاقة الحرارية الداخلية للكرة الأرضية؟","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":1,"total":1,"text":"4 تقويم النشاط 4 : أسئلة البكالوريا المتكررة 1. ما هو المصدر الأول والأساسي للطاقة الحرارية الداخلية للكرة الأرضية؟ أ) التفكك الإشعاعي التلقائي والمستمر للنظائر المشعة (اليورانيوم، الثوريوم، البوتاسيوم) الموجودة في صخور الأرض. ب) أشعة الشمس التي تخترق القشرة الأرضية. ج) احتراق النفط والفحم في باطن الأرض.","keywords":["المصدر","الاول","والاساسي","للطاقه","الحراريه","الداخليه","للكره","الارضيه؟","الدرس","الطاقه","الارضيه","التفكك","الاشعاعي","التلقايي","والمستمر","للنظاير","المشعه","اليورانيوم،"],"aliases":["1. ما هو المصدر الأول والأساسي للطاقة الحرارية الداخلية للكرة الأرضية؟"]},{"id":"lhx_phase18_chapitres_35_36_card5_1","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"الدرس 3 : الطاقة الداخلية للكرة الأرضية (1/2)","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 42-44) الوحدة: U9 — تحديد الصفائح التكتونية وحركاتها — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. ينقسم الغلاف الصخري (القشرة الأرضية) إلى صفائح صلبة تفصلها أحزمة نشطة (زلازل، براكين، ظهرات، خنادق). الحدود تباعدية (ظهرات وسط محيطية) و تقاربية (غوص في الخنادق أو تصادم مشكل للسلاسل الجبلية الحديثة). يستدل على التباعد بالمغنطة الاستحاثية : أحزمة متوازية متناظرة بالنسبة للظهرة تشبه جلد الحمار الوحشي ؛ عمر القاع يزداد بالابتعاد عن المحور.","keywords":["الدرس","الطاقه","الداخليه","للكره","الارضيه","المعرفيه","الرسمي","للكتاب","المدرسي","تحديد","الصفايح","وحركاتها","الكتاب","بتنسيق","قرايي،","تغيير","المعني","ينقسم"],"aliases":["الدرس 3","الطاقة الداخلية للكرة الأرضية"]},{"id":"lhx_phase18_chapitres_35_36_card5_2","kind":"html","lessonKey":"phase18_chapitres_35_36","title":"الدرس 3 : الطاقة الداخلية للكرة الأرضية (2/2)","lessonTitle":"الدرس 3 : الطاقة الداخلية للكرة الأرضية","unitId":9,"part":2,"total":2,"text":"تتوزع بؤر الزلازل في مناطق الغوص وفق مستوى بينيوف (ميل ≈ 45° على الأفق؛ ≈ 90° عند غوص قشرة محيطية تحت محيطية). الطاقة الداخلية : حرارة أولية (تشكل الأرض) + تحلل ذري للعناصر المشعة (²³⁸U, ²³⁵U, ⁴⁰K, ²³²Th) ← تيارات حمل في البرنس تحرك الصفائح فوق الأستينوسفير. نصّ حصيلة الوحدة 9 مصحَّح يدوياً؛ لم تُستخرج من النسخة الممسوحة ضوئياً.","keywords":["الدرس","الطاقه","الداخليه","للكره","الارضيه","تتوزع","الزلازل","مناطق","الغوص","بينيوف","الافق؛","محيطيه","حراره","اوليه","للعناصر","المشعه","تيارات","البرنس"],"aliases":["الدرس 3","الطاقة الداخلية للكرة الأرضية"]},{"id":"lhx_phase18_chapitres_35_36_2_intro_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 1 : النشاط التكتوني للصفائح 🎯 الهدف العلمي : حدّد مصدر الحرارة الداخلية للأرض (التفكك الإشعاعي)، وميّز بين التوصيل البطيء في الغلاف الصخري والحمل الحراري السريع في البرنس. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : بيّن أن الأرض تعمل كآلة حرارية تحول الطاقة الحرارية الداخلية إلى طاقة حركية ميكانيكية (تيارات الحمل الحراري) تدفع الظهرات وتسحب مناطق الغوص. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","الثالث","العامه","التكتوني","للصفايح","للارض","التفكك","الاشعاعي"],"aliases":["كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟"]},{"id":"lhx_phase18_chapitres_35_36_2_card1_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":1,"text":"1 الإشكالية الميكانيكية لحركة الصفائح ⚠️ كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟ تزن القارات والمحيطات ملايين المليارات من الأطنان. ما هي القوة الميكانيكية الخارقة القادرة على شق الظهرات المحيطية ودفع القارات وحني الغلاف الصخري في مناطق الغوص؟ وكيف تعمل الكرة الأرضية كـ \"آلة حرارية\" ( Machine thermique ) دقيقة؟","keywords":["كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","الميكانيكيه","لحركه","الصفايح","القارات","والمحيطات","ملايين","المليارات"],"aliases":["كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟"]},{"id":"lhx_phase18_chapitres_35_36_2_card2_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"خلية الحمل الحراري في البرنس المحركة للصفائح (1/2)","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":2,"text":"2 التحليل المنهجي لخلية الحمل الحراري (صعود الأعمدة الساخنة وهبوط الألواح الباردة) خلية الحمل الحراري في البرنس المحركة للصفائح حدود البرنس مع النواة (منطقة ساخنة جداً) عمود ساخن خفيف صاعد (Panache) ظهرة محيطية (تباعد) صفيحة باردة غائصة صفيحة باردة غائصة 💡 صعود المادة يسحب الظهرة، وهبوط اللوح البارد يسحب منطقة الغوص. محرك الأرض في البكالوريا كيف تعمل الآلة الحرارية للأرض؟ تسخين وتمدد المادة في العمق : تسخن مادة البرنس العميقة بفعل الحرارة الإشعاعية،","keywords":["خليه","الحمل","الحراري","البرنس","المحركه","للصفايح","كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","لخليه"],"aliases":["خلية الحمل الحراري في البرنس المحركة للصفائح"]},{"id":"lhx_phase18_chapitres_35_36_2_card2_2","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"خلية الحمل الحراري في البرنس المحركة للصفائح (2/2)","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":2,"total":2,"text":"فتتمدد وتقل كثافتها وتصعد نحو الأعلى مشكلة أعمده ساخنة صاعدة ( Panaches chauds ) أسفل الظهرات المحيطية، مما يدفع الصفائح للتباعد. تبريد وغوص المادة عند السطح : عند السطح، يفقد الغلاف الصخري المحيطي حرارته فيبرد ويزداد سمكه وكثافته، فيغوص بفعل ثقله في مناطق الغوص مشكلاً ألواحاً باردة هابطة ( Plaques plongeantes ) تسحب معها بقية الصفيحة.","keywords":["خليه","الحمل","الحراري","البرنس","المحركه","للصفايح","كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","فتتمدد"],"aliases":["خلية الحمل الحراري في البرنس المحركة للصفائح"]},{"id":"lhx_phase18_chapitres_35_36_2_card3_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"⚙️ الأرض آلة حرارية حية ونشطة","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":1,"text":"3 محاكي الآلة الحرارية لحركة القارات اضغط لتشغيل محرك الحمل الحراري ومعاينة تحول الطاقة الحرارية لميكانيكية : ⚙️ تشغيل تيارات الحمل الحراري (نشاط تكتوني مستمر) ❄️ تبريد باطن الأرض (توقف المحرك وموت الكوكب تكتونياً) ⚙️ الأرض آلة حرارية حية ونشطة تتحول الطاقة الحرارية الناتجة عن التفكك الإشعاعي إلى طاقة حركية (تيارات الحمل الحراري). صعود الماغما يدفع الظهرات، وغوص الألواح الباردة يسحب الخنادق، فتستمر زحزحة القارات وتجدد قشرة الأرض.","keywords":["الارض","اله","حراريه","حيه","ونشطه","كيف","تتحول","الحراره","الصامته","باطن","الي","محرك","جبار","يحرك","القارات؟","محاكي","الاله","الحراريه"],"aliases":["⚙️ الأرض آلة حرارية حية ونشطة"]},{"id":"lhx_phase18_chapitres_35_36_2_card4_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 بيّن مصدر الطاقة الداخلية للأرض ودورها في تحريك الصفائح التكتونية. تزداد درجة الحرارة في باطن الأرض مع العمق حتى النواة (نحو 5000 درجة). ينتج الحرارة الداخلية من الاضمحلال الإشعاعي للنظائر (اليورانيوم، الثوريوم، البوتاسيوم). يولد التدرج الحراري تيارات حمولة (Convection) في الوسط الصخري اللدن. تسحب تيارات الحمل الصفائح الليثوسفيرية وتحركها فوق الأستينوسفير. تتجلى الطاقة الداخلية في الزلازل والبراكين وبناء السلاسل الجبلية. 🔑 المصطلح المفتاحي في البكالوريا : تيارات الحمل / الاضمحلال الإشعاعي","keywords":["كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","خلاصه","الدرس","للارض","ودورها","تحريك","الصفايح","تزداد"],"aliases":["كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟"]},{"id":"lhx_phase18_chapitres_35_36_2_card5_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"1. لماذا نقول إن الكرة الأرضية تعمل كـ \"آلة حرارية\" ( Machine thermique )؟","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":1,"text":"4 تقويم النشاط 5 : أسئلة البكالوريا المتكررة 1. لماذا نقول إن الكرة الأرضية تعمل كـ \"آلة حرارية\" ( Machine thermique )؟ أ) لأنها تقوم بتحويل الطاقة الحرارية الداخلية (المكتسبة من التفكك الإشعاعي) إلى طاقة ميكانيكية حركية تتجلى في تيارات الحمل الحراري وحركة الصفائح التكتونية. ب) لأن حرارتها تشبه حرارة محرك السيارة. ج) لأنها تدور في الفضاء بسرعة ثابتة.","keywords":["لماذا","نقول","الكره","الارضيه","تعمل","اله","حراريه","machine","thermique","كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار"],"aliases":["1. لماذا نقول إن الكرة الأرضية تعمل كـ \"آلة حرارية\" ( Machine thermique )؟"]},{"id":"lhx_phase18_chapitres_35_36_2_card6_1","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟ (1/2)","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 42-44) الوحدة: U9 — تحديد الصفائح التكتونية وحركاتها — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. ينقسم الغلاف الصخري (القشرة الأرضية) إلى صفائح صلبة تفصلها أحزمة نشطة (زلازل، براكين، ظهرات، خنادق). الحدود تباعدية (ظهرات وسط محيطية) و تقاربية (غوص في الخنادق أو تصادم مشكل للسلاسل الجبلية الحديثة). يستدل على التباعد بالمغنطة الاستحاثية : أحزمة متوازية متناظرة بالنسبة للظهرة تشبه جلد الحمار الوحشي ؛ عمر القاع يزداد بالابتعاد عن المحور.","keywords":["كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","المعرفيه","الرسمي","للكتاب","المدرسي","تحديد","الصفايح","وحركاتها"],"aliases":["كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟"]},{"id":"lhx_phase18_chapitres_35_36_2_card6_2","kind":"html","lessonKey":"phase18_chapitres_35_36_2","title":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟ (2/2)","lessonTitle":"كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟","unitId":9,"part":2,"total":2,"text":"تتوزع بؤر الزلازل في مناطق الغوص وفق مستوى بينيوف (ميل ≈ 45° على الأفق؛ ≈ 90° عند غوص قشرة محيطية تحت محيطية). الطاقة الداخلية : حرارة أولية (تشكل الأرض) + تحلل ذري للعناصر المشعة (²³⁸U, ²³⁵U, ⁴⁰K, ²³²Th) ← تيارات حمل في البرنس تحرك الصفائح فوق الأستينوسفير. نصّ حصيلة الوحدة 9 مصحَّح يدوياً؛ لم تُستخرج من النسخة الممسوحة ضوئياً.","keywords":["كيف","تتحول","الحراره","الصامته","باطن","الارض","الي","محرك","جبار","يحرك","القارات؟","تتوزع","الزلازل","مناطق","الغوص","بينيوف","الافق؛","محيطيه"],"aliases":["كيف تتحول الحرارة الصامتة في باطن الأرض إلى محرك جبار يحرك القارات؟"]},{"id":"lhx_phase19_chapitres_37_38_intro_1","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"الدرس 1 : الموجات الزلزالية","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 2 : بنية الكرة الأرضية 🎯 الهدف العلمي : استغلّ اختلاف سرعة الموجات الزلزالية (P و S)، وبيّن وجود الانقطاعات الثلاثة (موهو، غوتنبرغ، ليمان) وحدّد الحالة الفيزيائية للنواة الخارجية السائلة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : قارن التركيب المعدني للقشرة القارية (غرانيتية SIAL) بالقشرة المحيطية (بازلتية SIMA)، ووضّح الطبيعة الفوق قاعدية للبرنس (البيريدوتيت). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","الموجات","الزلزاليه","الثالث","العامه","الكره","الارضيه","استغل","اختلاف","الانقطاعات","الثلاثه","موهو،","غوتنبرغ،","ليمان","الحاله","الفيزياييه","للنواه","الخارجيه"],"aliases":["الدرس 1","الموجات الزلزالية"]},{"id":"lhx_phase19_chapitres_37_38_card1_1","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"الدرس 1 : الموجات الزلزالية","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف عرفنا أن باطن الأرض مكون من طبقات وأن نواتها الخارجية سائلة دون حفر الأرض؟ أعمق بئر حفره الإنسان على وجه الأرض (بئر كولا في روسيا) لم يتجاوز عمقه 12 كيلومتراً، وهو لا يمثل سوى خدش بسيط في قشرة الأرض (نصف قطر الأرض = 6371 كم!). ومع ذلك، استطاع الجيولوجيون رسم خريطة دقيقة لكل أغلفة باطن الأرض. كيف تم استغلال سرعة وسلوك الموجات الزلزالية الطبيعية كـ \"جهاز إيكوغرافيا\" لكشف أسرار وأعماق الأرض؟","keywords":["الدرس","الموجات","الزلزاليه","وضعيه","الانطلاق","وبناء","العلميه","عرفنا","طبقات","نواتها","الخارجيه","سايله","الارض؟","الانسان","روسيا","يتجاوز","كيلومترا،","استطاع"],"aliases":["الدرس 1","الموجات الزلزالية"]},{"id":"lhx_phase19_chapitres_37_38_card2_1","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض (1/3)","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":1,"total":3,"text":"2 التحليل المنهجي لمنحنى سرعة الموجات الزلزالية (P و S) بدلالة العمق وانقطاعات الأرض منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض العمق (كم) السرعة V موهو (30 كم) غوتنبرغ (2900 كم) ليمان (5100 كم) الموجات P (تخترق كل شيء) الموجات S (تتوقف عند 2900 كم) النواة الخارجية (سائلة) النواة الداخلية 💡 اختفاء الموجات S عند عمق 2900 كم هو الدليل القاطع على سيولة النواة الخارجية. منهجية البكالوريا : تفسير سلوك الموجات ما هي خصائص الموجات والانقطاعات؟ 1. خصائص الموجات الزلزالية : • الموجات الأولية ( Ondes P ) :","keywords":["منحني","سرعه","الموجات","والانقطاعات","الثلاثه","لباطن","الارض","الدرس","الزلزاليه","لمنحني","بدلاله","العمق","وانقطاعات","السرعه","غوتنبرغ","ليمان","تخترق","تتوقف"],"aliases":["منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض"]},{"id":"lhx_phase19_chapitres_37_38_card2_2","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض (2/3)","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":2,"total":3,"text":"طولية، سريعة جداً، تنتشر في الأوساط الصلبة والسائلة . سرعتها تزداد بازدياد كثافة وصلابة الوسط. • الموجات الثانوية ( Ondes S ) : عرضية، أقل سرعة، تنتشر في الأوساط الصلبة فقط ولا تخترق السوائل أبداً . 2. الانقطاعات الكبرى ( Discontinuités تغير مفاجئ للسرعة ) : • انقطاع موهو ( Moho ) : يفصل بين القشرة والبرنس (على عمق ~30 كم قارياً و ~7 كم محيطياً). • انقطاع غوتنبرغ ( Gutenberg عمق 2900 كم ) : يفصل بين البرنس الصلب والنواة الخارجية، حيث تنعدم سرعة الموجات S كلياً وتنخفض سرعة P ، مما يثبت أن النواة الخارجية سائلة.","keywords":["منحني","سرعه","الموجات","والانقطاعات","الثلاثه","لباطن","الارض","الدرس","الزلزاليه","طوليه،","سريعه","تنتشر","الاوساط","الصلبه","والسايله","سرعتها","تزداد","بازدياد"],"aliases":["منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض"]},{"id":"lhx_phase19_chapitres_37_38_card2_3","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض (3/3)","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":3,"total":3,"text":"• انقطاع ليمان ( Lehmann عمق 5100 كم ) : يفصل بين النواة الخارجية السائلة والنواة الداخلية الصلبة (البذرة).","keywords":["منحني","سرعه","الموجات","والانقطاعات","الثلاثه","لباطن","الارض","الدرس","الزلزاليه","انقطاع","ليمان","lehmann","الخارجيه","السايله","والنواه","الصلبه","البذره"],"aliases":["منحنى سرعة الموجات P و S والانقطاعات الثلاثة لباطن الأرض"]},{"id":"lhx_phase19_chapitres_37_38_card3_1","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"📡 الموجات الأولية (Ondes P - تخترق كل الأرض)","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":1,"total":1,"text":"3 محاكي انتشار الموجات الزلزالية التفاعلي اختر نوع الموجة الزلزالية لمعاينة قدرتها على اختراق طبقات باطن الأرض : 📡 الموجات الأولية (Ondes P) 📡 الموجات الثانوية (Ondes S) 📡 الموجات الأولية (Ondes P - تخترق كل الأرض) تخترق القشرة والبرنس بسرعة عالية، وعند وصولها لعمق 2900 كم (انقطاع غوتنبرغ) تنخفض سرعتها فجأة وتنكسر لأنها دخلت في وسط سائل (النواة الخارجية)، ثم تزداد سرعتها مجدداً عند دخولها النواة الداخلية الصلبة عند 5100 كم.","keywords":["الموجات","الاوليه","ondes","تخترق","الارض","الدرس","الزلزاليه","محاكي","انتشار","التفاعلي","الموجه","لمعاينه","قدرتها","اختراق","طبقات","الثانويه","والبرنس","بسرعه"],"aliases":["📡 الموجات الأولية (Ondes P - تخترق كل الأرض)"]},{"id":"lhx_phase19_chapitres_37_38_card4_1","kind":"html","lessonKey":"phase19_chapitres_37_38","title":"1. ما هو الدليل العلمي القاطع الذي استنتجه العلماء من توقف واختفاء الموجات الزلزالية ( Ondes S ) عند انقطاع غوتنبرغ (عمق 2900 كم)؟","lessonTitle":"الدرس 1 : الموجات الزلزالية","unitId":10,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ما هو الدليل العلمي القاطع الذي استنتجه العلماء من توقف واختفاء الموجات الزلزالية ( Ondes S ) عند انقطاع غوتنبرغ (عمق 2900 كم)؟ أ) استنتجوا أن النواة الخارجية للكرة الأرضية توجد في حالة فيزيائية سائلة (مصهورة)، لأن الموجات S لا تنتشر في السوائل. ب) استنتجوا أن الأرض فارغة ومجوفة من الداخل. ج) استنتجوا أن النواة الخارجية أصلب من الماس.","keywords":["الدليل","العلمي","القاطع","الذي","استنتجه","العلماء","توقف","واختفاء","الموجات","الزلزاليه","ondes","عند","انقطاع","غوتنبرغ","عمق","2900","الدرس","استنتجوا"],"aliases":["1. ما هو الدليل العلمي القاطع الذي استنتجه العلماء من توقف واختفاء الموجات الزلزالية ( Ondes S ) عند انقطاع غوتنبرغ (عمق 2900 كم)؟"]},{"id":"lhx_phase19_chapitres_37_38_2_intro_1","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 2 : بنية الكرة الأرضية 🎯 الهدف العلمي : استغلّ اختلاف سرعة الموجات الزلزالية (P و S)، وبيّن وجود الانقطاعات الثلاثة (موهو، غوتنبرغ، ليمان) وحدّد الحالة الفيزيائية للنواة الخارجية السائلة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : قارن التركيب المعدني للقشرة القارية (غرانيتية SIAL) بالقشرة المحيطية (بازلتية SIMA)، ووضّح الطبيعة الفوق قاعدية للبرنس (البيريدوتيت). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","يختلف","التركيب","المعدني","لصخور","القارات","صخور","قاع","المحيطات","واعماق","البرنس؟","الثالث","العامه","الكره","الارضيه","استغل","اختلاف","الموجات"],"aliases":["لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟"]},{"id":"lhx_phase19_chapitres_37_38_2_card1_1","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":1,"total":1,"text":"1 الإشكالية الصخرية لأغلفة الأرض ⚠️ لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟ تتباين كثافة أغلفة الأرض من 2.7 في القشرة القارية إلى 3.0 في القشرة المحيطية وتصل إلى 3.3 في البرنس العلوي. ما هي المعادن والصخور المميزة لكل غلاف؟ وكيف يفسر التغير التدريجي لسرعة الموجات الزلزالية داخل البرنس رغم ثبات صخره الأم (البيريدوتيت)؟","keywords":["لماذا","يختلف","التركيب","المعدني","لصخور","القارات","صخور","قاع","المحيطات","واعماق","البرنس؟","الصخريه","لاغلفه","تتباين","كثافه","اغلفه","القاريه","المحيطيه"],"aliases":["لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟"]},{"id":"lhx_phase19_chapitres_37_38_2_card2_1","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"مقارنة الصخور المميزة للأغلفة الصخرية والستار الأرضي (1/2)","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":1,"total":2,"text":"2 التحليل المنهجي للتركيب المعدني (الكوارتز، الفلسبار، الأوليفين والبيروكسين) مقارنة الصخور المميزة للأغلفة الصخرية والستار الأرضي القشرة القارية صخر الغرانيت كوارتز + فلسبار SIAL (سيليس + ألمنيوم) الكثافة = 2.7 القشرة المحيطية بازلت + غابرو بيروكسين + بلاجيوكلاز SIMA (سيليس + مغنيزيوم) الكثافة = 3.0 البرنس (الستار) صخر البيريدوتيت أوليفين + بيروكسين صخر فوق قاعدي غني بالحديد الكثافة = 3.3 💡 تزداد نسبة الحديد والمغنيزيوم وتزداد الكثافة بالاتجاه نحو البرنس.","keywords":["مقارنه","الصخور","المميزه","للاغلفه","الصخريه","والستار","الارضي","لماذا","يختلف","التركيب","المعدني","لصخور","القارات","صخور","قاع","المحيطات","واعماق","البرنس؟"],"aliases":["مقارنة الصخور المميزة للأغلفة الصخرية والستار الأرضي"]},{"id":"lhx_phase19_chapitres_37_38_2_card2_2","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"مقارنة الصخور المميزة للأغلفة الصخرية والستار الأرضي (2/2)","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":2,"total":2,"text":"الخصائص الصخرية المعتمدة في البكالوريا ما هو التغير البلوري للبيريدوتيت؟ يتكون البرنس الأرضي بالكامل من صخر واحد هو البيريدوتيت ( Péridotite ) . ولكن سرعة الموجات الزلزالية تزداد تدريجياً وبقفزات داخل البرنس مع زيادة العمق والضغط! التفسير العلمي : لا يتغير التركيب الكيميائي للبيريدوتيت، ولكن الضغط الهائل في الأعماق يجبر ذرات معادنه (الأوليفين) على إعادة الترتيب والاندماج في أشكال بلورية أكثر تراصاً وكثافة (تغير البنية البلورية من أوليفين إلى إسبينيل ثم بيروفسكايت)، مما يزيد من سرعة الموجات.","keywords":["مقارنه","الصخور","المميزه","للاغلفه","الصخريه","والستار","الارضي","لماذا","يختلف","التركيب","المعدني","لصخور","القارات","صخور","قاع","المحيطات","واعماق","البرنس؟"],"aliases":["مقارنة الصخور المميزة للأغلفة الصخرية والستار الأرضي"]},{"id":"lhx_phase19_chapitres_37_38_2_card3_1","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"🪨 صخر البيريدوتيت (Péridotite)","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":1,"total":1,"text":"3 مختبر الصخور والمعادن التفاعلي اضغط على الصخر لمعاينة تركيبه المعدني وموقعه في الطبقات : 🪨 الغرانيت (Granite - قشرة قارية) 🪨 البازلت (Basalte - قشرة محيطية) 🪨 البيريدوتيت (Péridotite - البرنس) 🪨 صخر البيريدوتيت (Péridotite) هو الصخر المكون للبرنس (الستار) الأرضي بنسبة 100%. صخر فوق قاعدي غني جداً بمعدني الأوليفين والبيروكسين والحديد والمغنيزيوم، كثافته عالية (3.3 g/cm³).","keywords":["صخر","البيريدوتيت","ridotite","لماذا","يختلف","التركيب","المعدني","لصخور","القارات","صخور","قاع","المحيطات","واعماق","البرنس؟","مختبر","الصخور","والمعادن","التفاعلي"],"aliases":["🪨 صخر البيريدوتيت (Péridotite)"]},{"id":"lhx_phase19_chapitres_37_38_2_card4_1","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 استغل خصائص الموجات الزلزالية في التعرف على البنية الداخلية للأرض. تتولد الموجات الزلزالية عند بؤرة الزلزال وتنتقل في كل الاتجاهات داخل الأرض. تنقسم الموجات الحجمية إلى موجات P طولية سريعة وموجات S عرضية أبطأ. تتغير سرعة الموجات واتجاهها عند العبور بين أوساط مختلفة الكثافة (انكسار وانعكاس). لا تعبر موجات S الأوساط السائلة فيتأخر وصولها وتشكل مناطق ظل. يتكسر تراكم الإجهاد في الصخور فتنطلق الطاقة على شكل موجات زلزالية. 🔑 المصطلح المفتاحي في البكالوريا : الموجات الزلزالية (P و S) / الانقطاع","keywords":["لماذا","يختلف","التركيب","المعدني","لصخور","القارات","صخور","قاع","المحيطات","واعماق","البرنس؟","خلاصه","الدرس","استغل","خصايص","الموجات","الزلزاليه","التعرف"],"aliases":["لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟"]},{"id":"lhx_phase19_chapitres_37_38_2_card5_1","kind":"html","lessonKey":"phase19_chapitres_37_38_2","title":"1. ما هو الصخر الأم الأساسي الذي يتكون منه ستار أو برنس الكرة الأرضية ( Manteau ) بالكامل؟","lessonTitle":"لماذا يختلف التركيب المعدني لصخور القارات عن صخور قاع المحيطات وأعماق البرنس؟","unitId":10,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. ما هو الصخر الأم الأساسي الذي يتكون منه ستار أو برنس الكرة الأرضية ( Manteau ) بالكامل؟ أ) صخر البيريدوتيت ( Péridotite الغني بالأوليفين والبيروكسين). ب) صخر الغرانيت. ج) صخر الكلس.","keywords":["الصخر","الام","الاساسي","الذي","يتكون","منه","ستار","برنس","الكره","الارضيه","manteau","بالكامل؟","لماذا","يختلف","التركيب","المعدني","لصخور","القارات"],"aliases":["1. ما هو الصخر الأم الأساسي الذي يتكون منه ستار أو برنس الكرة الأرضية ( Manteau ) بالكامل؟"]},{"id":"lhx_phase20_chapitres_39_40_intro_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 2 : بنية الكرة الأرضية 🎯 الهدف العلمي : ابنِ نموذجاً تركيبياً متكاملاً لطبقات الأرض (القشرة، البرنس العلوي، البرنس السفلي، النواة الخارجية، والنواة الداخلية الصلبة) وفسّر تصلب البذرة رغم حرارتها الفائقة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : ميّز بين التشوهات اللدنة (الطيات المحدبة والمقعرة) والتشوهات الانكسارية (الفوالق العادية والمعكوسة)، واربطها بنوع القوى التكتونية (انضغاط أم شد). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","الثالث","العامه","الكره","نموذجا","تركيبيا","متكاملا","لطبقات","القشره،","البرنس","العلوي،","السفلي،","الخارجيه،"],"aliases":["الدرس 3","نمذجة البنية الداخلية للكرة الأرضية"]},{"id":"lhx_phase20_chapitres_39_40_card1_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ لماذا يبقى حديد النواة الداخلية (البذرة) صلباً رغم أن حرارته تفوق 5000°C؟ ينصهر الحديد في سطح الأرض عند حرارة 1538°C. وفي النواة الخارجية التي تبلغ حرارتها 4000°C نجد الحديد سائلاً بالفعل. ولكن في مركز الأرض (النواة الداخلية أو البذرة عند عمق 5100 كم) تبلغ الحرارة 5000°C، ومع ذلك يتحول الحديد إلى صلب تماماً! كيف يفسر علم الجيوفيزياء هذا التناقض العجيب؟ وكيف نربط جميع المعطيات السابقة في نموذج تركيبي واحد للكرة الأرضية؟","keywords":["الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","وضعيه","الانطلاق","وبناء","العلميه","البذره","حرارته","ينصهر","الحديد","حراره","الخارجيه","حرارتها","سايلا"],"aliases":["الدرس 3","نمذجة البنية الداخلية للكرة الأرضية"]},{"id":"lhx_phase20_chapitres_39_40_card2_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية (1/3)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":3,"text":"2 التحليل المنهجي للنموذج الريولوجي والكيميائي لطبقات الأرض الخمسة مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية 1. القشرة الأرضية (صلبة - 0 إلى 30 كم - الكثافة 2.7 إلى 3.0) 2. البرنس العلوي (30 إلى 670 كم - بيريدوتيت صلب/لدن - الكثافة 3.3) 3. البرنس السفلي (670 إلى 2900 كم - بيروفسكايت صلب - الكثافة 5.5) 4. النواة الخارجية (2900 إلى 5100 كم - حديد ونيكل سائل - الكثافة 10) 5.","keywords":["مخطط","قطاعي","يوضح","الاغلفه","الخمسه،","العمق،","الكثافه","والحاله","الفيزياييه","الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","للنموذج","الريولوجي","والكيميايي"],"aliases":["مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية"]},{"id":"lhx_phase20_chapitres_39_40_card2_2","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية (2/3)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":2,"total":3,"text":"النواة الداخلية / البذرة (5100 إلى 6371 كم - حديد صلب جداً - الكثافة 13) 💡 تزداد الكثافة والضغط والحرارة باطراد نحو المركز. منهجية البكالوريا : تفسير الحالة الفيزيائية لماذا البذرة صلبة رغم الحرارة؟ تتحدد الحالة الفيزيائية (صلب أم سائل) لأي مادة في باطن الأرض بالتنافس بين عاملين متضادين : • الحرارة ( Température ) : تعمل على تباعد الذرات وإحداث الانصهار (السيولة). • الضغط ( Pression ) : يعمل على تقارب ورص الذرات وإجبارها على التصلب. في النواة الخارجية يكون تأثير الحرارة يتفوق على الضغط، فيكون الحديد سائلاً.","keywords":["مخطط","قطاعي","يوضح","الاغلفه","الخمسه،","العمق،","الكثافه","والحاله","الفيزياييه","الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","البذره","تزداد","والضغط"],"aliases":["مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية"]},{"id":"lhx_phase20_chapitres_39_40_card2_3","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية (3/3)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":3,"total":3,"text":"أما في مركز الأرض (البذرة) يبلغ الضغط الهيدروستاتيكي قيماً خيالية (أكثر من 3.6 مليون ضغط جوي!)، فيتفوق تأثير الضغط على الحرارة ويجبر ذرات الحديد والنيكل على التراص في شبكة بلورية صلبة جداً.","keywords":["مخطط","قطاعي","يوضح","الاغلفه","الخمسه،","العمق،","الكثافه","والحاله","الفيزياييه","الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","البذره","الضغط","الهيدروستاتيكي"],"aliases":["مخطط قطاعي يوضح الأغلفة الخمسة، العمق، الكثافة والحالة الفيزيائية"]},{"id":"lhx_phase20_chapitres_39_40_card3_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"🟢 ستار الكرة الأرضية (البرنس الممتد من 30 إلى 2900 كم)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":1,"text":"3 مستكشف أغلفة الأرض التفاعلي اضغط على الطبقة لمعرفة خصائصها الكيميائية والفيزيائية : 🟢 البرنس / الستار (Manteau - 82% من حجم الأرض) 🟠 النواة الخارجية السائلة (Noyau externe) 🔴 البذرة الصلبة (Graine / Noyau interne) 🟢 ستار الكرة الأرضية (البرنس الممتد من 30 إلى 2900 كم) يتكون بالكامل من صخر البيريدوتيت فوق القاعدي. جزؤه العلوي يشكل مع القشرة الغلاف الصخري الصلب، وجزؤه الأوسط هو الاستينوسفير اللدن مقر تيارات الحمل الحراري، وجزؤه السفلي صلب تحت تأثير الضغط العالي.","keywords":["ستار","الكره","الارضيه","البرنس","الممتد","الي","2900","الدرس","نمذجه","البنيه","الداخليه","للكره","مستكشف","اغلفه","التفاعلي","الطبقه","لمعرفه","خصايصها"],"aliases":["🟢 ستار الكرة الأرضية (البرنس الممتد من 30 إلى 2900 كم)"]},{"id":"lhx_phase20_chapitres_39_40_card4_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"1. ما هو التركيب الكيميائي المميّز لقلب الأرض (النواة الخارجية والداخلية معاً) والذي يفسر كثافتها العالية جداً (10 إلى 13 g/cm³)؟","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ما هو التركيب الكيميائي المميّز لقلب الأرض (النواة الخارجية والداخلية معاً) والذي يفسر كثافتها العالية جداً (10 إلى 13 g/cm³)؟ أ) تتكون النواة من سبيكة معدنية ثقيلة جداً من الحديد والنيكل ( Fe - Ni أو NIFE ). ب) تتكون من صخر الغرانيت والكوارتز. ج) تتكون من ماء وأكسجين مضغوط.","keywords":["التركيب","الكيميايي","المميز","لقلب","الارض","النواه","الخارجيه","والداخليه","معا","والذي","يفسر","كثافتها","العاليه","جدا","الي","الدرس","نمذجه","البنيه"],"aliases":["1. ما هو التركيب الكيميائي المميّز لقلب الأرض (النواة الخارجية والداخلية معاً) والذي يفسر كثافتها العالية جداً (10 إلى 13 g/cm³)؟"]},{"id":"lhx_phase20_chapitres_39_40_card5_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية (1/2)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 45-47، ص 280-281) الوحدة: U10 — بنية الكرة الأرضية — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. البؤرة : نقطة الكسر؛ المركز السطحي : نقطة السطح؛ التسجيل بواسطة السيسمومتر (السيسموغرام). الموجات P : طولية، تنتشر في الصلب والسائل؛ S : عرضية، في الصلب فقط وأبطأ؛ L و R : سطحية، الأبطأ والأخطر. سرعة الموجات تزداد بالكثافة والضغط، وتتناقص بالحرارة؛ وهي أصغر في السائل منها في الصلب (نفس التركيب). القشرة القارية (سيال) : غرانيت، سيليس 70% + ألمنيوم 15%؛","keywords":["الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","المعرفيه","الرسمي","للكتاب","المدرسي","الكره","الكتاب","بتنسيق","قرايي،","تغيير","المعني","البوره","الكسر؛"],"aliases":["الدرس 3","نمذجة البنية الداخلية للكرة الأرضية"]},{"id":"lhx_phase20_chapitres_39_40_card5_2","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية (2/2)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":2,"total":2,"text":"القشرة المحيطية (سيما) : بازلت، سيليس 49% + الحديد والمغنيزيوم 20%؛ البرنس : بيريدوتيت، سيليس 44% + مغنيزيوم 42% + حديد 8.5%. الليتوسفير = القشرة + الجزء العلوي من البرنس العلوي (صلب، كسري)؛ الأستينوسفير = الجزء السفلي من البرنس العلوي. البرنس : 81% من حجم الكرة (بيريدوتيت)؛ النواة : 17%، غنية بالحديد والنيكل — خارجية سائلة وداخلية صلبة (دليلها الموجات S).","keywords":["الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","المحيطيه","بازلت،","سيليس","الحديد","والمغنيزيوم","البرنس","بيريدوتيت،","مغنيزيوم","الليتوسفير","الجزء","العلوي","الاستينوسفير"],"aliases":["الدرس 3","نمذجة البنية الداخلية للكرة الأرضية"]},{"id":"lhx_phase20_chapitres_39_40_card6_1","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية (1/2)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":1,"total":2,"text":"🗺 مخطط تحصيلي — البنية الداخلية للأرض الصورة الأصلية — طبقة الصورة تحوي أخطاء استخراج آلي («منهط» بدل «منهاج»، «وتكافة» بدل «وكثافة»)؛ النسخة المصححة أدناه هي المرجع القرائي. البيانات المطلوب وضعها على الأرقام (1 ← 6) : الغلاف الكتلة الحالة الفيزيائية الأغطية النوعية البتروغرافية الانقطاعات الزلزالية الأعماق المعلمة (Km) : 120 — 700 — 2900 — 5100 — 6375 (مركز الأرض). أنقل المخطط على كراسك مستعملا ورقا شفافا، ثم تعرّف على أغلفة الأرض وضع البيانات على الأرقام (1 ← 6).","keywords":["الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","تحصيلي","للارض","الصوره","الاصليه","اخطاء","استخراج","منهاج","وتكافه","وكثافه","النسخه","المصححه","ادناه"],"aliases":["الدرس 3","نمذجة البنية الداخلية للكرة الأرضية"]},{"id":"lhx_phase20_chapitres_39_40_card6_2","kind":"html","lessonKey":"phase20_chapitres_39_40","title":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية (2/2)","lessonTitle":"الدرس 3 : نمذجة البنية الداخلية للكرة الأرضية","unitId":10,"part":2,"total":2,"text":"حدد على المخطط في كراسك الحالة الفيزيائية وكثافة مختلف أغلفة الأرض. حدد على المخطط مكان الانقطاعات الزلزالية اعتمادا على المعلومات التي توصلت إليها. استخلص النوعية البتروغرافية لمختلف أغلفة الأرض. 🎯 الخلاصة : تجسيم البنية الداخلية للأرض على شكل طبقات، اعتمادا على المعارف المبنية خلال الوحدة. 🗺 الصورة الأصلية + تنسيق قرائي مصحح — ملاحظة : «غوتنبرغ» و«ليمان» غير واردتين في النص المُدخل آلياً وإن وردت الأعماق 2900 و5100.","keywords":["الدرس","نمذجه","البنيه","الداخليه","للكره","الارضيه","المخطط","كراسك","الحاله","الفيزياييه","وكثافه","مختلف","اغلفه","الانقطاعات","الزلزاليه","اعتمادا","المعلومات","توصلت"],"aliases":["الدرس 3","نمذجة البنية الداخلية للكرة الأرضية"]},{"id":"lhx_phase20_chapitres_39_40_2_intro_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 2 : بنية الكرة الأرضية 🎯 الهدف العلمي : ابنِ نموذجاً تركيبياً متكاملاً لطبقات الأرض (القشرة، البرنس العلوي، البرنس السفلي، النواة الخارجية، والنواة الداخلية الصلبة) وفسّر تصلب البذرة رغم حرارتها الفائقة. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : ميّز بين التشوهات اللدنة (الطيات المحدبة والمقعرة) والتشوهات الانكسارية (الفوالق العادية والمعكوسة)، واربطها بنوع القوى التكتونية (انضغاط أم شد). ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","الثالث","العامه","الكره","الارضيه","نموذجا","تركيبيا","متكاملا","لطبقات"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card1_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":1,"text":"1 الإشكالية الميكانيكية للتشوهات الصخرية ⚠️ لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟ تتعرض الطبقات الصخرية للقشرة الأرضية لقوى تكتونية هائلة ومهولة ناتجة عن حركة الصفائح. في بعض المناطق نجد الطبقات ملتوية ومنحنية في شكل موجات جبلية رائعة تسمى الطيات ( Plis ) . وفي مناطق أخرى نجد الطبقات مكسورة وممزقة ومزاحة عن بعضها البعض تسمى الفوالق ( Failles ) . ما هي العوامل الفيزيائية (الحرارة، الضغط، طبيعة الصخر) والقوى التكتونية التي تتحكم في نوع التشوه الصخري؟","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","الميكانيكيه","للتشوهات","الصخريه","تتعرض","الطبقات","للقشره","الارضيه","تكتونيه"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card2_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"مخطط التشوهات التكتونية : الطية المحدبة، الفالق العادي (شد)، والفالق المعكوس (انضغاط) (1/2)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":2,"text":"2 التحليل المنهجي لأنواع الطيات والفوالق وعلاقتها بالقوى التكتونية مخطط التشوهات التكتونية : الطية المحدبة، الفالق العادي (شد)، والفالق المعكوس (انضغاط) طية محدبة (قوى انضغاط + صخر لدن) فالق عادي (قوى شد + صخر صلب) فالق معكوس (قوى انضغاط + صخر صلب) 💡 قوى الشد تمزق وتوسّع، وقوى الانضغاط تثني أو تكسر وتكدس. التصنيف الميكانيكي في البكالوريا متى تتشكل الطية ومتى يتشكل الفالق؟ التشوهات اللدنة (الطيات Plis ) : تحدث عندما تكون الصخور في أعماق القشرة تحت حرارة وضغط عاليين (تتصرف كأنها لدنة Ductile )،","keywords":["مخطط","التشوهات","التكتونيه","الطيه","المحدبه،","الفالق","العادي","والفالق","المعكوس","انضغاط","لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور"],"aliases":["مخطط التشوهات التكتونية","الطية المحدبة، الفالق العادي (شد)، والفالق المعكوس (انضغاط)"]},{"id":"lhx_phase20_chapitres_39_40_2_card2_2","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"مخطط التشوهات التكتونية : الطية المحدبة، الفالق العادي (شد)، والفالق المعكوس (انضغاط) (2/2)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":2,"total":2,"text":"أو عندما تكون القوى التكتونية بطيئة. تؤدي قوى الانضغاط إلى انثنائها دون انكسار (طية محدبة أو مقعرة). التشوهات الانكسارية (الفوالق Failles ) : تحدث عندما تكون الصخور قريبة من السطح (باردة وصلبة كاسرة Cassante ) أو عند تطبيق قوى سريعة وشديدة، وتنقسم إلى : • فالق عادي ( Faille normale ) : ينتج عن قوى شد وتباعد ( Distension في الظهرات ) ، ويتميز بتباعد الكتل الصخرية. • فالق معكوس ( Faille inverse ) : ينتج عن قوى انضغاط وتقارب ( Compression في مناطق الغوص والتصادم ) ، ويتميز بركوب كتلة فوق أخرى.","keywords":["مخطط","التشوهات","التكتونيه","الطيه","المحدبه،","الفالق","العادي","والفالق","المعكوس","انضغاط","لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور"],"aliases":["مخطط التشوهات التكتونية","الطية المحدبة، الفالق العادي (شد)، والفالق المعكوس (انضغاط)"]},{"id":"lhx_phase20_chapitres_39_40_2_card3_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"🟢 الطيات المحدبة والمقعرة (Plis)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":1,"text":"3 محاكي التشوهات التكتونية التفاعلي اختر نوع القوى التكتونية وطبيعة الصخر لمعاينة البنية الجيولوجية الناتجة : 🟢 قوى انضغاط + صخر عميق لدن (طيات) 🔵 قوى شد وتباعد + صخر سطحي صلب (فالق عادي) 🟠 قوى انضغاط + صخر سطحي صلب (فالق معكوس) 🟢 الطيات المحدبة والمقعرة (Plis) تنثني الطبقات الرسوبية بشكل متموج وسلس. تعتبر الطيات المحدبة مصائد ممتازة للبترول والغاز الطبيعي في الصحراء الجزائرية، وهي شواهد مؤكدة على حدوث تقارب وانضغاط تكتوني.","keywords":["الطيات","المحدبه","والمقعره","plis","لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","محاكي","التشوهات","التفاعلي","القوي"],"aliases":["🟢 الطيات المحدبة والمقعرة (Plis)"]},{"id":"lhx_phase20_chapitres_39_40_2_card4_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 نمذج البنية الداخلية للكرة الأرضية انطلاقاً من المعطيات الزلزالية والكيميائية. تقسم الكرة الأرضية إلى ثلاثة أغلفة كبرى: القشرة، الوشاح (الغلاف الأوسط)، والنواة. يفصل بينها انقطاع موهو وانقطاع غوتنبرغ وانقطاع ليمان. تتكون القشرة من صخور غرانيتية قارية وصخور بازلتية محيطية. يوافق تركيب النيازك (الكونديريت) وكثافات الأغلفة نماذج التركيب الكيميائي للأرض. النواة الخارجية سائلة (لا تعبرها موجات S) والداخلية صلبة بفعل الضغط الهائل. 🔑 المصطلح المفتاحي في البكالوريا : انقطاع موهو وغوتنبرغ / النواة والوشاح","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","خلاصه","الدرس","للكره","الارضيه","انطلاقا","المعطيات","الزلزاليه","والكيمياييه"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card5_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"1. إذا وجدت في خريطة جيولوجية منطقة تحتوي على سلسلة كثيفة من \"الفوالق العادية\" ( Failles normales )، فماذا تستنتج حول النشاط التكتوني السائد في تلك المنطقة؟","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":1,"text":"4 تقويم النشاط 2 : أسئلة البكالوريا المتكررة 1. إذا وجدت في خريطة جيولوجية منطقة تحتوي على سلسلة كثيفة من \"الفوالق العادية\" ( Failles normales )، فماذا تستنتج حول النشاط التكتوني السائد في تلك المنطقة؟ أ) أستنتج أن المنطقة تخضع لنشاط تكتوني يتميز بقوى شد وتباعد ( Forces de distension ) مثل الظهرات أو الخسف القاري (Rift). ب) أستنتج أن المنطقة تخضع لقوى تصادم وانضغاط عنيف. ج) أستنتج أن المنطقة لا تشهد أي نشاط تكتوني نهائياً.","keywords":["اذا","وجدت","خريطه","جيولوجيه","منطقه","تحتوي","علي","سلسله","كثيفه","الفوالق","العاديه","failles","normales","فماذا","تستنتج","حول","النشاط","التكتوني"],"aliases":["1. إذا وجدت في خريطة جيولوجية منطقة تحتوي على سلسلة كثيفة من \"الفوالق العادية\" ( Failles normales )، فماذا تستنتج حول النشاط التكتوني السائد في تلك المنطقة؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card6_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟ (1/2)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 45-47، ص 280-281) الوحدة: U10 — بنية الكرة الأرضية — نص الكتاب بتنسيق قرائي، دون تغيير المعنى. البؤرة : نقطة الكسر؛ المركز السطحي : نقطة السطح؛ التسجيل بواسطة السيسمومتر (السيسموغرام). الموجات P : طولية، تنتشر في الصلب والسائل؛ S : عرضية، في الصلب فقط وأبطأ؛ L و R : سطحية، الأبطأ والأخطر. سرعة الموجات تزداد بالكثافة والضغط، وتتناقص بالحرارة؛ وهي أصغر في السائل منها في الصلب (نفس التركيب). القشرة القارية (سيال) : غرانيت، سيليس 70% + ألمنيوم 15%؛","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","المعرفيه","الرسمي","للكتاب","المدرسي","الكره","الارضيه","الكتاب","بتنسيق"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card6_2","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟ (2/2)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":2,"total":2,"text":"القشرة المحيطية (سيما) : بازلت، سيليس 49% + الحديد والمغنيزيوم 20%؛ البرنس : بيريدوتيت، سيليس 44% + مغنيزيوم 42% + حديد 8.5%. الليتوسفير = القشرة + الجزء العلوي من البرنس العلوي (صلب، كسري)؛ الأستينوسفير = الجزء السفلي من البرنس العلوي. البرنس : 81% من حجم الكرة (بيريدوتيت)؛ النواة : 17%، غنية بالحديد والنيكل — خارجية سائلة وداخلية صلبة (دليلها الموجات S).","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","المحيطيه","بازلت،","سيليس","الحديد","والمغنيزيوم","البرنس","بيريدوتيت،","مغنيزيوم"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card7_1","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟ (1/2)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":1,"total":2,"text":"🗺 مخطط تحصيلي — البنية الداخلية للأرض الصورة الأصلية — طبقة الصورة تحوي أخطاء استخراج آلي («منهط» بدل «منهاج»، «وتكافة» بدل «وكثافة»)؛ النسخة المصححة أدناه هي المرجع القرائي. البيانات المطلوب وضعها على الأرقام (1 ← 6) : الغلاف الكتلة الحالة الفيزيائية الأغطية النوعية البتروغرافية الانقطاعات الزلزالية الأعماق المعلمة (Km) : 120 — 700 — 2900 — 5100 — 6375 (مركز الأرض). أنقل المخطط على كراسك مستعملا ورقا شفافا، ثم تعرّف على أغلفة الأرض وضع البيانات على الأرقام (1 ← 6).","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","تحصيلي","للارض","الصوره","الاصليه","اخطاء","استخراج","منهاج","وتكافه"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase20_chapitres_39_40_2_card7_2","kind":"html","lessonKey":"phase20_chapitres_39_40_2","title":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟ (2/2)","lessonTitle":"لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟","unitId":10,"part":2,"total":2,"text":"حدد على المخطط في كراسك الحالة الفيزيائية وكثافة مختلف أغلفة الأرض. حدد على المخطط مكان الانقطاعات الزلزالية اعتمادا على المعلومات التي توصلت إليها. استخلص النوعية البتروغرافية لمختلف أغلفة الأرض. 🎯 الخلاصة : تجسيم البنية الداخلية للأرض على شكل طبقات، اعتمادا على المعارف المبنية خلال الوحدة. 🗺 الصورة الأصلية + تنسيق قرائي مصحح — ملاحظة : «غوتنبرغ» و«ليمان» غير واردتين في النص المُدخل آلياً وإن وردت الأعماق 2900 و5100.","keywords":["لماذا","تنثني","بعض","الصخور","كالمطاط","بينما","تنكسر","صخور","اخري","كالزجاج؟","المخطط","كراسك","الحاله","الفيزياييه","وكثافه","مختلف","اغلفه","الانقطاعات"],"aliases":["لماذا تنثني بعض الصخور كالمطاط بينما تنكسر صخور أخرى كالزجاج؟"]},{"id":"lhx_phase21_chapitres_41_42_intro_1","kind":"html","lessonKey":"phase21_chapitres_41_42","title":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","lessonTitle":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","unitId":11,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 3 : النشاط التكتوني والبنيات الجيولوجية المرتبطة به 🎯 الهدف العلمي : فسّر انصهار بيريدوتيت الاستينوسفير تحت الظهيرة بظاهرة تخفيف الضغط (Décompression adiabatique)، وحدّد خصائص البازلت الوسائدي والغابرو الثولييتي. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر تشكل سلاسل الجبال العظمى (الهيمالايا) باصطدام قارتين بعد إغلاق المحيط بالغوص، وحدّد شواهد التقصير والتسميك القاري والتراكبات. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["الدرس","المغماتيه","وتشكل","اللوح","المحيطي","الثالث","العامه","التكتوني","والبنيات","الجيولوجيه","المرتبطه","انصهار","بيريدوتيت","الاستينوسفير","الظهيره","بظاهره","تخفيف","الضغط"],"aliases":["الدرس 2","المغماتية وتشكل اللوح المحيطي"]},{"id":"lhx_phase21_chapitres_41_42_card1_1","kind":"html","lessonKey":"phase21_chapitres_41_42","title":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","lessonTitle":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","unitId":11,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ كيف ينصهر البيريدوتيت الجاف تحت الظهرة المحيطية رغم غياب الماء؟ في النشاط 34 عرفنا أن انصهار البرنس في مناطق الغوص يتطلب وجود الماء (الإماهة) لخفض نقطة الانصهار. ولكن في محور الظهرة المحيطية لا يوجد ماء محرر في العمق (صخر بيريدوتيت جاف تماماً)! ومع ذلك، تصعد ماغما بازلتية مائعة بكثافة هائلة وتبني القشرة المحيطية يومياً. ما هو العامل الترموديناميكي الخفي الذي يؤدي إلى انصهار البيريدوتيت الجاف أسفل الظهرة المحيطية؟","keywords":["الدرس","المغماتيه","وتشكل","اللوح","المحيطي","وضعيه","الانطلاق","وبناء","العلميه","ينصهر","البيريدوتيت","الجاف","الظهره","المحيطيه","الماء؟","عرفنا","انصهار","البرنس"],"aliases":["الدرس 2","المغماتية وتشكل اللوح المحيطي"]},{"id":"lhx_phase21_chapitres_41_42_card2_1","kind":"html","lessonKey":"phase21_chapitres_41_42","title":"مقطع في محور الظهرة يوضح صعود البيريدوتيت وتقاطع مساره مع منحنى الصلابة (1/2)","lessonTitle":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","unitId":11,"part":1,"total":2,"text":"2 التحليل المنهجي لصعود العمود الساخن والانصهار بتخفيف الضغط (Décompression adiabatique) مقطع في محور الظهرة يوضح صعود البيريدوتيت وتقاطع مساره مع منحنى الصلابة مياه المحيط (تبريد سريع لبازلت الوسائد Pillow Lavas) غرفة ماغماتية صعود سريع للبيريدوتيت الساخن (انخفاض الضغط P مع ثبات الحرارة T) 💡 الصعود السريع يقلل الضغط الهيدروستاتيكي فيحدث الانصهار الجزئي الجاف. السر الترموديناميكي في البكالوريا كيف ينصهر البيريدوتيت بتخفيف الضغط؟ الصعود الأدياباتيكي ( Montée adiabatique ) :","keywords":["مقطع","محور","الظهره","يوضح","صعود","البيريدوتيت","وتقاطع","مساره","منحني","الصلابه","الدرس","المغماتيه","وتشكل","اللوح","المحيطي","لصعود","العمود","الساخن"],"aliases":["مقطع في محور الظهرة يوضح صعود البيريدوتيت وتقاطع مساره مع منحنى الصلابة"]},{"id":"lhx_phase21_chapitres_41_42_card2_2","kind":"html","lessonKey":"phase21_chapitres_41_42","title":"مقطع في محور الظهرة يوضح صعود البيريدوتيت وتقاطع مساره مع منحنى الصلابة (2/2)","lessonTitle":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","unitId":11,"part":2,"total":2,"text":"تتسبب قوى الشد والتباعد في الظهرة في صعود سريع لعمود ساخن من البيريدوتيت الاستينوسفيري نحو الأعلى. انخفاض الضغط مع حفظ الحرارة : أثناء الصعود، ينخفض الضغط الواقع على الصخر بسرعة كبيرة جداً مقارنة بفقدان الحرارة، فيحتفظ البيريدوتيت بحرارته العالية (~1300°C) عند ضغط منخفض. الانصهار الجزئي الجاف : يتقاطع مسار البيريدوتيت الصاعد مع منحنى تصلبه الجاف ( Solidus anhydre )، فيحدث له انصهار جزئي بنسبة 20 إلى 30% مولداً ماغما ثولييتية مائعة ( Magma tholéiitique ) قليلة الغازات والماء.","keywords":["مقطع","محور","الظهره","يوضح","صعود","البيريدوتيت","وتقاطع","مساره","منحني","الصلابه","الدرس","المغماتيه","وتشكل","اللوح","المحيطي","تتسبب","والتباعد","لعمود"],"aliases":["مقطع في محور الظهرة يوضح صعود البيريدوتيت وتقاطع مساره مع منحنى الصلابة"]},{"id":"lhx_phase21_chapitres_41_42_card3_1","kind":"html","lessonKey":"phase21_chapitres_41_42","title":"🌊 بازلت الوسائد (Pillow Lavas - سطح القشرة المحيطية)","lessonTitle":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","unitId":11,"part":1,"total":1,"text":"3 محاكي صخور قاع المحيط (البازلت مقابل الغابرو) اضغط لمعاينة سرعة التبريد وتشكل صخور القشرة المحيطية الجديدة : 🌊 تبريد سطحي فوري في مياه المحيط (بازلت الوسائد Pillow Lavas) 🪨 تبريد بطيء في الغرفة الماغماتية العميقة (صخر الغابرو Gabbro) 🌊 بازلت الوسائد (Pillow Lavas - سطح القشرة المحيطية) عندما تتدفق الماغما البازلتية المائعة عبر خسف الظهرة وتلامس مياه المحيط الباردة (2°C)، تتصلب قشرتها الخارجية فوراً على شكل وسائد كروية متتالية. تتميز ببنية ميكروليتية وزجاجية بسبب التبريد الصاعق.","keywords":["بازلت","الوسايد","pillow","lavas","سطح","القشره","المحيطيه","الدرس","المغماتيه","وتشكل","اللوح","المحيطي","محاكي","المحيط","البازلت","مقابل","الغابرو","لمعاينه"],"aliases":["🌊 بازلت الوسائد (Pillow Lavas - سطح القشرة المحيطية)"]},{"id":"lhx_phase21_chapitres_41_42_card4_1","kind":"html","lessonKey":"phase21_chapitres_41_42","title":"1. ما هو الفرق الأساسي في عامل الانصهار بين الظهرة المحيطية (تباعد) ومنطقة الغوص (تقارب)؟","lessonTitle":"الدرس 2 : المغماتية وتشكل اللوح المحيطي","unitId":11,"part":1,"total":1,"text":"4 تقويم النشاط 1 : أسئلة البكالوريا المتكررة 1. ما هو الفرق الأساسي في عامل الانصهار بين الظهرة المحيطية (تباعد) ومنطقة الغوص (تقارب)؟ أ) في الظهرة العامل هو انخفاض الضغط (تخفيف الضغط الأدياباتيكي) في غياب الماء، بينما في الغوص العامل هو دخول الماء (الإماهة) الذي يخفض نقطة الانصهار. ب) لا يوجد فرق، فكلاهما انصهار مائي. ج) في الظهرة ينصهر الغرانيت وفي الغوص ينصهر الكلس.","keywords":["الفرق","الاساسي","عامل","الانصهار","بين","الظهره","المحيطيه","تباعد","ومنطقه","الغوص","تقارب","الدرس","المغماتيه","وتشكل","اللوح","المحيطي","العامل","انخفاض"],"aliases":["1. ما هو الفرق الأساسي في عامل الانصهار بين الظهرة المحيطية (تباعد) ومنطقة الغوص (تقارب)؟"]},{"id":"lhx_phase21_chapitres_41_42_2_intro_1","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":1,"total":1,"text":"المجال الثالث : التكتونية العامة • الوحدة 3 : النشاط التكتوني والبنيات الجيولوجية المرتبطة به 🎯 الهدف العلمي : فسّر انصهار بيريدوتيت الاستينوسفير تحت الظهيرة بظاهرة تخفيف الضغط (Décompression adiabatique)، وحدّد خصائص البازلت الوسائدي والغابرو الثولييتي. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : فسّر تشكل سلاسل الجبال العظمى (الهيمالايا) باصطدام قارتين بعد إغلاق المحيط بالغوص، وحدّد شواهد التقصير والتسميك القاري والتراكبات. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة","keywords":["كيف","تكونت","قمه","ايفرست","8848","متر","وسلسله","الاطلس","التلي؟","الثالث","العامه","التكتوني","والبنيات","الجيولوجيه","المرتبطه","انصهار","بيريدوتيت","الاستينوسفير"],"aliases":["كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟"]},{"id":"lhx_phase21_chapitres_41_42_2_card1_1","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":1,"total":1,"text":"1 الإشكالية الجبلية لختام برنامج العلوم الطبيعية ⚠️ كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟ كانت الهند جزيرة قارية منفصلة عن آسيا يفصل بينهما محيط قديم يسمى (محيط التيثس Téthys ). وبفعل الغوص المستمر، اختفى هذا المحيط تماماً واصطدمت قارة الهند بقارة آسيا! وبما أن القشرة القارية خفيفة جداً ( Kthafa = 2.7 )، فإنها لا تستطيع الغوص في الاستينوسفير الكثيف (3.3) . ماذا يحدث للقشرتين القاريتين المتصادمتين؟ وكيف تفسر هذه الظاهرة التسميك الهائل للقشرة الأرضية (جذر الجبل 70 كم) وتشكل غرانيت التصادم (أناتيكسيا)؟","keywords":["كيف","تكونت","قمه","ايفرست","8848","متر","وسلسله","الاطلس","التلي؟","الجبليه","لختام","برنامج","العلوم","الطبيعيه","الهند","جزيره","قاريه","منفصله"],"aliases":["كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟"]},{"id":"lhx_phase21_chapitres_41_42_2_card2_1","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"مقطع رأسي في سلسلة جبال التصادم (الهيمالايا) يظهر تقصير وتسميك القشرة (1/2)","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":1,"total":2,"text":"2 التحليل المنهجي لخطوات التصادم القاري وتسميك القشرة (التراكبات والسدائم) مقطع رأسي في سلسلة جبال التصادم (الهيمالايا) يظهر تقصير وتسميك القشرة الاستينوسفير (Asthénosphère) قارة الهند (دافعة →) (← آسيا) سلسلة جبال الهيمالايا (قمم شامخة) جذر الجبل (تسميك القشرة حتى 70 كم) 💡 استحالة غوص القارة يؤدي إلى تقصير أفقي وتسميك رأسي ضخم. المميزات الجيولوجية للتصادم ما هي شواهد التصادم القاري؟ اختفاء المحيط التام : غوص القشرة المحيطية بالكامل وانغلاق الحوض المحيطي (وجود بقايا صخور الأفيوليت المحيطية محصورة بين القارتين).","keywords":["مقطع","راسي","سلسله","جبال","التصادم","الهيمالايا","يظهر","تقصير","وتسميك","القشره","كيف","تكونت","قمه","ايفرست","8848","متر","وسلسله","الاطلس"],"aliases":["مقطع رأسي في سلسلة جبال التصادم (الهيمالايا) يظهر تقصير وتسميك القشرة"]},{"id":"lhx_phase21_chapitres_41_42_2_card2_2","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"مقطع رأسي في سلسلة جبال التصادم (الهيمالايا) يظهر تقصير وتسميك القشرة (2/2)","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":2,"total":2,"text":"التقصير والتسميك القاري ( Raccourcissement et Épaississement ) : قوى الانضغاط الشديدة تؤدي لطي الطبقات وتكسيرها بفوالق معكوسة وتراكبات، فيقل عرض القارة ويزداد سمك القشرة من 30 كم إلى أكثر من 70 كم تشكل جذر الجبل ( Racine crustale ) . الأناتيكسيا وغرانيت التصادم ( Anatexie crustale ) : التسميك الرأسي يزيد الحرارة والضغط في أسفل جذر الجبل، فتنصهر صخور القشرة القارية انصهاراً جزئياً لتولد غرانيت التصادم الحديث.","keywords":["مقطع","راسي","سلسله","جبال","التصادم","الهيمالايا","يظهر","تقصير","وتسميك","القشره","كيف","تكونت","قمه","ايفرست","8848","متر","وسلسله","الاطلس"],"aliases":["مقطع رأسي في سلسلة جبال التصادم (الهيمالايا) يظهر تقصير وتسميك القشرة"]},{"id":"lhx_phase21_chapitres_41_42_2_card3_1","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"3️⃣ التسميك وبلوغ قمة إيفرست (الوضع الحالي)","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":1,"total":1,"text":"3 محاكي تشكل الجبال والتسميك القاري التفاعلي اضغط لمعاينة مراحل تطور تصادم قارة الهند بآسيا وتأسيس جبال الهيمالايا : 1️⃣ قبل 50 مليون سنة (غوص المحيط الفاصل التيثس) 2️⃣ لحظة التصادم واختفاء المحيط (احتجاز الأفيوليت) 3️⃣ التسميك وبلوغ قمة إيفرست (الوضع الحالي) 3️⃣ التسميك وبلوغ قمة إيفرست (الوضع الحالي) تستمر الهند بالدفع شمالاً بمعدل 5 سم/سنة. تنضغط القشرة القارية وتتكدس في طيات وتراكبات ضخمة، فيرتفع السطح ليتجاوز 8800 متر، وينغرس جذر الجبل في العمق ليتجاوز 70 كيلومتراً.","keywords":["التسميك","وبلوغ","قمه","ايفرست","الوضع","الحالي","كيف","تكونت","8848","متر","وسلسله","الاطلس","التلي؟","محاكي","الجبال","والتسميك","القاري","التفاعلي"],"aliases":["3️⃣ التسميك وبلوغ قمة إيفرست (الوضع الحالي)"]},{"id":"lhx_phase21_chapitres_41_42_2_card4_1","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 فسّر المغماتية وتشكل اللوح المحيطي عند الظهرات وسط المحيطية. يتشكل الغلاف المحيطي عند محاور الظهرات انطلاقاً من التصعيد المغماتي. تبعد الصفائح عن محور الظهر بفعل اندفاع الماغما وترسب الحبش. يحدث التفاعل بين الماغما والصخور المجاورة مكوناً صخر المغماتيت (مزيج انتقالي). يوثق التمغنط المتباين المتناظر على جانبي الظهر تمدد القاع وانعكاس المجال المغناطيسي. يزداد عمر صخور القاع كلما ابتعدنا عن محور الظهر. 🔑 المصطلح المفتاحي في البكالوريا : المغماتيت / التمدد المحيطي","keywords":["كيف","تكونت","قمه","ايفرست","8848","متر","وسلسله","الاطلس","التلي؟","خلاصه","الدرس","المغماتيه","وتشكل","اللوح","المحيطي","الظهرات","المحيطيه","يتشكل"],"aliases":["كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟"]},{"id":"lhx_phase21_chapitres_41_42_2_card5_1","kind":"html","lessonKey":"phase21_chapitres_41_42_2","title":"1. لماذا تعتبر صخور \"الأفيوليت\" ( Ophiolites ) الموجودة فوق قمم جبال الألب والهيمالايا دليلاً قاطعاً على حدوث تصادم قاري مسبوق بغوص؟","lessonTitle":"كيف تكونت قمة إيفرست (8848 متر) وسلسلة الأطلس التلي؟","unitId":11,"part":1,"total":1,"text":"4 تقويم النشاط 2 : ختام أسئلة البكالوريا 1. لماذا تعتبر صخور \"الأفيوليت\" ( Ophiolites ) الموجودة فوق قمم جبال الألب والهيمالايا دليلاً قاطعاً على حدوث تصادم قاري مسبوق بغوص؟ أ) لأن الأفيوليت يمثل بقايا القشرة المحيطية القديمة التي احتجزت وانحصرت ورفعت إلى القمم أثناء اصطدام القارتين وإغلاق المحيط الذي كان يفصل بينهما. ب) لأن الجبال تتكون من براكين بازلتية حديثة. ج) لأن قمة إيفرست كانت جزيرة بركانية.","keywords":["لماذا","تعتبر","صخور","الافيوليت","ophiolites","الموجوده","فوق","قمم","جبال","الالب","والهيمالايا","دليلا","قاطعا","علي","حدوث","تصادم","قاري","مسبوق"],"aliases":["1. لماذا تعتبر صخور \"الأفيوليت\" ( Ophiolites ) الموجودة فوق قمم جبال الألب والهيمالايا دليلاً قاطعاً على حدوث تصادم قاري مسبوق بغوص؟"]},{"id":"lhx_phase22_chapitres_43_44_intro_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي) (1/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":2,"text":"المجال الثالث : التكتونية العامة • الوحدة 3 : النشاط التكتوني والبنيات الجيولوجية المرتبطة به 🎯 الهدف العلمي : بيّن أن الصخور النارية والرسوبية والمتحولة في دورة جيولوجية مغلقة ومستمرة بفعل عوامل التجوية، التصخر، التحول، والانصهار. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد أصل المحروقات (العوالق البحرية) وشروط تشكل المصيدة البترولية (صخر الأم، الخزان، والغطاء)، وتبيّن ثروة الأحواض المائية الجوفية بالجنوب الجزائري. ⏱️ المدة التقديرية للتعلم الذاتي :","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","الثالث","العامه","التكتوني","والبنيات","الجيولوجيه","المرتبطه","الناريه","والرسوبيه","والمتحوله","جيولوجيه","مغلقه","ومستمره"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_intro_2","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي) (2/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":2,"total":2,"text":"25 دقيقة ⚠️ إثراء ثقافي — غير وارد في الكتاب المدرسي المقرر ولا في موارد المنهاج","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","الكتاب","المدرسي","المقرر","موارد","المنهاج"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_card1_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":1,"text":"1 وضعية الانطلاق وبناء الإشكالية العلميـة ⚠️ هل الصخور مواد جامدة لا تتغير أبداً بمرور الزمن؟ يعتقد الكثيرون أن الصخر مادة أبدية ثابتة لا تتغير. ولكن الجيولوجيا تثبت أن القشرة الأرضية نشطة للغاية، حيث تتآكل الجبال وتتحول لرمال، وتتحول الرمال لصخور صلبة، وتغوص الصخور في أعماق الأرض لتنصهر أو تتحول وتصعد كبراكين جديدة! كيف ترتبط المجموعات الصخرية الثلاث (الرسوبية، النارية، والمتحولة) في دورة جيولوجية دائمة التجدد؟","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","وضعيه","الانطلاق","وبناء","العلميه","جامده","تتغير","بمرور","الزمن؟","يعتقد","الكثيرون","الصخر","ابديه"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_card2_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"مخطط دورة الصخور الجيوديناميكية في القشرة والبرنس (1/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":2,"text":"2 التحليل المنهجي لمخطط دورة الصخور (التجوية، التصخر، التحول، والانصهار) مخطط دورة الصخور الجيوديناميكية في القشرة والبرنس الماغما (الصهارة) صخور نارية / مغماتية صخور رسوبية صخور متحولة تبريد وتصلب تجوية وتعرية وترسيب ضغط وحرارة (تحول) انصهار كلي 💡 أي صخر يمكن أن يتحول لأي نوع آخر حسب الظروف التكتونية والمناخية. العمليات الصخرية في البكالوريا كيف تتم الدورة الصخرية؟ الصخور النارية ( Roches Magmatiques ) : تنتج عن تصلب وتبريد الماغما الساخنة (مثل الغرانيت في العمق والبازلت على السطح).","keywords":["مخطط","دوره","الصخور","الجيوديناميكيه","القشره","والبرنس","الدرس","الطبيعه","اثراء","ثقافي","لمخطط","التجويه،","التصخر،","التحول،","والانصهار","الماغما","الصهاره","ناريه"],"aliases":["مخطط دورة الصخور الجيوديناميكية في القشرة والبرنس"]},{"id":"lhx_phase22_chapitres_43_44_card2_2","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"مخطط دورة الصخور الجيوديناميكية في القشرة والبرنس (2/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":2,"total":2,"text":"الصخور الرسوبية ( Roches Sédimentaires ) : تتعرض الصخور السطحية لعوامل التجوية والتعرية (رياح، أمطار) فتتفتت لرسوبات تنقل وتترسب في الأحواض وتتصخر (مثل الحجر الرملي والكلسي). الصخور المتحولة ( Roches Métamorphiques ) : عند غوص الصخور الرسوبية أو النارية في العمق، تتعرض لحرارة وضغط عاليين فيتغير تركيبها المعدني في الحالة الصلبة دون انصهار (مثل تحول الكلس إلى رخام، والغرانيت إلى غنيس). وإذا زادت الحرارة تنصهر كلياً لتعود ماغما جديدة.","keywords":["مخطط","دوره","الصخور","الجيوديناميكيه","القشره","والبرنس","الدرس","الطبيعه","اثراء","ثقافي","الرسوبيه","roches","dimentaires","تتعرض","السطحيه","لعوامل","التجويه","والتعريه"],"aliases":["مخطط دورة الصخور الجيوديناميكية في القشرة والبرنس"]},{"id":"lhx_phase22_chapitres_43_44_card3_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"🌧️ تشكل الصخور الرسوبية","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":1,"text":"3 محاكي التحولات الصخرية التفاعلي اختر العامل الجيولوجي المؤثر لمعاينة الصخر الناتج : 🌧️ تجوية + تعرية + ترسيب وتصخر 🔥 زيادة الضغط والحرارة دون انصهار (تحول) 🌋 انصهار كلي ثم تبريد وتصلب (صهارة ونار) 🌧️ تشكل الصخور الرسوبية تتفتت الصخور السابقة وتنقل الجزيئات لتترسب على شكل طبقات متتالية في قاع البحار والبحيرات. تنضغط وتلتحم بمرور ملايين السنين مشكلة صخوراً رسوبية طبقية غنية بالمستحاثات.","keywords":["تشكل","الصخور","الرسوبيه","الدرس","دوره","الطبيعه","اثراء","ثقافي","محاكي","التحولات","الصخريه","التفاعلي","العامل","الجيولوجي","الموثر","لمعاينه","الصخر","الناتج"],"aliases":["🌧️ تشكل الصخور الرسوبية"]},{"id":"lhx_phase22_chapitres_43_44_card4_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"1. ما هو الفرق الجوهري في آلية التشكل بين الصخر المتحول ( Roche métamorphique ) والصخر الناري ( Roche magmatique )؟","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":1,"text":"4 تقويم النشاط 3 : أسئلة البكالوريا المتكررة 1. ما هو الفرق الجوهري في آلية التشكل بين الصخر المتحول ( Roche métamorphique ) والصخر الناري ( Roche magmatique )؟ أ) الصخر المتحول يتغير في الحالة الصلبة تحت تأثير الضغط والحرارة دون أن ينصهر، بينما الصخر الناري ينتج عن تصلب سائل صهاري مصهور بالكامل (الماغما). ب) الصخر المتحول يتكون في السطح فقط. ج) لا يوجد أي فرق بينهما.","keywords":["الفرق","الجوهري","اليه","التشكل","بين","الصخر","المتحول","roche","tamorphique","والصخر","الناري","magmatique","الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي"],"aliases":["1. ما هو الفرق الجوهري في آلية التشكل بين الصخر المتحول ( Roche métamorphique ) والصخر الناري ( Roche magmatique )؟"]},{"id":"lhx_phase22_chapitres_43_44_card5_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي) (1/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 54، ص 330) الوحدة: D3-U11 — الظواهر التكتونية — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. ينتج عن التقلص القشري تحول الصخور العميقة تحت تأثير ارتفاع درجة الحرارة والضغط، وانصهار جزئي لغرانيت القشرة القارية (صخر الميغماتيت). يؤدي تقارب الألواح التكتونية إلى تشوه حدود الصفائح واندساس بقايا المحيط داخل السلسلة الجبلية على شكل أوفيوليت : متتالية من الأسفل إلى الأعلى من بيريدوتيت - غابرو - مركب بازلتي.","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","المعرفيه","الرسمي","للكتاب","المدرسي","الظواهر","الكتاب","بتنسيق","قرايي،","تغيير","المعني،","تنسيق","قرايي"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_card5_2","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي) (2/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":2,"total":2,"text":"يعد تواجد الأوفيوليت في السلاسل الجبلية الحديثة شاهداً على التصادم القاري واختفاء محيط قديم، وتبقى منصفة تاكسنة الشاهد الوحيد في الجزائر. يمثل المخطط التحصيلي ديناميكية الليتوسفير من التباعد إلى غاية تشكل سلسلة جبلية (Orogenèse).","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","تواجد","الاوفيوليت","السلاسل","الجبليه","الحديثه","شاهدا","التصادم","القاري","واختفاء","قديم،","وتبقي","منصفه"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_card6_1","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي) (1/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":1,"total":2,"text":"🗺 مخطط تحصيلي — من الوجه إلى سلسلة جبلية (Orogenèse) (ص 330) الصورة الأصلية — طبقة الصورة تحوي أخطاء آلية («الستينوزوي» بدل «السينوزوي»، «مخطية» بدل «محيطية»، «البرنس اليتوسفيري» بدل «الليثوسفيري»، «تصاعد» بدل «تقارب/التصادم»)؛ النسخة المصححة أدناه هي المرجع القرائي. قشرة قارية مستقرة (سمك ≈ 30 Km). تباعد : فتح الوجه (rift) وتشكل حواف قارية. تشكل المحيط : قشرة محيطية في المحور + ترسب الصخور الرسوبية في الحواف. تقارب : بداية التصادم — انغلاق المحيط واندساس القشرة المحيطية. التصادم الكامل :","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","تحصيلي","الوجه","سلسله","جبليه","orogen","الصوره","الاصليه","اخطاء","الستينوزوي","السينوزوي","مخطيه","محيطيه"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_card6_2","kind":"html","lessonKey":"phase22_chapitres_43_44","title":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي) (2/2)","lessonTitle":"الدرس 5 : دورة الصخور في الطبيعة (إثراء ثقافي)","unitId":11,"part":2,"total":2,"text":"تشكل سلسلة الجبال (Orogenèse) على المقياس القاري (سمك ≈ 50 Km) مع المعقد الأفوليني والنابيات. مفتاح الألوان : الصخور الرسوبية (السينوزوي، الطباشيري، الجوراسي، الترياسي) — قشرة قديمة (قارية) — قشرة محيطية — الليثوسفيري — الأستينوسفيري. 🗺 الصورة الأصلية (ص 330) + تنسيق قرائي مصحح — المفردات مثبتة في النص الرسمي (سلسلة جبلية 12×، الليثوسفير 20×، الأستينوسفير 5×، التصادم 21×، تقارب 14×، تباعد 21×).","keywords":["الدرس","دوره","الصخور","الطبيعه","اثراء","ثقافي","سلسله","الجبال","orogen","المقياس","القاري","المعقد","الافوليني","والنابيات","مفتاح","الالوان","الرسوبيه","السينوزوي،"],"aliases":["الدرس 5","دورة الصخور في الطبيعة (إثراء ثقافي)"]},{"id":"lhx_phase22_chapitres_43_44_2_intro_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ (1/2)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":2,"text":"المجال الثالث : التكتونية العامة • الوحدة 3 : النشاط التكتوني والبنيات الجيولوجية المرتبطة به 🎯 الهدف العلمي : بيّن أن الصخور النارية والرسوبية والمتحولة في دورة جيولوجية مغلقة ومستمرة بفعل عوامل التجوية، التصخر، التحول، والانصهار. ⏱️ المدة التقديرية للتعلم الذاتي : 25 دقيقة 🎯 الهدف العلمي : حدّد أصل المحروقات (العوالق البحرية) وشروط تشكل المصيدة البترولية (صخر الأم، الخزان، والغطاء)، وتبيّن ثروة الأحواض المائية الجوفية بالجنوب الجزائري. ⏱️ المدة التقديرية للتعلم الذاتي :","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","الثالث","العامه","التكتوني","والبنيات","الجيولوجيه","المرتبطه"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_intro_2","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ (2/2)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":2,"total":2,"text":"25 دقيقة ⚠️ إثراء ثقافي — غير وارد في الكتاب المدرسي المقرر ولا في موارد المنهاج","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","اثراء","ثقافي","الكتاب","المدرسي","المقرر","موارد"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card1_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":1,"text":"1 الإشكالية الاقتصادية والجيولوجية للصحراء الجزائرية ⚠️ كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ تضم الصحراء الجزائرية حقولاً عالمية عملاقة مثل حقل البترول في حاسي مسعود وحقل الغاز في حاسي الرمل ، بالإضافة لأكبر خزان مياه عذبة جوفية في العالم (الطبقة الألبية Nappe Albienne ). كيف أدى التاريخ الجيولوجي العريق لأحواض الصحراء (عندما كانت مغطاة ببحار دافئة قبل ملايين السنين) والتشوهات التكتونية (الطيات والفوالق) إلى تشكل وحجز هذه الثروات الاستراتيجية؟","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","الاقتصاديه","والجيولوجيه","للصحراء","الجزايريه","الصحراء","حقولا"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card2_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع (1/3)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":3,"text":"2 التحليل المنهجي لشروط المصيدة البترولية (الخزان، الغطاء، وترتيب الموائع) مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع صخر غطاء غير منفذ (طين / جبس) غاز طبيعي (خفيف جداً) بترول خام (كثافة متوسطة) ماء مالح (كثيف وثقيل) صخر الأم غني بالمادة العضوية (سجيل غضاري) بئر تنقيب 💡 تترتب الموائع حسب الكثافة : الغاز فوق، البترول في الوسط، والماء أسفل. شروط الحقل البترولي في البكالوريا كيف تتشكل وتحجز المحروقات؟ صخر الأم ( Roche mère ) :","keywords":["مقطع","مصيده","بتروليه","طيه","محدبه","anticlinal","تبين","الشروط","الثلاثه","وترتيب","الموايع","كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات"],"aliases":["مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع"]},{"id":"lhx_phase22_chapitres_43_44_2_card2_2","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع (2/3)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":2,"total":3,"text":"صخر غضاري عميق ترسبت فيه العوالق البحرية العضوية بمعزل عن الأكسجين وتحولت بفعل البكتيريا والحرارة والضغط إلى مادة كيروجين ثم إلى قطرات بترول وغاز. هجرة البترول نحو صخر الخزان ( Roche réservoir ) : يهاجر البترول الخفيف نحو الأعلى حتى يدخل في صخر مسامي ومنفذ يحتوي على فراغات وشقوق (مثل الحجر الرملي الكوارتزي في حاسي مسعود). صخر الغطاء والمصيدة التكتونية ( Roche couverture & Piège ) : لمنع تسرب البترول للسطح وضياعه،","keywords":["مقطع","مصيده","بتروليه","طيه","محدبه","anticlinal","تبين","الشروط","الثلاثه","وترتيب","الموايع","كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات"],"aliases":["مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع"]},{"id":"lhx_phase22_chapitres_43_44_2_card2_3","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع (3/3)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":3,"total":3,"text":"يجب أن يعترض مساره صخر كتيم غير منفذ (مثل الطين أو الجبس) يتخذ شكلاً تكتونياً محدباً (طية محدبة أو فالق) يحجز المحروقات.","keywords":["مقطع","مصيده","بتروليه","طيه","محدبه","anticlinal","تبين","الشروط","الثلاثه","وترتيب","الموايع","كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات"],"aliases":["مقطع في مصيدة بترولية (طية محدبة Anticlinal) تبين الشروط الثلاثة وترتيب الموائع"]},{"id":"lhx_phase22_chapitres_43_44_2_card3_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"🛢️ حقل حاسي مسعود العملاق (البترول الخام)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":1,"text":"3 مستكشف ثروات الصحراء الجزائرية التفاعلي اضغط لمعاينة خصائص الحقول الجزائرية الكبرى وأهمية حمايتها واستغلالها العقلاني : 🛢️ حقل حاسي مسعود (البترول الخام) 🔥 حقل حاسي الرمل (الغاز الطبيعي) 💧 حوض الألبي الجوفي (المياه العذبة المستحاثية) 🛢️ حقل حاسي مسعود العملاق (البترول الخام) اكتشف عام 1956، ويعتبر من أكبر حقول النفط في العالم. يتميز بصخر خزان رملي كوارتزي ( Grès cambro-ordovicien ) شديد المسامية والنفاذية محجوز تحت غطاء ملحي صلب، وينتج نفطاً ممتازاً خفيفاً وقليل الكبريت.","keywords":["حقل","حاسي","مسعود","العملاق","البترول","الخام","كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","والغاز","والمياه","العذبه","العالم؟","مستكشف"],"aliases":["🛢️ حقل حاسي مسعود العملاق (البترول الخام)"]},{"id":"lhx_phase22_chapitres_43_44_2_card4_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":1,"text":"📝 خلاصة الدرس 🎯 بيّن دورة الصخور في الطبيعة كدورة جيولوجية مغلقة ومستمرة. تتحول الصخور النارية والرسوبية والمتحولة بفعل التجوية والتصخر والتحول والانصهار. يهدم التعرية الصخور وترسب موادها فتشكل صخوراً رسوبية جديدة. يولد الغوص والتصادم تحولاً (مطاعن) وانصهاراً مكوناً الصخور النارية. تشكل الدورة الجيولوجية نظاماً مغلقاً ومستمراً منذ تشكل الأرض. توثق الصخور وشواهدها الأحفورية أحداث التاريخ الجيولوجي القديم. 🔑 المصطلح المفتاحي في البكالوريا : دورة الصخور / التحول (المطاعن)","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","خلاصه","الدرس","الصخور","الطبيعه","كدوره","جيولوجيه"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card5_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"1. لماذا تترتب الموائع الثلاثة المحجوزة داخل صخر الخزان في المصيدة البترولية بالترتيب التالي من الأعلى إلى الأسفل : (غاز طبيعي ← ثم بترول خام ← ثم ماء مالح)؟","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":1,"text":"4 تقويم النشاط 4 : الختام التام لأسئلة البكالوريا 1. لماذا تترتب الموائع الثلاثة المحجوزة داخل صخر الخزان في المصيدة البترولية بالترتيب التالي من الأعلى إلى الأسفل : (غاز طبيعي ← ثم بترول خام ← ثم ماء مالح)؟ أ) تترتب وفقاً لتباين الكثافة ( Ségrégation gravitaire par densité ) : الغاز أخف الموائع فيصعد للقمة، يليه البترول في الوسط، بينما الماء المالح هو الأثقل والأكثف فيستقر في قاع الخزان. ب) تترتب حسب درجة الحرارة. ج) تترتب بشكل عشوائي ومختلط دائماً.","keywords":["لماذا","تترتب","الموايع","الثلاثه","المحجوزه","داخل","صخر","الخزان","المصيده","البتروليه","بالترتيب","التالي","الاعلي","الي","الاسفل","غاز","طبيعي","بترول"],"aliases":["1. لماذا تترتب الموائع الثلاثة المحجوزة داخل صخر الخزان في المصيدة البترولية بالترتيب التالي من الأعلى إلى الأسفل","(غاز طبيعي ← ثم بترول خام ← ثم ماء مالح)؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card6_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ (1/2)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":2,"text":"🏛 الحصيلة المعرفية — النص الرسمي للكتاب المدرسي (الفصل 54، ص 330) الوحدة: D3-U11 — الظواهر التكتونية — نص الكتاب بتنسيق قرائي، دون تغيير في المعنى، مع تنسيق قرائي يجعل النص مقروءاً. ينتج عن التقلص القشري تحول الصخور العميقة تحت تأثير ارتفاع درجة الحرارة والضغط، وانصهار جزئي لغرانيت القشرة القارية (صخر الميغماتيت). يؤدي تقارب الألواح التكتونية إلى تشوه حدود الصفائح واندساس بقايا المحيط داخل السلسلة الجبلية على شكل أوفيوليت : متتالية من الأسفل إلى الأعلى من بيريدوتيت - غابرو - مركب بازلتي.","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","المعرفيه","الرسمي","للكتاب","المدرسي","الظواهر","الكتاب"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card6_2","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ (2/2)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":2,"total":2,"text":"يعد تواجد الأوفيوليت في السلاسل الجبلية الحديثة شاهداً على التصادم القاري واختفاء محيط قديم، وتبقى منصفة تاكسنة الشاهد الوحيد في الجزائر. يمثل المخطط التحصيلي ديناميكية الليتوسفير من التباعد إلى غاية تشكل سلسلة جبلية (Orogenèse).","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","تواجد","الاوفيوليت","السلاسل","الجبليه","الحديثه","شاهدا"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card7_1","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ (1/2)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":1,"total":2,"text":"🗺 مخطط تحصيلي — من الوجه إلى سلسلة جبلية (Orogenèse) (ص 330) الصورة الأصلية — طبقة الصورة تحوي أخطاء آلية («الستينوزوي» بدل «السينوزوي»، «مخطية» بدل «محيطية»، «البرنس اليتوسفيري» بدل «الليثوسفيري»، «تصاعد» بدل «تقارب/التصادم»)؛ النسخة المصححة أدناه هي المرجع القرائي. قشرة قارية مستقرة (سمك ≈ 30 Km). تباعد : فتح الوجه (rift) وتشكل حواف قارية. تشكل المحيط : قشرة محيطية في المحور + ترسب الصخور الرسوبية في الحواف. تقارب : بداية التصادم — انغلاق المحيط واندساس القشرة المحيطية. التصادم الكامل :","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","تحصيلي","الوجه","سلسله","جبليه","orogen","الصوره"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lhx_phase22_chapitres_43_44_2_card7_2","kind":"html","lessonKey":"phase22_chapitres_43_44_2","title":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟ (2/2)","lessonTitle":"كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟","unitId":11,"part":2,"total":2,"text":"تشكل سلسلة الجبال (Orogenèse) على المقياس القاري (سمك ≈ 50 Km) مع المعقد الأفوليني والنابيات. مفتاح الألوان : الصخور الرسوبية (السينوزوي، الطباشيري، الجوراسي، الترياسي) — قشرة قديمة (قارية) — قشرة محيطية — الليثوسفيري — الأستينوسفيري. 🗺 الصورة الأصلية (ص 330) + تنسيق قرائي مصحح — المفردات مثبتة في النص الرسمي (سلسلة جبلية 12×، الليثوسفير 20×، الأستينوسفير 5×، التصادم 21×، تقارب 14×، تباعد 21×).","keywords":["كيف","تختزن","صحراء","الجزاير","الجافه","اكبر","احتياطيات","البترول","والغاز","والمياه","العذبه","العالم؟","سلسله","الجبال","orogen","المقياس","القاري","المعقد"],"aliases":["كيف تختزن صحراء الجزائر الجافة أكبر احتياطيات البترول والغاز والمياه العذبة في العالم؟"]},{"id":"lha_d1-u1-l1-expression-genique_active_1","kind":"active","lessonKey":"d1-u1-l1-expression-genique","title":"الوحدة 1 : التعبير المورثي ونقل المعلومة (1/6)","lessonTitle":"الوحدة 1 : التعبير المورثي ونقل المعلومة","unitId":1,"part":1,"total":6,"text":"الوحدة 1 : التعبير المورثي ونقل المعلومة الدخول إلى المجال من وضعية مشكلة حقيقية كما في الكتاب. كيف يمكن لتغير في بنية بروتين أن يؤدي إلى مرض خطير؟ ننطلق من حالة البريون ومرض جنون البقر لنفهم لماذا ليست البروتينات مجرد تعريفات تُحفظ، بل جزيئات يؤدي تغير بنيتها إلى آثار خطيرة. وثيقة دعم حديثة شبيهة بالهستولوجيا الإسفنجية المرتبطة بحالة البريون. دعم بصري إضافي: الحقل النسيجي يوضح أن الخلل البنيوي للبروتين قد ينعكس على النسيج العصبي. ابدأ من وضعية البريون أفهم أولاً لماذا يهمّنا البروتين قبل الدخول إلى آلية تركيبه.","keywords":["الوحده","التعبير","المورثي","ونقل","المعلومه","الدخول","وضعيه","مشكله","حقيقيه","الكتاب","لتغير","بروتين","خطير؟","ننطلق","البريون","البقر","لنفهم","البروتينات"],"aliases":["الوحدة 1","التعبير المورثي ونقل المعلومة"]},{"id":"lha_d1-u1-l1-expression-genique_active_2","kind":"active","lessonKey":"d1-u1-l1-expression-genique","title":"الوحدة 1 : التعبير المورثي ونقل المعلومة (2/6)","lessonTitle":"الوحدة 1 : التعبير المورثي ونقل المعلومة","unitId":1,"part":2,"total":6,"text":"الدخول إلى الوحدة من صورة حية قريبة من كتاب المدرسة. العنكبوت يصنع خيطاً دقيقاً جداً — كيف تصنع الخلية بروتيناً؟ صورة خيط العنكبوت تجعل السؤال مركزاً: كيف تستطيع الخلية تركيب بروتين مضبوط البنية والوظيفة؟ وثيقة دعم حديثة تذكر ببنية الخلية الحيوانية ومسار المعلومة من النواة إلى الهيولى. تذكير بنيوي: أين توجد النواة؟ أين تعمل الريبوزومات؟ ابدأ من سؤال التركيب أنتقل من المثال الحي إلى الوثائق التي تشرح التعبير المورثي. ربط المورثات بالبروتينات واستنتاج مفهوم التعبير المورثي.","keywords":["الوحده","التعبير","المورثي","ونقل","المعلومه","الدخول","قريبه","المدرسه","العنكبوت","دقيقا","بروتينا؟","السوال","مركزا","تستطيع","بروتين","مضبوط","والوظيفه؟","حديثه"],"aliases":["الوحدة 1","التعبير المورثي ونقل المعلومة"]},{"id":"lha_d1-u1-l1-expression-genique_active_3","kind":"active","lessonKey":"d1-u1-l1-expression-genique","title":"الوحدة 1 : التعبير المورثي ونقل المعلومة (3/6)","lessonTitle":"الوحدة 1 : التعبير المورثي ونقل المعلومة","unitId":1,"part":3,"total":6,"text":"مخطط يبين مورثات على ADN وبروتينات مقابلة لها في السيتوبلازم. الوثيقة: مورثات مختلفة تقابلها بروتينات مختلفة. ماذا تلاحظ بين المورثات والبروتينات؟ مورثات مختلفة بروتينات مختلفة أحسنت، وصفت العلاقة المشاهدة. صف ما تراه: مورثات مختلفة ↔ بروتينات مختلفة. ما العلاقة بين المورثة 1 والبروتين 1؟ كل مورثة بروتين محدد ممتاز، ربطت كل مورثة بمنتوجها. حاول أن تذكر أن كل مورثة تحمل معلومات بروتين محدد. استنتج استنتج مفهوم التعبير المورثي. المعلومات الوراثية تركيب بروتين أحسنت، هذا هو معنى التعبير المورثي.","keywords":["الوحده","التعبير","المورثي","ونقل","المعلومه","مورثات","وبروتينات","مقابله","السيتوبلازم","الوثيقه","مختلفه","تقابلها","بروتينات","تلاحظ","المورثات","والبروتينات؟","احسنت،","العلاقه"],"aliases":["الوحدة 1","التعبير المورثي ونقل المعلومة"]},{"id":"lha_d1-u1-l1-expression-genique_active_4","kind":"active","lessonKey":"d1-u1-l1-expression-genique","title":"الوحدة 1 : التعبير المورثي ونقل المعلومة (4/6)","lessonTitle":"الوحدة 1 : التعبير المورثي ونقل المعلومة","unitId":1,"part":4,"total":6,"text":"اربط بين استعمال المعلومة الوراثية وظهور بروتين محدد. التعبير المورثي هو استعمال المعلومة الموجودة في المورثة من أجل تركيب بروتين محدد. استخلاص مقر تركيب البروتين وتبريره انطلاقاً من وثيقتين. صورة مجهرية تبين مناطق ظهور البروتينات الموسومة. الوثيقة 1: صورة قريبة من الوثيقة التجريبية. رسم تفسيري لخلية مع مواقع ظهور البروتينات المشعة. الوثيقة 2: رسم تفسيري. ما مقر تركيب البروتين داخل الخلية؟ علل جوابك اعتماداً على الوثيقتين. الريبوزومات الإشعاع الوثيقتين يتم تركيب البروتين على مستوى الريبوزومات،","keywords":["الوحده","التعبير","المورثي","ونقل","المعلومه","استعمال","الوراثيه","وظهور","بروتين","الموجوده","المورثه","استخلاص","وتبريره","انطلاقا","وثيقتين","مجهريه","مناطق","البروتينات"],"aliases":["الوحدة 1","التعبير المورثي ونقل المعلومة"]},{"id":"lha_d1-u1-l1-expression-genique_active_5","kind":"active","lessonKey":"d1-u1-l1-expression-genique","title":"الوحدة 1 : التعبير المورثي ونقل المعلومة (5/6)","lessonTitle":"الوحدة 1 : التعبير المورثي ونقل المعلومة","unitId":1,"part":5,"total":6,"text":"ويثبت ذلك ظهور الوسم في هذه المناطق في الوثيقتين. اقتراح فرضية تفسر انتقال المعلومة الوراثية من النواة إلى السيتوبلازم. كيف تنتقل المعلومة الوراثية من النواة إلى السيتوبلازم من أجل تركيب البروتين؟ نتائج تجربة ثلاث مجموعات توضح أثر حقن ARN. اقترح فرضية تفسر هذا الانتقال. حلل نتائج المجموعات الثلاث بإيجاز. هل تؤيد النتائج فرضية وجود جزيء وسيط؟ علل. جزيء وسيط النواة السيتوبلازم تركيب البروتين المجموعة الثالثة هيموغلوبين جزيء وسيط يوجه تركيب بروتين تؤيد التجربة وجود جزيء وسيط من نوع ARN يوجّه تركيب بروتين محدد.","keywords":["الوحده","التعبير","المورثي","ونقل","المعلومه","ويثبت","الوسم","المناطق","الوثيقتين","اقتراح","فرضيه","انتقال","الوراثيه","السيتوبلازم","تنتقل","البروتين؟","نتايج","تجربه"],"aliases":["الوحدة 1","التعبير المورثي ونقل المعلومة"]},{"id":"lha_d1-u1-l1-expression-genique_active_6","kind":"active","lessonKey":"d1-u1-l1-expression-genique","title":"الوحدة 1 : التعبير المورثي ونقل المعلومة (6/6)","lessonTitle":"الوحدة 1 : التعبير المورثي ونقل المعلومة","unitId":1,"part":6,"total":6,"text":"التحقق من دور ARN الرسول باستعمال اليوراسيل المشع. لماذا يظهر الوسم أولاً في النواة ثم لاحقاً في السيتوبلازم؟ وثيقة تبين تموضع الوسم بعد مدة قصيرة وبعد مدة أطول. ما الفرضية التي يدعمها هذا التتبع؟ أين يظهر الوسم أولاً؟ وأين يظهر لاحقاً؟ هل تتحقق الفرضية؟ علل. اقترح تسمية مناسبة لهذا ARN. اليوراسيل النواة السيتوبلازم النواة السيتوبلازم ينتقل النواة السيتوبلازم ARN رسول يُصنّع ARNm في النواة ثم ينتقل إلى السيتوبلازم حاملاً نسخة من المعلومة الوراثية.","keywords":["الوحده","التعبير","المورثي","ونقل","المعلومه","التحقق","الرسول","باستعمال","اليوراسيل","المشع","الوسم","لاحقا","السيتوبلازم؟","تموضع","قصيره","الفرضيه","يدعمها","التتبع؟"],"aliases":["الوحدة 1","التعبير المورثي ونقل المعلومة"]},{"id":"lha_lecon_transcription_active_1","kind":"active","lessonKey":"lecon_transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (1/3)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":3,"text":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN اكتشاف مقر وآلية تركيب جزيئة ARNm انطلاقا من ADN. تتم عملية [____] داخل [____] حيث يركب إنزيم [____] سلسلة ARNm انطلاقا من السلسلة القالبية. نقل المعلومة الوراثية من ADN إلى ARNm داخل النواة. المقر الذي يتم فيه الاستنساخ عند حقيقيات النوى. الإنزيم الذي يركب ARN في اتجاه 5←3 ويقرأ القالب 3←5. ما هو الإنزيم الذي يركب ARNm انطلاقا من السلسلة القالبية؟ ARN بوليميراز التعريف الصحيح: ARN بوليميراز ربط السلسلة القالبية باتجاه القراءة.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","اكتشاف","واليه","جزييه","انطلاقا","عمليه","سلسله","القالبيه","المعلومه","المقر","الاستنساخ"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_lecon_transcription_active_2","kind":"active","lessonKey":"lecon_transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (2/3)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":2,"total":3,"text":"يقرأ الريبوزوم السلسلة الرسولية من [____] نحو [____]، بينما يُستعمل مرجع تكامل القواعد ما يسمى بـ [____]. السلسلة التي تُستعمل مرجعا لتكامل قواعد ARNm. اتجاه قراءة ARNm وتركيب البروتين. أكمل: السلسلة التي تُستعمل مرجعا لتكامل قواعد ARNm تسمى _______ السلسلة القالبية التعريف الصحيح: السلسلة القالبية تحديد مقر الاستنساخ ثم تحليل انتقال الإشعاع منهجياً. لاحظ مخطط خلية حقيقية النوى. حدد مقر حدوث الاستنساخ ثم حلل ظاهرة انتقال الإشعاع من النواة نحو الهيولى دون تفسير (تحليل محض). انقر على مقر حدوث الاستنساخ (داخل النواة).","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الريبوزوم","الرسوليه","بينما","يستعمل","تكامل","القواعد","تستعمل","مرجعا","لتكامل","قواعد"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_lecon_transcription_active_3","kind":"active","lessonKey":"lecon_transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (3/3)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":3,"total":3,"text":"صحيح! الاستنساخ يتم داخل النواة حيث يوجد ADN. حلل ظاهرة انتقال الإشعاع من النواة إلى الهيولى (تحليل محض، بدون تفسير). التحليل (ملاحظة محضة) ماذا تلاحظ بعد 15 ثم 90 دقيقة؟ تجنب لأن/راجع إلى... النواة الهيولى الإشعاع الاستنتاج استنتج مقر وآلية تركيب ARNm... يتم تركيب","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الاستنساخ","ظاهره","انتقال","الاشعاع","تحليل","تفسير","ملاحظه","تلاحظ","دقيقه؟","الاستنتاج"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_phase11_chapitres_21_22_active_1","kind":"active","lessonKey":"phase11_chapitres_21_22","title":"الفصل 31 : تذكير بالمكتسبات — الفصل 32 : مقر عملية التركيب الضوئي (1/2)","lessonTitle":"الفصل 31 : تذكير بالمكتسبات — الفصل 32 : مقر عملية التركيب الضوئي","unitId":6,"part":1,"total":2,"text":"الفصل 31 : تذكير بالمكتسبات — الفصل 32 : مقر عملية التركيب الضوئي تحديد مقر التفاعلات الضوئية ثم تحليلها منهجياً. لاحظ مخطط الصانعة الخضراء. حدد مقر التفاعلات الضوئية (التيلاكويد) ثم حلل دور الأنظمة الضوئية في التقاط الفوتونات. انقر على التيلاكويد (مقر التفاعلات الضوئية). صحيح! التفاعلات الضوئية تتم على غشاء التيلاكويد. حلل دور الأنظمة الضوئية PSII و PSI في التقاط الفوتونات (تحليل محض). التحليل صف ما يحدث للإلكترونات دون تفسير... الفوتون الأنظمة الضوئية الإلكترونات الاستنتاج استنتج مصدر الأكسجين","keywords":["الفصل","تذكير","بالمكتسبات","مقر","عمليه","التركيب","الضويي","تحديد","التفاعلات","الضوييه","تحليلها","منهجيا","الصانعه","الخضراء","التيلاكويد","الانظمه","التقاط","الفوتونات"],"aliases":["الفصل 31","تذكير بالمكتسبات","الفصل 32","مقر عملية التركيب الضوئي"]},{"id":"lha_phase11_chapitres_21_22_active_2","kind":"active","lessonKey":"phase11_chapitres_21_22","title":"الفصل 31 : تذكير بالمكتسبات — الفصل 32 : مقر عملية التركيب الضوئي (2/2)","lessonTitle":"الفصل 31 : تذكير بالمكتسبات — الفصل 32 : مقر عملية التركيب الضوئي","unitId":6,"part":2,"total":2,"text":"المنطلق... الماء الأكسجين","keywords":["الفصل","تذكير","بالمكتسبات","مقر","عمليه","التركيب","الضويي","المنطلق","الاكسجين"],"aliases":["الفصل 31","تذكير بالمكتسبات","الفصل 32","مقر عملية التركيب الضوئي"]},{"id":"lha_synapse_active_1","kind":"active","lessonKey":"synapse","title":"الفصل 26 : آلية النقل المشبكي (1/2)","lessonTitle":"الفصل 26 : آلية النقل المشبكي","unitId":5,"part":1,"total":2,"text":"الفصل 26 : آلية النقل المشبكي تحديد النهاية قبل المشبكية ثم تحليل تحوّل التنبيه. لاحظ مخطط المشبك الكيميائي. حدد النهاية قبل المشبكية ثم حلل تحوّل التنبيه الكهربائي إلى رسالة كيميائية ثم كهربائية. وثيقة حديثة تبين مستقبلات وقنوات مرتبطة بالربيطة على الغشاء بعد المشبكي. دعم بنيوي: المستقبل بعد المشبكي يفتح قناة مرتبطة بالربيطة عند ارتباط الناقل العصبي. انقر على النهاية قبل المشبكية (مقر تحرير الناقل العصبي). صحيح! عند الوصول الكمون العمل تنفتح قنوات Ca²⁺ وتتحرر الحويصلات المشبكية.","keywords":["الفصل","اليه","النقل","المشبكي","تحديد","النهايه","المشبكيه","تحليل","التنبيه","المشبك","الكيميايي","الكهربايي","رساله","كيمياييه","كهرباييه","حديثه","مستقبلات","وقنوات"],"aliases":["الفصل 26","آلية النقل المشبكي"]},{"id":"lha_synapse_active_2","kind":"active","lessonKey":"synapse","title":"الفصل 26 : آلية النقل المشبكي (2/2)","lessonTitle":"الفصل 26 : آلية النقل المشبكي","unitId":5,"part":2,"total":2,"text":"حلل تحوّل التنبيه الكهربائي إلى رسالة كيميائية ثم كهربائية (تحليل محض). الملاحظة صف ما يحدث عند وصول كمون العمل إلى النهاية قبل المشبكية... كمون العمل حويصلات الآلية اشرح كيف يتحوّل التنبيه الكهربائي إلى رسالة كيميائية... ناقل عصبي شق مشبكي مستقبل الاستنتاج استنتج كيف تعود الإشارة إلى شكل كهربائي بعد المشبكي... كمون بعد مشبكي","keywords":["الفصل","اليه","النقل","المشبكي","التنبيه","الكهربايي","رساله","كيمياييه","كهرباييه","تحليل","الملاحظه","العمل","النهايه","المشبكيه","حويصلات","الاليه","يتحول","مشبكي"],"aliases":["الفصل 26","آلية النقل المشبكي"]},{"id":"lha_subduction_active_1","kind":"active","lessonKey":"subduction","title":"الفصل 43 : تحديد الصفائح التكتونية — الفصل 44 : حركات الصفائح التكتونية (1/2)","lessonTitle":"الفصل 43 : تحديد الصفائح التكتونية — الفصل 44 : حركات الصفائح التكتونية","unitId":11,"part":1,"total":2,"text":"الفصل 43 : تحديد الصفائح التكتونية — الفصل 44 : حركات الصفائح التكتونية تحديد منطقة الغوص ثم تحليل دور الماء المحرر. لاحظ مخطط الغوص. حدد اللوح الغائص ومصدر الماء ثم حلل كيف يخفض الماء درجة انصهار الوشاح. انقر على اللوح الغائص (الصفيحة المحيطية الكثيفة). صحيح! الصفيحة المحيطية الباردة الكثيفة تنغمس تحت الصفيحة الطافية. حلل كيف يخفض الماء المحرر درجة انصهار الوشاح فوق اللوح الغائص (تحليل محض). الملاحظة صف ما يحدث للصفيحة المحيطية عند الغوص...","keywords":["الفصل","تحديد","الصفايح","التكتونيه","حركات","منطقه","الغوص","تحليل","المحرر","اللوح","الغايص","ومصدر","انصهار","الوشاح","الصفيحه","المحيطيه","الكثيفه","البارده"],"aliases":["الفصل 43","تحديد الصفائح التكتونية","الفصل 44","حركات الصفائح التكتونية"]},{"id":"lha_subduction_active_2","kind":"active","lessonKey":"subduction","title":"الفصل 43 : تحديد الصفائح التكتونية — الفصل 44 : حركات الصفائح التكتونية (2/2)","lessonTitle":"الفصل 43 : تحديد الصفائح التكتونية — الفصل 44 : حركات الصفائح التكتونية","unitId":11,"part":2,"total":2,"text":"اندساس صفيحة محيطية كثيفة باردة الآلية اشرح كيف يتحرر الماء من اللوح الغائص... معادن الوشاح انصهار جزئي الاستنتاج استنتج كيف تتولد الصهارة والبركانية... صهارة بركانية أنديزيت","keywords":["الفصل","تحديد","الصفايح","التكتونيه","حركات","اندساس","صفيحه","محيطيه","كثيفه","بارده","الاليه","يتحرر","اللوح","الغايص","معادن","الوشاح","انصهار","الاستنتاج"],"aliases":["الفصل 43","تحديد الصفائح التكتونية","الفصل 44","حركات الصفائح التكتونية"]},{"id":"lha_protein_structure_function_active_1","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (1/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":1,"total":10,"text":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين الدخول إلى الدرس من وضعية مرضية تُظهر أن تغير حمض أميني واحد قد يغيّر وظيفة البروتين. كيف يمكن لتبديل حمض أميني واحد أن يغيّر شكل الخلية ووظيفتها؟ ننطلق من حالة الهيموغلوبين وفقر الدم المنجلي: تغيير صغير في البنية الأولية قد يقود إلى تغير في الطي، ثم في وظيفة البروتين، ثم في حالة الخلية كلها. ابدأ من حالة الهيموغلوبين أفهم أولاً كيف تربط الوثيقة بين الطفرة والبنية والوظيفة. فهم أن الحمض الأميني هو وحدة البناء وأن تتابعه يحدد البنية الأولية ومسار الطي.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","الدخول","الدرس","وضعيه","مرضيه","اميني","وظيفه","لتبديل","ووظيفتها؟","ننطلق","الهيموغلوبين","المنجلي","تغيير"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_2","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (2/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":2,"total":10,"text":"وثيقة تبين الصيغة العامة للحمض الأميني مع مثال الألانين وتمثيله داخل السلسلة. وحدة البناء: كل كرة في السلسلة تمثل حمضاً أمينياً له مجموعة جانبية. وثيقة تبين مسار الانتقال من سلسلة خطية إلى طي محلي ثم شكل وظيفي. المسار البنيوي: تتابع خطي ⟶ طي محلي ⟶ شكل وظيفي. حدد ماذا تمثل الوحدة الأساسية في هذه الوثيقة، وما الذي يختلف من حمض أميني إلى آخر؟ حمض أميني مجموعة جانبية أحسنت، ميزت بين الهيكل العام والمجموعة الجانبية. اذكر أن الوحدة الأساسية هي الحمض الأميني وأن الاختلاف يكون في المجموعة الجانبية.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","الصيغه","العامه","للحمض","الاميني","الالانين","وتمثيله","البناء","امينيا","مجموعه","جانبيه","الانتقال","سلسله"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_3","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (3/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":3,"total":10,"text":"استنتج استنتج معنى البنية الأولية للبروتين. تتابع الأحماض الأمينية رابطة ببتيدية|روابط ببتيدية ممتاز، ربطت البنية الأولية بالتتابع الخطي. اذكر أن البنية الأولية هي تتابع الأحماض الأمينية المرتبطة بروابط ببتيدية. فسّر لماذا يمكن لتغير حمض أميني واحد أن يؤثر لاحقاً في طي البروتين ووظيفته. حمض أميني الطي وظيفة جيد، ربطت بين التغير الأولي ونتيجته الوظيفية. اربط بين تبديل حمض أميني واحد وتغير الطي ثم تغير الوظيفة. البنية الأولية هي تتابع الأحماض الأمينية، وأي تغير نوعي في هذا التتابع قد يغيّر لاحقاً طي البروتين ووظيفته.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","استنتج","الاوليه","للبروتين","تتابع","الاحماض","الامينيه","رابطه","ببتيديه","روابط","ممتاز،","بالتتابع","الخطي"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_4","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (4/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":4,"total":10,"text":"المقارنة بين أهم شكلين من البنى الثانوية قبل الانتقال إلى البنية الثالثية. قارن بين البنية الحلزونية α والبنية الصفائحية β حسب المعايير الآتية. وثيقة مقارنة بين الحلزون α والصفائح β مع إبراز الروابط الهيدروجينية. الشكل العام حلزون لولبي صفائح مستوية نوع التثبيت روابط هيدروجينية روابط هيدروجينية المستوى البنيوي بنية ثانوية بنية ثانوية اكتب خلاصة قصيرة تشرح ما تمثله البنى الثانوية في البروتين. البنية الثانوية روابط هيدروجينية الحلزون α والصفائح β شكلان من أشكال البنية الثانوية،","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","المقارنه","شكلين","البني","الثانويه","الانتقال","الثالثيه","الحلزونيه","والبنيه","الصفايحيه","المعايير","الاتيه","مقارنه"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_5","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (5/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":5,"total":10,"text":"ويثبتهما أساساً تشكل روابط هيدروجينية داخل السلسلة أو بينها. ربط التآثرات الداخلية بتشكل البنية الثالثية والموقع الوظيفي للبروتين. وثيقة تبين بعض التآثرات التي تثبت البنية الفراغية للبروتين. تآثرات متعددة تثبت الشكل النهائي للبروتين. رسم يوضح البروتين المطوي مع موقعه النشط. النتيجة الوظيفية: يتشكل الموقع النشط من البنية الفراغية النهائية. حدد مثالين من التآثرات التي تساهم في تثبيت البنية الفراغية للبروتين. روابط هيدروجينية روابط شاردية أحسنت، ذكرت تآثرات تثبيت رئيسية.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","ويثبتهما","اساسا","روابط","هيدروجينيه","بينها","التاثرات","بتشكل","الثالثيه","والموقع","للبروتين","الفراغيه","تاثرات"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_6","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (6/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":6,"total":10,"text":"اذكر مثالين واضحين مثل الروابط الهيدروجينية والروابط الشاردية. فسر كيف تسمح هذه التآثرات بتثبيت البنية الثالثية. تآثرات تثبت البنية الثالثية جيد، ربطت التآثر بالثبات البنيوي. اذكر أن هذه التآثرات تثبت البنية الثالثية وتحافظ على الشكل الفراغي. استنتج استنتج لماذا يرتبط الموقع النشط مباشرة بالبنية الثالثية ووظيفة البروتين. الموقع النشط وظيفة البنية الثالثية ممتاز، ربطت الشكل الفراغي بالوظيفة. اربط بين تشكل الموقع النشط والبنية الثالثية ثم وظيفة البروتين. البنية الثالثية ليست مجرد شكل؛","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","مثالين","واضحين","الروابط","الهيدروجينيه","والروابط","الشارديه","التاثرات","بتثبيت","الثالثيه","تاثرات","التاثر","بالثبات"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_7","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (7/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":7,"total":10,"text":"فهي التي تسمح بتشكل الموقع النشط، وبالتالي تحدد طبيعة الوظيفة البيولوجية للبروتين. ترتيب المستويات البنيوية الأربعة من الأبسط إلى الأكثر تركيباً. رتب مستويات بنية البروتين من التتابع الخطي إلى المعقد الكامل. وثيقة تلخص المستويات الأربعة لبنية البروتين. وثيقة توضح معنى البنية الرباعية عبر مثال بروتين متعدد الوحدات. البنية الرباعية تظهر عندما تتجمع عدة سلاسل أو وحدات فرعية.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","بتشكل","النشط،","وبالتالي","طبيعه","الوظيفه","البيولوجيه","للبروتين","ترتيب","المستويات","البنيويه","الاربعه","الابسط"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_8","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (8/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":8,"total":10,"text":"تتابع خطي للأحماض الأمينية = البنية الأولية تشكل حلزون α أو صفائح β = البنية الثانوية انطواء السلسلة إلى شكل ثلاثي الأبعاد = البنية الثالثية تجمع عدة سلاسل/وحدات في معقد واحد = البنية الرباعية اشرح بإيجاز كيف ينتقل البروتين من تتابع خطي إلى معقد وظيفي كامل. البنية الأولية البنية الثانوية البنية الثالثية البنية الرباعية يبنى البروتين على مستويات متتالية: أولية ثم ثانوية ثم ثالثية، وقد يصل إلى رباعية عندما تتجمع عدة وحدات في معقد وظيفي واحد. العودة إلى حالة الهيموغلوبين لاستنتاج السلسلة السببية الكاملة:","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","تتابع","للاحماض","الامينيه","الاوليه","حلزون","صفايح","الثانويه","انطواء","ثلاثي","الابعاد","الثالثيه","سلاسل"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_9","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (9/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":9,"total":10,"text":"تغير في التتابع ⟶ تغير في البنية ⟶ تغير في الوظيفة. وثيقة تربط بين تغير تتابع الهيموغلوبين وتغير شكل كريات الدم الحمراء. حالة مدرسية نموذجية: تغير حمض أميني واحد قد يقود إلى مرض. وثيقة داعمة لفهم أن الهيموغلوبين بروتين متعدد الوحدات. الهيموغلوبين مثال مناسب لربط البنية بالوظيفة ثم بالحالة المرضية. حلل ماذا تغير في شكل الكريات الحمراء بين الحالة العادية والحالة المرضية. شكل منجلي كريات الدم أحسنت، وصفت المظهر الظاهري النهائي. اذكر أن بعض كريات الدم تصبح ذات شكل منجلي في الحالة المرضية.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","التتابع","الوظيفه","تتابع","الهيموغلوبين","وتغير","كريات","الحمراء","مدرسيه","نموذجيه","اميني","داعمه","بروتين"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_protein_structure_function_active_10","kind":"active","lessonKey":"protein_structure_function","title":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين (10/10)","lessonTitle":"الفصل 8 : العلاقة بين بنية ووظيفة البروتين","unitId":2,"part":10,"total":10,"text":"فسر كيف يمكن لتغير حمض أميني واحد أن يغيّر بنية الهيموغلوبين. تغير حمض أميني واحد بنية الهيموغلوبين جيد، ربطت بين الطفرة والبنية البروتينية. اربط بين تغير حمض أميني واحد وتغير بنية الهيموغلوبين. استنتج استنتج كيف يقود هذا التغير البنيوي إلى تغير الوظيفة ثم إلى المرض. وظيفة هيموغلوبين ممتاز، بنيت السلسلة السببية كاملة. اذكر أن تغير بنية الهيموغلوبين يغير وظيفته ويؤدي في النهاية إلى مرض. الوثيقة تلخص الفكرة المركزية للدرس: تغير بسيط في البنية الأولية قد يغيّر البنية الفراغية، ثم الوظيفة، ثم الحالة الخلوية والمرضية.","keywords":["الفصل","العلاقه","بين","بنيه","ووظيفه","البروتين","لتغير","اميني","الهيموغلوبين","الطفره","والبنيه","البروتينيه","وتغير","استنتج","التغير","البنيوي","الوظيفه","المرض"],"aliases":["الفصل 8","العلاقة بين بنية ووظيفة البروتين"]},{"id":"lha_immunity_self_nonself_active_1","kind":"active","lessonKey":"immunity_self_nonself","title":"الفصل 14 : الذات واللاذات (1/4)","lessonTitle":"الفصل 14 : الذات واللاذات","unitId":4,"part":1,"total":4,"text":"الفصل 14 : الذات واللاذات فهم كيف تمثل جزيئات HLA / CMH بطاقة الهوية المناعية للخلية، وكيف يقود اختلافها إلى رفض الطعم غير المتوافق. ابدأ من مقارنة HLA-I و HLA-II ثم من مثال الزمر الدموية وعامل Rh لتفهم أن الخلية تحمل محددات سطحية تُقرأ مناعياً. بعد ذلك حدد جزيئات HLA / CMH على الغشاء وفسر لماذا قد يرفض الجسم طعماً غير متوافق. وثيقة حديثة تبين كيف تسمح المحددات السطحية بتحديد الزمرة الدموية. مثال مدرسي قريب: الزمرة الدموية تكشف أن الخلية تحمل علامات سطحية نوعية.","keywords":["الفصل","الذات","واللاذات","بطاقه","الهويه","المناعيه","للخليه،","اختلافها","الطعم","المتوافق","مقارنه","الزمر","الدمويه","وعامل","لتفهم","محددات","سطحيه","مناعيا"],"aliases":["الفصل 14","الذات واللاذات"]},{"id":"lha_immunity_self_nonself_active_2","kind":"active","lessonKey":"immunity_self_nonself","title":"الفصل 14 : الذات واللاذات (2/4)","lessonTitle":"الفصل 14 : الذات واللاذات","unitId":4,"part":2,"total":4,"text":"وثيقة حديثة تقارن بين Rh+ و Rh− من حيث مولد الضد D على السطح. عامل Rh يضيف علامة سطحية أخرى تدخل في منطق التوافق الحيوي. وثيقة حديثة شبيهة بالمجهر الإلكتروني تبين وجود بروتينات مدمجة داخل الغشاء البلازمي. رؤية مجهرية: العلامات السطحية ليست فكرة مجردة بل بروتينات مدمجة في الغشاء. وثيقة حديثة تلخص النموذج الفسيفسائي المائع للغشاء مع البروتينات السطحية. النموذج الغشائي يوضح أين تتموضع البروتينات والعلامات المناعية. وثيقة حديثة تبين أن الغشاء بنية مائعة ديناميكية تسمح بحركة البروتينات السطحية وتجمعها.","keywords":["الفصل","الذات","واللاذات","حديثه","تقارن","السطح","علامه","سطحيه","التوافق","الحيوي","شبيهه","بالمجهر","الالكتروني","بروتينات","مدمجه","البلازمي","مجهريه","العلامات"],"aliases":["الفصل 14","الذات واللاذات"]},{"id":"lha_immunity_self_nonself_active_3","kind":"active","lessonKey":"immunity_self_nonself","title":"الفصل 14 : الذات واللاذات (3/4)","lessonTitle":"الفصل 14 : الذات واللاذات","unitId":4,"part":3,"total":4,"text":"سيولة الغشاء تساعد على فهم توزع الواسمات السطحية وتغير تجمعها. انقر على جزيئات HLA / CMH السطحية (بطاقة الهوية المناعية). صحيح! هذه الجزيئات السطحية تحمل هوية الخلية، واختلافها قد يثير رفض الطعم. حلل كيف يميز الجهاز المناعي الذات عن اللاذات اعتماداً على جزيئات HLA / CMH ومفهوم المحددات السطحية. الملاحظة صف ما تحمله الخلايا على سطحها، وما الذي يختلف من فرد إلى آخر... خلايا الآلية اشرح كيف تسمح هذه الجزيئات بالتعرف على الذات واللاذات...","keywords":["الفصل","الذات","واللاذات","سيوله","تساعد","الواسمات","السطحيه","وتغير","تجمعها","بطاقه","الهويه","المناعيه","الجزييات","الخليه،","واختلافها","الطعم","الجهاز","المناعي"],"aliases":["الفصل 14","الذات واللاذات"]},{"id":"lha_immunity_self_nonself_active_4","kind":"active","lessonKey":"immunity_self_nonself","title":"الفصل 14 : الذات واللاذات (4/4)","lessonTitle":"الفصل 14 : الذات واللاذات","unitId":4,"part":4,"total":4,"text":"تعرف مناعي لاذات الاستنتاج استنتج لماذا يؤدي اختلاف هذه الجزيئات إلى رفض الطعم غير المتوافق... تعرف","keywords":["الفصل","الذات","واللاذات","مناعي","لاذات","الاستنتاج","استنتج","اختلاف","الجزييات","الطعم","المتوافق"],"aliases":["الفصل 14","الذات واللاذات"]},{"id":"lha_immunity_humoral_response_active_1","kind":"active","lessonKey":"immunity_humoral_response","title":"الفصل 16 : المعقد المناعي (1/3)","lessonTitle":"الفصل 16 : المعقد المناعي","unitId":4,"part":1,"total":3,"text":"الفصل 16 : المعقد المناعي فهم كيف تنطلق الاستجابة الخلطية من لمفاوية B نوعية ثم تنتهي بإفراز أجسام مضادة نوعية وتشكيل معقدات مناعية. ابدأ من مخطط يربط اللمفاوية B بالتكاثر النسيلي ثم بالخلية البلازمية. بعد ذلك استعن ببنية الجسم المضاد وبخطوط الترسب لتفهم لماذا تكون الأجسام المضادة نوعية تجاه مستضد معين. وثيقة حديثة تبين السلاسل الثقيلة والخفيفة وموقعي الارتباط بالمستضد في الجسم المضاد. بنية الجسم المضاد تفسر نوعية الارتباط بالمستضد. وثيقة حديثة تبين خطوط الترسب في الانتشار المناعي المزدوج.","keywords":["الفصل","المعقد","المناعي","تنطلق","الاستجابه","الخلطيه","لمفاويه","نوعيه","تنتهي","بافراز","اجسام","مضاده","وتشكيل","معقدات","مناعيه","اللمفاويه","بالتكاثر","النسيلي"],"aliases":["الفصل 16","المعقد المناعي"]},{"id":"lha_immunity_humoral_response_active_2","kind":"active","lessonKey":"immunity_humoral_response","title":"الفصل 16 : المعقد المناعي (2/3)","lessonTitle":"الفصل 16 : المعقد المناعي","unitId":4,"part":2,"total":3,"text":"خطوط الترسب تُظهر أن الأجسام المضادة ترتبط نوعياً بمحددات معينة. وثيقة حديثة تبين تشكل معقد الهجوم الغشائي بعد تنشيط المتممة. نتيجة ممكنة لارتباط الأجسام المضادة: تنشيط المتممة وإحداث ثقوب غشائية. انقر على اللمفاوية B (الخلية التي تتعرف أولاً على المستضد). صحيح! هنا تبدأ الاستجابة الخلطية قبل التكاثر النسيلي والتمايز إلى خلايا بلازمية. حلل كيف يؤدي التعرف النوعي للمستضد إلى تكاثر اللمفاوية B وتمايزها ثم إفراز أجسام مضادة نوعية. الملاحظة صف ما يحدث عندما تتعرف اللمفاوية B النوعية على المستضد...","keywords":["الفصل","المعقد","المناعي","الترسب","الاجسام","المضاده","ترتبط","نوعيا","بمحددات","معينه","حديثه","الهجوم","الغشايي","تنشيط","المتممه","نتيجه","ممكنه","لارتباط"],"aliases":["الفصل 16","المعقد المناعي"]},{"id":"lha_immunity_humoral_response_active_3","kind":"active","lessonKey":"immunity_humoral_response","title":"الفصل 16 : المعقد المناعي (3/3)","lessonTitle":"الفصل 16 : المعقد المناعي","unitId":4,"part":3,"total":3,"text":"لمفاوية B مستضد تعرف الآلية اشرح كيف يحدث التكاثر النسيلي والتمايز إلى خلايا بلازمية... تكاثر نسيلي تمايز خلية بلازمية الاستنتاج استنتج كيف تظهر الأجسام المضادة النوعية في المصل وما أثرها على المستضد... جسم مضاد إفراز بلازمية","keywords":["الفصل","المعقد","المناعي","لمفاويه","مستضد","الاليه","التكاثر","النسيلي","والتمايز","خلايا","بلازميه","تكاثر","نسيلي","تمايز","الاستنتاج","استنتج","الاجسام","المضاده"],"aliases":["الفصل 16","المعقد المناعي"]},{"id":"lha_immunity_cellular_response_active_1","kind":"active","lessonKey":"immunity_cellular_response","title":"الفصل 18 : العناصر الدفاعية في الحالة الثانية (1/3)","lessonTitle":"الفصل 18 : العناصر الدفاعية في الحالة الثانية","unitId":4,"part":1,"total":3,"text":"الفصل 18 : العناصر الدفاعية في الحالة الثانية فهم كيف تتعرف اللمفاوية T القاتلة على الخلية الهدف نوعياً، ثم كيف تقصيها تماسياً. ابدأ من وثيقة التعرف النوعي بين LT والخلية الهدف، ثم استعن بوثائق التكاثر النسيلي وآلية perforines / granzymes لتفهم أن الاستجابة الخلوية تقوم على التعرف أولاً ثم الإقصاء الموجه. وثيقة حديثة تبين التكاثر النسيلي وتميز اللمفاويات T بعد التنشيط. بعد التعرف النوعي تتضاعف الخلايا T الموافقة ثم تتمايز إلى خلايا فعالة. وثيقة حديثة تبين إطلاق perforines و granzymes نحو الخلية الهدف.","keywords":["الفصل","العناصر","الدفاعيه","الحاله","الثانيه","تتعرف","اللمفاويه","القاتله","نوعيا،","تقصيها","تماسيا","التعرف","النوعي","والخليه","الهدف،","استعن","بوثايق","التكاثر"],"aliases":["الفصل 18","العناصر الدفاعية في الحالة الثانية"]},{"id":"lha_immunity_cellular_response_active_2","kind":"active","lessonKey":"immunity_cellular_response","title":"الفصل 18 : العناصر الدفاعية في الحالة الثانية (2/3)","lessonTitle":"الفصل 18 : العناصر الدفاعية في الحالة الثانية","unitId":4,"part":2,"total":3,"text":"آلية الإقصاء تكون تماسية وموجهة نحو الخلية الهدف بعد التعرف. وثيقة حديثة تقارن بين تماس نوعي ينجح في الإقصاء وتماس غير نوعي لا يفعل القتل. ليس كل تماس كافياً: النوعية شرط أساسي في الاستجابة الخلوية. انقر على اللمفاوية T القاتلة (الخلية الزرقاء التي تتعرف على الهدف). صحيح! هذه هي اللمفاوية T القاتلة التي تبدأ بالتعرف النوعي ثم تنفذ الإقصاء. حلل كيف تقصي اللمفاويات T الخلايا المصابة اعتماداً على التعرف النوعي ثم آلية القتل التماسي. الملاحظة صف ما يحدث عندما تلامس اللمفاوية T الخلية الهدف وما الذي يميز هذه الحالة...","keywords":["الفصل","العناصر","الدفاعيه","الحاله","الثانيه","الاقصاء","تماسيه","وموجهه","التعرف","حديثه","تقارن","وتماس","القتل","كافيا","النوعيه","اساسي","الاستجابه","الخلويه"],"aliases":["الفصل 18","العناصر الدفاعية في الحالة الثانية"]},{"id":"lha_immunity_cellular_response_active_3","kind":"active","lessonKey":"immunity_cellular_response","title":"الفصل 18 : العناصر الدفاعية في الحالة الثانية (3/3)","lessonTitle":"الفصل 18 : العناصر الدفاعية في الحالة الثانية","unitId":4,"part":3,"total":3,"text":"لمفاوية T خلية هدف تعرف الآلية اشرح كيف يرتبط التعرف النوعي بجزيئات CMH والمحدد المستضدي ثم بإطلاق آليات القتل... محدد مستضدي تعرف نوعي الاستنتاج استنتج كيف يتم إقصاء الخلية الهدف ولماذا تعد هذه الاستجابة خلوية نوعية... إقصاء خلوي استجابة خلوية","keywords":["الفصل","العناصر","الدفاعيه","الحاله","الثانيه","لمفاويه","الاليه","يرتبط","التعرف","النوعي","بجزييات","والمحدد","المستضدي","باطلاق","اليات","القتل","مستضدي","الاستنتاج"],"aliases":["الفصل 18","العناصر الدفاعية في الحالة الثانية"]},{"id":"lha_immunity_memory_response_active_1","kind":"active","lessonKey":"immunity_memory_response","title":"الفصل 20 : مصدر اللمفاويات LTc (1/3)","lessonTitle":"الفصل 20 : مصدر اللمفاويات LTc","unitId":4,"part":1,"total":3,"text":"الفصل 20 : مصدر اللمفاويات LTc فهم لماذا تكون الاستجابة الثانوية أسرع وأقوى، وكيف يستغل التلقيح هذا المبدأ عبر تكوين خلايا الذاكرة. ابدأ من منحنى يقارن بين الاستجابة الأولية والثانوية، ثم استعن بوثائق تكوين خلايا الذاكرة والجرعة التذكيرية لتفهم أن الذاكرة المناعية هي التي تختصر زمن الكمون وترفع شدة الاستجابة. وثيقة حديثة تبين تشكل خلايا ذاكرة بعد التعرض الأول للمستضد. في نهاية الاستجابة الأولى تبقى خلايا ذاكرة طويلة البقاء. وثيقة حديثة تبين أثر الجرعة التذكيرية على شدة الاستجابة المناعية.","keywords":["الفصل","مصدر","اللمفاويات","ltc","الاستجابه","الثانويه","واقوي،","يستغل","التلقيح","المبدا","تكوين","خلايا","الذاكره","منحني","يقارن","الاوليه","والثانويه،","استعن"],"aliases":["الفصل 20","مصدر اللمفاويات LTc"]},{"id":"lha_immunity_memory_response_active_2","kind":"active","lessonKey":"immunity_memory_response","title":"الفصل 20 : مصدر اللمفاويات LTc (2/3)","lessonTitle":"الفصل 20 : مصدر اللمفاويات LTc","unitId":4,"part":2,"total":3,"text":"التلقيح والجرعة التذكيرية يطبقان مبدأ الذاكرة المناعية عملياً. وثيقة حديثة تبين إعادة تنشيط خلايا الذاكرة بسرعة عند التعرض الثاني. عند التعرض الثاني تُفعل خلايا الذاكرة بسرعة أكبر من الخلايا البكر. وثيقة تركيبية حديثة تلخص مسار المناعة من التعرف إلى الاستجابة ثم الذاكرة. خريطة تركيبية نهائية: الذات واللاذات → خلطية / خلوية → ذاكرة. انقر على الاستجابة الثانوية (المنحنى الأحمر الأعلى والأسرع). صحيح! الاستجابة الثانوية ترتفع بسرعة أكبر وتبلغ ذروة أعلى بفضل خلايا الذاكرة.","keywords":["الفصل","مصدر","اللمفاويات","ltc","التلقيح","والجرعه","التذكيريه","يطبقان","الذاكره","المناعيه","عمليا","حديثه","اعاده","تنشيط","خلايا","بسرعه","التعرض","الثاني"],"aliases":["الفصل 20","مصدر اللمفاويات LTc"]},{"id":"lha_immunity_memory_response_active_3","kind":"active","lessonKey":"immunity_memory_response","title":"الفصل 20 : مصدر اللمفاويات LTc (3/3)","lessonTitle":"الفصل 20 : مصدر اللمفاويات LTc","unitId":4,"part":3,"total":3,"text":"حلل الفرق بين الاستجابة الأولية والثانوية من حيث زمن الكمون والشدة، ثم اربط ذلك بخلايا الذاكرة المناعية. الملاحظة صف ما تلاحظه في منحنى الاستجابة الأولية والثانوية من حيث السرعة والذروة... استجابة أولية زمن كمون أجسام مضادة الآلية اشرح كيف تتكون خلايا الذاكرة وكيف يعاد تنشيطها عند التعرض الثاني... خلايا ذاكرة تكاثر نسيلي تمايز الاستنتاج استنتج لماذا تكون الاستجابة الثانية أسرع وأقوى وما علاقة ذلك بالتلقيح... استجابة ثانوية أسرع أقوى ذاكرة","keywords":["الفصل","مصدر","اللمفاويات","ltc","الفرق","الاستجابه","الاوليه","والثانويه","الكمون","والشده،","بخلايا","الذاكره","المناعيه","الملاحظه","تلاحظه","منحني","السرعه","والذروه"],"aliases":["الفصل 20","مصدر اللمفاويات LTc"]},{"id":"lha_seismic_waves_active_1","kind":"active","lessonKey":"seismic_waves","title":"الفصل 39 : الموجات الزلزالية — الفصل 40 : التركيب الكيميائي للصخور (1/2)","lessonTitle":"الفصل 39 : الموجات الزلزالية — الفصل 40 : التركيب الكيميائي للصخور","unitId":10,"part":1,"total":2,"text":"الفصل 39 : الموجات الزلزالية — الفصل 40 : التركيب الكيميائي للصخور فهم كيف تكشف الأمواج P و S عن بنية باطن الأرض. لاحظ مخطط انتشار الأمواج الزلزالية. حدد الموجة P ثم الموجة S ثم فسّر سلوكهما عند انقطاع غوتنبرغ. انقر على الموجة P (موجة انضغاطية). صحيح! الموجات P انضغاطية وتنتشر في الأوساط الصلبة والسائلة. حلل كيف تكشف الأمواج الزلزالية عن بنية باطن الأرض (تحليل محض). الملاحظة صف سلوك الموجات P و S في القشرة والوشاح... موجات P موجات S سرعة الآلية اشرح ماذا يحدث عند انقطاع غوتنبرغ...","keywords":["الفصل","الموجات","الزلزاليه","التركيب","الكيميايي","للصخور","الامواج","انتشار","الموجه","سلوكهما","انقطاع","غوتنبرغ","انضغاطيه","وتنتشر","الاوساط","الصلبه","والسايله","تحليل"],"aliases":["الفصل 39","الموجات الزلزالية","الفصل 40","التركيب الكيميائي للصخور"]},{"id":"lha_seismic_waves_active_2","kind":"active","lessonKey":"seismic_waves","title":"الفصل 39 : الموجات الزلزالية — الفصل 40 : التركيب الكيميائي للصخور (2/2)","lessonTitle":"الفصل 39 : الموجات الزلزالية — الفصل 40 : التركيب الكيميائي للصخور","unitId":10,"part":2,"total":2,"text":"اختفاء S نواة خارجية سائلة موجات P الاستنتاج استنتج لماذا تدل هذه الظواهر على سيولة النواة الخارجية... سائلة قوى قص نواة خارجية استنتاج","keywords":["الفصل","الموجات","الزلزاليه","التركيب","الكيميايي","للصخور","اختفاء","خارجيه","سايله","موجات","الاستنتاج","استنتج","الظواهر","سيوله","الخارجيه","استنتاج"],"aliases":["الفصل 39","الموجات الزلزالية","الفصل 40","التركيب الكيميائي للصخور"]},{"id":"lha_d1-u1-l2-transcription_active_1","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (1/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":1,"total":7,"text":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN المقارنة بين ADN و ARN حسب معايير واضحة قبل فهم آلية الاستنساخ. قارن بين ADN و ARN حسب المعايير الآتية. مقارنة بصرية حديثة بين ADN و ARN من حيث السكر والقواعد وعدد السلاسل والوظيفة. وثيقة دعم حديثة تبين تركيب النيكليوتيد الريبوزي من فوسفات وسكر ريبوز وقاعدة آزوتية. تفكيك بنية النيكليوتيد: فوسفات + ريبوز + قاعدة آزوتية. وثيقة دعم حديثة تبين أن ARN سلسلة واحدة تبنى في اتجاه 5 شرطة إلى 3 شرطة. شكل ARN نفسه: سلسلة واحدة تحمل القواعد A U G C.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","المقارنه","معايير","واضحه","الاستنساخ","المعايير","الاتيه","مقارنه","بصريه","حديثه","السكر"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l2-transcription_active_2","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (2/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":2,"total":7,"text":"وثيقة دعم حديثة تلخص مكونات ARN ووظيفته الأساسية في نقل المعلومة. لوحة كيميائية سريعة: السكر، القاعدة، عدد السلاسل، الوظيفة. السكر منقوص الأكسجين ريبوز منقوص الأكسجين ريبوز القواعد الآزوتية الثايمين اليوراسيل عدد السلاسل ثنائي سلسلتين أحادي سلسلة واحدة الوظيفة يحفظ المعلومات الوراثية تخزين المعلومة الوراثية ينقل المعلومة الوراثية نسخة من المعلومة الوراثية اكتب خلاصة قصيرة للمقارنة بين الجزيئين. المعلومة الوراثية ADN يخزن المعلومة الوراثية، أما ARN فيساهم في نقلها واستعمالها، مع اختلاف في السكر والقواعد والبنية.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","حديثه","مكونات","ووظيفته","الاساسيه","المعلومه","كيمياييه","سريعه","السكر،","القاعده،","السلاسل،"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l2-transcription_active_3","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (3/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":3,"total":7,"text":"تحليل وثيقة الاستنساخ ومنحنى المثبط لاستنتاج دور ARN بوليمراز. وثيقة تبين منطقة الاستنساخ وتفاصيل عمل ARN بوليمراز على ADN. وثيقة الاستنساخ وتحديد اتجاه تركيب ARNm. وثيقة تربط بين α-amanitine وانخفاض تشكل ARNm. وثيقة داعمة: تأثير α-amanitine على تشكل ARNm. حدد اتجاه حدوث الاستنساخ انطلاقاً من الوثيقة. 5|خماسي 3|ثلاثي نحو|الى|إلى|من 5|خماسي 3|ثلاثي أحسنت، حددت اتجاه القراءة والتركيب. اذكر اتجاه قراءة السلسلة الناسخة واتجاه تركيب ARNm. حلل منحنى تأثير α-amanitine على تشكل ARNm. انخفاض|تناقص|نقصان|قلة تركيز جيد،","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","تحليل","الاستنساخ","ومنحني","المثبط","لاستنتاج","بوليمراز","منطقه","وتفاصيل","وتحديد","اتجاه"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l2-transcription_active_4","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (4/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":4,"total":7,"text":"وصفت العلاقة بين تركيز المثبط وتشكل ARNm. اذكر أن زيادة تركيز المثبط ترافقها قلة تشكل ARNm. استنتج استنتج دور ARN بوليمراز. ARN بوليمراز ضروري الاستنساخ أحسنت، استنتجت الدور الإنزيمي الصحيح. اربط بين تثبيط α-amanitine وتعطل تشكل ARNm. انخفاض تشكل ARNm بوجود α-amanitine يدل على أن ARN بوليمراز إنزيم أساسي في عملية الاستنساخ. ترتيب مراحل الاستنساخ ثم صياغتها في نص علمي مرتب. رتب مراحل الاستنساخ من البداية إلى النهاية. رسم يوضح تشكل ARNm انطلاقاً من ADN أثناء الاستنساخ.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","العلاقه","تركيز","المثبط","وتشكل","زياده","ترافقها","استنتج","بوليمراز","ضروري","الاستنساخ"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l2-transcription_active_5","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (5/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":5,"total":7,"text":"وثيقة حديثة تبين عدة خيوط ARN في طور التشكل على نفس المورثة. صورة حدسية: يمكن أن تتشكل عدة نسخ ARN على نفس المورثة في آن واحد. تثبت ARN بوليمراز على منطقة البداية انفتاح جزء محدود من ADN استعمال إحدى السلسلتين قالباً إضافة النيكليوتيدات المكملة واستطالة ARNm الوصول إلى منطقة النهاية وتحرر ARNm اشرح مراحل الاستنساخ في 3 إلى 5 أسطر. ARN بوليمراز السلسلة القالب تكامل يبدأ الاستنساخ بتثبت الإنزيم، ثم انفتاح ADN، ثم تركيب ARNm المكمل للسلسلة القالبية إلى غاية النهاية.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","حديثه","التشكل","المورثه","حدسيه","تتشكل","بوليمراز","منطقه","البدايه","انفتاح","محدود"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l2-transcription_active_6","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (6/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":6,"total":7,"text":"فهم تحول ARNm الأولي إلى ARNm ناضج بعد انتهاء الاستنساخ. رتب الخطوات التي تفسر نضج ARNm بعد انتهاء الاستنساخ. رسم يوضح تحول ADN إلى ARNm أولي ثم ARNm ناضج. صورة مجهرية مع تفسير بصري لظاهرة التضفير. وثيقة داعمة: صورة بالمجهر + رسم تفسيري للتضفير. يتشكل ARNm أولي بعد الاستنساخ تُحدد الأجزاء المحتفظ بها والأجزاء التي ستُحذف تُحذف بعض المقاطع غير المحتفظ بها يتشكل ARNm ناضج أقصر وصالح للترجمة فسر لماذا يكون ARNm الناضج أقصر من ARNm الأولي.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الاولي","انتهاء","الاستنساخ","الخطوات","مجهريه","تفسير","لظاهره","التضفير","داعمه","بالمجهر"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l2-transcription_active_7","kind":"active","lessonKey":"d1-u1-l2-transcription","title":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN (7/7)","lessonTitle":"الفصل 3 : استنساخ المعلومات الوراثية الموجودة على مستوى ADN","unitId":1,"part":7,"total":7,"text":"ARNm أولي ARNm ناضج أقصر ARNm الناضج أقصر لأن النسخة الأولية تخضع لعملية نضج تُحذف خلالها بعض المقاطع قبل أن تصبح صالحة للترجمة.","keywords":["الفصل","استنساخ","المعلومات","الوراثيه","الموجوده","علي","مستوي","adn","الناضج","النسخه","الاوليه","لعمليه","خلالها","المقاطع","صالحه","للترجمه"],"aliases":["الفصل 3","استنساخ المعلومات الوراثية الموجودة على مستوى ADN"]},{"id":"lha_d1-u1-l3-traduction_active_1","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (1/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":1,"total":10,"text":"الفصل 4 : الترجمة استنتاج لماذا يجب أن تكون الشفرة الوراثية ثلاثية القواعد. إذا كانت اللغة النووية مكوّنة من 4 قواعد فقط بينما اللغة البروتينية تضم 20 حمضاً أمينياً، فكم قاعدة نحتاج في الرامزة الواحدة؟ تجربة توضح أن ARNm الاصطناعي متعدد U ينتج متعدد Phe، وباقي القواعد تعطي أحماضاً أخرى. علل اختيارك بالحساب: ماذا تعطي قاعدة واحدة؟ قاعدتان؟ ثلاث قواعد؟ الشفرة الوراثية ثلاثية لأن 4³ = 64 احتمالاً، وهو عدد كافٍ لتشفير 20 حمضاً أمينياً. فهم العلاقة بين الكودون على ARNm ومضاد الكودون على ARNt داخل الريبوزوم.","keywords":["الفصل","الترجمه","استنتاج","الشفره","الوراثيه","ثلاثيه","القواعد","اللغه","النوويه","مكونه","قواعد","بينما","البروتينيه","امينيا،","قاعده","نحتاج","الرامزه","الواحده؟"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_2","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (2/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":2,"total":10,"text":"مخطط يبين ARNm والريبوزوم و ARNt الحامل لمضاد الكودون والحمض الأميني. مخطط الترجمة: كودون ↔ مضاد الكودون ↔ حمض أميني. جدول الشفرة الوراثية لقراءة الرامزات وتحديد الحمض الأميني الموافق. جدول داعم لقراءة الرامزات وتحديد رموز البدء والتوقف. حدد أين يوجد الكودون وأين يوجد مضاد الكودون. الكودون مضاد الكودون أحسنت، ميزت بين موضع الكودون وموضع مضاد الكودون. اذكر أن الكودون على ARNm ومضاد الكودون على ARNt. فسّر كيف يضمن هذا الاقتران اختيار الحمض الأميني الصحيح. تكامل الحمض الأميني جيد،","keywords":["الفصل","الترجمه","والريبوزوم","الحامل","لمضاد","الكودون","والحمض","الاميني","كودون","اميني","الشفره","الوراثيه","لقراءه","الرامزات","وتحديد","الحمض","الموافق","البدء"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_3","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (3/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":3,"total":10,"text":"ربطت بين التكامل واختيار الحمض الأميني. اربط بين تكامل الكودون/مضاد الكودون وحمل ARNt لحمض أميني محدد. استنتج استنتج دور AUG ودور رامزات التوقف. بداية توقف أحسنت، ميزت بين الانطلاق والتوقف في الترجمة. اذكر أن AUG رامزة بداية وأن UAA/UAG/UGA رامزات توقف. تتم ترجمة رسالة ARNm بفضل تكامل الكودون مع مضاد الكودون، حيث يوجه كل ARNt حمضاً أمينياً محدداً إلى الريبوزوم. ترتيب خطوات الترجمة من بدء القراءة إلى تشكل السلسلة الببتيدية. رتب مراحل الترجمة على مستوى الريبوزوم من البداية إلى النهاية. وثيقة حديثة تلخص مراحل الترجمة:","keywords":["الفصل","الترجمه","التكامل","واختيار","الحمض","الاميني","تكامل","الكودون","اميني","استنتج","رامزات","التوقف","بدايه","احسنت،","الانطلاق","والتوقف","رامزه","ترجمه"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_4","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (4/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":4,"total":10,"text":"انطلاق، استطالة، توقف. وثيقة حديثة تبين تجربة تثبت نوعية ارتباط الرامزة مع ARNt الموافق. تجربة دعم: الزوج الصحيح كودون / مضاد كودون هو الذي يثبت نوعياً. يرتبط ARNm بالريبوزوم عند AUG يدخل ARNt الحامل للحمض الأميني الموافق يتكامل مضاد الكودون مع الكودون تتشكل رابطة ببتيدية بين الأحماض الأمينية تتكرر العملية فيطول السلسلة الببتيدية تتوقف الترجمة عند رامزة توقف اشرح في 3 إلى 5 أسطر كيف تنتقل الشفرة الوراثية إلى سلسلة ببتيدية. الريبوزوم رابطة ببتيدية تبدأ الترجمة عند AUG،","keywords":["الفصل","الترجمه","انطلاق،","استطاله،","حديثه","تجربه","نوعيه","ارتباط","الرامزه","الموافق","الزوج","الصحيح","كودون","نوعيا","يرتبط","بالريبوزوم","الحامل","للحمض"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_5","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (5/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":5,"total":10,"text":"ثم تُقرأ الكودونات تباعاً ويجلب كل ARNt حمضه الأميني الموافق، فتتشكل الروابط الببتيدية إلى غاية رامزة التوقف. تحديد مقر الترجمة في الهيولى وفهم دور متعدد الريبوزوم في زيادة مردود التركيب. رسم يوضح عدة ريبوزومات تترجم نفس ARNm داخل الهيولى. ترجمة نفس الرسالة من طرف عدة ريبوزومات. وثيقة حديثة تتبع البروتين داخل الخلايا من الشبكة الهيولية الخشنة إلى الغولجي ثم الحويصلات. رؤية خلوية موسعة: إنتاج كمية كبيرة من البروتين يتكامل مع التوجيه داخل الخلية. حدد مقر تركيب البروتين في الهيولى. الريبوزومات الهيولى أحسنت،","keywords":["الفصل","الترجمه","الكودونات","تباعا","ويجلب","الاميني","الموافق،","فتتشكل","الروابط","الببتيديه","رامزه","التوقف","تحديد","متعدد","الريبوزوم","زياده","مردود","ريبوزومات"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_6","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (6/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":6,"total":10,"text":"حددت مقر الترجمة. اذكر أن الترجمة تتم على مستوى الريبوزومات في الهيولى. استنتج استنتج دور متعدد الريبوزوم. عدة ريبوزومات نفس ARNm زيادة جيد، استنتجت كيف يرفع متعدد الريبوزوم مردود التركيب. اربط بين قراءة نفس ARNm من طرف عدة ريبوزومات وزيادة كمية البروتين المصنّع. وجود متعدد الريبوزوم يعني أن عدة ريبوزومات تترجم نفس ARNm في وقت واحد، مما يزيد كمية البروتين المصنّع. تمييز مكونات الريبوزوم وبنية ARNt وربطهما بوظيفتهما في الترجمة. رسم يوضح الريبوزوم بموقعي A وP وبنية ARNt. الريبوزوم و ARNt: بنية مرتبطة مباشرة بالوظيفة.","keywords":["الفصل","الترجمه","الريبوزومات","استنتج","متعدد","الريبوزوم","ريبوزومات","زياده","استنتجت","مردود","قراءه","وزياده","المصنع","تترجم","واحد،","تمييز","مكونات","وبنيه"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_7","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (7/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":7,"total":10,"text":"حدد مكونات الريبوزوم الأساسية وموقعي A وP. تحت وحدة كبرى تحت وحدة صغرى أحسنت، ميزت بين البنية ومواقع الارتباط. اذكر تحت الوحدة الكبرى، تحت الوحدة الصغرى، وموقعي A وP. استنتج استنتج كيف تسمح بنية ARNt بوظيفته في الترجمة. الحمض الأميني الرامزة المضادة جيد، ربطت البنية بوظيفة النقل والتعرف. اذكر أن ARNt يحمل حمضاً أمينياً في طرف، ورامزة مضادة في الطرف الآخر. الريبوزوم يوفر مواقع A وP لترتيب الترجمة، بينما تسمح بنية ARNt بحمل الحمض الأميني والتعرف على الكودون الموافق.","keywords":["الفصل","الترجمه","مكونات","الريبوزوم","الاساسيه","وموقعي","احسنت،","ومواقع","الارتباط","الكبري،","الصغري،","استنتج","بوظيفته","الحمض","الاميني","الرامزه","المضاده","بوظيفه"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_8","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (8/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":8,"total":10,"text":"ترتيب خطوات تنشيط الأحماض الأمينية قبل إدخالها في الترجمة. رتب مراحل تنشيط الحمض الأميني وربطه بـ ARNt. رسم يوضح تدخل الإنزيم النوعي وATP في شحن ARNt بحمضه الأميني. يجتمع حمض أميني و ARNt وإنزيم نوعي تُستهلك طاقة ATP لتشكيل المعقد يرتبط الحمض الأميني بـ ARNt الموافق يتحرر ARNt مشحون وجاهز للترجمة اشرح لماذا تحتاج الترجمة إلى تنشيط الأحماض الأمينية قبل بدايتها. إنزيم نوعي حمض أميني قبل الترجمة يجب شحن كل ARNt بحمضه الأميني المناسب بوساطة إنزيم نوعي وطاقة من ATP.","keywords":["الفصل","الترجمه","ترتيب","خطوات","تنشيط","الاحماض","الامينيه","ادخالها","مراحل","الحمض","الاميني","وربطه","النوعي","بحمضه","يجتمع","اميني","وانزيم","تستهلك"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_9","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (9/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":9,"total":10,"text":"فهم مصير البروتين بعد تركيبه داخل الهيولى أو على الشبكة الهيولية الخشنة. رتب مسار البروتين بعد تركيبه عندما يكون موجهاً للإفراز. رسم يوضح مرور البروتين عبر الشبكة الهيولية الخشنة ثم جهاز غولجي ثم الحويصلات. وثيقة حديثة شبيهة بخلايا بنكرياسية مفرزة تربط الشبكة الهيولية الخشنة وجهاز غولجي بالإفراز. مثال نسيجي: الخلايا المفرزة مثل خلايا البنكرياس تُظهر بوضوح مسار البروتين الإفرازي. وثيقة حديثة بيانية تبين انتقال الوسم البروتيني زمنياً من الشبكة الهيولية إلى الغولجي ثم الحويصلات. رؤية كمية:","keywords":["الفصل","الترجمه","تركيبه","الشبكه","الهيوليه","الخشنه","عندما","موجها","للافراز","غولجي","الحويصلات","حديثه","شبيهه","بخلايا","بنكرياسيه","مفرزه","وجهاز","بالافراز"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u1-l3-traduction_active_10","kind":"active","lessonKey":"d1-u1-l3-traduction","title":"الفصل 4 : الترجمة (10/10)","lessonTitle":"الفصل 4 : الترجمة","unitId":1,"part":10,"total":10,"text":"الإشارة ترتفع تباعاً في الشبكة ثم الغولجي ثم الحويصلات / الخارج. يُركّب البروتين على الشبكة الهيولية الخشنة ينتقل إلى جهاز غولجي للتعديل والتغليف يُعبأ داخل حويصلات يتجه إلى الغشاء أو يُفرز خارج الخلية فسر بإيجاز كيف يصل البروتين إلى مكان عمله بعد تركيبه. الشبكة الهيولية جهاز غولجي حويصلات مكان عمله لا تنتهي وظيفة الخلية عند تركيب البروتين؛ إذ يُنقل ويُعدّل ثم يُوجّه إلى مكان عمله داخل الخلية أو خارجها.","keywords":["الفصل","الترجمه","الاشاره","ترتفع","تباعا","الشبكه","الغولجي","الحويصلات","الخارج","الهيوليه","الخشنه","ينتقل","غولجي","للتعديل","والتغليف","حويصلات","بايجاز","تركيبه"],"aliases":["الفصل 4","الترجمة"]},{"id":"lha_d1-u3-l1-enzyme_active_1","kind":"active","lessonKey":"d1-u3-l1-enzyme","title":"الإنزيمات والحفز (Enzymes et catalyse) (1/5)","lessonTitle":"الإنزيمات والحفز (Enzymes et catalyse)","unitId":3,"part":1,"total":5,"text":"الإنزيمات والحفز (Enzymes et catalyse) إظهار دور الإنزيم كحفاز بيولوجي نوعي الإنزيم عبارة عن [____] نوعي يعمل كحفاز بيولوجي يخفض [____] اللازمة لانطلاق التفاعل دون أن يُستهلك، ويرتبط مع [____] وفق خاصية التكامل البنيوي على مستوى الموقع الفعال. الإنزيمات في الغالب عبارة عن بروتينات (أحيانا بروتين-حمض نووي) تعطيها بنيتها الفراغية تخصصا وظيفيا. الطاقة الدنيا التي يجب توفيرها لانطلاق التفاعل الكيميائي. الجزيئة التي يرتبط بها الإنزيم وتتحول إلى نواتج.","keywords":["الانزيمات","والحفز","enzymes","catalyse","اظهار","كحفاز","بيولوجي","عباره","اللازمه","لانطلاق","التفاعل","يستهلك،","ويرتبط","خاصيه","التكامل","البنيوي","الغالب","بروتينات"],"aliases":["الإنزيمات والحفز (Enzymes et catalyse)"]},{"id":"lha_d1-u3-l1-enzyme_active_2","kind":"active","lessonKey":"d1-u3-l1-enzyme","title":"الإنزيمات والحفز (Enzymes et catalyse) (2/5)","lessonTitle":"الإنزيمات والحفز (Enzymes et catalyse)","unitId":3,"part":2,"total":5,"text":"ما هو المصطلح الذي يدل على الطاقة الدنيا اللازمة لانطلاق التفاعل والتي يخفضها الإنزيم؟ طاقة التنشيط طاقة التفعيل الإنزيم يخفض \"طاقة التنشيط\" (أو طاقة التفعيل) دون أن يُستهلك. فهم الموقع الفعال وخاصية التكامل البنيوي يرتبط الإنزيم مع مادة التفاعل على مستوى [____] الذي يمتلك شكلا جيبيا يتكامل بنيويا مع مادة التفاعل. هذه الخاصية تفسر [____] الإنزيم (عمله على مادة تفاعل واحدة أو مجموعة قليلة). جزء من الإنزيم ذو شكل جيبي يتكون من عدد محدود من الأحماض الأمينية، يرتبط مع مادة التفاعل وفق خاصية التكامل البنيوي.","keywords":["الانزيمات","والحفز","enzymes","catalyse","المصطلح","الدنيا","اللازمه","لانطلاق","التفاعل","والتي","يخفضها","الانزيم؟","التنشيط","التفعيل","يستهلك","وخاصيه","التكامل","البنيوي"],"aliases":["الإنزيمات والحفز (Enzymes et catalyse)"]},{"id":"lha_d1-u3-l1-enzyme_active_3","kind":"active","lessonKey":"d1-u3-l1-enzyme","title":"الإنزيمات والحفز (Enzymes et catalyse) (3/5)","lessonTitle":"الإنزيمات والحفز (Enzymes et catalyse)","unitId":3,"part":3,"total":5,"text":"خاصية الإنزيم في العمل على مادة تفاعل محددة فقط بفضل التكامل البنيوي. أكمل: الإنزيم يعمل على مادة تفاعل واحدة بفضل خاصية تسمى _______ نوعية النوعية التكامل البنيوي الإجابة الصحيحة: النوعية (عبر التكامل البنيوي على الموقع الفعال). ربط العامل الأنزيمي بالوسط (pH و الحرارة) لكل إنزيم [____] مثلى تسمح بتكامل بنيوي أمثل، وتتغير هذه القيمة حسب الوسط (pH و الحرارة). تجاوز الحرارة المثلى يؤدي إلى [____] البنية الفراغية وفقدان النشاط. لكل إنزيم درجة حرارة مثلى تتغير عندها سرعة التفاعل بشكل أقصى.","keywords":["الانزيمات","والحفز","enzymes","catalyse","خاصيه","العمل","تفاعل","محدده","التكامل","البنيوي","واحده","نوعيه","النوعيه","الاجابه","الصحيحه","العامل","الانزيمي","بالوسط"],"aliases":["الإنزيمات والحفز (Enzymes et catalyse)"]},{"id":"lha_d1-u3-l1-enzyme_active_4","kind":"active","lessonKey":"d1-u3-l1-enzyme","title":"الإنزيمات والحفز (Enzymes et catalyse) (4/5)","lessonTitle":"الإنزيمات والحفز (Enzymes et catalyse)","unitId":3,"part":4,"total":5,"text":"فقدان البنية الفراغية للبروتين عند الحرارة العالية فيفقد الإنزيم نشاطه. ماذا يحدث لبنية الإنزيم عند تجاوز درجة الحرارة المثلى؟ تبديل تشوه فقدان النشاط ينفقد النشاط الحرارة المفرطة تؤدي إلى \"تبديل\" (dénaturation) البنية الفراغية وفقدان النشاط. صياغة المشكل العلمي وإعادة الاستثمار يظل الإنزيم حفازا دون أن يُستهلك، فيسرّع التفاعل ويحافظ على توازن الوسط الخلوي. صغ المشكل العلمي الذي يفسر كيف يسرّع الإنزيم التفاعل دون أن يُستهلك (جملة استفهامية تبدأ بـ كيف وتنتهي بـ ؟). يجب أن تبدأ بـ \"كيف\" وتنتهي بعلامة استفهام \"؟\".","keywords":["الانزيمات","والحفز","enzymes","catalyse","فقدان","الفراغيه","للبروتين","العاليه","فيفقد","نشاطه","لبنيه","تجاوز","المثلي؟","تبديل","ينفقد","المفرطه","naturation","وفقدان"],"aliases":["الإنزيمات والحفز (Enzymes et catalyse)"]},{"id":"lha_d1-u3-l1-enzyme_active_5","kind":"active","lessonKey":"d1-u3-l1-enzyme","title":"الإنزيمات والحفز (Enzymes et catalyse) (5/5)","lessonTitle":"الإنزيمات والحفز (Enzymes et catalyse)","unitId":3,"part":5,"total":5,"text":"مثال: كيف يخفض الإنزيم طاقة التنشيط دون أن يُستهلك؟","keywords":["الانزيمات","والحفز","enzymes","catalyse","التنشيط","يستهلك؟"],"aliases":["الإنزيمات والحفز (Enzymes et catalyse)"]},{"id":"lha_d2-u6-l1-hill-ruben_active_1","kind":"active","lessonKey":"d2-u6-l1-hill-ruben","title":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي (1/6)","lessonTitle":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي","unitId":6,"part":1,"total":6,"text":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي الدخول إلى التجربتين التاريخيتين من وضعية مشكلة: من أين يأتي الأكسجين المنطلق؟ هل يأتي الأكسجين المنطلق من CO₂ أم من الماء H₂O؟ حتى سنة 1937 اعتُقد أن الأكسجين المنطلق في التركيب الضوئي يأتي من تحلل ثاني أكسيد الكربون. جاءت تجربة هيل ثم تجربة روبن بالوسم المشع لتثبت العكس ببرهان تجريبي صارم. ابدأ من وضعية تجربة هيل أعِد ذكر شروط عمل الصانعة الخضراء ثم صِغ فرضياتك حول مصدر الأكسجين. صياغة فرضيات حول مصدر الأكسجين المنطلق والتحقق منها بتجربتي هيل وروبن.","keywords":["تجربه","هيل","وروبن","مصدر","الاكسجين","المنطلق","التركيب","الضويي","الدخول","التجربتين","التاريخيتين","وضعيه","مشكله","المنطلق؟","اعتقد","اكسيد","الكربون","بالوسم"],"aliases":["تجربة هيل وروبن","مصدر الأكسجين المنطلق في التركيب الضوئي"]},{"id":"lha_d2-u6-l1-hill-ruben_active_2","kind":"active","lessonKey":"d2-u6-l1-hill-ruben","title":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي (2/6)","lessonTitle":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي","unitId":6,"part":2,"total":6,"text":"انطلاقا من معادلة التركيب الضوئي الكلية، ما مصدر الأكسجين المنطلق: جزيئة CO₂ أم جزيئة H₂O؟ وثيقة تجريبية: تجربة هيل بالصانعات المعزولة مع مستقبل اصطناعي، ثم وسم ¹⁸O عند روبن. اقترح فرضية أو فرضيتين توضحان مصدر الأكسجين المنطلق (من CO₂ أم من H₂O؟). حلل النتائج: انطلاق O₂ من الصانعات المعزولة في وسط خالٍ من CO₂، ثم وسم O₂ المنطلق بـ ¹⁸O فقط حين يكون الوسم في الماء. تحقق من الفرضيات: أي جزيء يأتي منه الأكسجين المنطلق؟ علّل اعتمادا على الوثيقتين. سمِّ تحلل الماء تحت تأثير الضوء داخل النظام الضوئي.","keywords":["تجربه","هيل","وروبن","مصدر","الاكسجين","المنطلق","التركيب","الضويي","انطلاقا","معادله","الكليه،","جزييه","تجريبيه","بالصانعات","المعزوله","مستقبل","اصطناعي،","اقترح"],"aliases":["تجربة هيل وروبن","مصدر الأكسجين المنطلق في التركيب الضوئي"]},{"id":"lha_d2-u6-l1-hill-ruben_active_3","kind":"active","lessonKey":"d2-u6-l1-hill-ruben","title":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي (3/6)","lessonTitle":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي","unitId":6,"part":3,"total":6,"text":"التحلل الضوئي للماء الأكسجين الماء الإلكترونات انطلاق O₂ بدون CO₂ الماء التحلل الضوئي الأكسجين التحلل الضوئي للماء التحلل الضوئي تظهر تجربة هيل أن الصانعات المعزولة تنطلق O₂ في غياب CO₂، وتثبت تجربة روبن بوسم ¹⁸O أن مصدر الأكسجين المنطلق هو التحلل الضوئي لجزيئات الماء. استثمار وثيقة التجربتين لاستخلاص دور الضوء واليخضور ومصدر الإلكترونات. لوحتان تجريبيتان: تجربة هيل بالصانعات المعزولة، وتجربة روبن بمياه موسومة بـ ¹⁸O. الوسم يتبع الماء: الأكسجين المنطلق يأتي من H₂O لا من CO₂. حدد دور أملاح الحديد Fe³⁺ في تجربة هيل.","keywords":["تجربه","هيل","وروبن","مصدر","الاكسجين","المنطلق","التركيب","الضويي","التحلل","للماء","الالكترونات","انطلاق","الصانعات","المعزوله","تنطلق","وتثبت","لجزييات","استثمار"],"aliases":["تجربة هيل وروبن","مصدر الأكسجين المنطلق في التركيب الضوئي"]},{"id":"lha_d2-u6-l1-hill-ruben_active_4","kind":"active","lessonKey":"d2-u6-l1-hill-ruben","title":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي (4/6)","lessonTitle":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي","unitId":6,"part":4,"total":6,"text":"مستقبل اصطناعي الإلكترونات أحسنت: Fe³⁺ يقوم دور المستقبل الاصطناعي الذي يقبل الإلكترونات المحررة. اذكر أن Fe³⁺ يُرجَع إلى Fe²⁺ إذ يقبل الإلكترونات: هو مستقبل اصطناعي يحل محل NADP الطبيعي. فسّر فسّر لماذا يعد انطلاق O₂ في تجربة هيل دليلا على أن CO₂ ليس مصدره. بدون CO₂ الأكسجين صحيح: انطلاق الأكسجين في غياب كلي للـ CO₂ يفيد أن CO₂ ليس مصدره. اذكر أن الوسط المعزول خالٍ تماما من CO₂ ومع ذلك ينطلق O₂. استنتج استنتج من وسم ¹⁸O عند روبن مصدر الأكسجين المنطلق. التحلل الضوئي ممتاز: الوسم يظهر في O₂ فقط عندما يكون في الماء،","keywords":["تجربه","هيل","وروبن","مصدر","الاكسجين","المنطلق","التركيب","الضويي","مستقبل","اصطناعي","الالكترونات","احسنت","المستقبل","الاصطناعي","المحرره","الطبيعي","انطلاق","دليلا"],"aliases":["تجربة هيل وروبن","مصدر الأكسجين المنطلق في التركيب الضوئي"]},{"id":"lha_d2-u6-l1-hill-ruben_active_5","kind":"active","lessonKey":"d2-u6-l1-hill-ruben","title":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي (5/6)","lessonTitle":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي","unitId":6,"part":5,"total":6,"text":"إذن المصدر هو التحلل الضوئي للماء. اذكر أن O₂ موسوم بـ ¹⁸O فقط في الوسط المحتوي على H₂¹⁸O. الضوء الممتص في النظام الضوئي يطرد إلكترونات اليخضور، وتعوّضها إلكترونات الماء: التحلل الضوئي للماء يوفر الإلكترونات ويحرر الأكسجين. ترتيب أحداث المرحلة الكيميوضوئية منذ امتصاص الفوتون إلى إرجاع المستقبل النهائي. رتب أحداث المرحلة الكيميوضوئية منذ امتصاص الضوء إلى تشكل نواتجها. وثيقة تجريبية تربط تحلل الماء بمرور الإلكترونات وإرجاع المستقبل.","keywords":["تجربه","هيل","وروبن","مصدر","الاكسجين","المنطلق","التركيب","الضويي","المصدر","التحلل","للماء","موسوم","الوسط","المحتوي","الضوء","الممتص","النظام","الكترونات"],"aliases":["تجربة هيل وروبن","مصدر الأكسجين المنطلق في التركيب الضوئي"]},{"id":"lha_d2-u6-l1-hill-ruben_active_6","kind":"active","lessonKey":"d2-u6-l1-hill-ruben","title":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي (6/6)","lessonTitle":"تجربة هيل وروبن : مصدر الأكسجين المنطلق في التركيب الضوئي","unitId":6,"part":6,"total":6,"text":"يمتص اليخضور فوتون الضوء فيتهيج ويطرد إلكترونا تحلل الماء يعوّض الإلكترون المطرود ويحرر O₂ تمر الإلكترونات في سلسلة النواقل داخل غشاء التيلاكويد يُرجَع NADP إلى NADPH ويتركب ATP اشرح بإيجاز علاقة تحلل الماء بمرور الإلكترونات في السلسلة. الماء الإلكترونات التحلل الضوئي الفوتون يطرد إلكترونات اليخضور، وتعوّضها الإلكترونات الآتية من تحلل الماء الذي يحرر الأكسجين، ثم تمر الإلكترونات في السلسلة فتُرجَع NADP ويتركب ATP.","keywords":["تجربه","هيل","وروبن","مصدر","الاكسجين","المنطلق","التركيب","الضويي","اليخضور","فوتون","الضوء","فيتهيج","ويطرد","الكترونا","الالكترون","المطرود","ويحرر","الالكترونات"],"aliases":["تجربة هيل وروبن","مصدر الأكسجين المنطلق في التركيب الضوئي"]},{"id":"lha_d2-u6-l2-jagendorf_active_1","kind":"active","lessonKey":"d2-u6-l2-jagendorf","title":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات (1/5)","lessonTitle":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات","unitId":6,"part":1,"total":5,"text":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات مساءلة الفكرة الشائعة القائلة إن الضوء يتركب ATP مباشرة داخل الصانعة. هل يتركب ATP في الصانعة بفعل الضوء مباشرة؟ جرت العادة على القول إن الضوء يصنع ATP في التركيب الضوئي. جاءت تجربة جاغندورف سنة 1966 لتوضح الدور الحقيقي للضوء: لا يتركب ATP إلا بفضل فرق تدرج البروتونات H⁺. اكتشف بروتوكول جاغندورف انظر ماذا يحدث عندما نحاكي تدرج H⁺ صناعيا في الظلام. تحديد مسار البروتونات في المرحلة الكيميوضوئية قبل تفسير التجربة.","keywords":["تجربه","جاغندورف","تركيب","atp","الظلام","وتدرج","البروتونات","مساءله","الفكره","الشايعه","القايله","الضوء","يتركب","مباشره","الصانعه","مباشره؟","العاده","القول"],"aliases":["تجربة جاغندورف","تركيب ATP في الظلام وتدرج البروتونات"]},{"id":"lha_d2-u6-l2-jagendorf_active_2","kind":"active","lessonKey":"d2-u6-l2-jagendorf","title":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات (2/5)","lessonTitle":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات","unitId":6,"part":2,"total":5,"text":"أثناء المرحلة الكيميوضوئية تُضخ شوارد H⁺ من الحشوة إلى تجويف [____] داخل غشاء [____]، فيتكون تدرج في التركيز، ثم تعود H⁺ نحو الحشوة عبر [____] التي تقوم بدور تركيب ATP. تجويف الكييس: الفضاء الداخلي للثيلاكويد حيث يتجمع البروتون H⁺. كيس غشائي داخل الصانعة الخضراء تحدث فيه تفاعلات المرحلة الكيميوضوئية. معقد إنزيمي (ATP-synthase) يسمح بعودة H⁺ وتركيب ATP. أكمل: تعود H⁺ عبر ______ المذنبة لتركيب ATP. الكرية المذنبة الكرية الجواب: الكرية المذنبة (ATP-synthase).","keywords":["تجربه","جاغندورف","تركيب","atp","الظلام","وتدرج","البروتونات","اثناء","المرحله","الكيميوضوييه","شوارد","الحشوه","تجويف","فيتكون","التركيز،","الكييس","الفضاء","الداخلي"],"aliases":["تجربة جاغندورف","تركيب ATP في الظلام وتدرج البروتونات"]},{"id":"lha_d2-u6-l2-jagendorf_active_3","kind":"active","lessonKey":"d2-u6-l2-jagendorf","title":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات (3/5)","lessonTitle":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات","unitId":6,"part":3,"total":5,"text":"التحقق من دور تدرج البروتونات في تركيب ATP عبر تجربة جاغندورف. ما الدور الحقيقي للضوء في تركيب ATP في الصانعة: تركيب مباشر أم تكوين تدرج H⁺؟ بروتوكول جاغندورف: كييسات في الظلام عند pH = 4 ثم نقلها إلى pH = 8 مع ADP وPi في الظلام. اقترح فرضية: إذا كان تدرج H⁺ هو مصدر الطاقة لتركيب ATP، فماذا تتوقع في الظلام عند خلق فرق pH صناعي؟ حلل النتيجة: تكوّن ATP في الظلام بعد خلق فرق تدرج خارجي. تحقق من الفرضية وعلل: لماذا لا يتركب ATP بدون فرق تدرج البروتونات؟ سمِّ النظرية التي تفسر تركيب ATP عبر تدرج البروتونات.","keywords":["تجربه","جاغندورف","تركيب","atp","الظلام","وتدرج","البروتونات","التحقق","الدور","الحقيقي","للضوء","الصانعه","مباشر","تكوين","بروتوكول","كييسات","نقلها","اقترح"],"aliases":["تجربة جاغندورف","تركيب ATP في الظلام وتدرج البروتونات"]},{"id":"lha_d2-u6-l2-jagendorf_active_4","kind":"active","lessonKey":"d2-u6-l2-jagendorf","title":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات (4/5)","lessonTitle":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات","unitId":6,"part":4,"total":5,"text":"تدرج البروتونات الكرية المذنبة الظلام فرق pH تدرج تدرج البروتونات الكرية المذنبة النظرية الكيمياؤسموزية نظرية ميتشل الكيمياؤسموزية تكوّن ATP في الظلام عند فرق pH صناعي يثبت أن تدرج البروتونات هو مصدر الطاقة، وأن دور الضوء هو تكوين هذا التدرج داخل التيلاكويد. ترتيب مراحل تجربة جاغندورف التي أثبتت تركيب ATP في الظلام. رتب مراحل تجربة جاغندورف منذ تحضير الكييسات إلى ظهور ATP. أربع مراحل لتجربة جاغندورف في الظلام: pH 4 ثم pH 8 مع ADP وPi ثم تركيب ATP.","keywords":["تجربه","جاغندورف","تركيب","atp","الظلام","وتدرج","البروتونات","الكريه","المذنبه","النظريه","الكيمياوسموزيه","نظريه","ميتشل","صناعي","الطاقه،","الضوء","تكوين","التدرج"],"aliases":["تجربة جاغندورف","تركيب ATP في الظلام وتدرج البروتونات"]},{"id":"lha_d2-u6-l2-jagendorf_active_5","kind":"active","lessonKey":"d2-u6-l2-jagendorf","title":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات (5/5)","lessonTitle":"تجربة جاغندورف : تركيب ATP في الظلام وتدرج البروتونات","unitId":6,"part":5,"total":5,"text":"وضع الكييسات في الظلام في محلول pH = 4 نقل الكييسات إلى محلول pH = 8 يحتوي ADP و Pi عودة H⁺ من التجويف إلى الوسط عبر الكرية المذنبة تكوّن ATP في الظلام بلا ضوء اشرح لماذا تدل تجربة جاغندورف على كفاية التدرج البروتوني. الظلام تدرج تحقق تركيب ATP في الظلام بمجرد خلق فرق تدرج H⁺ صناعي: التدرج هو مصدر الطاقة وليس الضوء مباشرة.","keywords":["تجربه","جاغندورف","تركيب","atp","الظلام","وتدرج","البروتونات","الكييسات","محلول","يحتوي","التجويف","الوسط","الكريه","المذنبه","كفايه","التدرج","البروتوني","بمجرد"],"aliases":["تجربة جاغندورف","تركيب ATP في الظلام وتدرج البروتونات"]},{"id":"lha_d2-u6-l3-calvin_active_1","kind":"active","lessonKey":"d2-u6-l3-calvin","title":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن (1/5)","lessonTitle":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن","unitId":6,"part":1,"total":5,"text":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن الدخول إلى تجربة كالفن من سؤال مصير CO₂ الممتص. ما مصير ثاني أكسيد الكربون الممتص في الصانعة الخضراء؟ نواتج المرحلة الكيميوضوئية (ATP و NADPH) تُوظف في المرحلة الكيميوحيوية لصنع مركبات عضوية. لكشف المسار استعمل كالفن الكربون الموسوم ¹⁴CO₂ مع كروماتوغرافيا ثنائية الأبعاد وتصوير إشعاعي ذاتي. تتبع الكربون في الزمن خذ عينات عند 5 و30 و60 ثانية وراقب المركبات الموسومة. استثمار نتائج الكروماتوغرافيا ثنائية الأبعاد لتحديد أول مركب مثبت للكربون.","keywords":["تجربه","كالفن","تتبع","وكشف","حلقه","الدخول","الممتص","اكسيد","الكربون","الصانعه","الخضراء؟","نواتج","المرحله","الكيميوضوييه","nadph","الكيميوحيويه","مركبات","عضويه"],"aliases":["تجربة كالفن","تتبع ¹⁴CO₂ وكشف حلقة كالفن"]},{"id":"lha_d2-u6-l3-calvin_active_2","kind":"active","lessonKey":"d2-u6-l3-calvin","title":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن (2/5)","lessonTitle":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن","unitId":6,"part":2,"total":5,"text":"تركيب تجريبي (مصاصة) ولوحات كروماتوغرافية عند 5 و30 و60 ثانية. الوسم يظهر أولا في 3-PGA ثم يتوسع إلى تريوزات فوسفاتية ثم سكريات. حدد أول مركب عضوي موسوم بعد 5 ثوان من التثبيت. حمض فوسفوغليسريك أحسنت: أول مركب موسوم هو حمض فوسفوغليسريك (3-PGA). اذكر حمض فوسفوغليسريك (3-PGA) الذي يظهر وحده على اللوحة عند 5 ثوان. فسّر فسّر سبب استعمال الميثانول المغلي لإيقاف العينة. إيقاف التفاعلات صحيح: الميثانول المغلي يوقف التفاعلات فورا فيتثبت الوضع الحالي للمركبات.","keywords":["تجربه","كالفن","تتبع","وكشف","حلقه","تجريبي","مصاصه","ولوحات","كروماتوغرافيه","ثانيه","الوسم","يتوسع","تريوزات","فوسفاتيه","سكريات","موسوم","التثبيت","فوسفوغليسريك"],"aliases":["تجربة كالفن","تتبع ¹⁴CO₂ وكشف حلقة كالفن"]},{"id":"lha_d2-u6-l3-calvin_active_3","kind":"active","lessonKey":"d2-u6-l3-calvin","title":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن (3/5)","lessonTitle":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن","unitId":6,"part":3,"total":5,"text":"اذكر أن الميثانول المغلي يوقف التفاعلات لحظيا ليحفظ المركبات المتشكلة في اللحظة المأخوذة. استنتج استنتج من تدرج ظهور الوسم طبيعة مسار تثبيت الكربون. حلقة تجديد المستقبل ممتاز: الظهور التدريجي يفيد مسارا حلقيا مع تجديد مستقبل CO₂. اذكر أن المسار حلقي: تثبيت ثم اختزال ثم تجديد المستقبل الذي يعاد توظيفه. كشف كالفن أول مركب مثبت (3-PGA) وتدرج الوسم في التريوزات ثم السكريات: تثبيت الكربون يدور في حلقة تجدد فيها المستقبل. ترتيب خطوات حلقة كالفن كما كشفتها تجربة كالفن. رتب خطوات حلقة كالفن من تثبيت CO₂ إلى بناء السكريات.","keywords":["تجربه","كالفن","تتبع","وكشف","حلقه","الميثانول","المغلي","التفاعلات","لحظيا","ليحفظ","المركبات","المتشكله","اللحظه","الماخوذه","استنتج","الوسم","طبيعه","تثبيت"],"aliases":["تجربة كالفن","تتبع ¹⁴CO₂ وكشف حلقة كالفن"]},{"id":"lha_d2-u6-l3-calvin_active_4","kind":"active","lessonKey":"d2-u6-l3-calvin","title":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن (4/5)","lessonTitle":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن","unitId":6,"part":4,"total":5,"text":"لوحات كروماتوغرافية ومسار حلقة كالفن. تثبيت CO₂ على مركب 5 كربون (RuBP) بوساطة إنزيم Rubisco تشكل 3-PGA (حمض فوسفوغليسريك) اختزال 3-PGA إلى APG (تريوزات فوسفاتية) بوساطة ATP و NADPH تجديد RuBP وبناء جزيئات عضوية (غلوكوز) اشرح دور نواتج المرحلة الكيميوضوئية في الحلقة. الاختزال تزود المرحلة الكيميوضوئية الحلقة بـ ATP للطاقة و NADPH لقدرة الإرجاع: تثبيت ثم اختزال ثم تجديد المستقبل. حفظ الحصيلة الطاقوية للحلقة الكالفنية. لكل 3 جزيئات CO₂ مثبتة في حلقة كالفن،","keywords":["تجربه","كالفن","تتبع","وكشف","حلقه","لوحات","كروماتوغرافيه","ومسار","تثبيت","كربون","بوساطه","rubisco","فوسفوغليسريك","اختزال","تريوزات","فوسفاتيه","nadph","تجديد"],"aliases":["تجربة كالفن","تتبع ¹⁴CO₂ وكشف حلقة كالفن"]},{"id":"lha_d2-u6-l3-calvin_active_5","kind":"active","lessonKey":"d2-u6-l3-calvin","title":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن (5/5)","lessonTitle":"تجربة كالفن : تتبع ¹⁴CO₂ وكشف حلقة كالفن","unitId":6,"part":5,"total":5,"text":"تستهلك الخلية [____] جزيئات ATP و [____] جزيئات NADPH لتكوين جزيء APG (تريوز فوسفاتي) واحد قابل لبناء الجزيئات العضوية. غليسيرين ألدهيد 3 فوسفات: تريوز فوسفاتية ناتجة عن اختزال 3-PGA، تبنى منها السكريات وتجدد منها RuBP. أكمل: 3 CO₂ تحتاج 9 ATP و ______ NADPH. الجواب: 6 جزيئات NADPH (مضاعفة 9 ATP / 6 NADPH لكل 3 CO₂).","keywords":["تجربه","كالفن","تتبع","وكشف","حلقه","تستهلك","nadph","لتكوين","تريوز","فوسفاتي","لبناء","الجزييات","العضويه","غليسيرين","الدهيد","فوسفات","فوسفاتيه","ناتجه"],"aliases":["تجربة كالفن","تتبع ¹⁴CO₂ وكشف حلقة كالفن"]},{"id":"lha_d2-u7-l1-mitchell-racker_active_1","kind":"active","lessonKey":"d2-u7-l1-mitchell-racker","title":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل (1/6)","lessonTitle":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل","unitId":7,"part":1,"total":6,"text":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل الدخول إلى إعادة البناء الاصطناعي عند راكر من سؤال آلية التحويل. ما الذي يحوِّل تدرج H⁺ إلى ATP داخل الكرية المذنبة؟ بعد اكتشاف تدرج البروتونات في الميتوكندرون والصانعة، ظلت آلية تحويله إلى ATP لغزا. أعاد راكر سنة 1974 بناء النظام اصطناعيا: مضخة بروتونات تعمل بالضوء (بكتيريورودوبسين) + كرية مذنبة = ATP. برهان قاطع على نظرية ميتشل. ابنِ الحويصلة مع راكر ضَع بروتينين فقط في غشاء اصطناعي وراقب ما يحدث مع الضوء.","keywords":["تجربه","راكر","اثبات","النظريه","الكيمياوسموزيه","لميتشل","الدخول","اعاده","البناء","الاصطناعي","التحويل","الكريه","المذنبه؟","اكتشاف","البروتونات","الميتوكندرون","والصانعه،","تحويله"],"aliases":["تجربة راكر","إثبات النظرية الكيمياؤسموزية لميتشل"]},{"id":"lha_d2-u7-l1-mitchell-racker_active_2","kind":"active","lessonKey":"d2-u7-l1-mitchell-racker","title":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل (2/6)","lessonTitle":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل","unitId":7,"part":2,"total":6,"text":"استثمار وثيقة إعادة البناء الاصطناعي لاستخلاص البرهان على النظرية الكيمياؤسموزية. حويصلة غشائية تحمل بروتين بكتيريورودوبسين مضخة H⁺ وكرية مذنبة، مع شواهد الضوء والظلام. بروتينان فقط: مضخة H⁺ بالضوء + كرية مذنبة = تركيب ATP. حدد مصدر تشكل تدرج H⁺ في تجربة راكر. البكتيريورودوبسين الضوء أحسنت: البكتيريورودوبسين مضخة H⁺ تحركها طاقة الضوء (مستخلصة من البكتيريا Halobacterium). اذكر البكتيريورودوبسين: بروتين مضخة H⁺ تعمل بفعل الضوء دون أي سلسلة تنفسية. فسّر فسّر دور الضوء في هذه التجربة. تدرج صحيح:","keywords":["تجربه","راكر","اثبات","النظريه","الكيمياوسموزيه","لميتشل","استثمار","اعاده","البناء","الاصطناعي","لاستخلاص","البرهان","حويصله","غشاييه","بروتين","بكتيريورودوبسين","وكريه","مذنبه،"],"aliases":["تجربة راكر","إثبات النظرية الكيمياؤسموزية لميتشل"]},{"id":"lha_d2-u7-l1-mitchell-racker_active_3","kind":"active","lessonKey":"d2-u7-l1-mitchell-racker","title":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل (3/6)","lessonTitle":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل","unitId":7,"part":3,"total":6,"text":"الضوء لا يتركب ATP مباشرة بل يحرك مضخة البروتونات فيتكون التدرج. اذكر أن الضوء يضخ H⁺ داخل الحويصلة فيتكون تدرج البروتونات. استنتج استنتج البرهان الذي تقدمه هذه التجربة لنظرية ميتشل. تدرج البروتونات الكرية المذنبة ممتاز: تدرج H⁺ وحده كاف لتركيب ATP عبر الكرية المذنبة: النظرية صحيحة. اذكر أن عودة H⁺ عبر الكرية المذنبة تتركب ATP في غياب كل شيء آخر. إعادة البناء الاصطناعي عند راكر برهنت أن تدرج البروتونات وحده، مع الكرية المذنبة، كاف لتركيب ATP: إذ صححت النظرية الكيمياؤسموزية لميتشل (نوبل 1978).","keywords":["تجربه","راكر","اثبات","النظريه","الكيمياوسموزيه","لميتشل","الضوء","يتركب","مباشره","البروتونات","فيتكون","التدرج","الحويصله","استنتج","البرهان","تقدمه","التجربه","لنظريه"],"aliases":["تجربة راكر","إثبات النظرية الكيمياؤسموزية لميتشل"]},{"id":"lha_d2-u7-l1-mitchell-racker_active_4","kind":"active","lessonKey":"d2-u7-l1-mitchell-racker","title":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل (4/6)","lessonTitle":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل","unitId":7,"part":4,"total":6,"text":"ترتيب خطوات تجربة راكر من تركيب الحويصلة إلى إنتاج ATP. رتب خطوات تجربة راكر. ترتيب خطوات إعادة البناء الاصطناعي. عزل بروتين البكتيريورودوبسين من البكتيريا وإدخاله في حويصلة غشائية إضافة الكرية المذنبة (ATP-synthase) إلى الغشاء الاصطناعي إضاءة الحويصلات: ضخ H⁺ إلى الداخل وتكوين التدرج تركيب ATP خارج الحويصلة بفضل عودة H⁺ عبر الكرية المذنبة اشرح لماذا تدل التجربة على صحة النظرية الكيمياؤسموزية. تدرج الكرية المذنبة بغياب كل مكونات السلسلة التنفسية، يكفي تدرج H⁺ مع الكرية المذنبة لتركيب ATP:","keywords":["تجربه","راكر","اثبات","النظريه","الكيمياوسموزيه","لميتشل","ترتيب","خطوات","الحويصله","انتاج","اعاده","البناء","الاصطناعي","بروتين","البكتيريورودوبسين","البكتيريا","وادخاله","حويصله"],"aliases":["تجربة راكر","إثبات النظرية الكيمياؤسموزية لميتشل"]},{"id":"lha_d2-u7-l1-mitchell-racker_active_5","kind":"active","lessonKey":"d2-u7-l1-mitchell-racker","title":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل (5/6)","lessonTitle":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل","unitId":7,"part":5,"total":6,"text":"دليل أن التدرج هو الوسيط الطاقوي الوحيد. ربط التحويلات الطاقوية في التركيب الضوئي والتنفس الخلوي بمفهوم التدرج البروتوني. التفسير الكيمياؤسموزي يوحد بين التركيب الضوئي والتنفس الخلوي: في الصانعة تُضخ H⁺ داخل تجويف [____]، وفي الميتوكوندريون تُضخ H⁺ في المسافة [____]، وفي الحالتين تعود H⁺ عبر [____] لتركيب ATP. الغشاء الداخلي للكييس في الصانعة الخضراء: مقر ضخ H⁺ في التركيب الضوئي. الفضاء بين الغشاء الداخلي والخارجي في الميتوكوندريون: مقر تراكم H⁺ في التنفس الخلوي. ATP-synthase:","keywords":["تجربه","راكر","اثبات","النظريه","الكيمياوسموزيه","لميتشل","التدرج","الوسيط","الطاقوي","الوحيد","التحويلات","الطاقويه","والتنفس","الخلوي","بمفهوم","البروتوني","التفسير","الكيمياوسموزي"],"aliases":["تجربة راكر","إثبات النظرية الكيمياؤسموزية لميتشل"]},{"id":"lha_d2-u7-l1-mitchell-racker_active_6","kind":"active","lessonKey":"d2-u7-l1-mitchell-racker","title":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل (6/6)","lessonTitle":"تجربة راكر : إثبات النظرية الكيمياؤسموزية لميتشل","unitId":7,"part":6,"total":6,"text":"الإنزيم الذي يحول طاقة التدرج البروتوني إلى طاقة كيميائية في ATP. أكمل: يعود H⁺ عبر ______ لتركيب ATP في الصانعة والميتوكندريون معا. الكرية المذنبة الكرية الجواب: الكرية المذنبة (ATP-synthase) في كلتا الحالتين.","keywords":["تجربه","راكر","اثبات","النظريه","الكيمياوسموزيه","لميتشل","التدرج","البروتوني","كيمياييه","لتركيب","الصانعه","والميتوكندريون","الكريه","المذنبه","الجواب","synthase","الحالتين"],"aliases":["تجربة راكر","إثبات النظرية الكيمياؤسموزية لميتشل"]},{"id":"lha_d3-u9-l2-benioff_active_1","kind":"active","lessonKey":"d3-u9-l2-benioff","title":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص (1/6)","lessonTitle":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص","unitId":9,"part":1,"total":6,"text":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص الدخول إلى تحليل بنيوف من سؤال الشاهد الجيوفيزيائي على الغوص. كيف نثبت أن الصفيحة المحيطية تغوص فعلا داخل البرنس؟ لا يمكن ملاحظة الغوص مباشرة في عمق الأرض. لكن أعاد واداتي ثم بنيوف ترصيد بؤر الزلازل في مناطق الاندساس: اصطففت على مستوى مائل من الخندق حتى عمق 700 كلم. هذا الاصطفاف هو بصمة الغوص. حلل توزع بؤر الزلازل لاحظ كيف تتعمق البؤر كلما ابتعدنا عن الخندق نحو القارة. استثمار وثيقة توزع البؤر الزلزالية لاستخلاص دليل الغوص.","keywords":["مستوي","بنيوف","توزع","بور","الزلازل","دليل","علي","الغوص","الدخول","تحليل","الشاهد","الجيوفيزيايي","الصفيحه","المحيطيه","البرنس؟","ملاحظه","مباشره","واداتي"],"aliases":["مستوى بنيوف","توزع بؤر الزلازل دليل على الغوص"]},{"id":"lha_d3-u9-l2-benioff_active_2","kind":"active","lessonKey":"d3-u9-l2-benioff","title":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص (2/6)","lessonTitle":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص","unitId":9,"part":2,"total":6,"text":"مقطع في منطقة غوص يبين الخندق والصفيحة الغائصة واصطفاف البؤر الزلزالية على مستوى مائل. بؤر الزلازل ترسم مستوى مائلا من الخندق حتى 700 كلم: مستوى بنيوف. حدد كيف تتوزع بؤر الزلازل في منطقة الغوص. سطحية الخندق عميقة أحسنت: البؤر سطحية عند الخندق وتتعمق تدريجيا نحو القارة. اذكر أن البؤر سطحية قرب الخندق ثم تتعمق كلما ابتعدنا نحو القارة. فسّر فسّر وجود زلازل على عمق 300 و500 و700 كلم. صفيحة صلبة برنس تنكسر صحيح: وجود بؤر عميقة يثبت أن مادة صلبة وباردة تغوص وتنكسر داخل البرنس المطاطي.","keywords":["مستوي","بنيوف","توزع","بور","الزلازل","دليل","علي","الغوص","منطقه","الخندق","والصفيحه","الغايصه","واصطفاف","البور","الزلزاليه","مايلا","تتوزع","سطحيه"],"aliases":["مستوى بنيوف","توزع بؤر الزلازل دليل على الغوص"]},{"id":"lha_d3-u9-l2-benioff_active_3","kind":"active","lessonKey":"d3-u9-l2-benioff","title":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص (3/6)","lessonTitle":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص","unitId":9,"part":3,"total":6,"text":"اذكر أن الاستينوسفير المطاطي لا يولد زلازل، إذن البؤر العميقة تعود إلى صفيحة صلبة غائصة تنكسر. استنتج استنتج ما يدل عليه اصطفاف البؤر على مستوى مائل. مستوى بنيوف الغوص الصفيحة ممتاز: مستوى بنيوف هو مسار الصفيحة المحيطية الغائصة داخل البرنس. اذكر أن اصطفاف البؤر على مستوى مائل يرسم مسار غوص الصفيحة المحيطية. اصطفاف بؤر الزلازل على مستوى مائل (مستوى بنيوف) من الخندق حتى 700 كلم هو الدليل الجيوفيزيائي القاطع على غوص الصفيحة المحيطية الصلبة الباردة داخل البرنس.","keywords":["مستوي","بنيوف","توزع","بور","الزلازل","دليل","علي","الغوص","الاستينوسفير","المطاطي","زلازل،","البور","العميقه","صفيحه","غايصه","تنكسر","استنتج","اصطفاف"],"aliases":["مستوى بنيوف","توزع بؤر الزلازل دليل على الغوص"]},{"id":"lha_d3-u9-l2-benioff_active_4","kind":"active","lessonKey":"d3-u9-l2-benioff","title":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص (4/6)","lessonTitle":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص","unitId":9,"part":4,"total":6,"text":"ترتيب الشواهد الجيوفيزيائية من السطح إلى العمق في منطقة الغوص. رتب الشواهد المرصودة في منطقة الغوص من الأقرب إلى الأبعد عن الخندق. مقطع يبين الخندق ثم بؤر الزلازل العميقة ثم البركان الأنديزي. خندق محيطي عميق عند حدود التقاء الصفيحتين زلازل سطحية قرب الخندق (< 70 كلم) زلازل عميقة جدا على مستوى مائل (حتى 700 كلم) بركان أنديزي على الصفيحة الطافية بعد أن يتحرر الماء اشرح علاقة عمق الزلازل بمسافة الخندق. العمق الخندق الغوص كلما ابتعدنا عن الخندق اتجهنا نحو القارة ازداد عمق البؤر الزلزالية:","keywords":["مستوي","بنيوف","توزع","بور","الزلازل","دليل","علي","الغوص","ترتيب","الشواهد","الجيوفيزياييه","السطح","العمق","منطقه","المرصوده","الاقرب","الابعد","الخندق"],"aliases":["مستوى بنيوف","توزع بؤر الزلازل دليل على الغوص"]},{"id":"lha_d3-u9-l2-benioff_active_5","kind":"active","lessonKey":"d3-u9-l2-benioff","title":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص (5/6)","lessonTitle":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص","unitId":9,"part":5,"total":6,"text":"ذلك يرسم مسار الغوص المائل للصفيحة المحيطية. ربط مستوى بنيوف بالانصهار المائي والنشاط البركاني على الصفيحة الطافية. الصفيحة الغائصة تحمل معها ماء التحولات، وعند عمق معين يتحرر الماء فيُميّه بيريدوتيت [____] للصفيحة الطافية فيخفض درجة انصهاره، فينشأ انصهار جزئي وتصعد ماغما أنديزيتية فتتشكل [____] على الصفيحة الطافية. الجزء الصخري الدافئ أسفل القشرة: مصدر الانصهار الجزئي المائي في مناطق الغوص. قوس بركاني (كالأنديز أو اليابان) ينشأ فوق منطقة الغوص بفعل الماغما الأنديزيتية اللزجة. أكمل:","keywords":["مستوي","بنيوف","توزع","بور","الزلازل","دليل","علي","الغوص","المايل","للصفيحه","المحيطيه","بالانصهار","المايي","والنشاط","البركاني","الصفيحه","الطافيه","الغايصه"],"aliases":["مستوى بنيوف","توزع بؤر الزلازل دليل على الغوص"]},{"id":"lha_d3-u9-l2-benioff_active_6","kind":"active","lessonKey":"d3-u9-l2-benioff","title":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص (6/6)","lessonTitle":"مستوى بنيوف : توزع بؤر الزلازل دليل على الغوص","unitId":9,"part":6,"total":6,"text":"يخفض الماء درجة انصهار بيريدوتيت ______ فيحدث انصهار جزئي. البرنس الستار المعطف الجواب: بيريدوتيت البرنس (المعطف) للصفيحة الطافية.","keywords":["مستوي","بنيوف","توزع","بور","الزلازل","دليل","علي","الغوص","انصهار","بيريدوتيت","فيحدث","البرنس","الستار","المعطف","الجواب","للصفيحه","الطافيه"],"aliases":["مستوى بنيوف","توزع بؤر الزلازل دليل على الغوص"]},{"id":"lha_d3-u11-l1-migmatite_active_1","kind":"active","lessonKey":"d3-u11-l1-migmatite","title":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت (1/5)","lessonTitle":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت","unitId":11,"part":1,"total":5,"text":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت الدخول إلى شواهد التقلص من سؤال دليل التضاعف القشري. كيف نثبت أن القشرة تزداد سمكا عند التصادم القاري؟ يؤدي التصادم القاري إلى تقلص أفقي. لكن كيف نحصل على دليل صخري على أن الليتوسفير صار أسمك؟ الجواب موجود في صخر المغماتيت : صخر متحول لا يتشكل إلا في أعماق القشرة المتضاعفة. ابدأ من الصخر الشاهد اقرأ الوثيقة البتروغرافية واستخرج معادن المغماتيت. استثمار وثيقة المغماتيت والتضاعف القشري لاستخلاص شواهد التقلص. لوحة تربط التصادم القاري بالتضاعف القشري،","keywords":["الدرس","شواهد","التقلص","التضاعف","القشري","وصخر","المغماتيت","الدخول","تزداد","التصادم","القاري؟","القاري","الليتوسفير","اسمك؟","الجواب","موجود","متحول","يتشكل"],"aliases":["الدرس 7","شواهد التقلص","التضاعف القشري وصخر المغماتيت"]},{"id":"lha_d3-u11-l1-migmatite_active_2","kind":"active","lessonKey":"d3-u11-l1-migmatite","title":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت (2/5)","lessonTitle":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت","unitId":11,"part":2,"total":5,"text":"مع شريحة المغماتيت ومعادنه المميزة. المغماتيت : تناوب كوارتز-غرونا-ميكا-بلاجيوكلاز مع صفوف أومفيبوليت. حدّد حدّد نوع التركيب الجيولوجي الناشئ المميز لمنطقة التصادم. فالق عكسي تضاعف قشري أحسنت: الطيات والفوالق العكسية والصخور المغتربة هي تراكيب مناطق التصادم. اذكر الطيات والفوالق العكسية والصخور المغتربة التي تنشأ بفعل قوى الانضغاط. صف كيفية توضع المعادن المكونة لصخر المغماتيت. تناوب غرونا ميكا جيد: معادن المغماتيت متوضعة في صفوف متناوبة (كوارتز-غرونا-ميكا-بلاجيوكلاز) مع صفوف أومفيبوليت.","keywords":["الدرس","شواهد","التقلص","التضاعف","القشري","وصخر","المغماتيت","شريحه","ومعادنه","المميزه","تناوب","كوارتز","غرونا","بلاجيوكلاز","اومفيبوليت","الجيولوجي","الناشي","المميز"],"aliases":["الدرس 7","شواهد التقلص","التضاعف القشري وصخر المغماتيت"]},{"id":"lha_d3-u11-l1-migmatite_active_3","kind":"active","lessonKey":"d3-u11-l1-migmatite","title":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت (3/5)","lessonTitle":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت","unitId":11,"part":3,"total":5,"text":"اذكر التناوب بين صفوف المعادن : الغرونا والميكا والكوارتز والبلاجيوكلاز. استنتج استنتج لماذا يعد المغماتيت شاهد ودليلا على التضاعف القشري. انصهار جزئي الغرانيت السمك ممتاز: المغماتيت ناتج عن انصهار جزئي لغرانيت القشرة العميقة بفعل ارتفاع الحرارة والضغط ⟶ دليل زيادة سمك الليتوسفير. اربط المغماتيت بالانصهار الجزئي لغرانيت القشرة العميقة الذي لا يحدث إلا في سمك قشري متزايد. يدل صخر المغماتيت على التضاعف القشري وزيادة سمك الليتوسفير :","keywords":["الدرس","شواهد","التقلص","التضاعف","القشري","وصخر","المغماتيت","التناوب","المعادن","الغرونا","والميكا","والكوارتز","والبلاجيوكلاز","استنتج","ودليلا","انصهار","الغرانيت","السمك"],"aliases":["الدرس 7","شواهد التقلص","التضاعف القشري وصخر المغماتيت"]},{"id":"lha_d3-u11-l1-migmatite_active_4","kind":"active","lessonKey":"d3-u11-l1-migmatite","title":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت (4/5)","lessonTitle":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت","unitId":11,"part":4,"total":5,"text":"فهو ينتج عن تحول الصخور العميقة وانصهار جزئي لغرانيت القشرة القارية بفعل ارتفاع الحرارة والضغط. ترتيب مراحل تشكل صخر المغماتيت : التقلص ⇐ التضاعف القشري ⇐ التحول ⇐ الانصهار الجزئي. رتّب مراحل تشكل صخر المغماتيت من التصادم القاري حتى الصخر الشاهد. لوحة التضاعف القشري والمغماتيت. التصادم القاري يسبب تقلصا أفقيا التضاعف القشري يزيد سمك الليتوسفير تحول الصخور العميقة بارتفاع الحرارة والضغط انصهار جزئي لغرانيت القشرة ⇐ المغماتيت لخّص في نص علمي مراحل تشكل صخر المغماتيت.","keywords":["الدرس","شواهد","التقلص","التضاعف","القشري","وصخر","المغماتيت","الصخور","العميقه","وانصهار","لغرانيت","القاريه","ارتفاع","والضغط","ترتيب","مراحل","التحول","الانصهار"],"aliases":["الدرس 7","شواهد التقلص","التضاعف القشري وصخر المغماتيت"]},{"id":"lha_d3-u11-l1-migmatite_active_5","kind":"active","lessonKey":"d3-u11-l1-migmatite","title":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت (5/5)","lessonTitle":"الدرس 7 : شواهد التقلص — التضاعف القشري وصخر المغماتيت","unitId":11,"part":5,"total":5,"text":"التقلص التضاعف القشري الانصهار الجزئي المغماتيت التصادم القاري ⇐ تقلص أفقي ⇐ تضاعف قشري وزيادة سمك الليتوسفير ⇐ تحول الصخور العميقة ⇐ انصهار جزئي للغرانيت ⇐ صخر المغماتيت الشاهد على التقلص. إنتاج النص العلمي المطلوب في الكتاب : مراحل تشكل المغماتيت. لخّص في نص علمي مراحل تشكل صخر المغماتيت. التقلص التضاعف القشري الانصهار الجزئي الغرانيت الجواب : التصادم ⇐ التقلص ⇐ التضاعف القشري ⇐ الانصهار الجزئي للغرانيت ⇐ المغماتيت.","keywords":["الدرس","شواهد","التقلص","التضاعف","القشري","وصخر","المغماتيت","الانصهار","الجزيي","التصادم","القاري","تضاعف","وزياده","الليتوسفير","الصخور","العميقه","انصهار","للغرانيت"],"aliases":["الدرس 7","شواهد التقلص","التضاعف القشري وصخر المغماتيت"]}];
